object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  val L, A, B = in.next().toLong
  val M = in.next().toInt

  def matMulti(mat1: Array[Array[Long]], mat2: Array[Array[Long]], mod: Int): Array[Array[Long]] = {
    val res = Array.ofDim[Long](3, 3)
    for (y <- 0 until 3; x <- 0 until 3) {
      for (i <- 0 until 3) {
        res(y)(x) = mat1(y)(i) * mat2(i)(x)
        res(y)(x) %= mod
      }
    }

    res
  }

  // (x ^ n) % mod
  def repeatSquares(mat: Array[Array[Long]], n: Long, mod: Int): Array[Array[Long]] = {
    if(n == 0)
      mat
    else if(n % 2 == 0)
      repeatSquares(matMulti(mat, mat, mod), n/2, mod)
    else {
      val res = matMulti(mat, mat, mod)
      repeatSquares(matMulti(mat, res, mod), n/2, mod)
    }
  }


  // val a = new Array[Int](N)

  def mkBase(d: Int) = Array(
    Array(Math.pow(10, d).toLong, 0L, 0L),
    Array(1L, 1L, 0L),
    Array(0L, B, 1L)
  )

  var ans = 0L
  var cnt = 0L
  var ind = 1

  var preCd = 0L
  var s = A

  breakable {
    var flag = true
    while (flag) {
      val d = Math.pow(10, ind).toLong - 1
      val hoge = (d-A + (B-1)) / B
      println(hoge)

      var Cd = hoge - preCd
      if(hoge >= L) {
        flag = false
        Cd = L
      }

      preCd = hoge

      val fuga = repeatSquares(mkBase(ind), Cd, M)
      val X = (ans * fuga(0)(0)) % M + s
      ans += X
      ans %= M
      s = (s + B) % M

      ind += 1
    }
  }

  println(ans)
}

