class Integer{
public:
  string val;
  Integer():val("0"){}
  Integer(string num,bool reversed=0){if(!reversed)R(num); val = num;}
  Integer(Int num){val = to_string(num); R(val);}

  void R(string &a){reverse(a.begin(),a.end());}
  bool neg(const string &a)const{return a.back() == '-';}
  char& operator [] (Int i){assert(i<(Int)val.size());return val[i];}

  bool operator ==  (Integer b) {R(b.val); return *this == b.val;}
  bool operator ==  (string b) {R(b);return val == b;}
  template<class T> bool operator == (T b){return *this == Integer(b);}

  bool operator !=  (Integer b) {R(b.val); return *this != b.val;}
  bool operator !=  (string b) {R(b);return !(val == b);}
  template<class T> bool operator != (T b){return *this != Integer(b);}

  bool operator >=  (Integer b) {R(b.val); return *this >= b.val;}
  bool operator >=  (string b) {return !(*this < b);}
  template<class T> bool operator >= (T b){return *this >= Integer(b);}

  bool operator >   (Integer b) {R(b.val); return *this > b.val;}
  bool operator >   (string b) {return *this>=b && *this != b;}
  template<class T> bool operator > (T b){return *this > Integer(b);}

  bool operator <=  (Integer b) {R(b.val); return *this <= b.val;}
  bool operator <=  (string b) {return *this<b || *this == b;}
  template<class T> bool operator <= (T b){return *this <= Integer(b);}

  bool operator <   (Integer b) {R(b.val); return *this < b.val;}
  template<class T> bool operator < (T b){return *this < Integer(b);}

   bool operator <   (string b) {
    R(b);
    const string &a = val;
    if(neg(a) != neg(b)) return neg(a)? 1:0;
    if(a.size() != b.size()) return !neg(a)? (a.size()<b.size()):(a.size()>b.size());
    for(Int i=a.size()-1;i>=0;i--)if(a[i] != b[i]) return !neg(a)? a[i] < b[i]: a[i] > b[i];
    return 0;
  }

  Integer operator + (string b){
    R(b);
    string a = val;
    string fa = neg(a)? "-":"";
    string fb = neg(b)? "-":"";
    if(neg(a)) a.pop_back();
    if(neg(b)) b.pop_back();
    if(Integer(a,1) < Integer(b,1)) swap(a,b),swap(fa,fb);

    if(fa == fb){
      a += '0';
      for(Int i=0;i<(Int)a.size()-1;i++){
        if(i < (Int)b.size()) a[i] += b[i]-'0';
        a[i+1] += (a[i]-'0')/10;
        a[i] = (a[i]-'0')%10 + '0';
      }
      if(a.size() > 1 && a.back() == '0') a.pop_back();
      if((Int)a.size() > 1 && a.back() == '0') a.pop_back();
      if(a != "0") a += fa;
    }
    else {
      for(Int i=0;i<(Int)a.size();i++){
        if(i < (Int)b.size()) a[i] -= b[i]-'0';
        if(a[i]-'0' < 0) a[i]+=10, a[i+1]--; 
      }
      while((Int)a.size()>1 && a.back() == '0') a.pop_back();
      if(a != "0") a += fa;
    }
    return Integer(a,1);
  }

  Integer operator * (string b){
    R(b);
    vector<Int> res;
    string a = val;
    string fa = neg(a)? "-":"";
    string fb = neg(b)? "-":"";
    if(neg(a)) a.pop_back();
    if(neg(b)) b.pop_back();
    if(a.size() < b.size()) swap(a,b), swap(fa,fb);
    if(a == "0" || b == "0") return Integer("0");

    for(Int j=0;j<(Int)b.size();j++)
      for(Int i=0;i<(Int)a.size();i++){
        if(i+j >= (Int)res.size()) res.push_back(0);
        res[i+j] += (a[i]-'0') * (b[j]-'0');
      }
    for(Int i=0; i <(Int)res.size(); i++) {
      if(res[i]/10 == 0) continue;
      if(i + 1 >= (Int)res.size()) res.push_back(0);
      res[i+1] += res[i]/10, res[i]=res[i]%10;
    }
    string sres;
    for(Int i:res) sres += char(i + '0');
    if(fa != fb) sres += '-';
    return Integer(sres,1);
  }

  Integer div(string b,Int flg){
    assert(b != "0");
    string a = val;
    string fa = neg(a)? "-":"";
    string fb = b[0]=='-'? "-":"";
    if(neg(a)) a.pop_back();
    if(b[0]=='-') b.erase(b.begin());
    Integer mod("0");
    string d="0";
    for(Int i=(Int)a.size()-1;i>=0;i--){
      mod = mod * 10 + (a[i] - '0');
      while(mod >= b) mod -= b, d.back()+=1;
      if(i && d != "0") d += '0'; 
    }
    if(flg == 0 && d != "0" && (fa != fb)) d = "-" + d;
    if(flg == 1 && mod != "0" && (fa == "-")) mod *= -1;
    return flg==0? d:mod;
  }

  Integer operator + (Integer b){R(b.val); return *this + b.val;}
  template<class T> Integer operator + (T b){return *this + Integer(b);}

  Integer operator * (Integer b){R(b.val); return *this * b.val;}
  template<class T> Integer operator * (T b){return *this * Integer(b);}

  Integer operator - (string b){b = (b[0] == '-')? b.substr(1):"-" + b;return *this + b;}
  Integer operator - (Integer b){R(b.val); return *this - b.val;} 
  template<class T> Integer operator - (T b){return *this - Integer(b);}

  Integer operator / (string b){return div(b,0);}
  Integer operator / (Integer b){R(b.val);return div(b.val,0);}
  template<class T> Integer operator / (T b){return *this / Integer(b);}

  Integer operator % (string b){return div(b,1);}
  Integer operator % (Integer b){R(b.val);return div(b.val,1);}
  template<class T> Integer operator % (T b){return *this % Integer(b);}

  Integer operator += (Integer b){return *this = *this+b;}
  Integer operator += (string b){return *this = *this+b;}
  template<class T> Integer operator += (T b){return *this += Integer(b);}

  Integer operator -= (Integer b){return *this = *this-b;}
  Integer operator -= (string b){return *this = *this-b;}
  template<class T> Integer operator -= (T b){return *this -= Integer(b);}

  Integer operator *= (Integer b){return *this = *this*b;}
  Integer operator *= (string b){return *this = *this*b;}
  template<class T> Integer operator *= (T b){return *this *= Integer(b);}

  Integer operator /= (string b){return *this = *this/b;}
  Integer operator /= (Integer b){return *this = *this/b;}
  template<class T> Integer operator /= (T b){return *this /= Integer(b);}

  Integer operator %= (string b){return *this = *this % b;}
  Integer operator %= (Integer b){return *this=*this%b;}
  template<class T> Integer operator %= (T b){return *this %= Integer(b);}

