int mod;

struct ModInt {
  int x;
  ModInt(): x(0) {}
  ModInt(i64 a) { x = a % mod; if (x < 0) x += mod; }
  ModInt &operator+=(ModInt that) { x = (x + that.x) % mod; return *this; }
  ModInt &operator-=(ModInt that) { x = (x + mod - that.x) % mod; return *this; }
  ModInt &operator*=(ModInt that) { x = (i64) x * that.x % mod; return *this; }
  ModInt &operator/=(ModInt that) { return *this *= that.inverse(); }
  ModInt operator-() { return ModInt(-this->x); }
  friend ostream& operator<<(ostream &os, ModInt m) { return os << m.x; }
  ModInt inverse() {
    int a = x, b = mod, u = 1, v = 0;
    while (b) { int t = a / b; a -= t * b; u -= t * v; swap(a, b); swap(u, v); }
    return ModInt(u);
  }
  #define op(o, p) ModInt operator o(ModInt that) { return ModInt(*this) p that; }
    op(+, +=) op(-, -=) op(*, *=) op(/, /=)
  #undef op
  #define op(o) bool operator o(ModInt that) const { return x o that.x; }
    op(==) op(!=) op(<) op(<=) op(>) op(>=)
  #undef op
};

using mint = ModInt;

void solve() {
  vi64 cnt(19);
  i64 L, A, B, M; cin >> L >> A >> B >> M;
  reps(i, 18) {
    i64 c = power((i64) 10, i) - A;
    if (c <= 0) continue;
    c = (c + B) / B;
    if (B * c == power((i64) 10, i) + B - A) c--;
    if (c < 0) c = 0;
    cnt[i] = c;
  }
  rreps(i, 18) cnt[i] -= cnt[i - 1];
  vi64 as(19);
  reps(i, 18) as[i] = A + cnt[i] * B;
  if (L == 1) {
    cout << A % M << '\n';
    return;
  }
  mod = M;
  mint ans = 0;
  i64 s = 1;
  reps(i, 18) {
    i64 c = min(L, cnt[i]);
    if (c == 0) continue;
    i64 t = s + c - 1;
    {
      ans = ans * power((mint) 10, i * (t - s + 1));
      ans += (mint) A * (power((mint) 10, i * (t - s + 1)) - 1) / (power((mint) 10, i) - 1);
      {
        mint temp = 0;
        repic(j, s, t) {
          temp += (mint) (j - 1) * power((mint) 10, i * (t - j));
        }
        ans += temp * B;
      }
    }
    L -= c;
    s = t + 1;
  }
  cout << ans << '\n';
}

