struct MOD_INT{
  ll x;

  MOD_INT(ll arg_x){
	  x = arg_x;
	  x %= M;
  }

  MOD_INT& operator+=(const MOD_INT a) {
    (x += a.x) %= M;
    return *this;
  }
  MOD_INT& operator-=(const MOD_INT a) {
    (x += M-a.x) %= M;
    return *this;
  }
  MOD_INT& operator*=(const MOD_INT a) {
    (x *= a.x) %= M;
    return *this;
  }
  MOD_INT operator+(const MOD_INT a) const {
	  MOD_INT res(*this);
    return res+=a;
  }
  MOD_INT operator-(const MOD_INT a) const {
	  MOD_INT res(*this);
    return res-=a;
  }
  MOD_INT operator*(const MOD_INT a) const {
    MOD_INT res(*this);
    return res*=a;
  }
};


MOD_INT mod_pow(MOD_INT x,ll count, ll mod){

	if(count == 0){

		return 1;
	}

	if(count%2 == 1){

		return mod_pow(x,count-1,mod)*x;
	}
	else{

		MOD_INT y = mod_pow(x,count/2,mod);
		return y*y;
	}
}


MOD_INT f(ll loc){
	if(loc == 0){

		return 0;
	}

	MOD_INT ret(0);

	if(loc%2 == 1){

		ll tmp = loc-1;
		ret = f(tmp);
		return ret*S+1;

	}else{

		ll tmp = loc/2;
		ret = f(tmp);
		return ret*mod_pow(S,loc/2,M)+ret;
	}
}


MOD_INT g(ll loc){
	if(loc == 0){

		return 0;
	}

	MOD_INT ret(0);

	if(loc%2 == 1){

		ll tmp = loc-1;
		ret = g(tmp);
		return ret*S+MOD_INT(B)*tmp;

	}else{

		ll tmp = loc/2;
		ret = g(tmp);
		return ret = ret*mod_pow(S,tmp,M)+ret+MOD_INT(B)*tmp*f(tmp);
	}
}


