			tail = (maxi-A)/B*B+A;
		}

		num = (tail-head)/B+1;
		//printf("i:%lld head:%lld  tail:%lld num:%lld\n",i,head,tail,num);

		ans *= mod_pow(S,num,M);
		ans += f(num)*head;
