struct Matrix {
    ll m[3][3];
    Matrix(vector<ll> v) {
        rep(i, 9) {
            m[i/3][i%3] = v[i];
        }
    }
};

Matrix multiple(Matrix a, Matrix b) {
    vector<ll> v(9);
    rep(i, 9) {
        ll x = i/3;
        ll y = i%3;
        rep(j, 3) {
            v[i] += __int128(a.m[x][j]*b.m[j][y]) % mod;
            v[i] %= mod;
        }
    }
    return Matrix(v);
}

Matrix power(Matrix a, ll n) {
    if (n==0) {
        vector<ll> v(9);
        rep(i, 9) {
            if (i==0 || i==4 || i==8) v[i] = 1LL;
        }
        return Matrix(v);
    }
    if (n==1) return a;
    if (n%2==0) {
        return power(multiple(a, a), n/2);
    }
    return multiple(a, power(a, n-1));
}



