vvi pow(vvi A, ll x, ll mod) {
  vvi tmp = A;
  vvi ans = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
  while(x) {
    if (x % 2) {
      ans = mult(ans, tmp, mod);
    }
    tmp = mult(tmp, tmp, mod);
    x /= 2;
  }
  return ans;
}

