int64 mod;
int64 power_mod(int64 a, int64 n) {
  int64 ret = 1;
  for (; n; n >>= 1) {
    if (n & 1) ret = ret * a % mod;
    a = a * a % mod;
  }
  return ret;
}

// sum_{i,0,n-1}q^i
int64 geometric_seq(int64 q, int64 n) {
  q %= mod;
  if (n == 1) return 1;
  if (n % 2) return (1 + q * geometric_seq(q, n - 1)) % mod;
  int64 ret = geometric_seq(q, n / 2);
  ret = ret * (power_mod(q, n / 2) + 1) % mod;
  return ret;
}

// sum_{i,0,n-1}i*q^i
int64 geometric_seq1(int64 q, int64 n) {
  q %= mod;
  if (n == 1) return 0;
  if (n % 2) return (geometric_seq(q, n - 1) +
                     geometric_seq1(q, n - 1)) * q % mod;
  int64 t = power_mod(q, n / 2);
  int64 L = geometric_seq1(q, n / 2);
  int64 R = (L + n / 2 * geometric_seq(q, n / 2) % mod) * t % mod;
  return (L + R) % mod;
}

