class trie {
public:
  trie(size_t max_size) {
    size = 1; // only root
    next.assign(26, vector<int>(max_size, -1));
    end.assign(max_size, false);
    //
    count.assign(26, vector<int>(max_size, 0));
    //
  }

  bool search(string s) {
    int now = 0;
    for (char c : s) {
      if (next[c - 'a'][now] == -1) return false;
      now = next[c - 'a'][now];
    }
    return end[now];
  }

  void insert(string s) {
    int now = 0;
    vector<int> path;
    for (char c : s) {
      path.push_back(now);
      if (next[c - 'a'][now] == -1) next[c - 'a'][now] = size++;
      now = next[c - 'a'][now];
    }
    end[now] = true;

    int mask = 0;
    for (int i = s.length() - 1; i >= 0; --i) {
      mask |= 1 << (s[i] - 'a');
      for (int j = 0; j < 26; ++j)
        if (mask >> j & 1) count[j][path[i]]++;
    }
  }
  //
  int solve(string s, char x) {
    int now = 0;
    for (char c : s) now = next[c - 'a'][now];
    return count[x - 'a'][now];
  }
  //

private:
  vector<vector<int>> next;
  vector<bool> end;
  //
  vector<vector<int>> count;
  //
  int size;
};

template <typename T>
class Matrix {
public:
  vector<vector<T>> mat;
  Matrix(int h, int w) : mat(h, vector<T>(w)) {}
  vector<T>& operator[](int i) { return mat[i]; }
  const vector<T>& operator[](int i) const { return mat[i]; }
  const size_t height() const { return mat.size(); }
  const size_t width() const { return mat[0].size(); }

  // only square matrix
  static Matrix identity(int n) {
    Matrix E(n, n);
    for (int i = 0; i < n; ++i) E[i][i] = 1;
    return E;
  }

  // O(N^3)
  Matrix& operator*=(const Matrix& m) {
    int h = m.height(), w = m.width();
    vector<vector<T>> res(height(), vector<T>(w));
    for (int i = 0; i < height(); ++i)
      for (int k = 0; k < h; ++k)
        for (int j = 0; j < w; ++j) {
          if (i == 0)
            (res[i][j] += (*this)[i][k] % M * (m[k][j] % M)) %= M;
          else
            res[i][j] += (*this)[i][k] * m[k][j];
        }
    mat.swap(res);
    return *this;
  }

  Matrix& operator*(const Matrix& rhs) { return Matrix(*this) *= rhs; }

  // O(N^3logK)
  Matrix operator^(T exponent) {
    Matrix res = Matrix::identity(height());
    Matrix product = *this;

    while (exponent) {
      if (exponent & 1) res *= product;
      product *= product;
      exponent >>= 1;
    }
    return res;
  }

  friend ostream& operator<<(ostream& os, Matrix& m) {
    os << "---- Matrix ----" << endl;
    for (int i = 0; i < m.height(); ++i)
      for (int j = 0; j < m.width(); ++j)
        os << m[i][j] << " \n"[j == m.width() - 1];
    os << "---- Matrix end ----" << endl;
    return os;
  }
};

