    b[0][1] = 1;
    b[1][1] = 1;
    b[1][2] = 1;
    b[2][2] = 1;
    b = b ^ x;
    c[0][0] = ans;
    c[1][0] = now;
    c[2][0] = B;
    b *= c;
    ans = b[0][0];
    now = b[1][0];
    L -= x;
  }
  cout << ans << endl;
  return 0;
}

