template<typename T>
T modpow(T x, T y,T M){
    if(y == 0)return 1;
    if(y == 1)return x % M;
    T res = modpow(x,y/2,M);
    res = res * res % M;
    if(y%2)res = res * x % M;
    return res;
}
ll pow2(ll x, ll y){
    if(y == 0)return 1;
    if(y == 1)return x;
    ll res = pow2(x,y/2);
    res = res * res;
    if(y%2)res = res * x;
    return res;
}
ll cal(ll A, ll B, ll k, ll sz){
    show(A,B,k,sz);
    ll res = 0;
    MPI hoge = pow(MPI(10),MPI(sz));
    MPI MOD = MPI(mod);
    MPI MOD2 = MOD * (hoge-1);
    MPI temp = MPI(A) * (modpow(hoge,MPI(k+1),MOD2)-1+MOD2)%MOD2 / (hoge - 1) % MOD;
    assert(temp<MOD and temp >= 0);
    show(temp);
    res += temp.to_ll()%mod;
    MPI K = MPI(k);
    MPI MOD3 = MOD2*(hoge-1);
    temp = MPI(b) * hoge %MOD3 * (MPI(1) +MOD3 - (K+1)*modpow(hoge,K,MOD3)%MOD3+K*modpow(hoge,K+1,MOD3)%MOD3)%MOD3/(hoge-1)/(hoge-1) % MOD;
    assert(temp<MOD and temp >= 0);
    show(temp);
    res -= temp.to_ll()%mod;
    res += mod;
    res %= mod;
    assert(res < mod and res >= 0);
    return res;
}
