    row = N;
    col = M;
  }
  bool operator<(const matrix &right) const
  { // 使わないけどtupleに必要
    if (row != right.row)
    {
      return row < right.row;
    }
    if (col != right.col)
    {
      return col < right.col;
    }
    for (auto i = 0; i < row * col; i++)
    {
      if (a[i] != right.a[i])
