ll mod_pow(ll x,ll count, ll mod){

	if(count == 0)return 1;
	ll ret = mod_pow((x*x)%mod,count/2,mod);
	if(count%2 == 1){

		ret = (ret*x)%mod;
	}
	return ret;
}

ll f(ll loc){
	if(loc == 0){

		return 0;
	}

	ll ret;

	if(loc%2 == 1){

		ret = f(loc-1);
		ret = S*ret+1;
		ret %= M;

	}else{

		ret = f(loc/2);
		ret = ret*mod_pow(S,loc/2,M)+ret;
		ret %= M;
	}
	return ret;
}

ll g(ll loc){
	if(loc == 0){

		return 0;
	}

	ll ret;

	if(loc%2 == 1){

		ret = g(loc-1);
		ret = S*ret+B*(loc-1);
		ret %= M;

	}else{

		ret = g(loc/2);
		ret = ret*mod_pow(S,loc/2,M)+ret+B*(loc/2)*f(loc/2);
	}
	return ret%M;
}


