		a[0][0] = A, a[0][1] = 1, a[0][2] = 0; // cur
		a[1][0] = 0, a[1][1] = 1, a[1][2] = C; // B
		a[2][0] = 0, a[2][1] = 0, a[2][2] = 1; // 1
	}
