}

lint binsearch(lint i, lint a, lint b, lint l){
    if(to_string(a).size() > i) return 0;
    if(to_string(a+b*(l-1)).size() <= i) return l-1;
    lint low = 0;
    lint high = l-1;
    while(high - low > 1){
        lint mid = (high + low) / 2;
        if(to_string(a+b*mid).size() > i) high = mid;
        else low = mid;
    }
    return low;
}

