ll MOD;

class mod {
public:
    mod() {m_n = 0;}
    mod(ll n) {if (n >= 0) m_n = n % MOD; else m_n = n % MOD + MOD;}
    friend bool operator== (const mod& a, const mod& b) {return a.m_n == b.m_n;}
    friend bool operator!= (const mod& a, const mod& b) {return !(a == b);}
    friend mod operator+ (const mod& a, const mod& b) {return (a.m_n + b.m_n) % MOD;}
    friend mod& operator+= (mod& a, const mod& b) {return a = a + b;}
    friend mod operator- (const mod& a) {return -a.m_n;}
    friend mod operator- (const mod& a, const mod& b) {return (a.m_n + (-b.m_n)) % MOD;}
    friend mod& operator-= (mod& a, const mod& b) {return a = a - b;}
    friend mod operator* (const mod& a, const mod& b) {return (a.m_n * b.m_n) % MOD;}
    friend mod& operator*= (mod& a, const mod& b) {return a = a * b;}
    friend mod mod_pow(const mod& n, ll r) {
        if (r == 0) {
            return 1;
        } else if (r < 0) {
            return mod_pow(n, (MOD - 2) * (-r));
        } else if (r % 2 == 0) {
            mod tmp = mod_pow(n, r / 2);
            return tmp * tmp;
        } else {
            return n * mod_pow(n, r - 1);
        }
    }
    friend mod operator/ (const mod& a, const mod& b) {return a * mod_pow(b, -1);}
    friend mod& operator/= (mod& a, const mod& b) {return a = a / b;}
    friend ostream& operator<< (ostream& os, const mod& n) {os << n.m_n; return os;}
    friend istream& operator>> (istream& is, mod& n) {ll tmp; is >> tmp; n = mod(tmp); return is;}
    ll m_n;
};
mod mod_pow(ll x, ll r) { return mod_pow(mod(x), r); }
mod mod_pow(mod x, mod r) { return mod_pow(x, r.m_n); }

map<ll, mod> tab_pow10;
mod mod_pow10 (ll k) {
    auto it = tab_pow10.find(k);
    if (it != tab_pow10.end()) return it->second;
    return mod_pow(10, k);
}
map<pair<ll, ll>, mod> tab1;
mod Calc1(ll p, ll k) {
    auto it = tab1.find({p, k});
    if (it != tab1.end()) return it->second;
    if (p == 1) return 1;
    if (p%2 == 1) {
        return Calc1(p-1, k) + mod_pow(mod_pow10(k), (p-1));
    } else {
        return Calc1(p/2, k) * (1 + mod_pow(mod_pow10(k), p/2));
    }
}

map<pair<ll, ll>, mod> tab2;
mod Calc2(ll p, ll k) {
    auto it = tab2.find({p, k});
    if (it != tab2.end()) return it->second;
    if (p == 1) return 0;
    if (p%2 == 1) {
        return Calc2(p-1, k) * mod_pow10(k)+ p-1;
    } else {
        return Calc2(p/2, k) * (1 + mod_pow(mod_pow10(k), p/2)) + p/2 * Calc1(p/2, k);
    }
}

