llint modpow(llint a, llint n)
{
	if(n == 0) return 1;
	if(n % 2){
		return ((a%mod) * (modpow(a, n-1)%mod)) % mod;
	}
	else{
		return modpow((a*a)%mod, n/2) % mod;
	}
}

llint calc(llint l, llint r, llint d)
{
	//cout << l << "  " << r << " " << d << endl;
	if(l > r) return 0;
	if(l == r) return (a+b*l%mod) % mod;
	llint m = (l+r)/2;
	return (calc(l, m, d) * modpow(10, (r-m)*d%mod) % mod + calc(m+1, r, d) ) % mod;
}

