class Matrix{
private:
    const int n, mod;
public:
    Wlli mtx;
    Matrix(Wlli &M, int mod): n(M.size()), mod(mod){ mtx = std::move(M);
        REP(i, n) REP(j, n) mtx[i][j] %= mod;
    }
    Matrix id(){
        Wlli E(n, Vlli(n));
        REP(i, n) REP(j, n) E[i][j] = ((i == j) ? 1 : 0);
        return Matrix(E, mod);
    }
    Matrix times(Matrix &m){
        Wlli E(n, Vlli(n, 0));
        REP(i, n) REP(j, n) REP(k, n){
            E[i][k] += this->mtx[i][j] * m.mtx[j][k];
            E[i][k] %= mod;
        }
        return Matrix(E, mod);
    }
    Matrix power(lli k){
        if(k == 0) return id();
        Matrix e = power(k/2);
        Matrix de = e.times(e);
        if(k % 2 == 0) return de;
        return this->times(de);
    }
    Vlli OPE(Vlli &A){
        Vlli RES(n, 0);
        REP(i, n) REP(j, n){
            RES[i] += this->mtx[i][j] * A[j];
            RES[i] %= mod;
        }
        return std::move(RES);
    }
    void show(){
        REP(i, n){
            REP(j, n){
                printf("%lld", mtx[i][j]);
                putchar((j == n-1) ? '\n' : ' ');
            }
        }
    }
};


