struct BigInt
{
    int t[41];
    BigInt() {}
    BigInt(LL x)
    {
        memset(t, 0, sizeof(t));
        int len = 0;
        while(x)
            t[len++] = x % 10, x /= 10;
    }

    BigInt push()
    {
        for(int i = 0; i < 40; i++)
            t[i + 1] += t[i] / 10, t[i] %= 10;
    }

    BigInt operator + (const BigInt &x) const
    {
        BigInt res(0LL);
        for(int i = 0; i < 40; i++)
            res.t[i] = t[i] + x.t[i];
        res.push();
        return res;
    }

    BigInt operator * (const BigInt &x) const
    {
        BigInt res(0LL);
        for(int i = 0; i < 40; i++)
            for(int j = 0; j <= i; j++)
                res.t[i] += t[j] * x.t[i - j];
        res.push();
        return res;
    }

    int getlen()
    {
        for(int i = 40; ~i; i--)
            if(t[i])
                return i + 1;
        return 0;
    }

};

LL getbound(LL x)
{
    LL l = x, r = L - 1, mid, res;
    int len = (BigInt(A) + BigInt(B) * BigInt(x)).getlen();
    while(l <= r)
    {
        mid = MID(l, r);
        if((BigInt(A) + BigInt(B) * BigInt(mid)).getlen() == len)
        {
            res = mid;
            l = mid + 1;
        }
        else
        {
            r = mid - 1;
        }
    }
    return res;
}

