var m int

// Matrix type
type Matrix struct {
	arr      []int
	row, col int
}

// MatrixInit function
func MatrixInit(row, col int, a []int) Matrix {
	arr := make([]int, row*col)
	copy(arr, a)
	res := Matrix{arr, row, col}
	return res
}

// ImatrixInit function
func ImatrixInit(n int) Matrix {
	arr := make([]int, n*n)
	for i := 0; i < n; i++ {
		arr[i+i*n] = 1
	}
	res := Matrix{arr, n, n}
	return res
}

// At function for Matrix
func (mat Matrix) At(i, j int) int {
	return mat.arr[i*mat.col+j]
}

// AddMatrix function
func AddMatrix(a, b Matrix) Matrix {
	if a.row != b.row || a.col != b.col {
		return Matrix{}
	}
	for i := 0; i < a.row*a.col; i++ {
		a.arr[i] += b.arr[i]
	}
	return a
}

// SubMatrix function
func SubMatrix(a, b Matrix) Matrix {
	if a.row != b.row || a.col != b.col {
		return Matrix{}
	}
	for i := 0; i < a.row*a.col; i++ {
		a.arr[i] -= b.arr[i]
	}
	return a
}

// MulMatrix function
func MulMatrix(a, b Matrix) Matrix {
	if a.col != b.row {
		return Matrix{}
	}
	res := MatrixInit(a.row, b.col, nil)
	for i := 0; i < res.row; i++ {
		for j := 0; j < res.col; j++ {
			for k := 0; k < a.col; k++ {
				res.arr[i*res.col+j] += (a.arr[i*a.col+k] * b.arr[k*b.col+j]) % m
				res.arr[i*res.col+j] %= m
			}
		}
	}
	return res
}

// PowMatrix function
func PowMatrix(a Matrix, n int) Matrix {
	if a.row != a.col {
		return Matrix{}
	}
	res := ImatrixInit(a.row)
	for n > 0 {
		if n&1 == 1 {
			res = MulMatrix(res, a)
		}
		a = MulMatrix(a, a)
		n >>= 1
	}
	return res
}

#include <bits/stdc++.h>
using namespace std;
long long MOD;
long long modpow(unsigned long long b){
  long long ans = 1;
  long long a = 10;
  while (b > 0){
    if (b % 2 == 1){
      ans *= a;
      ans %= MOD;
    }
    a *= a;
    a %= MOD;
    b /= 2;
  }
  return ans;
}
long long gp(int i, unsigned long long N){
  //1+10^i+10^2i+...+10^(N-1)i
  if (N == 1){
    return 1;
  } else {
    if (N % 2 == 0){
      long long ans = gp(i, N / 2);
      ans *= modpow(N / 2 * i) + 1;
      ans %= MOD;
      return ans;
    } else {
      long long ans = gp(i, N - 1);
      for (int j = 0; j < i; j++){
        ans *= 10;
        ans %= MOD;
      }
      ans++;
      ans %= MOD;
      return ans;
    }
  }
}
long long apgp(int i, unsigned long long N){
  //1+2*10^i+3*10^2i+...+N*10^(N-1)i
  if (N == 1){
    return 1;
  } else {
    if (N % 2 == 0){
      long long ans = apgp(i, N / 2);
      ans *= modpow(N / 2 * i) + 1;
      ans %= MOD;
      ans += gp(i, N / 2) * (N / 2 % MOD) % MOD;
      ans %= MOD;
      return ans;
    } else {
      long long ans = apgp(i, N - 1);
      for (int j = 0; j < i; j++){
        ans *= 10;
        ans %= MOD;
      }
      ans += N;
      ans %= MOD;
      return ans;
    }
  }
}
long long apgp2(unsigned long long lb, unsigned long long ub, long long B, int i){
  unsigned long long len = (ub - lb) / B + 1;
  long long ans = 0;
  if (lb >= B){
    ans += gp(i, len) * ((lb - B) % MOD) % MOD;
  } else {
    ans -= gp(i, len) * ((B - lb) % MOD) % MOD;
    ans += MOD;
  }
  ans %= MOD;
  ans += B % MOD * apgp(i, len) % MOD;
  ans %= MOD;
  return ans;
}
int main(){
  unsigned long long L, A, B, M;
  cin >> L >> A >> B >> M;
  MOD = M;
  unsigned long long C = A + B * (L - 1);
  long long r = A % B;
  long long ans = 0;
  unsigned long long digit_cnt = 0;
  for (int i = 18; i >= 1; i--){
    unsigned long long lb = 1;
    for (int j = 0; j < i - 1; j++){
      lb *= 10;
    }
    unsigned long long ub = lb * 10;
    lb = (lb - r + B - 1) / B * B + r;
    ub = (ub - r - 1) / B * B + r;
    if (lb <= C && A <= ub && lb <= ub){
      lb = max(lb, A);
      ub = min(ub, C);
      ans += apgp2(lb, ub, B, i) * modpow(digit_cnt) % MOD;
      digit_cnt += i * ((ub - lb) / B + 1);
    }
  }
  ans %= MOD;
  cout << ans << endl;
}

