const int MAXcomb = 2000100;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}
ll disit(ll x){
  ll res = 0;
  while(x){
    res++;
    x /= 10;
  }
  return res;
}


typedef vector<ll> vec;
typedef vector<vec> mat;

mat mul_mat(mat A, mat B){
  mat res(A.size(), vec(B[0].size(), 0));
  rep(i, A.size())rep(k, B.size())rep(j, B[0].size()){
    res[i][j] = (res[i][j] + A[i][k] % MOD * (B[k][j] % MOD) % MOD) % MOD;
  }
  return res;
}

mat pow_mat(mat A, ll n){
  mat res(A.size(), vec(A.size(), 0));
  rep(i, A.size()) res[i][i] = 1;
  while(n > 0){
    if(n&1) res = mul_mat(res, A);
    A = mul_mat(A, A);
    n >>= 1;
  }
  return res;
}

ll L, A, B;
void solve(){
  cin >> L >> A >> B >> MOD;
  /*
  (sum) = (10^d, 1, 1)(sum)
  (A+1) = (   0, 1, 1)(A__)
  (d__) = (   0, 0, 1)(d__)

  (0)
  (3)
  (4)
  */
  ll sum = 0;
  ll d = disit(A);
  while(L){
    ll next = pow_long(10, d);
    ll need = min((next - A + B - 1)/B, L);
    L -= need;
    mat M = {{pow_long(10, d) % MOD, 1, 0},
             {0, 1, 1},
             {0, 0, 1}};
    M = pow_mat(M, need);
    mat x = {{sum % MOD}, {A % MOD}, {B}};
    x = mul_mat(M, x);
    sum = x[0][0];
    A += B * need;
    d++;
  }
  cout << sum << endl;
}

