ll MOD;

int calc_lg(ll x) {
  int res = 0;
  while (x > 0) {
    ++res;
    x /= 10;
  }
  return res;
}

ll calc_ten(int e) {
  ll v = 1;
  for (int i = 0; i < e; i++) v *= 10;
  return v;
}

ll power(ll x, ll e) {
  x %= MOD;
  ll v = 1;
  for (; e > 0; e >>= 1) {
    if (e & 1) {
      v = v * x % MOD;
    }
    x = x * x % MOD;
  }
  return v;
}

typedef vector<ll> Vec;
typedef vector<Vec> Mat;

Mat eye(int n) {
  Mat I(n, Vec(n));
  for (int i = 0; i < n; ++i)
    I[i][i] = 1;
  return I;
}
Mat mul(Mat A, const Mat& B) {
  for (int i = 0; i < A.size(); ++i) {
    Vec x(A[0].size());
    for (int k = 0; k < B.size(); ++k)
      for (int j = 0; j < B[0].size(); ++j)
        (x[j] += A[i][k] * B[k][j] % MOD) %= MOD;
    A[i].swap(x);
  }
  return A;
}
Mat pow(Mat A, ll k) {
  Mat X = eye(A.size());
  for (; k > 0; k /= 2) {
    if (k & 1) X = mul(X, A);
    A = mul(A, A);
  }
  return X;
}
Vec mul(const Mat& A, const Vec& b) {
  Vec y(A.size());
  for (int i = 0; i < A.size(); ++i)
    for (int j = 0; j < A[0].size(); ++j)
      (y[i] += A[i][j] * b[j] % MOD) %= MOD;
  return y;
}

ll solveSub(ll A, ll B, ll L, ll ten) {
  A %= MOD;
  B %= MOD;
  ten %= MOD;
  Mat M = {
      {ten, A, B},
      {0, 1, 0},
      {0, 1, 1}};
  vector<ll> init = {0, 1, 0};
  auto goal = mul(pow(M, L), init);
  return goal[0];
}

