	LL now = 0;
	for(int i=1; i<=18; i++){
		Matrix mask(3, 3);
		mask[1][1] = power(10, i);
		mask[2][1] = 1;
		mask[2][2] = 1;
		mask[3][2] = B;
		mask[3][3] = 1;
		LL num = binary_search(now*10+9) - binary_search(now);
		now = now*10+9;
		if(num > 0) m = m*power(mask, num);
	}
	cout << m[1][1] << endl;
}

