		mult *= 10;
	}
	int ans = 0; unsigned long long curlen = 0;
	for (int i = max_digits; i >= 1; --i) {
		mult /= 10;
		long long pl = (mult < A ? 0 : (mult - A + B - 1) / B);
		long long pr = (mult * 10 < A ? 0 : (mult * 10 - A + B - 1) / B);
		if (pl > L) pl = L;
