struct mint {
	long long num;
	mint(long long a = 0) : num((a%MOD+MOD)%MOD){}
	mint operator-() const { return mint(-num); }
	mint &operator+= (const mint &a) {
		if((num += a.num) >= MOD) num -= MOD;
		return *this;
	}
	mint &operator-= (const mint &a) {
		if((num += MOD-a.num) >= MOD) num -= MOD;
		return *this;
	}
	mint &operator*= (const mint &a) {
		(num *= a.num) %= MOD;
		return *this;
	}
	mint operator+ (const mint &a) const { return mint(*this) += a; }
	mint operator- (const mint &a) const { return mint(*this) -= a; }
	mint operator* (const mint &a) const { return mint(*this) *= a; }

	inline bool operator== (const mint &a) const { return num == a.num; }
	inline bool operator!= (const mint &a) const { return num != a.num; }

	mint pow(long long n) const {
		mint ret(1), mul(num);
		while(n > 0){
			if(n & 1) ret *= mul;
			mul *= mul;
			n >>= 1ll;
		}
		return ret;
	}

	// for prime MOD	
	mint inverse() const {
		long long a = num, b = MOD, u = 1, v = 0, t;
		while(b > 0){
			t = a/b;
			swap(a -= t*b, b);
			swap(u -= t*v, v);
		}
		return mint(u);
	}
	mint &operator/= (const mint &a) {
		(*this) *= a.inverse();
		return *this;
	}
	mint operator/ (const mint &a) const { return mint(*this) /= a; }
};

template<class T> struct Matrix {
	vector<vector<T>> A;
	Matrix() {}
	Matrix(size_t n, size_t m) : A(n, vector<T>(m, 0)) {};

	static Matrix I(size_t n) {
		Matrix mat(n, n);
		for(size_t i = 0; i < n; i++) mat[i][i] = 1;
		return (mat);
	}

	size_t height() const { return (A.size()); }
	size_t width() const { return (A[0].size()); }

	inline const vector<T> &operator[](int k) const { return (A.at(k)); }
	inline vector<T> &operator[](int k) { return (A.at(k)); }

	Matrix &operator+= (const Matrix &B){
		size_t n = height(), m = width();
		assert(n == B.height() and m == B.width());
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				(*this)[i][j] += B[i][j];
			}
		}
		return (*this);
	}
	Matrix &operator-= (const Matrix &B){
		size_t n = height(), m = width();
		assert(n == B.height() and m == B.width());
		for(size_t i = 0; i < n; i++)
			for(size_t j = 0; j < m; j++)
				(*this)[i][j] -= B[i][j];
		return (*this);
	}
	Matrix &operator*= (const Matrix &B){
		size_t n = height(), m = B.width(), p = width();
		assert(p == B.height());
		vector<vector<T>> C(n, vector<T>(m, 0));
		for(size_t i = 0; i < n; i++)
			for(size_t j = 0; j < m; j++)
				for(size_t k = 0; k < p; k++)
					C[i][j] = (C[i][j] + (*this)[i][k] * B[k][j]);
		A.swap(C);
		return (*this);
	}
	Matrix &operator^= (long long p){
		Matrix B = Matrix::I(height());
		while(p > 0){
			if(p & 1) B *= (*this);
			(*this) *= (*this);
			p >>= 1ll;
		}
		A.swap(B.A);
		return (*this);
	}

	Matrix operator+ (const Matrix &B) const { return (Matrix(*this) += B); }
	Matrix operator- (const Matrix &B) const { return (Matrix(*this) -= B); }
	Matrix operator* (const Matrix &B) const { return (Matrix(*this) *= B);	}
	Matrix operator^ (const long long p) const { return (Matrix(*this) ^= p); }
};

