i64 mpow(i64 r,i64 n) {
    r%=M;
    if(!n) return 1;
    i64 res=mpow(r*r % M,n/2);
    return res * (n&1 ? r : 1) % M;
}

i64 touhi(i64 r,i64 n) {
    r%=M;
    if(!n) return 0;
    i64 ret=touhi(r,n/2)*(mpow(r,n/2)+1)%M;
    if(n&1) {
        ret=(ret+mpow(r,n-1))%M;
    }
    return ret;
}

i64 touhitousa(i64 r,i64 n) {
    r%=M;
    if(!n) return 0;
    i64 ret=touhitousa(r,n/2)*(mpow(r,n/2)+1)%M;
    ret=(n/2 % M *touhi(r,n/2) * mpow(r,n/2) % M +ret)%M;
    if(n&1) {
        ret=(ret+(n-1)*mpow(r,n-1)%M)%M;
    }
    return ret;
}

