ll modx(ll Base, ll exponent, ll m)
{
	Base %= m;
	ll ans = 1;
	if(Base == 1)
		return Base;
	while(exponent)
	{
		if(exponent & 1LL)
			ans = (ans * Base)%m;
		Base = (Base * Base)%m;
		exponent = exponent >> 1;
	}
	return ans;
}

