inline int count_digs(ll n)
{
	int ans = 0;
	while(n > 0)
	{
		ans++;
		n /= 10LL;
	}
	return ans;
}

ll binsea(ll l, ll r, ll a, ll b, int val)
{
	if(l > r)
		return 0LL;
	ll mid = (l+r)>>1LL;
	if(count_digs(a+mid*b) <= val)
		return max(mid, binsea(mid+1LL,r,a,b,val));
	return binsea(l,mid-1LL,a,b,val);
}

