void matrix_square(int n, ll MOD)// B_temp = B x B
{
	int i, j, k;
	fo(i,1,n+1)
		fo(j,1,n+1)
			B_temp[i][j] = 0LL;
	fo(i,1,n+1)
		fo(j,1,n+1)
			fo(k,1,n+1)
				B_temp[i][j] = (B_temp[i][j] + B[i][k]*B[k][j])%MOD;
	fo(i,1,n+1)
		fo(j,1,n+1)
			B[i][j] = B_temp[i][j];
	return;
}

void matrix_multi(int n, ll MOD)// A_temp = A x B
{
	int i, j;
	fo(i,1,n+1)
		A_temp[i] = 0LL;
	fo(i,1,n+1)
		fo(j,1,n+1)
			A_temp[i] = (A_temp[i] + A[j]*B[j][i])%MOD;
	fo(i,1,n+1)
		A[i] = A_temp[i];
	return;
}

void matrix_expo(ll val, int n, ll MOD)
{
	while(val > 0LL)
	{
		if(val&1LL)// Update A
			matrix_multi(n,MOD);
		matrix_square(n,MOD);// Update B
		val >>= 1;
	}
	return;
}

ll solve(ll val, int m, ll MOD)
