    for (int d = 1; d <= D; d++) {
        Matrix A = {{dec, 1, 0}, {0, 1, B % MOD}, {0, 0, 1}};
        v = mul(pow(A, c[d] - c[d - 1]), v);
        dec *= 10;
    }
    gf ans = v[0];

    return ans.n;
}

