        return modpow(phiM - 1, (R + M - 1) * (R + M - 1) % M, (A * (R + M - 1) % M * (modpow(N, R) + M - 1) + B * ((N - 1) * modpow(N + 1, R) % M + M - N * modpow(N, R) % M + R)) % M);
    };
    cout << [impl = [&M, &cal, &modpow](auto f, auto L, auto A, auto B) -> pair<unsigned long, unsigned long> {
        if(L == 1){
            return {to_string(A).size(), A % M};
        }else if(to_string(A).size() < to_string(A + (L - 1) * B).size()){
            auto a = f(f, L / 2, A, B), b = f(f, (L + 1) / 2, A + B * (L / 2), B);
