        }
        return {to_string(A).size() * L, cal(L, A, B, modpow(to_string(A).size()))};
    }](unsigned long L, unsigned long A, unsigned long B){return impl(impl, L, A, B).second;}(L, A, B) << endl;
    return 0;
}

