mint f(int x, int d){
  if (x==1) return 1;
  if (x%2==0){
    mint p = f(x/2, d);
    return (p + (pow_(pow_(10,d), (x/2))*p));
  }
  else{
    mint p = f(x-1, d);
    return (p + pow_(pow_(10, d), (x-1)));
  }
}

mint g(int x, int d){
  if (x==1) return pow_(10,d);
  mint ans = 0;
  if (x%2==0){
    int y = x/2;
    mint p = g(y, d);
    ans += p;
    ans += p * pow_(pow_(10,d),y);
    ans += f(y, d) * mint(y) * pow_(pow_(10,d),(y+1));
    return ans;
  }
  else{
    ans += g(x-1, d) + mint(x) * pow_(pow_(10,d), x);
    return ans;
  }
}

