//http://www.yamamo10.jp/yamamoto/comp/cpp/ex_class/matrix.php
class Matrix{
	int row; //行
	int column; //列
	vector<vector<long long>> p;

public:
	Matrix(int i=1, int j=1){
		if(i<1 || j<1) exit(1);
		row = i;
		column = j;
		p.resize(row+1);
		for(int k1=1; k1<=row; k1++){
			p[k1].resize(column+1);
			for(int k2=1; k2<=column; k2++)
				p[k1][k2] = 0;
		}
	}
	Matrix(const Matrix& cp){
		row = cp.row;
		column = cp.column;
		p.resize(row+1);
		for(int k1=1; k1<=row; k1++){
			p[k1].resize(column+1);
			for(int k2=1; k2<=column; k2++)
				p[k1][k2] = cp.p[k1][k2];
		}
	}

	int row_size(){ return(row); }
	int column_size(){ return(column); }

	void change_size(int i, int j){
		if(i<1 || j<1) exit(1);
		row = i;
		column = j;
		p.resize(row+1);
		for(int k1=1; k1<=row; k1++){
			p[k1].resize(column+1);
			for(int k2=1; k2<=column; k2++)
				p[k1][k2] = 0;
		}
	}

	//演算子
	vector<long long> operator[](int i){ return p[i]; }
	Matrix operator=(const Matrix& a){
		if(row != a.row || column != a.column){
			change_size(a.row, a.column);
		}

		for(int i=1; i<=row; i++){
			for(int j=1; j<=column; j++){
				p[i][j] = a.p[i][j];
			}
		}
		return(*this);
	}
	Matrix operator+(const Matrix& a){
		if(row != a.row || column != a.column) exit(0);
		Matrix r(row, column);
		for(int i=1; i<=row; i++){
			for(int j=1; j<=column; j++){
				r.p[i][j] = p[i][j] + a.p[i][j];
			}
		}
		return(r);
	}
	Matrix operator-(const Matrix& a){
		if(row != a.row || column != a.column) exit(0);
		Matrix r(row, column);
		for(int i=1; i<=row; i++){
			for(int j=1; j<=column; j++){
				r.p[i][j] = p[i][j] - a.p[i][j];
			}
		}
		return(r);
	}
	Matrix operator*(const Matrix& a){
		if(column != a.row) exit(0);
		Matrix r(row, a.column);
		for(int i=1; i<=row; i++){
			for(int j=1; j<=a.column; j++){
				for(int k=1; k<=column; k++){
					r.p[i][j] += p[i][k] * a.p[k][j];
					r.p[i][j] %= M;
				}
			}
		}
		return(r);
	}

	//定数倍
	friend Matrix operator*(const Matrix& a, double b){
		Matrix r(a.row, a.column);
		for(int i=1; i<=a.row; i++){
			for(int j=1; j<=a.column; j++){
				r[i][j] = b * a.p[i][j];
			}
		}
		return(r);
	}
	friend Matrix operator*(double b, const Matrix& a){
		Matrix r(a.row, a.column);
		for(int i=1; i<=a.row; i++){
			for(int j=1; j<=a.column; j++){
				r[i][j] = b * a.p[i][j];
			}
		}
		return(r);
	}
};

//累乗 O(log N)
long long power(long long x, int N){
	if(N == 1) return x;
	long long tmp = power(x, N/2);
	if(N%2 == 0) return tmp * tmp;
	else return tmp * tmp * x;
}

Matrix power(Matrix m, int N){
	if(N == 1) return m;
	Matrix tmp = power(m, N/2);
	if(N%2 == 0) return tmp * tmp;
	else return tmp * tmp * m;
}

LL binary_search(LL maximum){
	LL ok = -1;
	LL ng = L;
	while(ng-ok > 1){
		LL m = (ok+ng)/2;
		LL tmp = A+B*m;
		if(tmp <= maximum) ok = m;
		else ng = m;
	}
	return ok;
}

