const int sz = 3;
template<typename T>
struct Matrix {
   	array<array<T, sz>, sz> A;
	int N;

   	Matrix() : N(sz) {}
   	Matrix(int N) : N(N) {}

	inline const array<T, sz> &operator[](int k) const {return A[k];}
  	inline array<T, sz> &operator[](int k) {return A[k];}

  	static Matrix I(int N) {
    	Matrix<T> mat(N);
    	for(int i = 0; i < N; ++i) mat[i][i] = 1;
    	return mat;
  	}

  	Matrix &operator+=(const Matrix &B) {
    	for(int i = 0; i < N; ++i) {
      	    for(int j = 0; j < N; ++j) {
        	    (*this)[i][j] += B[i][j];
            }
        }
    	return (*this);
  	}

  	Matrix &operator-=(const Matrix &B) {
    	for(int i = 0; i < N; ++i) {
      		for(int j = 0; j < N; ++j) {
				(*this)[i][j] -= B[i][j];
			}
		}
    	return (*this);
  	}

    Matrix &operator*=(const Matrix &B) {
        Matrix<T> C(N);
        for(int i = 0; i < N; ++i) {
            for(int j = 0; j < N; ++j) {
                for(int k = 0; k < N; ++k) {
                    C[i][j] = (C[i][j] + (*this)[i][k] * B[k][j]);
                }
            }
        }
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                swap(A[i][j],C.A[i][j]);
            }
        }
        return *this;
    }

    Matrix &operator^=(long long k) {
        Matrix<T> B = Matrix<T>::I(N);
        while(k > 0) {
            if(k & 1) B *= *this;
            *this *= *this;
            k >>= 1LL;
        }
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                swap(A[i][j],B.A[i][j]);
            }
        }
        return *this;
    }

    Matrix operator+(const Matrix &B) const {return (Matrix(*this) += B);}
    Matrix operator-(const Matrix &B) const {return (Matrix(*this) -= B);}
    Matrix operator*(const Matrix &B) const {return (Matrix(*this) *= B);}
    Matrix operator^(const long long k) const {return (Matrix(*this) ^= k);}
};

