void make_borders(ll borders[20], ll len, ll a, ll b)
{
    rep (i, 20) borders[i] = len;
    borders[0] = 0LL;

    srep (i, 1, 19) {
        ll target = (ll)pow(10LL, i);
        ll left = 0LL;
        ll right = len - 1LL;
        ll now = (left + right) / 2LL;
        for ( ; left <= right; now = (left + right) / 2LL) {
            ll val = a + b * now;
            if (target <= val) {
                borders[i] = min(borders[i], now);
                right = now - 1LL;
            }
            else {
                left = now + 1LL;
            }
        }
    }

    debug_printf("---- borders\n"); debug_print(borders, 20);
}

void prepare_matrixes(ll m[66][3][3], ll digits, ll a, ll b, ll mod)
{
    ll matrix[3][3] = {{(ll)pow(10LL, digits) % mod, 0LL, 0LL},
        {1LL, 1LL, 0LL},
        {0LL, b % mod, 1LL}};

    memcpy(m[0], matrix, sizeof(m[0]));

    rep (i, 64) {
        rep (j, 3) {
            rep (k, 3) {
                m[i+1][j][k] = (m[i][j][0] * m[i][0][k]) % mod;
                m[i+1][j][k] += (m[i][j][1] * m[i][1][k]) % mod;
                m[i+1][j][k] += (m[i][j][2] * m[i][2][k]) % mod;
                m[i+1][j][k] %= mod;
            }
        }
    }
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll len; llin(len);
    ll a; llin(a);
    ll b; llin(b);
    ll mod; llin(mod);

    ll borders[20];
    make_borders(borders, len, a, b);

    t3 result = t3(0LL, a % mod, 1LL);

    srep (digits, 1, 19) {
        ll cnt = borders[digits] - borders[digits-1];

        static ll m[66][3][3];
        prepare_matrixes(m, digits, a, b, mod);

        rep (pos, 64) {
            if (!(cnt & (1LL<<pos))) continue;

            ll r[3];
            rep (i, 3) {
                r[i] = (get<0>(result) * m[pos][0][i]) % mod;
                r[i] += (get<1>(result) * m[pos][1][i]) % mod;
                r[i] += (get<2>(result) * m[pos][2][i]) % mod;
                r[i] %= mod;
            }

