typedef __int128 very_long;

namespace long_mul {


very_long mul(very_long a, very_long b, very_long mod) {
    if (b == 0) {
        return 0;
    }
    if (b % 2 == 0) {
        return (2 * mul(a, b / 2, mod)) % mod;
    }
    return (a + mul(a, b - 1, mod)) % mod;
}

very_long power(very_long a, very_long b, very_long mod) {
    if (b == 0) {
        return 1 % mod;
    }
    if (b % 2 == 0) {
        return power(mul(a, a, mod), b / 2, mod);
    }
    return mul(a, power(a, b - 1, mod), mod);
}

}

