int power(int a, unsigned long long b) {
    if (b == 0) {
        return 1;
    }
    if (b % 2 == 0) {
        return power(mul(a, a), b / 2);
    }
    return mul(a, power(a, b - 1));
}

int phi(int x) {
    int result = x;
    for (int i = 2; i * i <= x; ++i) {
        if (x % i == 0) {
            while (x % i == 0) {
                x /= i;
            }
            result -= result / i;
        }
    }
    if (x > 1) {
        result -= result / x;
    }
    return result;
}

