typedef vector<ll> vec;
typedef vector<vec> mat;

/*
 行列累乗
 X = A^M*B
 A ( N*N行列)

 O(N^3 logM)
 */
mat mul(mat&A,mat&B,const ll M){
    mat C(A.size(),vec(B[0].size()));
    for(int i = 0; i < (int)A.size();i++){
        for(int k = 0; k < (int)B.size();k++){
            if(A[i][k] == 0) continue;
            for(int j = 0; j < B[0].size();j++){
                C[i][j] = (C[i][j] + A[i][k]*B[k][j])%M;
            }
        }
    }
    return C;
}

mat pow(mat A,ll n,const ll M){
    mat B(A.size(),vec(A.size()));
    for(int i = 0; i < A.size();i++){
        B[i][i] = 1;
    }
    while(n > 0){
        if(n&1) B= mul(B,A,M);
        A = mul(A,A,M);
        n>>=1;
    }
    return B;
}

ll pow10(ll n){
    ll ret = 1;
    while(n--) ret *= 10;
    return ret;
}
template<class Type>
Type solve(Type res = Type()){
    ll L,A,B,M; cin >> L >> A >> B >> M;
    ll cnt[19] = {};
    ll sum = 0;
    for(ll d = 1; d < 19; d++){
        ll p10 = pow10(d) - 1;
        if(A > p10) continue;
        ll p = (p10 - A)/B;
        ll q = (p+1) - sum;
        cnt[d] = q;

        if(cnt[d] > L - sum){
            cnt[d] = L - sum;
            break;
        }
        sum += q;
    }

    mat R = {
        {0},
        {A},
        {1},
    };
    for(ll d = 1; d < 19; d++){
        mat A = {
            {pow10(d)%M,1,0},
            {0,1,B},
            {0,0,1},
        };
        mat B = pow(A,cnt[d],M);

        R = mul(B,R,M);
    }
    res = R[0][0];
    return res;
}

