// n = y[0] + c[0]*(y[1] + c[1]*(...))
void init(int n, const ll c[], ll x, ll y[]) {
	for(int i=0;i<n;i++) {
		y[i] = x % c[i];
		x /= c[i];
	}
}

void add(int n, const ll c[], const ll x[], const ll y[], ll z[]) {
	long long carry = 0; // 0 or 1
	for(int i=0;i<n;i++) {
		z[i] = x[i] + y[i] + carry;
		if(z[i] >= c[i]) {
			carry = 1;
			z[i] -= c[i];
		} else {
			carry = 0;
		}
	}
}
void sub(int n, const ll c[], const ll x[], const ll y[], ll z[]) {
	long long borrow = 0; // 0 or -1
	for(int i=0;i<n;i++) {
		z[i] = x[i] - y[i] + borrow;
		if(z[i] < 0) {
			borrow = -1;
			z[i] += c[i];
		} else {
			borrow = 0;
		}
	}
}

void mult(int n, const ll c[], const ll x[], ll a, ll y[]) {
	ll carry = 0;
	for(int i=0;i<n;i++) {
		__int128 p = carry + x[i] * (__int128)a;
		y[i] = p % c[i];
		carry = p / c[i];
	}
}

void mult(int n, const ll c[], const ll x[], const ll y[], ll z[]) {
	mult(n, c, x, y[n-1], z);
	for(int i=n-2;i>=0;i--) {
		ll tmp1[n], tmp2[n];
		mult(n, c, z, c[i], tmp1);
		mult(n, c, x, y[i], tmp2);
		add(n, c, tmp1, tmp2, z);
	}
}

void pow(int n, const ll c[], const ll x[], ll e, ll y[]) {
	init(n, c, 1, y);
	if(e == 0) return;
	int s = 63;
	while((e >> s) == 0) s--;
	for(;s>=0;s--) {
		ll tmp[n];
		mult(n, c, y, y, tmp);
		if((e >> s) & 1) {
			mult(n, c, x, tmp, y);
		} else {
			for(int i=0;i<n;i++) y[i] = tmp[i];
		}
	}
}

