int f(int n, int r) {
	if (n == 0) return 0;
	if (n % 2 == 1) {
		ll pl = n - 1;
		int x = f(pl, r);
		return ((x * r) % MOD + 1) % MOD;
	}
	else {
		ll pl = n / 2;
		int x = f(pl, r);
		return ((x * modpow(r, pl)) % MOD + x) % MOD;
	}
}
