	if (n == 0) return 0;
	if (n % 2 == 1) {
		ll pl = n - 1;
		int x = g(pl, r);
		return ((x * r) % MOD + pl) % MOD;
	}
	else {
		ll pl = n / 2;
		int x = g(pl, r);
		return ((x * modpow(r, pl)) % MOD + x + (pl * f(pl, r)) % MOD) % MOD;
	}
}

