template<typename T, int N>
struct Matrix {
    using vec = vector<T>;
    using mat = vector<vec>;
    mat dat;

    constexpr Matrix() : dat(N, vec(N, 0)) {}
    Matrix(mat dat) : dat(dat) {}

    static constexpr Matrix identity() {
        Matrix e;
        for (int i = 0; i < N; ++i)  e.dat[i][i] = 1;
        return e;
    }

    vec& operator [](int i) { return dat[i]; }
    Matrix operator +(const Matrix & a) const { return add(a); }
    Matrix operator -(const Matrix & a) const { return sub(a); }
    Matrix operator *(const Matrix & a) const { return mul(a); }

    Matrix add(const Matrix & a) const {
        Matrix y;
        for (int i = 0; i < N; ++i) for (int j = 0; j < N; ++j) {
            y.dat[i][j] = (dat[i][j] + a.dat[i][j]) % MOD;
        }
        return y;
    }
    Matrix sub(const Matrix & a) const {
        Matrix y;
        for (int i = 0; i < N; ++i) for (int j = 0; j < N; ++j) {
            y.dat[i][j] = (dat[i][j] + MOD - a.dat[i][j]) % MOD;
        }
        return y;
    }
    Matrix mul(const Matrix & a) const {
        Matrix y;
        for (int i = 0; i < N; ++i) for (int k = 0; k < N; ++k) for (int j = 0; j < N; ++j) {
            y.dat[i][j] = (y.dat[i][j] + dat[i][k] * a.dat[k][j] % MOD) % MOD;
        }
        return y;
    }
    Matrix pow(ll n) const {
        Matrix x(dat), y = identity();
        while (n > 0) {
            if (n % 2) y = x.mul(y);
            x = x.mul(x);
            n >>= 1;
        }
        return y;
    }
};

