ll extgcd(ll a, ll b, ll& x, ll& y){
  ll d = a;
  if(b != 0){
    d = extgcd(b, a%b, y, x);
    y -= (a/b) * x;
  }else{
    x = 1;
    y = 0;
  }
  return d;
}
ll mod_inverse(ll a, ll m){
  ll x, y;
  extgcd(a, m, x, y);
  return (m + x % m) % m;
}
ll mod_pow(ll x, ll n, ll mod){
  if(n==0) return 1;
  ll res = mod_pow(x * x % mod, n / 2, mod);
  if(n & 1) res = res * x % mod;
  return res;
}

int get_keta(ll x){
  int keta = 0;
  while(x>0){ keta++; x/=10; }
  return keta;
}

ll solve(ll L, ll A, ll B, ll M, ll st, ll ed, ll base){
  int keta = get_keta(A + B*st);
  ll N = ed-st+1;
  if(N==0) return 0;

  ll AA = A + B * ed;
  A = AA;

  ll c = mod_pow(10, keta, M);

  ll x = ((N-1) * mod_pow(c, N+1, M))%M;
  x -= (N * mod_pow(c, N, M))%M;
  x += M;
  x %= M;
  x += c;
  x %= M;
  x *= mod_inverse(c-1, M);
  x %= M;
  x *= mod_inverse(c-1, M);
  x %= M;

  ll y = mod_pow(c, N, M);
  y -= 1;
  y += M;
  y %= M;
  y *= mod_inverse(c-1, M);
  y %= M;

  if(c==0){
    x = 0;
    y = 1;
  }

  A %= M;
  B %= M;
  ll ret = (A * y)%M;
  ret -= (B * x)%M;
  ret += M;
  ret %= M;

  ret *= mod_pow(10, base, M);
  ret %= M;

  cerr << keta << " " << N << " " << A << " " << B << " " << c << " " << x << " " << y << " " << ret << endl;
  return ret;
}


int main(){
  ll L, A, B, M;
  cin >> L >> A >> B >> M;

  ll ret = 0;

  ll base = 0;
  for(int k=18; k>0; k--){
    ll st = -1, ed = -1;
    {
      ll lb = -1, ub = L;
      while(ub-lb>1){
        ll mid = (lb+ub)/2;

        ll s = A + B*mid;
        if(get_keta(s) < k) lb = mid;
        else ub = mid;
      }
      if(0<=ub && ub<L){
        if(get_keta(A+B*ub) == k) st = ub;
      }
    }
    {
      ll lb = -1, ub = L;
      while(ub-lb>1){
        ll mid = (lb+ub)/2;

        ll s = A + B*mid;
        if(get_keta(s) <= k) lb = mid;
        else ub = mid;
      }
      if(0<=lb && lb<L){
        if(get_keta(A+B*lb) == k) ed = lb;
      }
    }
    if(st != -1 && ed != -1){
      //cout << k << "\t" << st << "\t" << ed << "\t" << base << endl;
      ret += solve(L, A, B, M, st, ed, base);
      ret %= M;

      base += (ed-st+1)*k;
    }
  }

  cout << ret << endl;

  return 0;
}

