Matrix operator * (Matrix A, Matrix B){
	Matrix ret(A.w, B.h);
	FOR(i, 0, ret.w){
		FOR(j, 0, ret.h){
			FOR(k, 0, A.h) (ret[i][j] += (A[i][k] % m * B[k][j] % m) % m) %= m;
