int main(int argc, char *argv[]) {
  // read inputs
  long L, A, B, M;
  scanf("%ld %ld %ld %ld", &L, &A, &B, &M);

  // calculate ten_pows[k]
  //     ten_pows[k] = 10^k
  vector<long> ten_pows(19, 0);
  ten_pows[0] = 1;
  for (long k = 0; k < 18; k++) {
    ten_pows[k + 1] = 10 * ten_pows[k];
  }

  // calculate as[k]
  //     as[k] : min(min_i {i | s_i >= 10^{k-1}}, L)
  vector<long> as;
  as.push_back(0);  // let as[0] = 0
  for (long k = 1; k <= 19; k++) {
    const long ten_pow_km1 = ten_pows[k - 1];
    long le = -1, ri = L;
    while (ri - le > 1) {
      const long m = (le + ri) / 2;
      if (A + B * m >= ten_pow_km1) {
        ri = m;
      } else {
        le = m;
      }
    }
    as.push_back(ri);
    // printf("k = %ld, as[k] = %ld\n", k, as[k]);
  }

  // solve
  const long N = 3;
  vector<vector<long>> xss(N, vector<long>(N, 0)),
      x_tmpss(N, vector<long>(N, 0));
  vector<long> vs(N, 0), v_tmps(N, 0);
  // initial vs = [t_1, s_1, 1]
  vs[0] = 0;
  vs[1] = A;
  vs[2] = 1;
  for (long k = 1; k < 19; k++) {
    // input X_k
    xss[0][0] = mod(ten_pows[k], M);
    xss[0][1] = 1;
    xss[0][2] = 0;
    xss[1][0] = 0;
    xss[1][1] = 1;
    xss[1][2] = B;
    xss[2][0] = 0;
    xss[2][1] = 0;
    xss[2][2] = 1;
    // calculate (X_k)^{as[k + 1] - as[k]}
    mat_pow(xss, as[k + 1] - as[k], x_tmpss, M);
    copy_mat(x_tmpss, xss);
    // update vs
    mat_mult_vec(xss, vs, v_tmps, M);
    copy_vec(v_tmps, vs);
  }
  printf("%ld\n", vs[0]);

  return 0;
}

