    cin.tie(0), cout.tie(0);

    ll L, A, B;
    cin >> L >> A >> B >> MOD;

    vector<mn> contr(19);

    ll lb = 1, ub = 10;
    for (int dc = 1; dc <= 18; dc++) {
        if (dc > 1) { lb *= 10, ub *= 10; }
        if (A >= ub) continue;

        ll fi = max(0ll, (lb - A + B - 1) / B);
        ll li = min(L, (ub - A + B - 1) / B);

        if (fi < li) {
            mn shift = mn(10).pow(prod(li - fi, dc, MOD - 1));
            for (int pd = 1; pd < dc; pd++)
                contr[pd] *= shift;

            if (ub % MOD != 1) {
                mn aW = mn(shift - 1) / mn(ub - 1);
                contr[dc] += (mn(A) + fi * mn(B)) * aW;

                mn bW = mn(aW - 1 - (li - fi - 1)) / mn(ub - 1);
                contr[dc] += mn(B) * bW;
            } else {
                mn bW = (fi - li)&1 ? mn(fi - li) * mn((fi - li - 1) / 2)
                                    : mn((fi - li) / 2) * mn(fi - li - 1);
                contr[dc] = mn(A) * (fi - li) + mn(B) * bW;
            }
        }
    }

    mn ans = 0;
    for (mn v : contr)
        ans += v;
    cout << ans << endl;

    return 0;
}

