Matrix create(int op, int b) {
    Matrix a;
    a.data[0][0] = op%mod;
    a.data[0][1] = a.data[0][2] = 0;
    a.data[1][0] = 1;
    a.data[1][1] = 1;
    a.data[1][2] = 0;
    a.data[2][0] = 0;
    a.data[2][1] = b%mod;
    a.data[2][2] = 1;

    return a;
}

Matrix operator * (Matrix a, Matrix b) {
    Matrix c;
    for(int i = 0;i < 3;i++) {
        for(int j = 0;j < 3;j++) {
            c.data[i][j] = 0;
            for(int k = 0;k < 3;k++) {
                c.data[i][j] += (a.data[i][k]*b.data[k][j])%mod;
            }
            c.data[i][j] %= mod;
        }
    }

    return c;
}

Matrix pow(Matrix a, int n) {
    if(n == 0)
    {
        Matrix d;
        for(int i = 0;i < 3;i++) {
            for(int j = 0;j < 3;j++) {
                d.data[i][j] = 0;
            }
        }
        d.data[0][0] = d.data[1][1] = d.data[2][2] = 1;
        return d;
    }

    Matrix ret;
    ret = pow(a*a, n/2);
    if(n&1)
        ret = ret*a;

    return ret;
}

