int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  long long L, A, B;
  std::cin >> L >> A >> B >> md;
  constexpr int sz = 3;
  using vec = std::array<mint, sz>;
  using mat = std::array<vec, sz>;
  auto zr = [&] {
    return mat{};
  };
  auto id = [&] {
    mat ret{};
    for (int i = 0; i < sz; i++) {
      ret.at(i).at(i) = 1;
    }
    return ret;
  };
  auto mul = [&] (const mat& a, const mat& b) {
    auto c = zr();
    for (int i = 0; i < sz; i++) {
      for (int j = 0; j < sz; j++) {
        for (int k = 0; k < sz; k++) {
          c.at(i).at(k) += a.at(i).at(j) * b.at(j).at(k);
        }
      }
    }
    return c;
  };
  auto pow = [&] (mat a, long long b) {
    auto ret = id();
    for (; b; b /= 2) {
      if (b % 2 == 1) ret = mul(ret, a);
      a = mul(a, a);
    }
    return ret;
  };
  auto act = [&] (const mat& a, const vec& v) {
    vec ret{};
    for (int i = 0; i < sz; i++) {
      for (int j = 0; j < sz; j++) {
        ret.at(i) += a.at(i).at(j) * v.at(j);
      }
    }
    return ret;
  };
  mint ten = mint::normalize(10);
  auto solve = [&] (long long p, long long L, mint A, mint B) {
    auto C = mat{
      vec{power(ten, p), 1, 0},
      vec{0, 1, 1},
      vec{0, 0, 1}
    };
    return act(pow(C, L), vec{0, A, B}).at(0);
  };
  auto lb = [&] (long long k) {
    if (k <= A) return 0LL;
    if (k > A + (L - 1) * B) return L;
    return (k - A + B - 1) / B;
  };
  constexpr long long pmx = 18;
  mint ret = 0;
  long long lwr = 1, upr = 10;
  for (long long p = 1; p <= pmx; p++) {
    long long l = lb(lwr), r = lb(upr);
    assert(r >= l);
    ret *= power(ten, (r - l) * p);
    ret += solve(p, r - l, A + l * B, B);
    lwr *= 10, upr *= 10;
  }
  std::cout << ret << std::endl;
}

