    int sn = sz(A);
    int sm = sz(A[0]);
    assert(sz(B) == sm);
    int sl = sz(B[0]);

    vvi ret(sn, vi(sl));
    rep(y, 0, sn) {
        rep(x, 0, sl) {
            int tmp = 0;
            rep(k, 0, sm) {
                tmp += A[y][k] * B[k][x] % M;
                tmp %= M;
            }
            ret[y][x] = tmp;
        }
    }
    return ret;
