    const u64 &value() const noexcept { return a; }
    mint operator+(const mint rhs) const noexcept {return mint(*this) += rhs;}
    mint operator-(const mint rhs) const noexcept {return mint(*this) -= rhs;}
    mint operator*(const mint rhs) const noexcept {return mint(*this) *= rhs;}
    mint operator/(const mint rhs) const noexcept {return mint(*this) /= rhs;}
    mint &operator+=(const mint rhs) noexcept {a += rhs.a;if (a >= Mod) a -= Mod;return *this;}
    mint &operator++() noexcept {a += 1;if (a >= Mod) a -= Mod;return *this;}
    mint operator++(int) noexcept {mint m = *this;a += 1;if (a >= Mod) a -= Mod;return m;}
    mint &operator-=(const mint rhs) noexcept {if (a < rhs.a) a += Mod;a -= rhs.a;return *this;}
    mint &operator--() noexcept {if (a < 0) a += Mod;a -= 1;return *this;}
    mint operator--(int) noexcept {mint m = *this;if (a < 0) a += Mod;a -= 1;return m;}
    mint &operator*=(const mint rhs) noexcept {a = a * rhs.a % Mod;return *this;}
    mint &operator/=(mint rhs) noexcept {u64 exp = Mod - 2;while(exp) {if(exp % 2) {*this *= rhs;}rhs *= rhs;exp /= 2;}return *this;}
    operator long long() const {return a;}
    friend ostream& operator<< (ostream& os, const mint &m) {os << m.a;return os;};
    friend istream& operator>> (istream& is, mint &m) {long long l;is >> l;m.set(l);return is;};
};

// 正方行列
template <size_t N,typename R>
class SqMatrix {
public:
    using arr = array<R, N>;
    using mat = array<arr, N>;
    mat dat;
    SqMatrix() {
        rep(i, N) rep(j, N) dat[i][j] = R::add_identity();
    }
    SqMatrix& operator=(const SqMatrix& a) {
        dat = a.dat;
        return (*this);
    }
    bool operator==(const SqMatrix& a) {
        return dat == a.dat;
    }
    static SqMatrix add_id() {
        return SqMatrix();
    }
    static SqMatrix mul_id() {
        SqMatrix res;
        rep(i, N) res[i][i] = R::mul_identity();
        return res;
    }
    size_t size() const {return (N);}
    arr& operator[](size_t k) {return dat[k];}
    const arr& operator[](size_t k) const {return dat[k];}
    SqMatrix operator*(const SqMatrix& a) {
        SqMatrix res;
        rep(i, N) rep(j, N) rep(k, N) res[i][j] = res[i][j] + (dat[i][k] * a[k][j]);
        return res;
    }
    SqMatrix operator+(const SqMatrix& a) {
        SqMatrix res;
        rep(i, N) rep(j, N) res[i][j] = dat[i][j] + a[i][j];
        return res;
    }
    SqMatrix pow(ll n) {
        SqMatrix a=*this, res = mul_id();
        while(n) {
            if(n & 1) res = res * a;
            a = a * a;
            n >>= 1;
        }
        return res;
    }
    friend ostream& operator<< (ostream& os, const SqMatrix &m) {
        rep(i, N) {
            rep(j, N) {
                os << m.dat[i][j] << " ";
            }
            if (i != N - 1) os << endl;
        }
        return os;
    }
};

