template <typename T>
matrix<T> dot(matrix<T>& lhs, matrix<T>& rhs) {
  const size_t n1 = lhs.size();
  const size_t n2 = lhs[0].size();
  const size_t n3 = rhs[0].size();
  matrix<T> ans(n1, vector<T>(n3, 0));
  range(i, 0, n1, 1) {
    range(j, 0, n2, 1) {
      range(k, 0, n3, 1) {
        ans[i][k] = (ans[i][k] + (lhs[i][j] * rhs[j][k] % mod)) % mod;
      }
    }
  }
  return ans;
}

template <typename X, typename N>
X pow(X x, N n) {
  if (n == 0) return 1;
  if (n == 1) return x;
  X y = pow(x, n / 2);
  X ans = y * y % mod;
  if (n % 2 == 0)
    return ans;
  else
    return ans * x % mod;
}

template <typename N>
matrix<ll> mat_pow(matrix<ll> x, N n) {
  if (n == 0) return diag<ll>(x.size(), 1);
  if (n == 1) return x;
  matrix<ll> y = mat_pow(x, n / 2);
  matrix<ll> ans = dot(y, y);
  if (n % 2 == 0)
    return ans;
  else
    return dot(ans, x);
}

