  matrix(const matrix &M_){
    H=M_.H;
    W=M_.W;
    num.resize(H+5);
    for(int i=0;i<H+5;i++) num[i].resize(W+5,0);
    for(int i=1;i<=H;i++){
      for(int j=1;j<=W;j++) num[i][j]=M_.num[i][j];
    }
  }
  void set_val(ll x,ll y,ll v){
    if(x<=0||x>H||y<=0||y>W) return;
    num[x][y]=v;
  }
  matrix operator +(const matrix &M_){
    matrix res=matrix(H,W);
    if(H!=M_.H||W!=M_.W) return res;
    for(int i=1;i<=H;i++){
      for(int j=1;j<=W;j++){
        res.num[i][j]=num[i][j]+M_.num[i][j];
        res.num[i][j]%=mod;
      }
    }
    return res;
  }
  matrix operator -(const matrix& M_){
    ll x1=H,y1=W,x2=M_.H,y2=M_.W;
    matrix res(x1,y1);
    if(x1!=x2||y1!=y2) return res;
    for(int i=1;i<=x1;i++){
      for(int j=1;j<=y1;j++){
        res.num[i][j]=(num[i][j]-M_.num[i][j])%mod;
        res.num[i][j]+=mod;
        res.num[i][j]%=mod;
      }
    }
    return res;
  }
  matrix operator *(const matrix& M_){
    ll x1=H,y1=W,x2=M_.H,y2=M_.W;
    matrix res(x1,y2);
    if(y1!=x2) return res;
    for(int i=1;i<=x1;i++){
      for(int j=1;j<=y2;j++){
        for(int k=1;k<=y1;k++){
          res.num[i][j]+=num[i][k]*M_.num[k][j];
          res.num[i][j]%=mod;
        }
      }
    }
    return res;
  }
  void operator =(const matrix &M_){
    H=M_.H;
    W=M_.W;
    num.resize(H+5);
    for(int i=0;i<H+5;i++) num[i].resize(W+5,0);
    for(int i=1;i<=H;i++){
      for(int j=1;j<=W;j++) num[i][j]=M_.num[i][j];
    }
  }
  void print(){
    for(int i=1;i<=H;i++){
      for(int j=1;j<=W;j++) cout<<num[i][j]<<" ";
      cout<<endl;
    }
  }
};
matrix pow(matrix m,ll y){
  if(y==0){
    matrix e=m;
    for(int i=1;i<=e.H;i++){
      for(int j=1;j<=e.W;j++){
        if(i==j) e.set_val(i,j,1);
        else e.set_val(i,j,0);
      }
    }
    return e;
  }
  matrix res=pow(m,y/2);
  res=res*res;
  if(y%2==1) res=res*m;
  return res;
}
int main(){
  ll l,a,b;
  cin>>l>>a>>b>>mod;
  matrix ans(1,3);
  ans.set_val(1,1,0);
  ans.set_val(1,2,a);
  ans.set_val(1,3,1);
  ll past=-1;
  for(int d=1;d<=18;d++){
    matrix mt(3,3);
    ll tens=1;
    for(int i=0;i<d;i++) tens*=10;

    mt.set_val(1,1,tens%mod);
    mt.set_val(2,1,1);
    mt.set_val(2,2,1);
    mt.set_val(3,2,b);
    mt.set_val(3,3,1);

    ll lb=-1,rb=l;
    while(rb-lb>1){
      ll mid=(lb+rb)/2;
      if(a+mid*b<tens) lb=mid;
      else rb=mid;
    }
    ans=ans*pow(mt,lb-past);
    past=lb;
  }
  cout<<ans.num[1][1]<<endl;
}

// 解き直し.
// ABC 129解説.
