class Fp {
public:
	ll val;

private:
	inline void calc_mod(ll& v) {
		if (v >= mod)v -= mod;
	}
public:
	Fp() {}
	Fp(ll v) :val(v% mod) {
		if (val < 0)val += mod;
	}

	Fp operator+=(const Fp& in) {
		val += in.val;
		calc_mod(val);
		return *this;
	}

	Fp operator+(const Fp& in) const {
		return Fp(*this) += in;
	}

	Fp& operator-=(const Fp& in) {
		val -= in.val;
		calc_mod(val);
		if (val < 0)val += mod;
		return *this;
	}

	Fp operator-(const Fp& in) const {
		return Fp(*this) -= in;
	}

	Fp& operator*=(const Fp& in) {
		val = val * in.val % mod;
		return *this;
	}

	Fp operator*(const Fp& in) const {
		return Fp(*this) *= in;
	}

	Fp& operator/=(const Fp& in) {
		*this *= modpow(in, mod - 2);
		return *this;
	}

	Fp operator/(const Fp& in) const {
		return Fp(*this) /= in;
	}

	bool operator==(const Fp& in)const {
		return val == in.val;
	}

	bool operator!=(const Fp& in)const {
		return val != in.val;
	}

	friend Fp modpow(const Fp& in, ll n) {
		if (n == 0)return 1;
		if (n & 1) {
			return in * modpow(in * in, n / 2);
		}
		else {
			return modpow(in * in, n / 2);
		}
	}
};
using modll = Fp;

class Factorial {
public:
	vector<modll> fact, finv;
	Factorial(ll n) :fact(n + 1, modll(1)), finv(n + 1, modll(1)) {
		for (int i = 2; i <= n; i++) {
			modll tmp(i);
			fact[i] = fact[i - 1] * tmp;
			finv[i] = finv[i - 1] / tmp;
		}
	}

	modll com(const ll& n, const ll& k) {
		if (n < k || n < 0 || k < 0)return modll(0);
		return fact[n] * finv[k] * finv[n - k];
	}
};

ll getdigit(ll n) {
	ll res = 0;
	while (n > 0) {
		n /= 10;
		res++;
	}
	return res;
}

ll intpow(const int& a, const int& n) {
	if (n == 0)return 1;
	else if (n & 1)return intpow(a * a, n / 2) * a;
	else return intpow(a * a, n / 2);
}

long long modinv(long long a, long long m) {
	long long b = m, u = 1, v = 0;
	while (b) {
		long long t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= m;
	if (u < 0) u += m;
	return u;
}

