vvi mult(vvi A, vvi B, ll mod) {
  ll n = A.size();
  vvi C(n, vi(n));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      for (int k = 0; k < n; k++) {
        C[i][j] += A[i][k] * B[k][j];
        C[i][j] %= mod;
      }
    }
  }
  return C;
}

vvi pow(vvi A, ll x, ll mod) {
  vvi tmp = A;
  vvi ans = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
  while(x) {
    if (x % 2) {
      ans = mult(ans, tmp, mod);
    }
    tmp = mult(tmp, tmp, mod);
    x /= 2;
  }
  return ans;
}

