ll el(ll l ,ll r ,ll m) {
	if (l == 0)
		return 0;


	if (l % 2 == 0) {
		ll ol = l / 2;
		ll rl = getpow(r, ol, m);
		return (((1 + rl) % m) * el(ol, r, m)) % m;
	}
	else {
		ll ol = l - 1;
		ll rl = getpow(r, ol, m);
		return (el(ol, r, m) + rl) % m;
	}
}
ll dl(ll l,ll r,ll ab, ll b,ll m) {
	if (l == 0)
		return 0;

	if (l % 2 == 0) {
		ll ol = l / 2;
		ll rl = getpow(r, ol, m);
		ll bl = (b * ol) % m;
		return (((((rl + 1) % m) * dl(ol, r, ab, b, m)) % m) + (bl * el(ol, r, m)) % m) % m;
	}
	else {
		ll ol = l - 1;
		ll bl = (b * ol) % m;
		return (((r * dl(ol, r, ab, b, m)) % m) + ((ab + bl) % m)) % m;
	}


}
void solv() {

	ll L, a, b, m;
	cin >> L >> a >> b >> m;

	ll ab = a;
	ll bef = 0;
	ll res = 0;
	for (ll i = 0; i < 18; i++)
	{
		ll t = pow(10, i + 1);
		if (a > t)
			continue;
		ll hi = L;
		ll lo = 0;
		while (lo + 1 < hi)
		{
			ll mid = (hi + lo) / 2;
			ll v = a + b * mid;
			if (v >= t) {
				hi = mid;
			}
			else {
				lo = mid;
			}
		}

		ll l = hi - bef;
		ll r = t % m;
		(res *= getpow(r, l, m)) %= m;
		(res += dl(l, r, ab, b,m)) %= m;
		(ab += b * l) %= m;
		bef = hi;
	}
	cout << res << endl;
}


