struct Matrix {
	ll m;//size of matrix
	vector<ll> dp;
	vector<vector<ll>> mt;

	//constructor
	Matrix(ll x) :dp(x), mt(x, vector<ll>(x, 0)) { m = x; }

	vector<ll> matmul() {
		vector<ll> ret(m, 0);
		REP(i, m)REP(j, m) {
			ret[i] += mt[i][j] * dp[j] % MOD;
			ret[i] %= MOD;
		}
		return ret;
	}
	void update() {
		vector<vector<ll>> ret(m, vector<ll>(m, 0));
		REP(i, m)REP(j, m)REP(k, m) {
			ret[i][j] += mt[i][k] * mt[k][j] % MOD;
			ret[i][j] %= MOD;
		}
		mt = ret;
	}
	void matpow(ll k) {
		while (k) {
			if (k & 1)dp = matmul();
			update();
			k /= 2;
		}
	}
};

