M3 operator*(const M3 &a, const M3 &b){
    return M3(
        (a.x1*b.x1 % MOD + a.x2*b.y1 % MOD + a.x3*b.z1 % MOD) % MOD,
        (a.x1*b.x2 % MOD + a.x2*b.y2 % MOD + a.x3*b.z2 % MOD) % MOD,
        (a.x1*b.x3 % MOD + a.x2*b.y3 % MOD + a.x3*b.z3 % MOD) % MOD,
        (a.y1*b.x1 % MOD + a.y2*b.y1 % MOD + a.y3*b.z1 % MOD) % MOD,
        (a.y1*b.x2 % MOD + a.y2*b.y2 % MOD + a.y3*b.z2 % MOD) % MOD,
        (a.y1*b.x3 % MOD + a.y2*b.y3 % MOD + a.y3*b.z3 % MOD) % MOD,
        (a.z1*b.x1 % MOD + a.z2*b.y1 % MOD + a.z3*b.z1 % MOD) % MOD,
        (a.z1*b.x2 % MOD + a.z2*b.y2 % MOD + a.z3*b.z2 % MOD) % MOD,
        (a.z1*b.x3 % MOD + a.z2*b.y3 % MOD + a.z3*b.z3 % MOD) % MOD
    );
}

M3 operator^(const M3 &a, ll n){
    if(n == 0) return M3(1, 0, 0, 0, 1, 0, 0, 0, 1);
    M3 m = a ^ (n/2);
    if(n % 2 == 0) return m * m;
    return m * m * a;
}

