{
	scanf("%lld%lld%lld%lld", &L, &A, &B, &mod);
	std::vector<int64_t> digit(19, -1);
	int64_t ten_pow{1};
	for (int i{1}; i <= 18; i++)
	{
		ten_pow *= 10;
		if (A >= ten_pow) continue;
		digit[i] = (ten_pow - 1 - A) / B;
		if (digit[i] >= L - 1)
		{
			digit[i] = L - 1;
			break;
		}
	}

	A %= mod;
	B %= mod;
	std::vector<int64_t> sum(19);
	ten_pow = 1;
	for (int i{1}; digit[i - 1] != L - 1; i++)
	{
		ten_pow = ten_pow * 10 % mod;
		if (digit[i] < 0 || digit[i] == digit[i - 1]) continue;
		int64_t num{digit[i] - digit[i - 1]};

		Matrix<> aMat(2, 2);
		aMat[0][0] = ten_pow;
		aMat[0][1] = aMat[1][1] = 1;
		std::vector<int64_t> beginA(2, 1);
		sum[i] = ((aMat ^ (num - 1)) * beginA)[0] * ((A + (digit[i - 1] + 1) % mod * B % mod) % mod) % mod;

		Matrix<> bMat(4, 4);
		bMat[0][0] = ten_pow;
		bMat[0][1] = bMat[1][1] = bMat[2][0] = bMat[3][1] = bMat[2][2] = bMat[3][3] = 1;
		Matrix<> beginB(4, 2);
		beginB[0][0] = beginB[1][1] = 1;
		sum[i] = (sum[i] + B % mod * ((bMat ^ (num - 1)) * beginB * beginA)[2] % mod) % mod;
	}
	std::vector<int64_t> shift(19, 1);
	for (int i{17}; i > 0; i--)
	{
		if (digit[i + 1] < 0) continue;
		int64_t tmp{1};
		ten_pow = 10;
		for (int64_t j{(digit[i + 1] - digit[i]) * (i + 1)}; j > 0; j >>= 1, ten_pow = ten_pow * ten_pow % mod)
			if (j & 1)
				tmp = tmp * ten_pow % mod;
		shift[i] = shift[i + 1] * tmp % mod;
		sum[i] = sum[i] * shift[i] % mod;
	}
	int64_t ans{};
	for (int i{1}; i <= 18; i++)
	{
		if (digit[i] < 0) continue;
		ans = (ans + sum[i]) % mod;
	}
	printf("%lld\n", ans);

	return 0;
}

