class modint {
public:
  long long value;
  //+
	modint operator + (modint mtmp) {
    modint mdnt;
    mdnt.value=(this->value+mtmp.value)%MOD;
    return mdnt;
	}
	modint operator + (long long ltmp) {
    modint mdnt;
    mdnt.value=(this->value+ltmp)%MOD;
    return mdnt;
	}
  //-
	modint operator - (modint mtmp) {
    modint mdnt;
    mdnt.value=(this->value-mtmp.value+MOD)%MOD;
    return mdnt;
	}
	modint operator - (long long ltmp) {
    modint mdnt;
    mdnt.value=(this->value-ltmp+MOD)%MOD;
    return mdnt;
	}
  //*
	modint operator * (modint mtmp) {
    modint mdnt;
    mdnt.value=(this->value*mtmp.value)%MOD;
    return mdnt;
	}
	modint operator * (long long ltmp) {
    modint mdnt;
    long long ltmpm=ltmp%MOD;
    if (ltmpm<0)ltmpm+=MOD;
    mdnt.value=(this->value*ltmp)%MOD;
    return mdnt;
	}
  ///
	modint operator / (long long ltmp) {
    modint mdnt;
    long long ltmpm=ltmp%MOD;
    if (ltmpm<0)ltmpm+=MOD;
    long long mdnv=this->value;

    ll x0=MOD,x1=ltmpm,x2,n0=0LL,n1=1LL,n2,t=mdnv%ltmpm,m,ans;
    if (t==0){
      mdnt.value=mdnv/ltmpm;
      return mdnt;
    } 
      for(int i=0;i<900;i++){
        m=x0/x1;
        x2=x0-x1*m;
        n2=(n0-m*n1)%MOD;
        if (x2==1){
          ans=(n2+MOD)%MOD;
          break;
        }
        x0=x1;x1=x2;
        n0=n1;n1=n2;
      }

    mdnt.value=(mdnv+((t*ans)%MOD)*ltmpm-t)/ltmpm;
    return mdnt;
  }

	modint operator / (modint mtmp) {
    modint mdnt;
    mdnt.value=this->value;
    return mdnt/mtmp.value;
	}

  //代入演算子のオーバーロード
  modint &operator = (const modint mtmp) 
  {
      this->value = mtmp.value%MOD;
      return *this;
  }
  modint &operator = (const long long ltmp) 
  {
      this->value = ltmp%MOD;
      return *this;
  }

  //exp関数
  //aのn乗 mod c
  modint exp(long long n){
    long long ans=1LL,aa=this->value,beki=n;
    for(int i=0;i<64;i++){
      if (beki%2==1) ans=ans*aa%MOD;
      aa=aa*aa%MOD;
      beki/=2;
      if (beki==0)break;
    }
    modint mdnt;
    mdnt.value=ans;
    return mdnt;
  }
  //friend ostream& operator << (ostream& os, const modint& m);
};


