struct ban
{
    vector<int> v;
    ban(){}
    ban(long long x)
    {
        while (x)
        {
            v.push_back(x % 10);
            x /= 10;
        }
        reverse(v.begin(), v.end());
    }
};
ban operator+(const ban& a, const ban& b)
{
    vector<int> aa = a.v;
    vector<int> bb = b.v;
    reverse(aa.begin(), aa.end());
    reverse(bb.begin(), bb.end());
    while (aa.size() < bb.size())
        aa.push_back(0);
    while (bb.size() < aa.size())
        bb.push_back(0);
    ban res;
    int m = 0;
    for (int i = 0; i < aa.size(); ++i)
    {
        res.v.push_back((aa[i] + bb[i] + m) % 10);
        m = (aa[i] + bb[i] + m) / 10;
    }
    res.v.push_back(m);
    while (res.v.back() == 0)
        res.v.pop_back();
    reverse(res.v.begin(), res.v.end());
    return res;
}
ban operator*(const ban& a, const ban& b)
{
    ban res;
    for (int i = 0; i < a.v.size(); ++i)
    {
        ban c;
        for (int j = 0; j < a.v[i]; ++j)
            c = c + b;
        for (int j = 0; j < a.v.size() - i - 1; ++j)
            c.v.push_back(0);
        res = res + c;
    }
    return res;
}

