Vi mul(const VVi &a, const Vi &b, ll m){
  ll x = a.size(), y = a[0].size(), y1 = b.size();
  assert(y == y1);
  Vi c(x, 0);
  REP(i, x) REP(j, y){
    c[i] += (a[i][j] % m) * (b[j] % m) % m; c[i] %= m;
  }
  return c;
}
VVi mul(const VVi &a, const VVi &b, ll m){
  //a * b 要素はmで割ったあまり
  ll x = a.size(), y1 = a[0].size(), y2 = b.size(), z = b[0].size();
  assert(y1 == y2);
  ll y = y1;
  VVi c(x, Vi(z, 0));
  REP(i, x) REP(j, z) REP(k, y){
    c[i][j] += (a[i][k] % m) * (b[k][j] % m) % m; c[i][j] %= m;
  }
  return c;
}
VVi pow(const VVi &a, ll n, ll m){
  if(n == 0) {
    ll x = a.size();
    VVi I(x, Vi(x, 0));
    REP(i, x) I[i][i] = 1;
    return I;
  }
  if(n % 2 == 0) return mul(pow(a, n/2, m), pow(a, n / 2, m), m);
  else return mul(pow(a, n - 1, m), a, m);
}

