			}
			z ^= 1;
		};
		for (int k = c[e + 1] - c[e];;) {
			if (k & 1) f(y);
			k >>= 1;
			if (!k) break;
			f(x);
		}
		S = (S*A[y][0][0] + T * A[y][0][1] + A[y][0][2]) % M;
		(T += A[y][1][2]) %= M;
	}
	cout << S << endl;
	return 0;
}

