ll ub(ll x){
  // uppber_bound
  ll left,right,middle;
  if(A>=x) return 0;
  left = 0;
  right = L;
  while(abs(left-right)>1){
    middle = (left+right)/2LL;
    ll y = A+B*middle;
    if(y>=x) right = middle;
    else left = middle;
  }
  return right;
}

