struct mint {
    ll x;

    mint(ll x = 0) : x(x % mod) {}

    mint &operator+=(const mint a) {
        (x += a.x) %= mod;
        return *this;
    }

    mint &operator-=(const mint a) {
        (x += mod - a.x) %= mod;
        return *this;
    }

    mint &operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }
};

ll b, ten;

mint pow_(mint x, ll t) {
    if (t == 0) return 1;
    if (t % 2 == 1) {
        return pow_(x, t - 1) * x;
    } else {
        mint y = pow_(x, t / 2);
        return y * y;
    }
}

mint f(ll l) {
    if (l == 0) return 0;
    if (l % 2 == 1) {
        ll pl = l - 1;
        mint x = f(pl);
        return x * ten + 1;
    } else {
        ll pl = l / 2;
        mint x = f(pl);
        return x * pow_(ten, pl) + x;
    }
}

mint g(ll l) {
    if (l == 0) return 0;
    if (l % 2 == 1) {
        ll pl = l - 1;
        mint x = g(pl);
        return x * ten + mint(b) * pl;
    } else {
        ll pl = l / 2;
        mint x = g(pl);
        return x * pow_(ten, pl) + x + mint(b) * pl * f(pl);
    }
}


