long long modpow(int n, int r)
{
    long long ret = 1;
    long long tmp = (long long)n;
    while (r != 0)
    {
        if (r % 2)
            ret *= tmp;
        tmp *= tmp;
        tmp %= mod;
        ret %= mod;
        r /= 2;
    }
    return ret;
}

