		REP(i, 18)
		{
			index.push_back(upper(l, L, A, B, t));
			t *= 10;
		}
	}
	index.push_back(L);

	A %= MOD;
	B %= MOD;


	llong ans = 0;
	REP(i, index.size() - 1)
	{
		llong k = i + 1;
		llong n = (index[i + 1] - index[i]);
		if (n == 0) { continue; }
		llong a = (A + B * index[i]) % MOD;

		X x{ k, a, B, MOD };
		ans = ans * modPow(10, n * k, MOD);
		ans %= MOD;

