	matrix2d pow(ll b){//(この行列)^bを求める
		assert(row==col);
		if(b==0){
			//return I
			matrix2d<T> id(row,col,0);
			for(ll i1=0;i1<row;i1++){
				id(i1,i1)=1;
			}
			return id;
		}else{
			matrix2d<T> temp = pow(b/2);
			temp = temp.dot(temp);
			if(b%2==1){
				temp=temp.dot(*this);
			}
			return temp;
		}
	}
	matrix2d powmod(ll b,ll m){//(この行列)^b mod mを求める
		assert(row==col);
		if(b==0){
			//return I
			matrix2d<T> id(row,col,0);
			for(ll i1=0;i1<row;i1++){
				id(i1,i1)=1;
			}
			return id;
		}else{
			matrix2d<T> temp = powmod(b/2,m);
			temp = temp .dot(temp);
			temp%=m;
			if(b%2==1){
				temp=temp.dot(*this);
				temp%=m;
			}
			return temp;
		}
	}


	const T& operator()(ll row,ll col) const{
