  MInt operator-(const MInt &r) const { MInt result = *this; result -= r; return result; }
  MInt operator*(const MInt &r) const { MInt result = *this; result *= r; return result; }
  MInt operator/(const MInt &r) const { MInt result = *this; result /= r; return result; }
  MInt pow(ll p) const {
    MInt result = 1, x = *this;
    for (;p;p >>= 1) {
      if (p & 1) result *= x;
      x *= x;
    }
    return result;
  }
  MInt inv() const { return this->pow(MOD - 2); }
