int get_len(long long x) {
    int res = 0;
    while (x) {
        ++res;
        x /= 10;
    }
    return res;
}

int geom(long long to, int p) {
    return mul(power(p, to) + mod - 1, inv(p + mod - 1));
}

int calc(int len, long long to, long long x) {
    int p = power(10, len);
    x %= mod;
    int y = (-b % mod + mod) % mod;

    //cout << x << " " << y << " " << p << endl;
    int res = mul(x, geom(to + 1, p));
    int add = mul(to, power(p, to + 1));
    add += 1 + mod - mul(to + 1, power(p, to));
    add %= mod;
    add = mul(add, p);
    add = mul(add, inv(mul(p + mod - 1, p + mod - 1)));

    res += mul(add, y);
    res %= mod;
    //cout << res << endl;
    return res;
}

