ll Keta(ll a, ll b = 10){
	static unordered_map<ll, vll> p;
	vll &L = p[b];
	if (L.empty()){
		L.push_back(0);
		L.push_back(1);
		for (ll n=1; n<=LLONG_MAX/b; n*=b) L.push_back(n*b);
	}
	for (ll o=(ll)L.size(), x=0; ; ) {
		ll m = (o+x)/2;
		if (a < L[m]) o=m; else x=m;
		if (o-x == 1) return x;
	}
}


mll Step(ll k, ll num){
	mll sum = 0;
	mll base = 1;
	ll bk = 1;
	for (ll i=0; num>0; i++, num>>=1){
		if (i > 0){
			base = base * POW(POW(mll(10), bk), k) + base;
			bk<<=1;
		}
		if (num&1){
			sum = sum * POW(POW(mll(10), bk), k) + base;
		}
	}
	return sum;
}

mll Stair(ll k, ll num){
	mll sum = 0;
	ll sumk = 0;
	mll base = 0;
	ll bk = 1;
	for (ll i=0; num>0; i++, num>>=1){
		if (i > 0){
			base = base * POW(POW(mll(10), bk), k) + base + Step(k, bk)*bk;
			bk <<= 1;
		}
		if (num&1){
			sum = sum * POW(POW(mll(10), bk), k) + base + (Step(k, bk) * sumk);
			sumk += bk;
		}
	}
	return sum;
}


void solve()
{
	ll L, A, B, M;
	cin >> L >> A >> B >> M;
	mll::MOD = M;

	ll kMin = Keta(A);
	ll kMax = Keta(A+B*(L-1));
	vll si(kMax+1);
	vll ni(kMax+1);
	si[kMin] = 0;
	REPS(k, kMin+1, kMax){
		si[k] = CEIL((POW(10, k-1) - A), B);
	}
	REPS(k, kMin, kMax-1){
		ni[k] = si[k+1] - si[k];
	}
	ni[kMax] = L - si[kMax];

	mll sum = 0;
	REPS(k, kMin, kMax){
		mll stair = Stair(k, ni[k]);
		mll step  = Step (k, ni[k]);
		sum = sum * POW(POW(mll(10), k), ni[k]) + stair*B + step*(A+B*si[k]);
	}
	cout << sum << '\n';
}

int main(){
	solve();
	return 0;
}

