matrix operator+(matrix&a, matrix&b){
    if(a.N != b.N || a.M != b.M)exit(1);
    matrix res(a.N, a.M);
    REP(i, res.N){
        REP(j, res.M){
            res[i][j]=(a[i][j] + b[i][j])%M;
        }
    }
    return res;
}

matrix operator-(matrix&a, matrix&b){
    if(a.N != b.N || a.M != b.M)exit(1);
    matrix bb = b;
    REP(i, bb.N)
        REP(j, bb.M)bb[i][j]=-b[i][j];
    return a + bb;
}

matrix operator*(matrix&a, matrix&b){
    if(a.M!=b.N)exit(1);
    matrix res(a.N, b.M);
    REP(i, res.N)
        REP(j, res.M){
            REP(k, a.M){
                a[i][k] %= M;
                b[k][j] %= M;
                res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % M;
            }
        }
    return res;
}

