template <typename X, typename N>
X pow(X x, N n) {
  if (n == 0) return 1;
  if (n == 1) return x;
  X y = pow(x, n / 2);
  X ans = y * y;
  if (n % 2 == 0)
    return ans;
  else
    return ans * x;
}

template <typename N>
matrix<ll> mat_pow(matrix<ll> x, N n) {
  if (n == 0) return diag<ll>(x.size(), 1);
  if (n == 1) return x;
  matrix<ll> y = mat_pow(x, n / 2);
  matrix<ll> ans = dot(y, y);
  if (n % 2 == 0)
