	ll t = fe(a, us/2);
	return (us&1)?(t*t%mod)*a%mod : t*t%mod;
}

ll duzver(ll son, ll k){
	if(son == 0)
		return 0;
	if(son == 1)
		return fe(10, k);
	ll ort = son/2;
	ll t = duzver(ort, k);
	ll don = (t + fe(10, ort*k%mod)*t%mod)%mod;
	if(son%2 == 0)
		return don;
	return (don + fe(10, son*k%mod))%mod;
}

ll ver(ll son, ll k){
	if(son == 0)
		return 0;
	if(son == 1)
		return fe(10, k);
	ll ort = son/2;
	ll t = ver(son/2, k);
	ll don = (t + fe(10, ort*k%mod)*(  (t + ort * duzver(ort, k)%mod )%mod  )%mod )%mod;
	if(son % 2 == 0)
		return don;
	return (don + son * fe(10, son*k%mod) % mod )%mod;

}

