{
    _LL l, a, b, m;
    cin >> l >> a >> b >> m;
    ModInt::_BM = m;
    _LL index[64]; // 桁の変わり目

    _LL keta = 0;
    _LL keta10 = 1;
    while( keta10 < a )
    {
        index[keta++] = 0;
        keta10 *= 10;
    }

    _LL s = a;
    _LL i = 0;
    while( i < l )
    {
        s = a + b * i;
        while( keta < 18 && keta10 * 10 - s < b )
        {
            index[keta++] = i;
            keta10 *= 10;
        }
        _LL lk = (keta10 - 1 - s) / b + 1;

        index[keta++] = i;
        keta10 *= 10;
        i += lk;
    }
    index[keta] = l;

    ModInt ans = 0;
    ModInt ketacalc = 1;
    for( int k = keta - 1; k >= 0; k-- )
    {
        keta10 = 1;
        for( int i = 0; i < k; i++ ) keta10 *= 10;

        _LL sl = (a + b * (index[k + 1] - 1));
        _LL n = index[k + 1] - index[k];
        if( n == 0 ) continue;
        ModInt tmp = 1;
        tmp *= ModInt::modpow(keta10, n);
        tmp -= 1;
        tmp *= (int)ModInt::reciprocal(keta10 - 1);
        tmp *= sl;

        ModInt btmp = (int)(b % m);
//        ModInt b2 = n * keta10 - n - keta10;
        ModInt b2 = n;
        b2 *= (keta10 - 1);
        b2 -= keta10;
