        btmp *= (int)ModInt::reciprocal(keta10 - 1);
        btmp *= (int)ModInt::reciprocal(keta10 - 1);
        tmp -= btmp;
        tmp *= ketacalc;
        ans += tmp;

        ketacalc *= ModInt::modpow(keta10, n);
    }

    cout << ans.getint();
}

