Mat mfp(Mat x, LL n)
{
    Mat res;
    res.M = x.M;
    for(int i = 0; i < 3; i++) res.a[i][i] = 1;

    while(n)
    {
        if(n & 1) res = res * x;
        n >>= 1;
        x = x * x;
    }
    return res;
}

