// 从数列第 st 项开始，查找区间 [L, R]，使得区间内的所有数都小于 bit 大于等于 bit/10。 
// 有返回 true 没有返回 false 
LL st = 0, bit = 10, l, r;
bool getLR() {
	if(st >= L || A + st * B >= bit) return false;
	l = st;
	r = L - 1;

	while(l < r) {
		LL mid = (l + r) >> 1;
		if(A + mid * B < bit) l = mid + 1;
		else r = mid;
	}

	if(A + r * B >= bit) --r;
	l = st;
	st = r + 1; // 下一个起始位置 
	return true;
}

