int ndig(ll n) {
    int ans = 0;
    while(n > 0) {
        n /= 10;
        ans++;
    }
    return ans;
}
modint solve(int digits, ll A, ll B, ll L, ll term) {
    sqmat<modint, 3> m = {{
        {10_m ^ digits, 1, 1},
        {0, 1, 1},
        {0, 0, 1}
    }};
    return ((m ^ term) | array<modint, 3>{A + B * L, A + B * L, B})[0];
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    ll n, A, B;
    cin >> n >> A >> B >> M;
    modint ans = 0, offset = 1;
    for(int digits = ndig(A + B * (n - 1)); digits >= ndig(A); digits--) {
        ll L = bsearch<ll>(-1, n - 1, [&](ll k) { return (k != 0 and B >= (lim<ll>::max() - A) / k) or ndig(A + B * k) >= digits; }, false);
        ll R = bsearch<ll>(0, n, [&](ll k) { return not (k != 0 and B >= (lim<ll>::max() - A) / k) and ndig(A + B * k) <= digits; });
        if(L <= R) {
            ll nterms = R - L + 1;
            ans += solve(digits, A, B, L, nterms - 1) * offset;
            offset *= 10_m ^ (digits * nterms);
        }
    }
    cout << ans << endl;
    return 0;
}

