long long M;
ll L,A,B;

ll powmod(ll a,ll k) {
  ll r = 1;
  while (k) { if (k & 1) r *= a; r %= M; a *= a; a %= M; k >>= 1; }
  return r;
}

ll ub(ll x){
  // uppber_bound
  ll left,right,middle;
  if(A>=x) return 0;
  left = 0;
  right = L;
  while(abs(left-right)>1){
    middle = (left+right)/2LL;
    ll y = A+B*middle;
    if(y>=x) right = middle;
    else left = middle;
  }
  return right;
}

ll g(ll ten,ll y){
  // ten^{y-1} + ten^{y-2} + .. + ten^{0}
  if(y==0) return 0LL;
  if(y%2==0){
    return (1+powmod(ten,y/2))*g(ten,y/2)%M;
  }
  return (1LL+ten*g(ten,y-1))%M;
}

ll f(ll ten,ll i,ll y){
  // ten^{y-1} * i + ten^{y-2} * (i+1) + .. + ten^{0} * (i+y-1)
  if(y==1){
    return i;
  }
  ll res = 0;
  if(y%2==0){
    y /= 2;
    ll res = (f(ten,i,y)*(powmod(ten,y)+1LL)%M+g(ten,y)*y%M)%M;
    dump(ten,i,y,res);
    return res;
  }
  res += ten*f(ten,i,y-1)+i+y-1;
  res %= M;
  dump(ten,i,y,res);
  return res;
}

void solve(){
  ll x = 0;
  ll nxt;
  rep(k,18){
    ll temp = 1; // 10^k
    rep(j,k) temp *= 10LL;
    ll i = ub(temp);
    if(i==L) break;
    temp *= 10LL;
    ll i2 = ub(temp);
    ll y = i2-i;
    if(y==0) continue;
    temp %= M;
    nxt = 0;
    nxt += powmod(temp,y) * x % M;
    nxt %= M;
    nxt += g(temp,y) * (A % M) % M;
    nxt %= M;
    nxt += f(temp,i,y) * (B % M) % M;
    nxt %= M;
    x = nxt;
    dump(i,y,x);
  }
  cout << nxt << endl;
}


