    std::cin >> L >> A >> B >> M;

    ll l = 0, ten = 1;
    ll res = 0;

    for(int i=1;i<=18;++i){
        ll s = A + B * l;

        unless(ten <= s && s < ten * 10){
            ten *= 10;
            continue;
        }

        ll r = std::min((ten * 10 - A + B - 1) / B, L), n = r - l;

        ll a = res * mod_expt(ten * 10 % M, n, M) % M,
            b = A % M * f(ten * 10 % M, n) % M,
            c = B % M * (g(ten * 10 % M, r) + M - g(ten * 10 % M, l) * mod_expt(ten * 10 % M, n, M) % M) % M;
        res = (a + b + c) % M;

        l = r;
        ten *= 10;
    }

    std::cout << res << std::endl;
}

