template<class T> struct mat{
    int n,m;
    vector<vector<T>> v;
    const ll MOD=1e9+7;
    mat(){}
    mat(int n_,int m_,T e){
        n=n_;m=m_;
        v.clear();
        v.resize(n);
        fr(i,n){
            v[i].resize(m);
            v[i][i]=e;
        }
    }
    mat(vector<vector<T>>& v_){
        n=v_.size();
        m=v_[0].size();
        swap(v,v_);
    }
    bool operator==(const mat& x){
        if(n!=x.n||m!=x.m) return 0;
        fr(i,n) fr(j,m) if(v[i][j]!=x.v[i][j]) return 0;
        return 1;
    }
    mat& operator=(const mat& x){
        n=x.n;
        m=x.m;
        v=vector<vector<T>>(n);
        copy(x.v.begin(),x.v.end(),v.begin());
        return *this;
    }
    mat operator+(const mat& x){
        if(n!=x.n||m!=x.m) return mat();
        vector<vector<T>> y(n,vector<T>(m));
        fr(i,n) fr(j,m) y[i][j]=v[i][j]+x.v[i][j];
        return mat(y);
    }
    mat operator-(const mat& x){
        if(n!=x.n||m!=x.m) return mat();
        vector<vector<T>> y(n,vector<T>(m));
        fr(i,n) fr(j,m) y[i][j]=v[i][j]-x.v[i][j];
        return mat(y);
    }
    mat operator*(const mat& x){
        if(m!=x.n) return mat();
        vector<vector<T>> y(n,vector<T>(x.m));
        fr(i,n) fr(k,m) fr(j,x.m) y[i][j]+=v[i][k]*x.v[k][j];
        return mat(y);
    }
    mat& operator+=(const mat& x){
        if(n!=x.n||m!=x.m) return mat();
        fr(i,n) fr(j,m) v[i][j]+=x.v[i][j];
        return *this;
    }
    mat& operator-=(const mat& x){
        if(n!=x.n||m!=x.m) return mat();
        fr(i,n) fr(j,m) v[i][j]-=x.v[i][j];
        return *this;
    }
    mat& operator*=(const mat& x){
        *this=*this*x;
        return *this;
    }
    T det(){
        if(n!=m) return T();
        mat y=*this;
        int c=1;
        for(int i=0;i<n;++i){
            for(int j=i;j<n;++j){
                if(v[j][i]!=T()){
                    if(i!=j){
                        swap(v[i],v[j]);
                        c*=-1;
                    }
                    break;
                }
                if(j==n-1) return T();
            }
            for(int j=i+1;j<n;++j){
                T ka=v[j][i]/v[i][i];
                for(int k=i;k<n;k++){
                    v[j][k]-=v[i][k]*ka;
                }
            }
        }
        T d=T(1);
        for(int i=0;i<n;i++) d*=v[i][i];
        d*=c;
        *this=y;
        return d;
    }
};

