vv matpow(vv X, ll K) {
	vv A(3, vector<ll>(3, 0)), N = A, S = A;
	A[0][0] = A[1][1] = A[2][2] = 1;
	while (K) {
		if (K & 1) {
			for (int i = 0;i < 3;i++) {
				for (int j = 0;j < 3;j++) {
					for (int k = 0;k < 3;k++) {
						N[j][k] += A[j][i] * X[i][k];
						N[j][k] %= M;
					}
				}
			}
		}
		else
			N = A;

		A = N;
		K /= 2;
		if (K < 1)break;


		N = S;
		for (int i = 0;i < 3;i++)
			for (int j = 0;j < 3;j++)
				for (int k = 0;k < 3;k++)
					N[j][k] += X[j][i] * X[i][k], N[j][k] %= M;
		X = N;
		N = S;
	}
	return A;
}


ll modpow(ll x, ll y) {
	ll ans = 1;
	while (y) {
		if (y & 1)ans *= x;
		x *= x;
		x %= M;
		ans %= M;
		y /= 2;
	}
	return ans;
}

