long long calc(long long L, long long A, long long B, long long d){
    long long lb = 0;
    long long ub = L-1;
    if(to_string(A).size() > d) return -1;
    if(to_string(A+(L-1)*B).size() <= d) return L-1;
    while(ub - lb > 1){
        long long mid = (lb + ub) / 2;
        if(to_string(A+mid*B).size() <= d) lb = mid;
        else ub = mid;
    }
    return lb;
}

template <class X>
vector<vector<X>> matmul(const vector<vector<X>> &mat1, const vector<vector<X>> &mat2) {
    int n = mat1.size();
    vector<vector<X>> ret(n, vector<X>(n, 0));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            for (int k = 0; k < n; k++){
                ret[i][j] += (mat1[i][k] * mat2[k][j]) % MOD;
                ret[i][j] %= MOD;
            }
    return ret;
}

template <class X>
vector<vector<X>> bipow(const vector<vector<X>> &mat, long long m) {
    int n = mat.size();
    vector<vector<X>> ret(n, vector<X>(n, 0));
    if (m == 0) {
        for (int i = 0; i < n; i++) ret[i][i] = 1;
        return ret;
    }
    if (m % 2 == 0) {
        ret = matmul(mat, mat);
        return bipow(ret, m / 2);
    } else
        return matmul(mat, bipow(mat, m - 1));
}

long long bipow(long long n, int m) {
    if (m == 0) return 1;
    if (m % 2 == 0) {
        n = (n * n) % MOD;
        return bipow(n, m / 2) % MOD;
    } else
        return (n * bipow(n, m - 1)) % MOD;
}

