int binsearch(int len, int lo, int hi)
{
	while(lo < hi)
	{
		int mid = (lo + hi + 1) / 2;
		int cur = a + mid * b;
		if(get(cur) < len)
			lo = mid + 1;
		else if(get(cur) == len)
			lo = mid;
		else
			hi = mid - 1;
	}
	return lo;
}

