template <class Integer>
class Matrix
{
private:
	ull rowCount_;
	ull colCount_;
	vector<Integer> values_;
public:
	Matrix(ull rowCount = 0ULL, ull colCount = 0ULL) :
		rowCount_(rowCount), colCount_(colCount),
		values_(rowCount_ * colCount_) { }

	ull getRowCount() const
	{
		return rowCount_;
	}

	ull getColCount() const
	{
		return colCount_;
	}

	Integer& operator()(ull rowIndex, ull colIndex)
	{
		return values_[rowIndex * colCount_ + colIndex];
	}

	const Integer& operator()(ull rowIndex, ull colIndex) const
	{
		return values_[rowIndex * colCount_ + colIndex];
	}

	inline Matrix operator*(const Matrix& rhs) const
	{
		if (colCount_ != rhs.rowCount_)
		{
			throw invalid_argument("The column size of the left matrix should be equal to the row size of the right matrix.");
		}
		Matrix res(this->rowCount_, rhs.colCount_);
		for (ll i = 0; i < rowCount_; ++i)
		{
			for (ll j = 0; j < rhs.colCount_; ++j)
			{
				for (ll k = 0; k < colCount_; ++k)
				{
					res(i, j) += (*this)(i, k) * rhs(k, j);
				}
			}
		}

		return res;
	}

	friend std::ostream& operator<<(std::ostream& lhs, const Matrix& rhs)
	{
		for (ll i = 0; i < rhs.rowCount_; ++i)
		{
			if (i == 0)
			{
				lhs << "[";
			}
			else
			{
				lhs << " ";
			}

			lhs << "[";
			for (ll j = 0; j < rhs.colCount_; ++j)
			{
				lhs << rhs.values_[i * rhs.colCount_ + j];
				if (j + 1 < rhs.colCount_)
				{
					lhs << ", ";
				}
			}

			if (i + 1 < rhs.rowCount_)
			{
				lhs << "]," << endl;
			}
			else
			{
				lhs << "]]";
			}
		}
		return lhs;
	}
};

template<class Integer>
inline Matrix<Integer> getPower(Matrix<Integer> base, unsigned exponential)
{
	if (base.getRowCount() != base.getColCount())
	{
		throw invalid_argument("The base matrix should be a square matrix.");
	}

	ull size = base.getRowCount();

	Matrix<Integer> result(size, size);
	for (ull i = 0; i < size; ++i)
	{
		result(i, i) = 1;
	}
	while (exponential >= 1)
	{
		if (exponential & 1)
		{
			result = result * base;
		}
		base = base * base;
		exponential >>= 1;
	}

	return result;
}


int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);


	ll L, A, B, M;
	cin >> L >> A >> B >> M;

	rll::global_mod_ = M;
	using mat = Matrix<rll>;

	rll res = 0;
	ll prev_index = 0, curr_index;
	ll base = 1;
	for (ll i = 1; prev_index < L && i <= 20; prev_index = curr_index, ++i)
	{
		base *= 10;
		curr_index = min(max(ll(ceil((double(base) - A) / B)), 0LL), L);
		if (curr_index <= prev_index)
		{
			continue;
		}

		mat recurrenceMatrix(4, 4);
		recurrenceMatrix(0, 0) = rll(base), recurrenceMatrix(0, 1) = 0, recurrenceMatrix(0, 2) = 0, recurrenceMatrix(0, 3) = 0,
		recurrenceMatrix(1, 0) = rll(base), recurrenceMatrix(1, 1) = rll(base), recurrenceMatrix(1, 2) = 0, recurrenceMatrix(1, 3) = 0,
		recurrenceMatrix(2, 0) = 1, recurrenceMatrix(2, 1) = 0, recurrenceMatrix(2, 2) = 1, recurrenceMatrix(2, 3) = 0,
		recurrenceMatrix(3, 0) = 0, recurrenceMatrix(3, 1) = 1, recurrenceMatrix(3, 2) = 0, recurrenceMatrix(3, 3) = 1;

		mat initialMatrix(4, 1);
		initialMatrix(0, 0) = 1, initialMatrix(1, 0) = 0, initialMatrix(2, 0) = 0, initialMatrix(3, 0) = 0;

		ll sequenceLength = curr_index - prev_index;

		mat resultingMatrix = getPower(recurrenceMatrix, sequenceLength) * initialMatrix;
		rll sumR = resultingMatrix(2, 0), sumNR = resultingMatrix(3, 0);

		res *= getPower(rll(10), i * sequenceLength);
		res += (rll(A) + rll(B) * (curr_index - 1)) * sumR - rll(B) * sumNR;
	}

	cout << res << endl;

	return 0;
}

