using namespace std;

ll po(ll k, ll x, ll mod) {
  if (x == 0) {
    return 1;
  }
  if (x == 1) {
    return k % mod;
  }
  ll y = po(k, x/2, mod);
  y = y * y % mod;
  if (x % 2 == 1) {
    y = y * k % mod;
  }
  return y;
}

int calc_digit(ll x) {
  int cnt = 0;
  while (x > 0) {
    x /= 10;
    cnt += 1;
  }
  return cnt;
}

