		else { l = (p10[i] - a + b - 1) / b; }
		r = (p10[i + 1] - a + b - 1) / b - 1;
		if (r >= L) r = L - 1;
		if (l > r) continue;
		//cout << i << ", " << "[l, r] = " << l << ", " << r << endl;

		int syo = a + l * b;
		int n = r - l + 1;
		ans += powmod(10, cnt, m) * calc(syo, b, n, i + 1) % m;
		ans %= m;
		cnt += n * (i + 1);
	}
	cout << ans << endl;
	return 0;
}

