	Matrix RowNormal(){
		vector<T> A(H*W);
		for(int i=0;i<H*W;i++){
			A[i] = data[i];
		}
		int rank = 0;
		for(int i=0;i<W;i++){
			int nonzero = rank;
			while(nonzero < H && A[nonzero*W+i] == M::id()){
				nonzero++;
			}
			if(nonzero == H){
				continue;
			}
			if(nonzero != rank){
				for(int j=i;j<W;j++){
					T temp = A[rank*W+j];
					A[rank*W+j] = A[nonzero*W+j];
					A[nonzero*W+j] = temp;
				}
			}
			{
				T d = M::Divide(A[rank*W+i]);
				for(int j=i;j<W;j++){
					A[rank*W+j] = M::Prod(A[rank*W+j],d);
				}
			}
			for(int j=0;j<H;j++){
				if(j == rank){
					continue;
				}
				T d = M::Minus(A[j*W+i]); 
				for(int k=i;k<W;k++){
					A[j*W+k] = M::Plus(A[j*W+k],M::Prod(A[rank*W+k],d));
				}
			}
			rank++;
		}	
		Matrix ans(H,W,A);
		return ans;
	}
	int Rank(){
		int ans = 0;
		vector<T> A(H*W);
		vector<bool> used(H);
		for(int i=0;i<H*W;i++){
			A[i] = data[i];
		}
		for(int i=0;i<W;i++){
			int nonzero = 0;
			while(nonzero < H && (used[nonzero] || A[nonzero*W+i] == M::id())){
				nonzero++;
			}
			if(nonzero == H){
				continue;
			}
			ans++;
			used[nonzero] = true;
			for(int j=0;j<H;j++){
				if(used[j]){
					continue;
				}
				T d = M::Minus(M::Prod(M::Divide(A[nonzero*W+i]),A[j*W+i])); 
				for(int k=i;k<W;k++){
					A[j*W+k] = M::Plus(A[j*W+k],M::Prod(A[nonzero*W+k],d));
				}
			}
		}	
		return ans;
	}
