                S[nonzeroline] = S[i];
                S[i] = temp;
			}
            L[i*N+i] = 1;
            U[i*N+i] = A[i*N+i];
            T aiiinv = M::Divide(A[i*N+i]);
            for(int j=i+1;j<N;j++){
                L[j*N+i] = M::Prod(A[j*N+i],aiiinv);
                U[i*N+j] = A[i*N+j];
            }
            for(int j=i+1;j<N;j++){
                for(int k=i+1;k<N;k++){
                    A[j*N+k] = M::Plus(A[j*N+k],M::Minus(M::Prod(L[j*N+i],U[i*N+k])));
