        }
		for(int i=0;i<N;i++){
            T sum = b2[i];
            for(int j=0;j<i;j++){
                sum = M::Plus(sum,M::Minus(M::Prod(b[j],L[i*N+j])));
            }
            b[i] = sum;
        }
		for(int i=N-1;i>=0;i--){
            T sum = b[i];
            for(int j=i+1;j<N;j++){
				sum = M::Plus(sum,M::Minus(M::Prod(b2[j],U[i*N+j])));
            }
            b2[i] = M::Prod(sum,M::Divide(U[i*N+i]));
        }
		return b2;
	}
