		long en = min((ten-A-1)/B,L-1);
		if(ten < A+1){
			en = -1;
		}
		vector<long> V(9);
		V[0] = ten % mod;
		V[1] = B % mod;
		V[2] = A % mod;
		V[4] = 1;
		V[5] = 1;
		V[8] = 1;
		Matrix<Mo> Mat(3,V);
