ll hoge(ll len,ll p) {
	if(len==0) return 0;
	if(len==1) return 1;
	ll a=modpow(p,len/2);
	ll v=hoge(len/2,p);
	if(len%2==0) {
		return v*(1+a)%mo;
	}
	else {
		return (v*(1+a)+a*a)%mo;
	}
}
ll hoge2(ll len,ll p) {
	if(len<=0) return 0;
	if(len==1) return 1;

	if(len%2==0) {
		ll a=modpow(p,len/2);
		ll v=hoge2(len/2,p);
		return (v*(1+a)+(len/2)%mo*hoge(len/2,p))%mo;
	}
	else {
		return (hoge2(len-1,p)+hoge(len,p))%mo;
	}
}


