int64_t power_mod(int64_t num, int64_t power){
    int64_t prod = 1;
    num %= MOD;
    while(power > 0){
        if(power&1) prod = prod * num % MOD;
        num = num * num % MOD;
        power >>= 1;
    }
    return prod;
}

// R+...+R^N
int64_t calc(int64_t R, int64_t N){
    int64_t res = 0;
    int64_t sum = R % MOD;
    int64_t base = 1;
    int64_t bs = R % MOD;
    while(N > 0){
        if(N%2){
            add(res, sum * base % MOD);
            mul(base, bs);
        }
        mul(sum, 1+bs);
        mul(bs, bs);
        N /= 2;
    }
    return res;
}

// R+...+NR^N
int64_t calc2(int64_t R, int64_t N){
    int64_t res = 0;
    int64_t sum = R % MOD;
    int64_t base = 1;
    int64_t bs = R % MOD;
    int64_t num = 0;
    int64_t b = 1;
    while(N > 0){
        if(N%2){
            add(res, (sum + num * calc(R, b)) % MOD * base % MOD);
            num += b;
            mul(base, bs);
        }
        mul(sum, 1+bs);
        add(sum, b % MOD * bs % MOD * calc(R, b) % MOD);
        mul(bs, bs);
        b *= 2;
        N /= 2;
    }
    return res;
}

