    for (ll d = 1, pow10 = 1; d < DIGITS; ++d) {
        seg[d].first = max(0ll, ceil_ll(pow10 - A, B));
        seg[d].second = min(ceil_ll(10 * pow10 - A - B, B), L - 1);
        if (seg[d].first <= seg[d].second)
            num[d] = seg[d].second - seg[d].first + 1;
        pow10 *= 10;
    }

    vector<ll> mul(DIGITS);
    for (int d = DIGITS - 2; 0 < d; --d) {
