ll f1(ll l, ll k) {
    if(l == 1) return 1;

    if(l % 2 == 0) {
        l /= 2;
        return (f1(l, k)*(1+power(power10[k], l)))%mod;
    }

    return (f1(l-1, k)*power10[k] + 1)%mod;
}

ll g1(ll l, ll k) {
    if(l == 1) return 0;
    if(l == 2) return 1;

    if(l % 2 == 0) {
        l /= 2;
        return (((g1(l, k)*power(power10[k], l))%mod) + g1(l+1, k) + ((f1(l, k)*((l-1)%mod)) % mod))%mod;
    }

    return (g1(l-1, k)*power10[k] + ((l-1)%mod)) % mod;
}

