typedef long long LL;
LL MOD;
struct qq{LL s[3][3];};
qq operator * (qq a,qq b)
{
    qq c;
    for (LL u=0;u<=2;u++)
        for (LL i=0;i<=2;i++)
        {
            c.s[u][i]=0;
            for (LL j=0;j<=2;j++)
                c.s[u][i]=(c.s[u][i]+a.s[u][j]*b.s[j][i]%MOD)%MOD;
        }
    return c;
};
LL L,A,B;
qq Pow (qq x,LL y)
{
	if (y==1) return x;
	qq lalal=Pow(x,y>>1);
	lalal=lalal*lalal;
	if (y&1) lalal=lalal*x;
	return lalal;
}
int main()
{
	scanf("%lld%lld%lld%lld",&L,&A,&B,&MOD);L--;
	LL op=10,ans=0;
	LL o=0;
	for (LL u=1;u<=19;u++)
	{
		LL l=o,r=L,p=-1;
		while (l<=r)
		{
			LL mid=(l+r)>>1;
			if (mid*B+A<op) {p=mid;l=mid+1;}
			else r=mid-1;
		}
		if (p!=-1)
		{
			qq a;
			a.s[0][0]=op%MOD;a.s[0][1]=1;a.s[0][2]=0;
			a.s[1][0]=0;a.s[1][1]=1;a.s[1][2]=B%MOD;
			a.s[2][0]=0;a.s[2][1]=0;a.s[2][2]=1;
			a=Pow(a,p-o+1);
			LL t=(o%MOD*B%MOD+A)%MOD;	
			//printf("%lld %lld %lld\n",op,t,p-o+1);
			ans=(ans*a.s[0][0]%MOD+t*a.s[0][1]%MOD+a.s[0][2])%MOD;
			o=p+1;
		}
		if (o>L) break;
		op*=10;
	}
	printf("%lld\n",ans);
	return 0;
}

