struct Matrix {
    ll dt[3][3];
    Matrix& operator = (const Matrix &other) {
        REP (i, 3) {
            REP (j, 3) {
                dt[i][j] = other.dt[i][j];
            }
        }
        return *this;
    }

	void check () const {
		REP (i, 3) {
			REP (j, 3) {
				assert(dt[i][j] < mod);
			}
		}
	}

    Matrix operator * (const Matrix &other) {
        Matrix res;
		this->check();
		other.check();
        REP (i, 3) {
            REP (j, 3) {
                res.dt[i][j] = 0;
                REP (k, 3) {
                    res.dt[i][j] = (res.dt[i][j]+dt[i][k] * other.dt[k][j]) % mod;
                }
            }
        }
        return res;
    }
};

ostream& operator << (ostream &os,const Matrix& m) {
    return os << m.dt[0][0] << "," << m.dt[0][1] << "," << m.dt[0][2] << "|" << m.dt[1][0] << "," << m.dt[1][1] << "," << m.dt[1][2] << "|" << m.dt[2][0] << "," << m.dt[2][1] << "," << m.dt[2][2] << "|";
}

ll mpow (ll base, ll ep) {
    ll ret = 1;
    while (ep) {
        if (ep & 1) {
            ret = ret * base % mod;
        }
        base = base * base % mod;
        ep >>= 1;
    }
    return ret;
}

ll solve (ll f, ll t) {
    debug(calc(f), calc(t));
    Matrix tr, res;
    memset(res.dt, 0, sizeof(res.dt));
    REP (i, 3) {
        res.dt[i][i] = 1;
    }
    tr.dt[0][0] = mpow(10, dig(calc(f)));
    tr.dt[0][1] = tr.dt[0][2] = tr.dt[1][2] = tr.dt[2][0] = 0;
    tr.dt[1][0] = tr.dt[1][1] = tr.dt[2][2] = 1;
    tr.dt[2][1] = b % mod;
	// res.check(), tr.check();

    //debug(tr);
    ll dl = t - f + 1;
    debug(dl,t , f);
    while (dl) {
        if (dl & 1) {
            res = res * tr;
        }
        tr = tr * tr;
        dl >>= 1;
    }
    //debug(res);
    //debug(tr);

    Matrix init;
	memset(init.dt, 0, sizeof(init.dt));
    init.dt[0][0] = 0, init.dt[0][1] = (calc(f)%mod), init.dt[0][2] = 1;
	init.check();
    init = init * res;

    return init.dt[0][0];
}


