	void init(int i)
	{
		memset(val, 0, sizeof val);
		val[0][0] = powt[i] % mod, val[1][0] = val[1][1] = val[2][1] = val[2][2] = 1;
	}
}a,res;

mat operator*(mat a, mat b)
{
	mat c;
	for (int i = 0; i<3; i++)
		for (int j = 0; j<3; j++)
			for (int k = 0; k<3; k++)
				c.val[i][j] = (c.val[i][j] + 1ll * a.val[i][k] * b.val[k][j]) % mod;
	return c;
