void poww(long long L,long long R,int d)
{
	long long n = (R - L) / B + 1;
	for (int i = 0; i < 3; i++)
		for (int j = 0; j < 3; j++)
			res.val[i][j] = (i == j);

	a.init(d);

	while (n)
	{
		if (n & 1)res = res * a;
		n >>= 1;
		a = a*a;
	}
	ans = (1ll * ans*res.val[0][0]%mod + L % mod*res.val[1][0] % mod + B % mod*res.val[2][0]) % mod;
}

