	for (int i = 1; i <= 18; i++)
		powt[i] = powt[i - 1] * 10ll;

	long long ed = A + B * (L - 1);

	for (int d = 1; d <= 18; d++)
	{
		if (A < powt[d])
		{
			long long R = (powt[d] - 1 - A) / B * B + A;
			R = min(R, ed);
			poww(A, R, d);
