using intM = unsigned int;
class modM {
private:
	const intM M;
public:
	modM(unsigned int m) : M(m) {}
	intM add(intM a, intM b) { return (a + b) % M; }
	intM sub(intM a, intM b) { return (a + (M - b)) % M; }
	intM mul(intM a, intM b) { return (intM)((unsigned long long)a * (unsigned long long)b % (unsigned long long)M); }
	intM pow(intM a, intM b) {
		if (b == 0) return 1;
		return mul(
			mul(pow(a, b / 2), pow(a, b / 2)),
			(b & 1) ? a : 1
		);
	}
	intM div1(intM b) {
		stack<pair<intM, pair<int, int>>> divbuf;
		intM buf = M;
		while (b != 0) { divbuf.push(make_pair(buf / b, make_pair(buf, b))); buf %= b; swap(b, buf); }
		pair<int, int> m = make_pair(buf, buf);
		while (!divbuf.empty()) {
			m.second = sub(m.second, mul(m.first, divbuf.top().first));
			divbuf.pop(); swap(m.first, m.second);
		}
		return m.first;
	}
	intM div(intM a, intM b) { return mul(div1(b), a); }
};


intM func(modM &m, intM d, intM n, intM b, intM mins) {
	if (n == 0) return 0;
	if (n == 1) return mins;
	intM buf = 0;
	if (n & 1) {
		n--;
		buf = m.add(buf, m.mul(mins, m.pow(10, m.mul(d, n))));
		mins += b;
	}
	intM a = func(m, d, n / 2, b, mins);
	intM pow10d = m.pow(10, d);
