        return mat[i];
    }
};

matrix operator+(matrix&a, matrix&b){
    if(a.N != b.N || a.M != b.M)exit(1);
    matrix res(a.N, a.M);
    REP(i, res.N){
        REP(j, res.M){
            res[i][j]=(a[i][j] + b[i][j])%M;
        }
    }
    return res;
}

matrix operator-(matrix&a, matrix&b){
    if(a.N != b.N || a.M != b.M)exit(1);
    matrix bb = b;
    REP(i, bb.N)
        REP(j, bb.M)bb[i][j]=-b[i][j];
    return a + bb;
}

matrix operator*(matrix&a, matrix&b){
    if(a.M!=b.N)exit(1);
    matrix res(a.N, b.M);
    REP(i, res.N)
        REP(j, res.M){
            REP(k, a.M){
                a[i][k] %= M;
                b[k][j] %= M;
                res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % M;
            }
        }
    return res;
}

matrix mexp(matrix x, LL b){
    matrix res(3, 3);
    REP(i, 3)res[i][i]=1;
    matrix sum = x;
    while(b){
        if(b&1)res = (res * sum);
        sum = (sum * sum);
        b>>=1;
    }
    return res;
}   

