ll ce(ll r, ll l) {
	if (l == 0)
		return 0;
	if (l % 2 == 0) {
		l /= 2;
		ll rl = getpow(r, l, m);
		return ((rl + 1) * ce(r, l)) % m;
	}
	else {
		l -= 1;

		return ((r * ce(r, l)) % m + 1) % m;
	}

}
ll cd(ll r, ll l, ll a, ll b) {
	if (l == 0)
		return 0;

	if (l % 2 == 0) {
		l /= 2;
		ll rl = getpow(r, l, m);
		ll bl = (b * l) % m;
		return (((rl + 1) * cd(r, l, a, b)) % m +
			(bl * ce(r, l)) % m) % m;
	}
	else {
		l -= 1;

		ll bl = (b * l) % m;
		return (((r * cd(r, l, a, b)) % m) + (a + bl) % m) % m;
	}
}
