template<typename T>
class Matrix {
private:
    using array = vector<T>;
    using matrix = vector<array>;
    matrix data_;
public:
    Matrix() {}
    Matrix(size_t row, size_t col):data_(row, array(col)) {}
    Matrix(const Matrix<T>& mat):data_(mat.data_) {}

    size_t row() const {
        return data_.size();
    }
    size_t col() const {
        return data_.front().size();
    }

    array& operator[](int idx) {
        return data_[idx];
    }

    const array& operator[](int idx) const {
        return data_[idx];
    }

    Matrix& operator+=(const Matrix& mat) {
        for (int i = 0; i < (int)data_.size(); i++) {
            for (int j = 0; j < (int)data_[i].size(); j++) {
                data_[i][j] += mat[i][j];
            }
        }
        return *this;
    }
    Matrix& operator-=(const Matrix& mat) {
        for (int i = 0; i < (int)data_.size(); i++) {
            for (int j = 0; j < (int)data_[i].size(); j++) {
                data_[i][j] -= mat[i][j];
            }
        }
        return *this;
    }
    Matrix operator*(const Matrix& mat) const {
        size_t row = data_.size();
        size_t col = mat.col();
        Matrix res(row, col);
        for (int i = 0; i < (int)res.row(); i++) {
            for (int j = 0; j < (int)res.col(); j++) {
                for (int k = 0; k < (int)data_.front().size(); k++) {
                    res[i][j] += data_[i][k] * mat[k][j];
                }
            }
        }
        return res;
    }
    Matrix& operator*=(T scalar) {
        for (int i = 0; i < (int)data_.size(); i++) {
            for (int j = 0; j < (int)data_[i].size(); j++) {
                data_[i][j] *= scalar;
            }
        }
        return *this;
    }
    Matrix& operator%=(T mod) {
        for (int i = 0; i < (int)data_.size(); i++) {
            for (int j = 0; j < (int)data_[i].size(); j++) {
                data_[i][j] %= mod;
            }
        }
        return *this;
    }
    const Matrix operator+(const Matrix& mat) const {
        return Matrix(*this) += mat;
    }
    const Matrix operator-(const Matrix& mat) const {
        return Matrix(*this) -= mat;
    }

    const Matrix operator*(T scalar) const {
        return Matrix(*this) *= scalar;
    }
    const Matrix operator%(T mod) const {
        return Matrix(*this) %= mod;
    }

    static Matrix identity(size_t row, size_t col) {
        Matrix<T> res(row, col);
        for (int i = 0; i < (int)res.row(); i++) {
            res[i][i] = 1;
        }
        return res;
    }
};
