template <typename T>
struct Matrix {
  vector<vector<T>> v;
  int r, c;
  Matrix(int r, int c, T d) : r(r), c(c) {
    v = vector<vector<T>>(r, vector<T>(c, d));
  }
  vector<T>& operator[](int x) {
    return v[x];
  }
  Matrix<T> operator*=(Matrix<T> that) {
    assert(c == that.r);
    auto ret = Matrix<T>(r, that.c, 0);
    rep(i, r) rep(j, that.c) rep(k, c) {
      ret[i][j] += v[i][k] * that[k][j];
    }
    return *this = ret;
  }
  Matrix<T> operator*(Matrix<T> that) {
    return *this *= that;
  }
  Matrix<T> pow(i64 n) {
    assert(r == c);
    auto e = Matrix<T>(r, c, 0);
    rep(i, r) e[i][i] = 1;
    return power(*this, n, e);
  }
};

void solve() {
  i64 L, A, B, M;
  cin >> L >> A >> B >> M;
  mod = M;
  vi64 cnt(19);
  reps(i, 18) {
    i64 c = (power((i64) 10, i) + B - A) / B;
    if (B * c == power((i64) 10, i) + B - A) c--;
    cnt[i] = c < 0 ? 0 : c;
  }
  rreps(i, 18) cnt[i] -= cnt[i - 1];

  Matrix<mint> e(3, 3, 0);
  e[1][0] = 1;
  e[1][1] = 1;
  e[2][1] = B % M;
  e[2][2] = 1;

  mint ans = 0, acc = A % M;
  reps(i, 18) {
    i64 c = min(L, cnt[i]);
    if (c == 0) continue;

    e[0][0] = power((mint) 10, i);

    Matrix<mint> src(1, 3, 1);
    src[0][0] = ans;
    src[0][1] = acc;

    auto dst = src * e.pow(c);

    ans = dst[0][0];
    acc = dst[0][1];

    L -= c;
  }
  cout << ans << '\n';
}

