class RuntimeModInt{
public:
  static uint32_t M;

  uint64_t val;
  RuntimeModInt(): val(0){}
  RuntimeModInt(int64_t n){
    if(n >= M) val = n % M;
    else if(n < 0) val = n % M + M;
    val = n;
  }

  const RuntimeModInt operator+(const RuntimeModInt &a) const {return RuntimeModInt((val+a.val)%M);}
  const RuntimeModInt operator-(const RuntimeModInt &a) const {return RuntimeModInt((val-a.val+M)%M);}
  const RuntimeModInt operator*(const RuntimeModInt &a) const {return RuntimeModInt((val*a.val)%M);}
  const RuntimeModInt operator/(const RuntimeModInt &a) const {return RuntimeModInt((val*a.inv().val)%M);}

  const RuntimeModInt& operator=(const RuntimeModInt &a){val = a.val; return *this;}
  const RuntimeModInt& operator+=(const RuntimeModInt &a){if((val += a.val) >= M) val -= M; return *this;}
  const RuntimeModInt& operator-=(const RuntimeModInt &a){if(val < a.val) val += M; val -= a.val; return *this;}
  const RuntimeModInt& operator*=(const RuntimeModInt &a){(val *= a.val) %= M; return *this;}
  const RuntimeModInt& operator/=(const RuntimeModInt &a){(val *= a.inv().val) %= M; return *this;}

  const bool operator==(const RuntimeModInt &a) const {return val==a.val;}
  const bool operator!=(const RuntimeModInt &a) const {return val!=a.val;}

  const static RuntimeModInt power(LLI n, LLI p){
    RuntimeModInt ret = 1, e = n;
    for(; p; e *= e, p >>= 1) if(p&1) ret *= e;
    return ret;
  }

  const RuntimeModInt power(LLI p) const{
    RuntimeModInt ret = 1, e = val;
    for(; p; e *= e, p >>= 1) if(p&1) ret *= e;
    return ret;
  }

  const RuntimeModInt inv() const{
    int64_t a = val, b = M, u = 1, v = 0;

    while(b){
      int64_t t = a/b;
      a -= t*b; swap(a,b);
      u -= t*v; swap(u,v);
    }
    u %= M;
    if(u < 0) u += M;

    return u;
  }
};

RuntimeModInt operator+(int64_t a, const RuntimeModInt &b){return RuntimeModInt(RuntimeModInt(a)+b.val);}
RuntimeModInt operator-(int64_t a, const RuntimeModInt &b){return RuntimeModInt(RuntimeModInt(a)-b.val);}
RuntimeModInt operator*(int64_t a, const RuntimeModInt &b){return RuntimeModInt(RuntimeModInt(a)*b.val);}
RuntimeModInt operator/(int64_t a, const RuntimeModInt &b){return RuntimeModInt(RuntimeModInt(a)/b.val);}

uint32_t RuntimeModInt::M;

istream& operator>>(istream &is, RuntimeModInt &a){is >> a.val; return is;}
ostream& operator<<(ostream &os, const RuntimeModInt &a){os << a.val; return os;}

