template <typename T> struct SquareMatrix{
  int N;
  vector<vector<T>> matrix;

  SquareMatrix(int N): N(N), matrix(N, vector<T>(N)){}
  SquareMatrix(const vector<vector<T>> &matrix): N(matrix.size()), matrix(matrix){}
  SquareMatrix(const SquareMatrix<T> &sm): N(sm.N), matrix(sm.matrix){}

  SquareMatrix& operator+=(const SquareMatrix &val){
    REP(i,N) REP(j,N) matrix[i][j] += val[i][j];
    return *this;
  }

  SquareMatrix& operator-=(const SquareMatrix &val){
    REP(i,N) REP(j,N) matrix[i][j] -= val[i][j];
    return *this;
  }

  SquareMatrix& operator*=(const SquareMatrix &val){
    vector<vector<T>> temp(N, vector<T>(N));
    REP(i,N) REP(j,N) REP(k,N) temp[i][j] += matrix[i][k] * val[k][j];
    matrix = temp;
    return *this;
  }

  inline const vector<T> operator[](size_t index) const {return matrix[index];}
  inline vector<T>& operator[](size_t index){return matrix[index];}
  inline int size() const {return N;}

  static SquareMatrix<T> make_unit(int N){
    SquareMatrix<T> ret(N);
    REP(i,N) ret[i][i] = 1;
    return ret;
  }

  SquareMatrix<T> transpose(){
    SquareMatrix<T> ret(N);
    REP(i,N) REP(j,N) ret[i][j] = matrix[j][i];
    return ret;
  }

  void debug(){
    REP(i,N){
      cerr << (i==0 ? "⎛" : (i==N-1 ? "⎝" : "⎜"));

      REP(j,N){
        cerr << setw(10) << matrix[i][j] << " ";
      }
      cerr << (i==0 ? "⎞" : (i==N-1 ? "⎠" : "⎟"));
      cerr << endl;
    }
  }
};

template <typename T> SquareMatrix<T> operator+(const SquareMatrix<T> &a, const SquareMatrix<T> &b){
  auto ret = a;
  ret += b;
  return ret;
}

template <typename T> SquareMatrix<T> operator-(const SquareMatrix<T> &a, const SquareMatrix<T> &b){
  auto ret = a;
  ret -= b;
  return ret;
}

template <typename T> SquareMatrix<T> operator*(const SquareMatrix<T> &a, const SquareMatrix<T> &b){
  auto ret = a;
  ret *= b;
  return ret;
}

template <typename T> SquareMatrix<T> power(SquareMatrix<T> a, uint64_t p){
  int N = a.size();

  if(p == 0) return SquareMatrix<T>::make_unit(N);
  if(p == 1) return a;

  SquareMatrix<T> temp = power(a, p/2);
  SquareMatrix<T> ret = temp * temp;

  if(p%2) ret *= a;

  return ret;
}







