    if (n == 0) return 0;
    Matrix<mint> m(3,3);
    mint init[3][3] = {
        { x, 1, 0 },
        { 0, 1, -1 },
        { 0, 0, 1 }
    };
    rep (i,3) rep (j,3) m[i][j] = init[i][j];
    m = m.pow(n-1);
    return m[0][0]*(n-1) + m[0][1]*(n-2) + m[0][2];
}

