template<class T> struct MatG{
	ll h, w; //h行w列
	vector<vector<T>> mat;
	MatG(ll h, ll w): h(h), w(w), mat(h, vector<T>(w)){}
	ll H() const { return h; }
	ll W() const { return w; }
	vector<T> & operator [] (ll i) { return mat[i]; }
	const vector<T> & operator [] (ll i) const { return mat[i]; }
	MatG<T> &operator += (const MatG<T> &B) { REP(i, h)REP(j, w) mat[i][j]+=B[i][j]; return *this; }
	MatG<T> operator + (const MatG<T> &B) const { return MatG<T>(*this) += B; }
	MatG<T> operator * (const MatG<T> &B) const {
		MatG<T> ret(h, B.W());
		REP(i, h) REP(j, B.W()) REP(k, w) ret[i][j] += mat[i][k] * B[k][j];
		return move(ret);
	}
	vector<T> operator * (const vector<T> &v) const {
		vector<T> ret(v.size());
		REP(i, this->h) REP(j, this->w) ret[i] += this->mat[i][j] * v[j];
		return move(ret);
	}
	MatG<T> Pow(ll N) const {
		MatG<T> ret(*this), a(*this);
		for (ll n=N-1; n>0; n>>=1, a=a*a){ if (n&1) ret=ret*a; }
		return move(ret);
	}
	MatG<T> t() const {
		MatG<T> ret(this->w, this->h);
		REP(i, this->w) REP(j, this->h) ret[i][j] = this->mat[j][i];
		return move(ret);
	}
};
using Mat = MatG<mll>;


void solve()
{
	ll MM=18;
	ll L, A, B, M;  cin >> L >> A >> B >> M;
	mll::MOD=M;

	vll b(MM+1);
	b[0]=1;
	b[MM]=L;
	rep(j, 1, MM-1){
		ll tenj=POW(10, j);

		ll ng=0;
		ll ok=L;
		while (abs(ng-ok)>1){
			ll x=(ng+ok)/2;
			ll s=A+B*x;
			if (s>=tenj) ok=x; else ng=x;
		}
		b[j]=ok;
	}

	vmll v={A,0,1};

	rep(k, 1, 18){
		ll st=b[k-1];
		ll en=b[k]-1;
		if (st>en)continue;

		Mat m(3, 3);
		m[0][0]=POW(mll(10), k);
		m[0][1]=B;
		m[0][2]=A+B;
		m[1][0]=0;
		m[1][1]=1;
		m[1][2]=1;
		m[2][0]=0;
		m[2][1]=0;
		m[2][2]=1;

		Mat mp = m.Pow(en-st+1);
		v = mp * v;
	}
	cout << v[0].val << '\n';
}

