ll cle(ll l, ll r) {
	if (l == 0)
		return 0;
	if (l % 2 == 1) {
		l--;
		ll rl = getpow(r, l, m);
		return (rl + cle(l, r) ) % m;
	}
	else {
		l /= 2;
		ll rl = getpow(r, l, m);
		return ((1 + rl) * cle(l, r)) % m;
	}
}
ll cld(ll l, ll r, ll a, ll b) {

	if (l == 0)
		return 0;

	if (l % 2 == 1) {
		l--;
		ll bl = (b * l) % m;
		return (((r * cld(l, r, a, b)) % m) + a + bl) % m;
	}
	else {
		l /= 2;
		ll rl = getpow(r, l, m);
		ll bl = (b * l) % m;
		return ((((rl + 1) * cld(l, r, a, b)) % m) + (bl * cle(l, r)) % m) % m;
	}
}

void solv() {

	ll L, a, b;
	cin >> L >> a >> b >> m;
	ll d = 1;
	ll bef = 0;
	ll res = 0;
	rep2(i, 1, 19) {
		ll t = pow(10, i);
		(d *= 10) %= m;
		if (a > t)
			continue;
		ll hi = L,lo = 0;
		while (lo + 1 < hi)
		{
			ll md = (hi + lo) / 2;
			if (a + b * md >= t) {
				hi = md;
			}
			else {
				lo = md;
			}
		}

		ll l = hi - bef;
		(res *= getpow(d, l, m)) %= m;
		(res += cld(l, d, (a + b * bef), b)) %= m;
		bef = hi;
	}
	cout << res << endl;
}



