template<typename T>
class Matrix {
public:
	vector<vector<T> > v;
	int n,m;
	Matrix(int n){
		this->n = this->m = n;
		v.resize(n,vector<T>(n,0));
	}

	Matrix(int n, int m){
		this -> n = n;
		this -> m = m;
		v.resize(n,vector<T>(m,0));
	}

	size_t size() const {
		return v.size();
	}

	int row() const {
		return n;
	}

	int col() const {
		return m;
	}

	Matrix operator+ (Matrix x) const {
		Matrix res(n,m);
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				res.v[i][j] = x.v[i][j]+v[i][j];
			}
		}
		return res;
	}

	Matrix operator-(Matrix x) const {
		Matrix res(n,m);
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				res.v[i][j] = v[i][j]-x.v[i][j];
			}
		}
	}

	Matrix operator*(Matrix x) const {
		Matrix res(n,x.m);
		for(int i = 0; i < n; i++){
			for(int j = 0; j < x.m; j++){
				for(int k = 0; k < m; k++){
					res.v[i][j] += v[i][k]*x.v[k][j];
				}
			}
		}
		return res;
	}

	Matrix operator-() const  {
		Matrix res = *this;
		for(int i = 0; i < (int)v.size(); ++i) {
			for(int j = 0; j < (int)v[i].size(); ++j) {
				res [i][j] *= -1;
			}
		}
		return res;
	}

	vector<T> operator*(vector<T> x) const {
		assert(x.size() == v.size());
		vector<T> res(v.size());
		for(int i = 0; i < n; i++){
			T tmp = 0;
			for(int j = 0; j < m; j++){
				tmp += v[i][j]*x[j];
			}
			res[i] = tmp;
		}
		return res;
	}

	Matrix pow(long long x) const {
		assert(n == m);
		assert(x >= 0);
		Matrix m = (*this);
		Matrix res(n);
		for(int i = 0; i < n; i++) res[i][i] = 1;
		while(x != 0) {
			if(x&1) {
				res = res*m;
			}
			m = m*m;
			x >>= 1;
		}
		return res;
	}

	vector<T>& operator[](int x){
		return v[x];
	}

	const vector<T>& operator[](int x) const {
		return v[x];
	}

	Matrix<T> inverse() const{
		assert(n == m);
		Matrix res(n);
		for(int i = 0; i < n; ++i) {
			res[i][i] = 1;
		}

		// vector<pair<int,int>> swap_log;
		Matrix<T> mat = *this;
		for(int k = 0; k < n; ++k) {
			T max_val = abs(mat[k][k]);
			int max_point = k;
			for(int i = k+1; i < n; ++i) {
				if(max_val < abs(mat[i][k])){
					max_val = abs(mat[i][k]);
					max_point = i;
				}
			}
			swap(mat[k],mat[max_point]);
			swap(res[k],res[max_point]);
			// swap_log.emplace_back(k,max_point);
			for(int i = k+1; i < n; ++i) {
				T m = mat[i][k]/mat[k][k];
				for(int j = 0; j < n; ++j) {
					mat[i][j] -= m*mat[k][j];
					res[i][j] -= m*res[k][j];
				}
			}
		}

		for(int k = n-1; k >= 0; --k) {
			for(int i = 0; i < k; ++i) {
				T m = mat[i][k]/mat[k][k];
				for(int j = 0; j < n; ++j) {
					// mat[i][j] -= mat[k][j]*m;
					res[i][j] -= res[k][j]*m;
				}
			}
		}
		for(int i = 0; i < n; ++i) {
			for(int j = 0; j < n; ++j) {
				res[i][j] /= mat[i][i];
			}
		}
		// for(auto&& e : swap_log) {
		// 	swap(res[e.first],res[e.second]);
		// }
		return res;
	}

	T det() const {
		Matrix<T> mat = *this;
		T res = 1;
		for(int k = 0; k < n; ++k) {
			T max_val = abs(mat[k][k]);
			int max_point = k;
			for(int i = k+1; i < n; ++i) {
				if(max_val < abs(mat[i][k])){
					max_val = abs(mat[i][k]);
					max_point = i;
				}
			}
			swap(mat[k],mat[max_point]);
			if(k != max_point) res *= -1;
			for(int i = k+1; i < n; ++i) {
				T m = mat[i][k]/mat[k][k];
				for(int j = 0; j < n; ++j) {
					mat[i][j] -= m*mat[k][j];
				}
			}
		}
		for(int i = 0; i < n; ++i) {
			res *= mat[i][i];
		}
		return res;
	}

	pair<T, vector<T>> getMaxEigenvalue(int iterNum = 10) const {
		assert(n == m);
		vector<T> xk_(n, 1);
		xk_ = (*this).pow(iterNum)*xk_;
		auto xk = (*this)*xk_;
		T xk_xk = 0, xk_xk_ = 0;
		for(int i = 0; i < n; i++) {
			xk_xk += xk[i]*xk[i];
			xk_xk_ += xk[i]*xk_[i];
		}
		T xkAbs = sqrt(xk_xk);
		auto res = xk;
		for(auto&& e : res) {
			e /= xkAbs;
		}
		return { xk_xk/xk_xk_, res };
	}

	void debug() const {
		for(auto&& ee : v) {
			for(auto&& e : ee) {
				cout << e << ' ';
			}
			cout << endl;
		}
		cout << endl;
	}
};

template<typename T>
Matrix<T> companion_pow(const Matrix<T>& A, long long m) {
	assert(A.col() == A.row());
	int n = A.col();
	Matrix<T> u(1, n), Ak = A;
	u[0][n-1] = 1;
	while(m > 0) {
		if(m&1) {
			u = u*Ak;
		}
		Matrix<T> a(1, n);
		for(int i = 0; i < n; ++i) {
			a[0][i] = Ak[n-1][i];
		}
		a = a*Ak;
		for(int i = n-1; i >= 0; --i) {
			for(int j = 0; j < n; ++j) {
				Ak[i][j] = a[0][j];
			}
			auto a00 = a[0][0];
			for(int j = 0; j < n-1; ++j) {
				a[0][j] = a[0][j+1]+A[0][j]*a00;
			}
			a[0][n-1] = A[0][n-1]*a00;
		}
		m >>= 1;
	}
	Matrix<T> res(n);
	for(int i = n-1; i >= 0; --i) {
		for(int j = 0; j < n; ++j) {
			res[i][j] = u[0][j];
		}
		auto u00 = u[0][0];
		for(int j = 0; j < n-1; ++j) {
			u[0][j] = u[0][j+1]+A[0][j]*u00;
		}
		u[0][n-1] = A[0][n-1]*u00;
	}
	return res;
}

