ll m;
ll cle(ll r, ll l) {
	if (l == 0)
		return 0;

	if (l % 2 == 0) {
		ll ol = l / 2;
		ll rl = getpow(r, ol, m);
		return (((rl + 1) % m) * cle(r, ol)) % m;
	}
	else {
		ll ol = l - 1;
		return ((r * cle(r, ol)) % m + 1) % m;
	}
}
ll cld(ll r, ll l, ll a, ll b) {
	if (l == 0)
		return 0;

	if (l % 2 == 0) {
		ll ol = l / 2;
		ll rl = getpow(r, ol, m);
		ll bl = (b * ol) % m;

		return (((((rl + 1) % m) * cld(r, ol, a, b)) % m) + (bl * cle(r, ol)) % m) % m;

	}
	else {
		ll ol = l - 1;
		ll bl = (b * ol) % m;
		return ((r * cld(r, ol, a, b)) % m + (a + bl) % m) % m;

	}
}
