long long solve(long long l, long long a, long long b)
{
    //cout << "Block with l = " << l << endl;
    long long last = a + (l - 1) * b;
    unsigned long long zeroes = 0;
    long long ans = 0;
    for (int i = log10(last); i >= 1 && l > 0; i--)
    {
        //cout << "last = " << last << endl;
        //cout << "zeroes = " << zeroes << endl;
        long long lesser = inq(10, i - 1);
        long long steps = (last - lesser + b - 1) / b;
        if (last - steps * b >= lesser) steps++;
        steps = min(steps, l);
        l = l - steps;
        long long Fi = last - steps * b + b;
        //cout << "Fi and La : " << Fi << " " << last << endl;
        long long value = scalar(Fi, b, 1, inq(10, log10(last), m), steps);
        ans = (ans + inq(10, zeroes, m) % m * value) % m;
        //cout << "and added : " << value << endl;
        //cout << "and zeroes : " << steps * log10(last) << endl;
        zeroes += steps * log10(last);
        last = last - steps * b;
    }
    return ans;
}

