using namespace std;

typedef long long ll;

ll mypow(ll x, ll y, ll m)
{
	if (y == 0) {
		return 1;
	}
	if (y % 2 == 1) {
		return mypow(x, y - 1, m) * x % m;
	} else {
		ll p = mypow(x, y / 2, m);
		return p * p % m;
	}
}

ll f(ll n, ll b, ll ten, ll m)
{
	if (n == 0) {
		return 0;
	}
	if (n % 2 == 1) {
		return ((f(n - 1, b, ten % m, m) * (ten % m)) + 1) % m;
	} else {
		ll x = f(n / 2, b, ten % m, m);
		return  (x * mypow(ten % m, n / 2, m) % m + x) % m;
	}
}

ll g(ll n, ll b, ll ten, ll m)
{
	if (n == 0) {
		return 0;
	}
	if (n % 2 == 1) {
		return (g(n - 1, b, ten % m, m) * (ten % m) % m + b % m * (n - 1)) % m;
	} else {
		ll x = g(n / 2, b, ten % m, m);
		return (x * mypow(ten % m, n / 2, m) % m + x + b % m * (n / 2 % m)) % m * f(n / 2, b, ten % m, m) % m;
	}
}

int main(int argc, char *argv[])
{
	ll L, A, B, M;

	cin >> L >> A >> B >> M;

	ll last = A + B * (L - 1);
	ll ten = 10;
	ll ans = 0;

	for (int i = 1; i <= 18; i++, ten *= 10) {
		ll l = ten / 10, r = ten - 1;
		if (A > r) {
			continue;
		}
		if (last < l) {
			continue;
		}
		ll a, nl;
		if (A >= l) {
			a = A;
		} else {
			ll n = ((l - A) + (B - 1)) / B;
			a = A + n * B;
			a = min(a, last);
		}
		ll nlast = 0;
		if (last < r) {
			nlast = last;
		} else {
			ll n = (r - A) / B;
			nlast = A + n * B;
		}
		nl = (nlast - a) / B + 1;

		ans *= mypow(ten % M, nl, M);
		ans %= M;
		ans += (a % M * f(nl, B % M, ten % M, M)) % M;
		ans %= M;
		ans += g(nl, B % M, ten % M, M);
		ans %= M;
	}

	cout << ans << "\n";

	return 0;
}

