i64 L,A,B,M;
i64 c[20];
i64 d[20];
i64 e[20];
i64 ans;

i64 mpow(i64 r,i64 n) {
    r%=M;
    if(!n) return 1;
    i64 res=mpow(r*r % M,n/2);
    return res * (n&1 ? r : 1) % M;
}

i64 touhi(i64 r,i64 n) {
    r%=M;
    if(!n) return 0;
    i64 ret=touhi(r,n/2)*(mpow(r,n/2)+1)%M;
    if(n&1) {
        ret=(ret+mpow(r,n-1))%M;
    }
    return ret;
}

i64 touhitousa(i64 r,i64 n) {
    r%=M;
    if(!n) return 0;
    i64 ret=touhitousa(r,n/2)*(mpow(r,n/2)+1)%M;
    ret=(n/2 % M * touhi(r,n/2) % M * mpow(r,n/2) % M +ret)%M;
    if(n&1) {
        ret=(ret+(n-1)*mpow(r,n-1)%M)%M;
    }
    return ret;
}

signed main() {
    cin>>L>>A>>B>>M;

    for(i64 i=1,t=1,rui=0; i<=18; ++i) {
        t*=10;
        i64 Y=t-1-A;
        if(Y<0) c[i]=0;
        else {
            c[i]=min(Y/B+1,L);
        }
        c[i]-=rui;
        rui+=c[i];
    }

    for(int i=17; i>=0; --i) {
        e[i]=e[i+1]+c[i+1];
    }

    A%=M,B%=M;
    (A+=(L-1)%M*B%M)%=M;
    B=(M-B)%M;

    i64 d10pw=1;
    for(i64 i=18; i; --i) {
        i64 tmp=0;
        i64 pp=mpow(10,i);
        tmp=(A+B*e[i]%M)%M*touhi(pp,c[i])%M;
        tmp+=B*touhitousa(pp,c[i])%M;
        tmp%=M;
        tmp=tmp*d10pw%M;
        ans=(ans+tmp)%M;
        d10pw*=mpow(pp,c[i]);
        d10pw%=M;
    }

    cout<<ans<<"\n";
}

