    }
    ll ans = 0;
    //i桁の数の総和
    rep3(i, 18, 1){
        //[l,r)項目を調べる
        ll l = step[i-1], r = step[i], n = r-l;
        if(l == r) continue;
        ll a = A+(r-1)*B, b = B, x = mpow(10, i);
