ll mod;

// mod
inline ll madd(ll a, ll b){return (a + b) % mod;}
inline ll msub(ll a, ll b){return (a + mod - b) % mod;}
inline ll mmul(ll a, ll b){return ((a % mod) * (b % mod)) % mod;}
ll mpow(ll a, ll b){if(b == 0) return 1; else if(b == 1) return a % mod; else if(b % 2 == 0){ll hlf = mpow(a,b/2);return (hlf * hlf) % mod;} else {ll hlf = mpow(a,b/2);return ( mmul(hlf , hlf) * a ) % mod;}}
inline ll mdiv(ll a, ll b){return mmul(a, mpow(b, mod-2));}

ll func(ll len, ll end, ll d, ll keta){
  ll kouhi = mpow( 10 , keta );
  ll bunshi;
  bunshi = mmul ( ( len - 1 ) , d);
  bunshi = msub( end , bunshi );
  bunshi = mmul ( bunshi, mpow( kouhi, len ) );

  ll hoge;
  hoge = mmul(d , kouhi);
  ll hoge2 = msub(mpow(kouhi, len-1) ,1);
  hoge = mmul(hoge , hoge2);
  hoge = mdiv( hoge , msub(kouhi , 1) );

  trc(bunshi , hoge ,kouhi);
  bunshi = msub( madd(bunshi,hoge) , end%mod);

  ll bunbo = msub( kouhi , 1);

  trc(bunshi , bunbo);
  return mdiv(bunshi , bunbo);
}

int main(){
  inl(L,A,B,M);
  mod = M;
  ll ans  = 0;
  FOR(keta , 1 , 19){
    trc(L,A,B,M);
    if(L == 0) break;
    if( pow(10 ,keta-1 ) <= A &&  A < pow(10,keta) ){
      ll N = min( L ,  (pow(10,keta) - A + B - 1) / B);
      ll end = A + B * (N - 1);
      ans = mmul(ans , mpow(10 , N * keta ));
      ll addans = func(N,end,B,keta);
      ans = madd(ans , addans);
      trc(N,end);
      A = A + B * N;
      L = L - N;
    }
  }
  out(ans);

}

