template<typename T>
T extgcd(T a, T b, T &x, T &y){
  T d = a;
  if(b != 0){
    d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  }else{
    x = 1, y = 0;
  }
  return d;
}

template <typename T>
T modinv(T a, T m){
  long long x = 0, y = 0;
  extgcd<long long>(a, m, x, y);
  x %= m;
  if(x < 0)x += m;
  return x;
}

template <typename T>
T power(T a, T n, T mod) {
  T res = 1;
  T tmp = n;
  T curr = a;
  while(tmp){
    if(tmp % 2 == 1){
      res = (T)((ll)res * curr % mod);
    }
    curr = (T)((ll)curr * curr % mod);
    tmp >>= 1;
  }
  return res;
}

ll ten[19];
ll l[21], r[21];

int main(int argc, char const* argv[])
{
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout << fixed << setprecision(20);
  ten[0] = 1;
  FOR(i, 1, 19)ten[i] = ten[i-1] * 10;
  LL(L); LL(A); LL(B); LL(M);
  FOR(i, 1, 19){
    l[i] = (ten[i-1] - A + B - 1) / B;
    r[i] = (ten[i] - A + B - 1) / B;
    l[i] = max(0LL, l[i]);
    r[i] = min(L, r[i]);
  }
  ll res = 0;
  ll curr = 1;
  A %= M;
  B %= M;
  for(int i = 18; i >= 1; i--){
    ten[i] %= M;
    if(ten[i] < 0)ten[i] += M;
    if(l[i] >= L)continue;
    if(r[i] <= l[i])continue;
    ll tmp1 = (A + B * l[i] % M) * power<ll>(ten[i], r[i] - l[i], M) % M;
    ll tmp2 = B * (power<ll>(ten[i], r[i] - l[i] - 1, M) - 1) % M;
    tmp2 = tmp2 * ten[i] % M;
    tmp2 = tmp2 * modinv<ll>(ten[i] - 1, M) % M;
    ll tmp3 = (A + B * (r[i] - 1) % M) % M;
    ll tmp = (tmp1 + tmp2 - tmp3) % M;
    if(tmp < 0)tmp += M;
    tmp = tmp * modinv(ten[i] - 1, M) % M;
    res = (res + curr * tmp % M) % M;
    curr = curr * power<ll>(10, i * (r[i] - l[i]), M) % M;
  }
  cout << res << endl;
  return 0;
}

