}

mat pow(mat& A, ll n, ll mod) {
  mat B(A.size(),vec(A.size(),0));
  rep(i,A.size()) B[i][i] = 1;
  while(n > 0){
    if(n & 1) B = mul(B, A, mod);
    A = mul(A, A, mod);
    n >>= 1;
  }
  return B;
}

ll Pow(ll x, ll n, ll mod){
  if(n == 0) return 1;
  if(n % 2 == 0) return Pow(x*x % mod, n/2, mod);
