  int M = ass.size(), N = ass[0].size();
  REP(i,M) {
    REP(j,N) {
      ass[i][j] = 0;
    }
  }
}

void zero_vec(vector<int> &as) {
  int N = as.size();
  REP(i,N) {
    as[i] = 0;
  }
}


void identity_mat(vector<vector<int>> &ass) {
   int  N = ass.size();
  REP(i,N) {
    REP(j,N){
      ass[i][j] = i == j;
    }
  }
}


void copy_mat(const vector<vector<int>> &from, vector<vector<int>> &to) {
  int M = from.size(), N = from[0].size();
  REP(i,M){
    REP(j,N) {
      to[i][j] = from[i][j];
    }
  }
}

void copy_vec(const vector<int> &from, vector<int> &to) {
  int N = from.size();
  REP(i,N) {
    to[i] = from[i];
  }
}


void mat_mult_mat(const vector<vector<int>> &ass,
                  const vector<vector<int>> &bss, vector<vector<int>> &css) {
  int L = ass.size(), M = ass[0].size(), N = bss[0].size();
  // initialize
  zero_mat(css);
  // calculate
  REP(i,L) {
    REP(k,M) {
      REP(j,N) {
        css[i][j] = (css[i][j] + (ass[i][k] * bss[k][j] % MOD) ) % MOD;
      }
    }
  }
}


void mat_mult_vec(const vector<vector<int>> &ass, const vector<int> &bs,
                  vector<int> &cs) {
  int M = ass.size(), N = ass[0].size();
  zero_vec(cs);
  REP(i,M) {
    REP(j,N) {
      cs[i] = ((ass[i][j] * bs[j] % MOD) + cs[i]) % MOD;
    }
  }
}


void mat_pow(const vector<vector<int>> &ass, long k, vector<vector<int>> &bss){
  int N = ass.size();
  // initialize
  identity_mat(bss);
  // calculate
  vector<vector<int>> xss(N, vector<int>(N, 0)), tss(N, vector<int>(N, 0));
  copy_mat(ass, xss);
  while (k > 0) {
    if (k % 2) {
      mat_mult_mat(bss, xss, tss);
      copy_mat(tss, bss);
    }
    k /= 2;
    mat_mult_mat(xss, xss, tss);
    copy_mat(tss, xss);
  }
}

