    }
    mint ans = 0;
    matrix<mint> b(3, 1);
    b[0][0] = 0;
    b[1][0] = -B;
    b[2][0] = 1;
    reps(i, 18) {
        matrix<mint> C(3, 3);
        C[0][0] = pow10[i], C[0][1] = 1, C[0][2] = A + B * (k[i] + 1);
        C[1][0] = 0, C[1][1] = 1, C[1][2] = B;
        C[2][0] = 0, C[2][1] = 0, C[2][2] = 1;
        ans += (C.pow(k[i + 1] - k[i]) * b)[0][0] * mint(10).pow(d[i]);
    }
    cout << ans << endl;
}

