    template<class U>mat(vector<vector <U>>& a){rep(i,sz(a))rep(j,sz(a[0 ]))(*this)[i][j]=a[i][j];}
    void unit(int v = 1) {int lim=min(h(),w()); rep(i,h())rep(j,w())(*this)[i][j]  = (i==j) ? v : 0;}
    void zero() { rep(i, h()) rep(j, w())(*this)[i][j] = 0; }
    mat(int v = 0) { if (v > 0)unit(v); }
    int h() const { return size(); }
    int w() const { return (*this)[0].size(); }
    template<class U>void fill(U v){rep(i,h())rep(j,w())(*this)[i][j]=v;}
    T sum(){T res=0;rep(i,h())rep(j,w())res+=(*this)[i][j];return res;}
    mat operator+( mat &r)  {        assert(h() == r.h() && w() == r.w());        mat res = mat();        res.zero();        rep(i, H) rep(j, W)res[i][j] = (this)[i][j] + r[i][j];        return res;    }
    mat operator-( mat &r) {        assert(h() == r.h() && w() == r.w());        mat res = mat();        res.zero();        rep(i, H) rep(j, W)res[i][j] = (this)[i][j] - r[i][j];        return res;    }
    mat operator*( mat &r)  {        assert(w() == r.h());        mat res = mat();        res.zero();        for (int i = 0; i < h(); i++) {            for (int j = 0; j < r.w(); j++) {                for (int k = 0; k < w(); k++) {                    res[i][j] += (*this)[i][k] * r[k][j];                }            }        }        return res;    }
    mat &operator+=( mat &r) { return *this = *this + r; }
    mat &operator-=( mat &r) { return *this = *this - r; }
    mat &operator*=( mat &r) { return *this = *this * r; }
    mat pow(ll n)  {        assert(h() == w());        mat x = *this;        mat r(1);        while (n) {            if (n & 1) r *= x;            x *= x;            n >>= 1;        }  return r;    }
};
