static ll BASE;

ll good_mod(ll x) {
    return (x % BASE + BASE) % BASE;
}

ll power(ll a, ll b) {
    if (b == 0) {
        return 1;
    } else if (b == 1) {
        return a;
    } else {
        ll h = b / 2;
        return good_mod(power(a, h) * power(a, b-h));
    }
}

// r^0 + r^1 + ... + r^(n-1) mod BASE
ll Sn(ll r, ll n) {
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    } else {
        ll h = n / 2;
        return good_mod(Sn(r, h) + good_mod(power(r, h) * Sn(r, n-h)));
    }
}

// 0r^0 + 1r^1 + ... + (n-1)r^(n-1) mod BASE
ll Tn(ll r, ll n) {
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return 0;
    } else {
        ll h = n / 2;
        return good_mod(Tn(r, h) + good_mod(power(r, h) * good_mod(good_mod(h * Sn(r, n-h)) + Tn(r, n-h))));
    }
}

int main(int argc, char* argv[]) {
    ll L, A, B, M;
    cin >> L >> A >> B >> M;
    BASE = M;
    vector<ll> exceed_index(19); // exceed_is[n] = s_iの桁が初めてn桁以上になるようなi
    auto si = [A,B](ll i) -> ll {
        return A + B * i;
    };
    auto si_len = [&si](ll i) -> ll {
        string si_str = to_string(si(i));
        return si_str.size();
    };
    for (ll n = 0; n <= 18; n++) {
        if (si_len(0) >= n) {
            exceed_index[n] = 0;
            continue;
        }
        ll lower_bound = 0;
        ll upper_bound = 1;
        while (true) {
            if (si_len(upper_bound) >= n) {
                break;
            }
            upper_bound *= 2;
        }
        while (true) {
            if (upper_bound - lower_bound == 1) {
                exceed_index[n] = upper_bound;
                break;
            }
            ll intermediate = lower_bound + (upper_bound - lower_bound) / 2;
            if (si_len(intermediate) >= n) {
                upper_bound = intermediate;
            } else {
                lower_bound = intermediate;
            }
        }
    }
    ll ans = 0;
    ll len = 0;
    ll last_i = L-1;
    while (last_i >= 0) {
        ll term_len = si_len(last_i);
        ll first_i = exceed_index[term_len];
        ll num_of_terms = last_i - first_i + 1;
        ll ten_pow_term_len = power(10, term_len);
        ll sub_sum = 0;
        ll A_plus_B_last_i = good_mod(A + good_mod(B * last_i));
        ll sn = Sn(ten_pow_term_len, num_of_terms);
        ll tn = Tn(ten_pow_term_len, num_of_terms);
        sub_sum += good_mod(A_plus_B_last_i * sn);
        sub_sum = good_mod(sub_sum - good_mod(good_mod(B) * tn));
        sub_sum = good_mod(power(10, len) * sub_sum);
        ans = good_mod(ans + sub_sum);
        len += term_len * num_of_terms;
        last_i = first_i - 1;
    }
    cout << ans << endl;
}

