	for (int i = 0; i < 3; i++)
	{
		for (int j = 0; j < 3; j++)
		{
			for (int k = 0; k < 3; k++)
			{
				c.val[i][j] = (c.val[i][j]+ a.val[i][k] * b.val[k][j]%mod)%mod;
			}
		}
	}
	return c;
}

node poww(node a, int b)
{
	node res = { 1,0,0,0,1,0,0,0,1 };
	while (b)
	{
		if (b & 1)res = mul(res, a);
		b >>= 1;
		a = mul(a, a);
	}
	return res;
}

