    static Matrix identity(int n) {
        Matrix ret(n,n);
        rep (i,n) ret[i][i] = 1;
        return ret;
    }
    Matrix pow(ll k) const {
        assert(n == m); assert(k >= 0);
        Matrix v = *this, r = Matrix::identity(n);
        for (; k > 0; k >>= 1, v *= v) if (k&1) r *= v;
        return r;
    }
};
