long ten[99],sten[99],iten[99];
long n;
long sum(long k)
{
	long ret=0,p=1;
	for(int i=61;i--;)
	{
		if(k>>i&1)
		{
			(ret+=sten[i]*p)%=M;
			p=p*ten[i]%M;
		}
	}
	return ret;
}
long isum(long k)
{
	long ret=0,p=1,g=0;
	for(int i=61;i--;)
	{
		if(k>>i&1)
		{
			(ret+=(iten[i]+sten[i]*g)%M*p)%=M;
			p=p*ten[i]%M;
			g=(g+(1LL<<i))%M;
		}
	}
	return ret;
}
long cnt[18],SUM[18];
main()
{
	cin>>L>>A>>B>>M;
	long pre=0,tmpten=1;
	long ans=0;
	for(n=1;n<=18;n++)
	{
		cnt[n-1]=1;
		long l=pre,r=L;
		tmpten*=10;
		while(r-l>1)
		{
			long m=(l+r)/2;
			if(A+B*m<tmpten)l=m;
			else r=m;
		}
		long k=l-pre;
		if(k<0||l>=L||A+B*l>=tmpten)
		{
			continue;
		}
		pre=l+1;
		ten[0]=tmpten%M;
		sten[0]=1;
		iten[0]=0;
		if(k+1&1)cnt[n-1]=tmpten%M;
		for(int i=1;i<61;i++)
		{
			ten[i]=ten[i-1]*ten[i-1]%M;
			sten[i]=(ten[i-1]+1)%M*sten[i-1]%M;
			iten[i]=((ten[i-1]+1)%M*iten[i-1]+(1LL<<i-1)%M*sten[i-1]%M*ten[i-1])%M;
			if(k+1>>i&1)cnt[n-1]=cnt[n-1]*ten[i]%M;
		}
		SUM[n-1]=(((A+B*l)%M*sum(k+1)%M-B%M*isum(k+1))%M+M)%M;
	}
	long p=1;
	for(int i=18;i--;)
	{
		ans=(ans+SUM[i]*p)%M;
		p=p*cnt[i]%M;
	}
	cout<<ans<<endl;
}

