  REP(i,A.size())
    REP(j,A[i].size())
    c[i] = (c[i] + A[i][j]*b[j]);
  return c;
}

mat mul(const mat &A, const mat &B) {
  mat C(A.size(), vec(B[0].size()));
  REP(i,A.size())
    REP(j,B[0].size())
    REP(k,B.size())
    C[i][j] = (C[i][j] + A[i][k]*B[k][j]);
  return C;
}

mat pow(mat A, ll n) {
  mat B(A.size(), vec(A.size()));
  REP(i,A.size())
    B[i][i] = 1;
  while(n) {
    if (n&1) B = mul(B, A);
    A = mul(A,A);
    n >>= 1;
  }
  return B;
}

