using namespace std;
namespace mint {
  int md;
  inline void add (int &a, int b) {
    assert(0 <= a && a < md && 0 <= b && b < md);
    a += b; if (a >= md) a -= md;
  }
  inline void sub (int &a, int b) {
    assert(0 <= a && a < md && 0 <= b && b < md);
    a -= b; if (a < 0) a += md;
  }
  inline int sum (int a, int b) {
    assert(0 <= a && a < md && 0 <= b && b < md);
    add(a, b); return a;
  }
  inline int dif (int a, int b) {
    assert(0 <= a && a < md && 0 <= b && b < md);
    sub(a, b); return a;
  }
  template<class... A>
  inline int prod (A... args) {
    long long ret = 1;
    for (int a :	initializer_list<int>{args...}) {
      assert(0 <= a && a < md);
      ret *= a;
      ret %= md;
    }
    return (int)(ret % md);
  }
  inline void mul (int &a, int b) {
    assert(0 <= a && a < md && 0 <= b && b < md);
    a = prod(a, b);
  }
  inline int inv (int a) {
    assert(0 <= a && a < md);
    a %= md;
    if(a < 0) a += md;
    int b = md, u = 0, v = 1;
    while (a) {
      int t = b / a;
      b -= a * t; swap(a, b);
      u -= v * t; swap(u, v);
    }
    assert(b == 1);
    if(u < 0) u += md;
    return u;
  }
  inline int quot (int a, int b) {
    assert(0 <= a && a < md && 0 <= b && b < md);
    return prod(a, inv(b));
  }
  inline void div (int& a, int b) {
    assert(0 <= a && a < md && 0 <= b && b < md);
    a = quot(a, b);
  }
  inline int pow (int a, long long b) {
    assert(0 <= a && a < md);
    int res = 1;
    for (; b; b >>= 1) {
      if (b & 1) mul(res, a);
      mul(a, a);
    }
    return res;
  }
  namespace factorials {
    int sz;
    vector<int> fact, finv;
    void init (int n) {
      sz = n;
      fact.resize(n); finv.resize(n);
      fact[0] = 1;
      for (int i = 1; i < n; i++) fact[i] = prod(fact[i - 1], i);
      finv[n - 1] = inv(fact[n - 1]);
      for (int i = n - 2; i >= 0; i--) finv[i] = prod(finv[i + 1], i + 1);
    }
  }
  inline int fct (int i) {
    using namespace factorials;
    assert(0 <= i && i < sz);
    return fact[i];
  }
  inline int fnv (int i) {
    using namespace factorials;
    assert(0 <= i && i < sz);
    return finv[i];
  }
  inline int binom (int n, int k) {
    using namespace factorials;
    assert(0 <= n && n < sz);
    if (0 < k || n < k) return 0;
    return prod(fact[n], finv[k], finv[n - k]);
  }
}
int main() {
  cin.tie(0); cin.sync_with_stdio(false);
  long long L, A, B;
  cin >> L >> A >> B >> mint::md;
  int ten = 10 % mint::md;
  const int mx = 18;
  auto lb = [&] (auto p) {
    auto border = [p] {
      long long ret = 1;
      for (int i = 0; i < p; i++) {
        ret *= 10;
      }
      return ret;
    }();
    auto ck = [&] (auto k) {
      return border <= A + k * B;
    };
    long long ok = L, ng = -1, md;
    while (abs(ok - ng) > 1) {
      md = (ok + ng) >> 1;
      if (ck(md)) ok = md;
      else ng = md;
    }
    return ok;
  };
  constexpr size_t N = 3;
  using mat_t = array<array<int, N>, N>;
  auto prod = [&] (const mat_t& a, const mat_t& b) {
    mat_t c;
    for (size_t i = 0; i < N; i++) {
      for (size_t j = 0; j < N; j++) {
        c[i][j] = 0;
      }
    }
    for (size_t i = 0; i < N; i++) {
      for (size_t j = 0; j < N; j++) {
        for (size_t k = 0; k < N; k++) {
          mint::add(c[i][k], mint::prod(a[i][j], b[i][j]));
        }
      }
    }
    return c;
  };
  auto mat_pow = [&] (mat_t a, long long b) {
    mat_t ret;
    for (size_t i = 0; i < N; i++) {
      for (size_t j = 0; j < N; j++) {
        ret[i][j] = (i == j);
      }
    }
    for (; b; b /= 2) {
      if (b % 2 == 1) ret = prod(ret, a);
      a = prod(a, a);
    }
    return ret;
  };
  auto cal = [&] (int p, long long L, long long A, long long B) -> int {
    if (L == 0) return 0;
    mat_t mat;
    for (size_t i = 0; i < N; i++) {
      for (size_t j = 0; j < N; j++) {
        mat[i][j] = (i == j);
      }
    }
    mat[0][0] = mint::pow(ten, p);
    mat[0][1] = 1;
    mat[1][1] = 1;
    mat[1][2] = 1;
    mat[2][2] = 1;
    mat = mat_pow(mat, L);
    int a = A % mint::md;
    int b = B % mint::md;
    int ret = mint::sum(
      mint::prod(mat[0][1], a),
      mint::prod(mat[0][2], b)
    );
    return ret;
  };
  int ret = 0;
  for (int p = 0; p <= mx; p++) {
    auto l = lb(p - 1);
    auto r = lb(p);
    auto val = cal(p, r - l, A + l * B, B);
    auto dgt = (r - l) * p;
    mint::mul(ret, mint::pow(ten, dgt));
    mint::add(ret, val);
  }
  cout << ret << endl;
  return 0;
}

