ll calc1(ll n, ll p){
    ll ten = powll(10, p);
    ll ret = 0, x = 1, c = 1;
    while (n){
        if (n & 1){
            ret = (ret * powll(ten, c)) % mod;
            ret = (ret + x) % mod;
        }
        x = (x + x * powll(ten, c)) % mod;
        c *= 2;
        n /= 2;
    }
    return ret;
}

ll calc2(ll n, ll p){
