    int128_t end = L - 1;
    int dig = digit(A + B * end, 10);
    int128_t ret = 0;
    int128_t tmp = 1;

    while (true) {
        BSR bsr = my_binary_search(0, end,
            [&](const int128_t i) { return digit(A + B * i, 10) == dig; }
        );
        int128_t num = end - bsr.begin + 1;
        ret = ret + ((A + B * end) % M) * pow_series_sum(pow_mod(10, dig, M), 0, num, M) * tmp ; // M が32bitに収まるなら、掛け算3回は無問題のはず。
        ret = cal_mod(ret, M);

        ret = ret - (B % M) * pow_series_sum(pow_mod(10, dig, M), 1, num, M) * tmp;
        ret = cal_mod(ret, M);

        if (bsr.begin == 0) {
            break;
        } else {
            tmp = (tmp * pow_mod(10, dig * num, M)) % M;
            end = bsr.begin - 1;
            dig = digit(A + B * end, 10);
        }
    }

    std::cout << (int)ret << std::endl;

    return 0;
}

