struct Matrix {
    using T = unsigned long;
    vector<vector<T> > data, tmp;
    Matrix(int h,int w) : data(h, vector<T>(w)) {}

    // get mat info
    inline T& at(int i,int j) { return data[i][j]; }
    inline const T& at(int i,int j) const { return data[i][j]; }
    inline int height() const { return (int)data.size(); }
    inline int width() const { return (int)data[0].size(); }
    //

    static Matrix identity(int n) {
        Matrix E(n, n);
        for(int i = 0; i < n; ++i) E.at(i,i) = 1;
        return E;
    }

    Matrix &operator*(const Matrix &m) {
        int H =   height(); int W =   width();
        int h = m.height(); int w = m.width();
        // assert(W == h);

        tmp.assign(H, vector<T>(w));
        for(int i = 0; i < H; ++i){
            for(int j = 0; j < w; ++j){
                T x = 0;
                for(int k = 0; k < h; ++k){
                    (x += data[i][k] % M * m.at(k, j) % M) %= M;
                }
                tmp[i][j] = x;
            }
        }
        data.swap(tmp);
        return *this;
    }
};

Matrix pow(Matrix &mat, long power) {
    Matrix product = Matrix::identity(mat.height());
    while(power) {
        if(power & 1) product = product * mat;
        mat = mat * mat;
        power >>= 1;
    }
    return product;
}

int main(){
    cin.tie(0); ios_base::sync_with_stdio(false);
    cin >> L >> A >> B >> M;
    // si = A + B * i (i:0~L-1)

    // 前提1：ばかでかい数のあまりは上位桁からとる。
    // 3 7 11 15 19 なら
    // ((((3 % M * 10 + 7) % M) * 10^2 + 11) % M) * 10^2 + 15 ...

    // 前提2：構築途中の整数をx, 次に下位にくっつける数字をsとすると、 x' = x*10^(sの桁数) + s
    // sの桁数が一定の場合、これはあふぃん変換になる。なので行列累乗で高速化できる。
    // 桁数は最大18なので、桁数ごとに行列累乗しても間に合う。

    // 前提3：桁ごとの行列演算に必要なのは、その桁の初項と項数
    // にぶたんでその桁の最小値をとるindexと、次の桁の最小値をとるindexをみつければよい。

    long x = 0;
    long now = 1;
    for(int i = 0; i < 18; ++i, now *= 10) {
        // 今の桁で最小値を出すindexをにぶたん
        long l = -1, r = L;
        while(abs(r - l) > 1) {
            long mid = (r + l) / 2;
            if(A + B * mid >= now) r = mid;
            else l = mid;
        }
        long idx = r;

        // 次の桁で最小値を出すindexをにぶたん
        l = -1, r = L;
        while(abs(r - l) > 1) {
            long mid = (r + l) / 2;
            if(A + B * mid >= now*10) r = mid;
            else l = mid;
        }
        long nidx = r;

        long first = A + B * idx;

        if(nidx - idx == 0) continue;
        // x' = (10^d 1 0) x
        // s' = (0    1 B) s
        // 1  = (0    0 1) 1
        // こう？

        // 行列演算
        Matrix mat(3, 3);
        mat.at(0, 0) = now * 10 % M;
        mat.at(0, 1) = 1;
        mat.at(1, 1) = 1;
        mat.at(1, 2) = B % M;
        mat.at(2, 2) = 1;
        mat = pow(mat, nidx - idx);

        Matrix target(3, 1);
        target.at(0, 0) = x;
        target.at(1, 0) = first % M;
        target.at(2, 0) = 1;

        target = mat * target;
        x = target.at(0, 0);
    }

    cout << x << endl;
    return 0;
}

