struct Matrix {
    int n, m;
    vector<vector<int>> a;

    Matrix() {
        n = -1;
        m = -1;
    }

    Matrix(int n_, int m_) {
        n = n_;
        m = m_;
        a.resize(n, vector<int> (m));
    }

    void set(int i, int j, int val) {
        a[i][j] = val;
    }

    friend Matrix mul(const Matrix &f, const Matrix &s) {
        int nn = (int)f.a.size();
        int mm = (int)f.a[0].size();
        int k = (int)s.a[0].size();
        Matrix res(nn, mm);
        for (int i = 0; i < nn; i++) {
            for (int j = 0; j < k; j++) {
                int val = 0;
                for (int t = 0; t < mm; t++) {
                    val = add(val, mul(f.a[i][t], s.a[t][j]));
                }
                res.set(i, j, val);
            }
        }
        return res;
    }
};

Matrix binpow(Matrix f, int b) {
    int n = (int)f.a.size();
    Matrix res(n, n);
    for (int i = 0; i < n; i++) {
        res.set(i, i, 1);
    }
    while (b > 0) {
        if (b % 2 == 1) {
            res = mul(res, f);
            b--;
        } else {
            f = mul(f, f);
            b /= 2;
        }
    }
    return res;
}

