	go.set(0, 1, 0);
	go.set(0, 2, mul(sub(0, ad), p));
	go.set(1, 0, 1);
	go.set(1, 1, 1);
	go.set(1, 2, 0);
	go.set(2, 0, 0);
	go.set(2, 1, 0);
	go.set(2, 2, p);
	go = binpow(go, len);
	Matrix bs(3, 1);
	bs.set(0, 0, pnt);
	bs.set(1, 0, 0);
	bs.set(2, 0, 1);
	Matrix rs = mul(go, bs);
	return rs.a[1][0];
}

