        ll R = bsearch<ll>(0, n, [&](ll k) { return ndig(A + B * k) <= digits; });
        if(L <= R) {
            ll nterms = R - L + 1;
            ans += solve(digits, A, B, L, nterms - 1) * offset;
            offset *= (10_m ^ digits) * (10_m ^ nterms);
        }
    }
