ll S1(ll r, ll T,ll M){
  if(r==1){
    return T%M;
  }
  ll x = pow_(r,T)%(M*(r-1)) -1;
  return (x%(r-1))%M;
}
ll S2(ll r,ll T,ll M){
  if(r==1){
    ll x = T*(T-1);
    return x%M;
  }
  ll Mr = M*(r-1);
  ll x = (T-1) * pow_(r,T)&Mr;
  x -= S1(r,T,Mr);
  x++;
  return x;
}

