// [a,b]でmod上でresのものは何個あるか
ll count(ll a, ll b, ll mod, ll res){
    if(a > b) return 0;
    ll cnt = 0;
    cnt += (b - res) / mod + 1;
    cnt -= (a - 1 - res) / mod + 1;
    return cnt;
}

