mp::cpp_int calc(mp::cpp_int a,mp::cpp_int b,mp::cpp_int p){//a^(b) mod p   
	if(b==0)return 1;
	mp::cpp_int y = calc(a,b/2,p);y=(y*y)%p;
	if(b & 1) y = (y * a) % p;
	return y;
}

mp::cpp_int keta_(mp::cpp_int x){
	mp::cpp_int ans = 0;
	while(x){
		x /= 10;
		ans++;
	}
	return ans;
}





int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);

	mp::cpp_int L,A,B,M;
	cin >> L >> A >> B >> M;

	mp::cpp_int now_keta = keta_(A);
	mp::cpp_int ans = 0;
	mp::cpp_int i=0,j=0;

	while(1){
		ll ok = i,ng = L;
		while(ng-ok>1){
			ll mid = (ok+ng)/2;
			if(keta_(A+B*mid)==now_keta){
				ok = mid;
			}else{
				ng = mid;
			}
		}
		j = ok;
		mp::cpp_int n = j-i+1;
		ans += (A+(i*B))*(1-calc(now_keta,j-i+1,M))*calc(1-now_keta,M-2,M)%M;
		ans += now_keta*(n*calc(now_keta,n+1,M)-(n+1)*calc(now_keta,n,M)+1)*calc(now_keta-1,M-2,M)*calc(now_keta-1,M-2,M);
		ans %= M;
		i = j+1;
		now_keta++;
		if(ok == L-1)break;
	}	

	cout << ans << endl;

}

