Matrix operator * (Matrix A, Matrix B)
{
    if (A.m != B.n)
    {
        cout << "Incorrect";
        exit(0);
    }
    int o = A.m;
    Matrix C(A.n, B.m);
    for (int i = 0; i < A.n; i++)
    {
        for (int j = 0; j < B.m; j++)
        {
            for (int k = 0; k < o; k++)
            {
                C.a[i][j] = (C.a[i][j] + A.a[i][k] * B.a[k][j]) % m;
            }
        }
    }
    return C;
}

Matrix operator ^ (Matrix A, long long c)
{
    if (c == 0)
    {
        Matrix NULLER(A.n, A.m);
        for (int i = 0; i < A.n; i++)
        {
            NULLER.a[i][i] = 1;
        }
        return NULLER;
    }
    if (c == 1) return A;
    Matrix B = A ^ (c / 2);
    if (c % 2) return B * B * A;
    return B * B;
}

long long scalar(long long k, long long b, long long x, long long a, long long n)
{
    if (n == 0)
        return 0;
    k = (mm + k) % m;
    b = (mm + b) % m;
    x = (mm + x) % m;
    a = (mm + a) % m;
    //n = (mm + n) % m;
    // k + i * b
    // x * (a ^ i)
    //cout << k << " " << b << " " << x << " " << a << " " << n << endl;
    Matrix Sta(1, 3);
    Matrix Exp(3, 3);
    Sta.a[0][0] = k;
    Sta.a[0][1] = (k + b) % m;
    Sta.a[0][2] = b;
    Exp.a[0][0] = a;
    Exp.a[1][0] = 1;
    Exp.a[1][1] = 1;
    Exp.a[2][1] = 1;
    Exp.a[2][2] = 1;
    Exp = Exp ^ (n - 1);
    Sta = Sta * Exp;
    return x * Sta.a[0][0] % m;
}

long long log10(long long x)
{
    if (x < 10)
        return 1;
    return log10(x / 10) + 1;
