int mod;
struct mint {
  ll x;
  mint (ll x = 0) : x(x >= 0 ? x % mod : (mod + x % mod) % mod) {}
  mint operator -() const { return mint(-x); }
  mint& operator += (const mint a) { // コンストラクタの、modで割った余りがくる
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator -= (const mint a) {
    if ((x += -a.x + mod) >= mod) x -= mod;
    return *this;
  }
  mint& operator *= (const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator + (const mint a) const {
    mint res(*this);
    return res += a; // ?
  }
  mint operator - (const mint a) const {
    mint res(*this);
    return res -= a;
  }
  mint operator * (const mint a) const {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const { // mint(a).pow(t) tは余りとったりしたらあかん
    if (t == 0) return 1;
    mint a = pow(t >> 1); // 再帰
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // 逆元
  mint inv() const {
    return pow(mod - 2);
  }
  mint& operator /= (const mint a) { // invを利用
    return (*this) *= a.inv();
  }
  mint operator / (const mint a) const {
    mint res(*this);
    return res /= a;
  }
  friend ostream &operator<<(ostream &s, mint a) { return s << a.x; }
};


mint modpow(mint x, ll t) {
  if (t == 0) return 1;
  if (t % 2) {
    return modpow(x, t - 1) * x;
  } else {
    mint y = modpow(x, t / 2);
    return y * y;
  }
}

mint f(ll l) {
  if (l == 0) return 0;
  if (l % 2) {
    return f(l - 1) * ten + 1;
  } else {
    mint x = f(l / 2); // x を事前に計算しないと, 計算量詰む
    return x * modpow(ten, l / 2) + x;
  }
}
mint g(ll l) {
  if (l == 0) return 0;
  if (l % 2) {
    mint x = g(l - 1);
    return x * ten + mint(B) * (l - 1);
  } else {
    mint x = g(l / 2);
    return x * modpow(ten, l / 2) + x + mint(B) * (l / 2) * f(l / 2);
  }
}
// xcode だと計算終わらない
void solve() {
  cin >> L >> A >> B >> mod;
  ll last = A + B * (L - 1);
  ten = 1;
  mint ans = 0;
  rep(i, 19) {
    ten *= 10;
    ll l = ten / 10, r = ten - 1;
    ll na, nlast;
    ll nl; // debuged, int to ll
    if (last < l) continue;
    if (r < A) continue;
    if (l <= A) na = A;
    // a + b * i = l
    else na = (l - A + (B - 1)) / B * B + A;
    if (last <= r) nlast = last;
    else nlast = (r - A) / B * B + A;
    nl = (nlast - na) / B + 1;
    ans *= modpow(ten, nl);
    ans += f(nl) * na; 
    ans += g(nl);
  }
  cout << ans << endl;
}

