ll M;
ll MOD;

ll POWER (ll x, ll y){
    ll p = x % M, ans = 1;
    while (y){
        if ((y & 1) > 0)
            ans = ans * p % M;
        p = p * p % M;
        y /= 2;
    }
    return ans;
}

ll F (ll x){
    if (x == 1)
        return 1;
    ll ans = 1;
    for (ll i = 2; i * i <= x; i++){
        if (x % i != 0)
            continue;
        ll p = i, q = 1;
        x /= p;
        while (x % i == 0){
            p *= i;
            q *= i;
            x /= i;
        }
        ans = ans * (p - q);
    }
    if (x == 1)
        return ans;
    for (ll i = x; i <= x; i++){
        if (x % i != 0)
            continue;
        ll p = i, q = 1;
        x /= p;
        while (x % i == 0){
            p *= i;
            q *= i;
            x /= i;
        }
        ans = ans * (p - q);
    }
    return ans;
}
ll fi;

ll solve (ll A, ll B, ll n, ll x){
    //cout << A << " " << B << " " << n << " " << x << endl;
    x %= M;
    A %= M;
    B %= M;
    if (x == 0){
        return (A + n % M * B) % M;
    }
    if (x == 1){
        n %= M;
        B = B * n % M;
        if (B % 2 == 1)
            B = B + M;
        B /= 2;
        A = (A + B) % M * (n + 1) % M;
        return A;
    }
    ll C = (POWER (x, n + 1) + M - 1) % M;
    ll D = POWER (x - 1, fi - 1);
    ll ans = A * C % MOD * D % MOD;
    A = ((C * D % MOD - n - 1) % MOD + M) % M;
    A = A * B % MOD * D % MOD;
    ans = (ans + A) % MOD;
    return ans;
}


