void matmul(vvi &C,vvi A,vvi B)
{
	REP(i,k){	
		REP(j,k){	
			C[i][j]=0;
			REP(l,k){
				C[i][j]+=A[l][j]*B[i][l];
			}
		}
	}
}

void matpow(vvi &matans,vvi &imat,ll num){
  vvi updmat(k, vi(k));  // k * k の正方行列
  REP(i,k) matans[i][i]=1;//単位行列 I
  REP(i,k)REP(j,k)updmat[i][j]=imat[i][j];
	while(num)
	{
		if (num%2==1)
		{
			matmul(matans,matans,updmat);
		}
		num/=2;
		matmul(updmat,updmat,updmat);
	}
	return;
}


int main(){
  cin >> L >> A >> B>>M;
  MOD=M;
  modint ans;
  ans=0;
  ll lasts;
  k=3;
  vvi mat2d(k, vi(k));  // k * k の正方行列
  mat2d[2][0]=0;
  mat2d[0][0]=mat2d[0][0]=1;
  modint sm;
  sm=1;
	for (int i=0;i<99;i++){
		lasts=(L-1)*B+A;
		ll lowL=(mylog10(lasts)-1-A)/B;
		if (mylog10(lasts)<1+A)
			lowL=-1;
		ll Lnmu=L-1-lowL;
		mat2d[1][1]=mat2d[2][2]=mat2d[1][0]=mylog10(lasts)*10;
		mat2d[2][1]=mat2d[1][1]*(-B%M);
    vvi ansmat(k, vi(k));  // k * k の正方行列
		matpow(ansmat,mat2d,Lnmu-1);
		modint pans=ansmat[0][0]*lasts+ansmat[1][0]*(lasts-B)+ansmat[2][0];
		ans+=pans*sm;
		sm*=mat2d[1][1].exp(Lnmu);
		L=lowL+1;
		if (L==0)break;
	}
  cout<<ans<<endl;
  return 0;
}

