int add(int a, int b)
{
	int res = a + b;
	res %= MOD;
	if(res >= MOD)
		return res - MOD;
	if(res < 0)
	{
		res += MOD;
		res %= MOD;
	}
	return res;
}

int mult(int a, int b)
{
	long long res = a;
	res *= b;
	if(res >= MOD)
		return res % MOD;
	return res;
}

