int solve(int lim, int d) {
    if(lim < 0) return 0;

    Matrix<int> mat;
    init_mat(mat, 4, 4);

    // s_{i+1} = s_i * 10^d + a_i
    int ten = 1;
    for(int i=0; i<d; i++) (ten *= 10) %= M;

    mat[0] = {ten, 1, 0, B%M};
    mat[1] = {  0, 1, 0, B%M};
    mat[2] = {  0, 1, 0, 0};
    mat[3] = {  0, 0, 0, 1};

    Matrix<int> vec;
    init_mat(vec, 4, 1);
    vec[0][0] = A%M;
    vec[1][0] = A%M;
    vec[2][0] = 0;
    vec[3][0] = 1;

    return calc_mat(mat_pow(mat, lim), vec)[0][0];
}

