    // fprintf(stderr, "digit: A = %lld, B = %lld\n", digits(A), digits(B));

    Matrix<int> mat_a;
    init_mat(mat_a, 3, 3);
    // s_{i+1}, s_i, 1

    // s_{i+1} = s_i + B
    mat_a[0] = {1, 0, B};
    mat_a[1] = {1, 0, 0};
    mat_a[2] = {0, 0, 1};

    Matrix<int> vec_a;
    init_mat(vec_a, 3, 1);
    vec_a[0][0] = A;
    vec_a[1][0] = 0;
    vec_a[2][0] = 1;

    // d 桁はどこからどこまで？
    vector<int> lims(D + 1);
    for(int d=1; d<=D; d++) {
        int ub = L, lb = -1;
        while(ub - lb > 1) {
            int mid = (ub + lb) / 2;
            int res_a = calc_mat(mat_pow(mat_a, mid, false), vec_a, false)[0][0];

            int dig = 0;
            while(res_a > 0) dig++, res_a /= 10;

            if(dig >= d) ub = mid;
            else lb = mid;
        }
        lims[d] = ub;
        // fprintf(stderr, "lims[%lld] = %lld\n", d, lims[d]);
    }

    int ans = 0;
    for(int d=1; d<=D; d++) {
        // (lb, ub]
        int lb = 0, ub = 0;
        {
            int res_a = calc_mat(mat_pow(mat_a, lims[d], false), vec_a, false)[0][0];

            int dig = 0;
            while(res_a > 0) dig++, res_a /= 10;

            if(dig != d) continue;
            else lb = lims[d] - 1;
        }
        {
            if(d == D) ub = L-1;
            else {
                int res_a = calc_mat(mat_pow(mat_a, lims[d+1], false), vec_a, false)[0][0];

                int dig = 0;
                while(res_a > 0) dig++, res_a /= 10;

                ub = lims[d+1] - 1;
            }
        }

        // 今までのやつをシフト
        int shift = (ub - lb) * d;
        // // fprintf(stderr, "shift = %lld\n", shift);
        (ans *= mod_pow(10, shift)) %= M;

        int resL = solve(lb, d) * mod_pow(10, shift) % M;
        int resR = solve(ub, d);
        int res = (resR - resL + M) % M;

        // fprintf(stderr, "(%lld, %lld]\n", lb, ub);
        // fprintf(stderr, "d = %lld, res = %lld\n", d, res);
        // fprintf(stderr, "resL = %lld, resR = %lld\n", resL, resR);
        (ans += res) %= M;
    }
    cout << ans << endl;
    return 0;
}

