    ll tmp = (d0-a-1)/b;
    if(d0-a-1<0) cd[i+1] = -1;
    else cd[i+1] = min(tmp,l-1);
    d0 *= 10;
  }
  //cout << cd << endl;
  RREP(i,18){
    cd[i+1] -= cd[i];
  }
  cout << cd << endl;
  a %= m;
  b %= m;
  ll x = 0;
  ll s = a;
  FOR(p,1,19){
    /*
    rは二乗する行列
    1乗時は以下の通り

    10^p 0 0
    1    1 0
    0    1 1

    d[p]は10^pを持っておく配列
    */
    vvl r(3,vl(3));
    r[0][0] = d[p]%m;
    r[0][1] = r[0][2] = 0;
    r[1][0] = r[1][1] = 1;
    r[1][2] = r[2][0] = 0;
    r[2][1] = r[2][2] = 1;

    //resはr^cd[p]を最終的に持つ行列
    //最初は単位行列にしておく。
    vvl res(3,vl(3,0));
    res[0][0] = res[1][1] = res[2][2] = 1;
    //行列累乗を繰り返し二乗法する
    for(;cd[p]>0;cd[p]>>=1){
      //その累乗が必要なら、resにrを右積する
      if(cd[p]&1){
        vvl tmp(3,vl(3,0));
        REP(i,3)REP(j,3)REP(k,3){
          tmp[i][j] += res[i][k]*r[k][j];
          tmp[i][j] %= m;
        }
        res = tmp;
      }
      //rを二乗する
      vvl t(3,vl(3,0));
      REP(i,3)REP(j,3)REP(k,3){
        t[i][j] += r[i][k]*r[k][j];
        t[i][j] %= m;
      }
      r = t;
    }
    //横ベクトルv={x,s,b}にresを右積して、横ベクトルtに遷移させる
    vl v(3);
    v[0] = x;
    v[1] = s;
    v[2] = b;
    vl t(3,0);
    REP(i,3)REP(j,3){
      t[i] += v[j]*res[j][i];
      t[i] %= m;
    }
    x = t[0];
    s = t[1];
    cout << x << " " << s << endl;
  }
  cout << x << endl;
}

