    op(int, +=);op(int, -=);op(int, *=);op(int, /=);op(int, %=);
    op(int, +);op(int, -);op(int, *);op(int, /);op(int, %);
    op(bool, ==);op(bool, !=);op(bool, <);op(bool, <=);op(bool, >);op(bool, >=);
#undef op
    template<class T> inline int operator<<=(T r) { return v *= p10[r]; }
    template<class T> inline int operator<<(T r) { return v * p10[r]; }
    template<class T> inline int operator>>=(T r) { return v /= p10[r]; }
    template<class T> inline int operator>>(T r) { return v / p10[r]; }
};
