int pow10(int N) {
	int res = 1;
	for (int i = 0; i < N; ++i) {
		res *= 10;
	}
	return res;
}

int tenModM(int L, int M, int base) {
	if (L == 0) {
		return 1;
	}
	if (L % 2 == 1) {
		return (base * tenModM(L - 1, M, base)) % M;
	}
	int tmp = tenModM(L / 2, M, base);
	return (tmp * tmp) % M;
}

//
int oneModM(int L, int M, int base) {

	if (L == 1) {
		return 1;
	}
	if (L % 2 == 1) {
		return (base * oneModM(L - 1, M, base) + 1) % M;
	}
	int tmp = oneModM(L / 2, M, base);
	return (tmp * (1 + tenModM(L / 2, M, base))) % M;
}

int seqModM(int L, int M, int base) {
	if (L == 0) {
		return 0;
	}
	if (L == 1) {
		return 1;
	}
	if (L % 2 == 1) {
		return (base * seqModM(L - 1, M, base) + L) % M;
	}
	int tmp = seqModM(L / 2, M, base);
	return (tmp * (1 + tenModM(L / 2, M, base)) + (L / 2 * oneModM(L / 2, M, base)) % M) % M;
}

int keta(int N) {
	int tmp = 1;
	for (int i = 0;; ++i) {
		if (N < tmp)return i;
		tmp *= 10;
	}
}

int solve(int L, int A, int B, int M, int base) {
	int res = 0;
	modify(A, M);
	modify(B, M);
	res += (A * oneModM(L, M, base)) % M;
	modify(res, M);
	res += (B * seqModM(L - 1, M, base)) % M;
	modify(res, M);
	return res;
}
int solve(int L, int A, int B, int M) {
	int ketaA = keta(A);
	int ketaB = keta(A + B * (L - 1));
	if (ketaA == ketaB)return solve(L, A, B, M, pow10(ketaA) % M);
	int base = pow10(ketaB);
	int id = (base / 10 - A) / B;
	int keta0 = keta(A + B * (id - 1));
	int keta1 = keta(A + B * (id));
	int keta2 = keta(A + B * (id + 1));
	int idd;
	if (keta0 == ketaB) {
		idd = id - 1;
	}
	else if (keta1 == ketaB) {
		idd = id;
	}
	else {
		assert(keta2 == ketaB);
		idd = id + 1;
	}
	int tmp = solve(L - idd, A + idd * B, B, M, base % M);
	int tmp2 = solve(idd, A, B, M);

	tmp2 *= tenModM(ketaB * (L - idd), M, 10);
	modify(tmp2, M);
	return (tmp + tmp2) % M;
}

