struct Num{
	int v;
	int mod;
	template<class T>
	Num(T n){
		mod = MOD;
		v = n%mod;
		if(v<0)v+=mod;
	}
	Num():v(0){}
	explicit operator int() const {return v;}
	explicit operator long long() const {return v;}
	inline void operator *=(const Num &a) {
		v = (v*(long long)a.v)%mod;
	}
	inline Num operator *(const Num &a) {
		Num n(*this);n*=a;
		return n;
	}
	inline void operator+=(const Num &a){
		v+=a.v;
		if(v>=mod)v-=mod;
		//	assert(0<=v and v<mod);
	}
	inline Num operator+(const Num &a){
		Num n(*this);n+=a;
		return n;
	}
	inline Num operator -(){
		if(v==0)return 0;
		else return Num(mod-v);
	}
	inline void operator -=(const Num &a){
		v-=a.v;
		if(v<0)v+=mod;
	}
	inline Num operator -(const Num &a){
		Num n(*this);n-=a;
		return n;
	}
#ifdef __GCD_H
	inline Num inv(){
		return Num(invMod(this->v,mod));
	}
	inline void operator /=(const Num &a){
		(*this)*=invMod(a.v,mod);
	}
	inline Num operator /(const Num &a){
		Num n(*this);n/=a;
		return n;
	}
#endif
};

