// x^y
mll pow_(mll x, ll y) {
    if (y==0)
        return mll(1);
    else if(y%2==1) {
        return pow_(x, y-1) * x;
    } else {
        mll z = pow_(x, y/2);
        return z*z;
    }
}

mll f(ll l) {
    if (l==0)
        return 0;

    if (l%2==1){
        ll pl = l-1;
        mll x = f(pl);
        return x*mll(ten)*mll(10)+mll(1);
    } else {
        ll pl = l/2;
        mll x = f(pl);
        return x*pow_(mll(ten)*mll(10), pl) + x;
    }
    return 0;
}

mll g(ll l) {
    if (l==0)
        return 0;

    if (l%2==1) {
        ll pl = l-1;
        mll x = g(pl);
        return x*mll(ten)*mll(10) + B*pl;
    } else {
        ll pl = l/2;
        mll x = g(pl);
        return x*pow_(mll(ten)*mll(10), pl) + x + mll(B)*mll(pl)*f(pl);
    }
}

