        dsum = (ll(dsum) * qpw + ll(p / 2) * ll(d) % mod * sum + ll(dsum)) % mod;
        sum = (ll(sum) * qpw + ll(sum)) % mod;
        qpw = ll(qpw) * qpw % mod;
        if (p % 2) {
            dsum = (ll(dsum) * q + ll(p / 2 * 2) * d + ll(d)) % mod;
            sum = (ll(sum) * q + 1ll) % mod;
            qpw = ll(qpw) * q % mod;
        }
    }
}

