int mod;

struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = (int) (1LL * x * p.x % mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt pow(__int128_t n) const {
    ModInt ret(1), mul(x);
    while(n > 0) {
      if(n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
    return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt(t);
    return (is);
  }
};

using modint = ModInt;


const long long MOD = 1000000007;

// 最大公約数
long long GCD(long long a, long long b) {
  if(b == 0) return a;
  else return GCD(b, a % b);
}

// Garner のアルゴリズムの前処理
long long PreGarner(vector< long long > &b, vector< long long > &m, long long MOD) {
  long long res = 1;
  for(int i = 0; i < (int) b.size(); ++i) {
    for(int j = 0; j < i; ++j) {
      long long g = GCD(m[i], m[j]);

      // これを満たさなければ解はない
      if((b[i] - b[j]) % g != 0) return -1;

      // s = m[i], t = m[j] を仮想的に素因数分解して s = p^k ... q^l ..., t = q^m ... r^n ... となったときに
      m[i] /= g; // p については i の方が大きかったものについての j との差分、と q
      m[j] /= g; // p については j の方が大きかったものについての i との差分、と r

      /*
          残る g を i と j に振り分ける (i の方が指数大きかった素因子 p の分は最終的に gi に、j の方が指数大きかった素因子 p の分は最終的に gj に)
       */
      // ひとまず j 側にある p については gj のみに行くようにする
      long long gi = GCD(m[i], g), gj = g / gi;

      // 本来 i 側に行くべき p で gj 側にあるものを gi 側に寄せていく
      do {
        g = GCD(gi, gj);
        gi *= g, gj /= g;
      } while(g != 1);

      // i 側と j 側に戻していく
      m[i] *= gi, m[j] *= gj;

      // m[i] と m[j] が元より小さくなったのに合わせて余りも計算し直しておく
      b[i] %= m[i], b[j] %= m[j];
    }
  }
  for(int i = 0; i < (int) b.size(); ++i) (res *= m[i]) %= MOD;
  return res;
}

// 負の数にも対応した mod (a = -11 とかでも OK)
inline long long mods(long long a, long long m) {
  long long res = a % m;
  if(res < 0) res += m;
  return res;
}

// 拡張 Euclid の互除法
long long extGCD(long long a, long long b, long long &p, long long &q) {
  if(b == 0) {
    p = 1;
    q = 0;
    return a;
  }
  long long d = extGCD(b, a % b, q, p);
  q -= a / b * p;
  return d;
}

// 逆元計算 (ここでは a と m が互いに素であることが必要)
long long modinv(long long a, long long m) {
  long long x, y;
  extGCD(a, m, x, y);
  return mods(x, m); // 気持ち的には x % m だが、x が負かもしれないので
}

// Garner のアルゴリズム, x%MOD, LCM%MOD を求める (m は互いに素でなければならない)
long long Garner(vector< long long > b, vector< long long > m, long long MOD) {
  m.push_back(MOD); // banpei
  vector< long long > coeffs((int) m.size(), 1);
  vector< long long > constants((int) m.size(), 0);
  for(int k = 0; k < (int) b.size(); ++k) {
    long long t = mods((b[k] - constants[k]) * modinv(coeffs[k], m[k]), m[k]);
    for(int i = k + 1; i < (int) m.size(); ++i) {
      (constants[i] += t * coeffs[i]) %= m[i];
      (coeffs[i] *= m[k]) %= m[i];
    }
  }
  return constants.back();
}


map< int64_t, int > prime_factor(int64_t n) {
  map< int64_t, int > ret;
  for(int64_t i = 2; i * i <= n; i++) {
    while(n % i == 0) {
      ret[i]++;
      n /= i;
    }
  }
  if(n != 1) ret[n] = 1;
  return (ret);
}

