int main() {
  ll L, A, B;
  int64 a, b, c, d;
  cin >> a >> b >> c >> d;
  L = a;
  A = b;
  B = c;

  auto fact = prime_factor(d);

  vector< long long > x;
  vector< long long > y;

  for(auto p : fact) {
    int q = p.second;
    mod = 1;
    while(q--) mod *= p.first;
    auto f = [](ll y, ll z, ll s, ll d) {
      modint ret = 0;
      ret += modint(10).pow(y * z + z) * d;
      ret += modint(10).pow(y * z + z) * d * y;
      ret -= modint(10).pow(y * z + z * 2) * d * y;
      ret -= modint(10).pow(z) * d;
      ret -= modint(10).pow(y * z + z) * s;
      ret += modint(10).pow(y * z + z * 2) * s;
      ret -= modint(10).pow(z) * s;
      ret += s;
      ret /= modint(10).pow(z) - 1;
      ret /= modint(10).pow(z) - 1;
      return ret;
    };


    modint ret = 0;
    modint mul = 1;
    int64 all = 0;
    for(__int128_t b = 100000000000000000, len = 18; b >= 1; b /= 10, len--) {
      auto low = b;
      auto high = b * 10;
      if(A >= high) continue;
      auto lowTap = A + (low - A + B - 1) / B * B;
      chmax(lowTap, A);
      auto highTap = A + (high - A - 1) / B * B;
      chmin(highTap, A + (L - 1) * B);
      if(lowTap > highTap) continue;
      int64 dist = (highTap - lowTap) / B;
      ret += f(dist, len, highTap, B) * mul;
      mul *= modint(10).pow((dist + 1) * len);
    }
