ll k;

ll f(ll l)
{
    if (l == 1)
        return 1;
    if (l % 2)
        return (f(l - 1) * pow(k) + 1) % m;
    return (1 + pow(l / 2, pow(k))) * f(l / 2) % m;
}

ll g(ll l)
{
    if (l == 1)
        return 0;
    if (l % 2)
        return (pow(k) * g(l - 1) + (l - 1)) % m;
    return ((1 + pow(l / 2, pow(k))) * g(l / 2) + l / 2 * f(l / 2)) % m;
}

