struct Matrix {
	vector<vector<long long> > val;
	Matrix(int n, int m, long long x = 0) : val(n, vector<long long>(m, x)) {}
	void init(int n, int m, long long x = 0) { val.assign(n, vector<long long>(m, x)); }
	size_t size() const { return val.size(); }
	inline vector<long long>& operator [] (int i) { return val[i]; }
	inline Matrix operator * (Matrix other)const
	{
		Matrix R(val.size(), other[0].size());
		for (int i = 0; i != val.size(); ++i)
			for (int j = 0; j != other[0].size(); ++j)
				for (int k = 0; k != other.size(); ++k)
					R[i][j] = (R[i][j] + (val[i][k] * other[k][j]) % MOD) % MOD;
		return R;
	}
	void print()const
	{
		for (int i = 0; i != val.size(); i++)
		{
			for (int j = 0; j != val[i].size(); j++)
			{
				cout << val[i][j];
				if (j + 1 == val[i].size())
				{
					cout << endl;
				}
				else
				{
					cout << " ";
				}
			}
		}
	}
};

Matrix matpow(Matrix A, long long n) {
	Matrix R(A.size(), A.size());
	for (int i = 0; i < A.size(); ++i) R[i][i] = 1;
	while (n > 0) {
		if (n & 1) R = R * A;
		A = A * A;
		n >>= 1;
	}
	return R;
}

long long modpow(long long a, long long n) {
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % MOD;
		a = a * a % MOD;
		n >>= 1;
	}
	return res;
}

