  unsigned long long L, A, B, M;
  cin >> L >> A >> B >> M;
  MOD = M;
  unsigned long long C = A + B * (L - 1);
  long long r = A % B;
  long long ans = 0;
  unsigned long long digit_cnt = 0;
  for (int i = 18; i >= 1; i--){
    unsigned long long lb = 1;
    for (int j = 0; j < i - 1; j++){
      lb *= 10;
    }
    unsigned long long ub = lb * 10;
    lb = (lb - r + B - 1) / B * B + r;
    ub = (ub - r - 1) / B * B + r;
    if (lb <= C && A <= ub && lb <= ub){
      lb = max(lb, A);
      ub = min(ub, C);
      ans += apgp2(lb, ub, B, i) * modpow(digit_cnt) % MOD;
      digit_cnt += i * ((ub - lb) / B + 1);
      assert((long long) digit_cnt >= 0);
    }
  }
  ans %= MOD;
  cout << ans << endl;
}

