vector<int> multi(vector<int> a, vector<int> b) {
	int gogo = sqrt(a.size());
	vector<int> ans;
	REP(i, gogo){
		REP(q,gogo){
			int geko = 0;
			REP(j, gogo) {
				geko += (a[i * gogo + j] * b[j * gogo + q]) % mod;
				geko %= mod;
			}
			ans.push_back(geko);
		}
	}
	return ans;
}
vector<int> powering(vector<int> a, int now) {
	vector<int> ans = a;
	now--;
	while (now != 0) {
		if (now % 2 == 1) {
			ans = multi(ans, a);
		}
		a = multi(a, a);
		now /= 2;
	}
	return ans;
}
