mat matpow(mat A, ll n) {
    mat ret(A.size(), vec(A.size()));
    REP(i, A.size()) ret[i][i] = 1;
    while(n) {
        if(n & 1) ret = matmul(ret, A);
        A = matmul(A, A);
        n >>= 1;
    }
    return ret;
}

