ll binary_search(ll d) {
  ll pd = pow(10ll, d)-1;
  if (pd < A) return -1;
  ll lb = 0, ub = L, mid;
  while ((ub-lb)>1) {
    mid = (ub+lb)/2;

    if (A+mid*B <= pd) {
      lb = mid;
    } else {
      ub = mid;
    }
  }

  return lb;
}

typedef vector<ll> vec;
typedef vector<vec> mat;

// A*Bの計算(mod M)
mat mul(mat &A, mat &B, ll M) {
  mat C(A.size(), vec(B[0].size(), 0));
  for (int i = 0; i < A.size(); ++i) {
    for (int k = 0; k < B.size(); ++k) {
      for (int j = 0; j < B[0].size(); ++j) {
        C[i][j] = (C[i][j] + A[i][k]*B[k][j]) % M;
      }
    }
  }
  return C;
}

// A^nの計算(mod M)
mat mat_pow(mat A, ll n, ll M) {
  mat B(A.size(), vec(A.size(), 0));
  for (int i = 0; i < A.size(); ++i) B[i][i] = 1;
  while (n > 0) {
    if (n & 1) B = mul(B, A, M);
    A = mul(A, A, M);
    n >>= 1;
  }
  return B;
}


//x^nをmodのもとで計算する
ll mod_pow(ll x, ll n, ll mod) {
  if (n == 0) return 1;
  ll res = mod_pow((x*x) % mod, n/2, mod);
  if (n & 1) res = (res*x) % mod;
  return res;
}

ll my_pow(ll x, ll n) {
  if (n == 0) return 1;
  ll res = pow(x*x, n/2);
  if (n & 1) res *= x;
  return res;
}

