ll pw(ll a, ll b){
	ll c=a, d=1;
	while(b){
		if(b&1) d = d*c % M;
		c = c*c % M;
		b /= 2;
	}
	return d;
}
ll u[62], v[62];
inline ll mrgu(ll d, ll y, ll ux, ll uy=-1){
	if(uy==-1) uy=ux;
	// DEBUG("mrgu(%lld, %lld, %lld, %lld)\n", d, y, ux, uy);
	return (pw(d,y)*ux %M + uy) %M;
}
inline ll mrgv(ll d, ll y, ll ux, ll vx, ll vy=-1){
	if(vy==-1) vy=vx;
	return (pw(d, y)*(y*ux %M + vx) %M + vy) %M;
}

