// multiplication, A[0].size = B.size が必要
mat mul(mat &A, mat &B) {
    mat C(A.size(), vector<ll>(B[0].size(), 0));
    for (int i = 0; i < A.size(); ++i) {
        for (int k = 0; k < B.size(); ++k) {
            for (int j = 0; j < B[0].size(); ++j) {
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % M;
            }
        }
    }
    return C;
}

// 正方行列の累乗
mat pow(mat A, ll n){
    mat B(A.size(), vector<ll>(A.size(), 0));
    for (int i = 0; i < A.size(); ++i) {
        B[i][i] = 1;
    }
    while(n > 0){
        if(n & 1) B = mul(B, A);
        A = mul(A, A);
        n >>= 1;
    }
    return B;
}

ll modPow(ll x, ll n) {
    ll res = 1;
    while(n > 0){
        if(n & 1) res = res * x % M;
        x = x * x % M;
        n >>= 1;
    }
    return res;
}

