ll mypow(ll x,ll n){
    ll ret = 1;
    while(n > 0){
        if(n&1){
            ret = (ret*x)%MOD;
        }
        x = (x*x)%MOD;
        n >>= 1;
    }
    return ret;
}

template<typename T>
T mypow(T x,ll n,function<T(T,T)> f,T init){
    T ret = init;
    while(n > 0){
        if(n&1){
            ret = f(ret,x);
        }
        x = f(x,x);
        n >>= 1;
    }
    return ret;
}

