ll g(ll l)
{
    if (l == 1)
        return 0;
    if (l % 2)
        return (pow(k) * g(l - 1) + (l - 1)) % m;
    return ((1 + pow(k * l / 2)) * g(l / 2) + l / 2 * f(l / 2)) % m;
}

