		// this->check();
		// other.check();
        REP (i, 3) {
            REP (j, 3) {
                res.dt[i][j] = 0;
                REP (k, 3) {
                    res.dt[i][j] = (res.dt[i][j]+dt[i][k] * other.dt[k][j]) % mod;
                }
            }
        }
        return res;
    }
};

