ll f(ll l, ll base, ll M) {
	if (l <= 1) return l;
	ll res = f(l / 2, base, M) * (mod_pow(base, l / 2, M) + 1) % M;
	if (l & 1) res = (res * base + 1) % M;
	return res;
}

ll g(ll l, ll base, ll M) {
	if (l <= 1) return 0;
	ll res = g(l / 2, base, M) * (mod_pow(base, l / 2, M) + 1) % M + f(l / 2, base, M) * ((l / 2) % M) % M;
	res %= M;
	if (l & 1) res = (res * base + l - 1) % M;
	return res;
}

