mat mul(mat& A, mat& B, ll mod){
  mat C(A.size(), vec(B[0].size(),0));
  rep(i, A.size()){
    rep(j, B[0].size()){
      rep(k, A[0].size()){
        C[i][j] = (C[i][j] + A[i][k]*B[k][j]) % mod;
      }
    }
  }
  return C;
}

mat pow(mat& A, ll n, ll mod) {
  mat B(A.size(),vec(A.size(),0));
  rep(i,A.size()) B[i][i] = 1;
  while(n > 0){
    if(n & 1) B = mul(B, A, mod);
    A = mul(A, A, mod);
    n >>= 1;
  }
  return B;
}

ll Pow(ll x, ll n, ll mod){
  if(n == 0) return 1;
  if(n % 2 == 0) return Pow(x*x % mod, n/2, mod);
  else return x * Pow(x ,n-1, mod) % mod;
}

ll digit(ll n) {
  ll dig = 0;
  while(n > 0) {
    n /= 10;
    dig++;
  }
  return dig;
}

int main(){
  ll l, a, b, mod;
  cin >> l >> a >> b >> mod;
  ll ini = a + b * (l-1);
  ll ans = 0, sd = 0;
  for(ll d = digit(ini); d >= digit(a); d--) {
    ll p = 1;
    rep(i,d-1) p *= 10;
    ll last  = min((ini-p)/b,l-1);
    p *= 10;
    ll first = max((ini-p)/b+1,(ll)0);
    ll c = (ini - first * b);
    if(digit(c) != d) continue;
    c %= mod;
    p %= mod;
    mat m(3,vec(3));
    m[0][0] = 1, m[0][1] = c, m[0][2] = -(b % mod);
    m[1][0] = 0, m[1][1] = p, m[1][2] = 0;
    m[2][0] = 0, m[2][1] = p, m[2][2] = p;
    m = pow(m,last-first,mod);
    ll res = (m[0][0] * c + m[0][1] * p + m[0][2] * p) % mod;
    (ans += Pow(10,sd,mod) * res) %= mod;
