            (p *= p) %= M;
            n >>= 1;
        }
        return ret;
    };
    auto cal = [&M, &modpow](auto N, auto A, auto B, auto R){
        unsigned long ret = 0;
        while(N){
            (ret *= R) %= M;
            if(N & 1){
                (ret += A) %= M;
                (A += B) %= M;
            }
            ((A *= R + 1) += B) %= M;
            (B *= 2 * (R + 1)) %= M;
            N >>= 1;
        }
        return ret;
    };
