ll mod_pow(ll a, ll b, ll p) {
  ll res = 1;
  while (b > 0) {
    if (b & 1) res = (res * a) % p;
    a = (a * a) % p;
    b >>= 1;
  }
  return res;
}


int getKeta(ll x) {
  int res = 0;
  while (x > 0) {
    x /= 10;
    res++;
  }
  return res;
}

// k 桁になる要素の個数
ll keta2(ll A, ll B, ll L, int k) {
  ll lb, ub;
  {
    ll lo = -1;
    ll hi = L;
    while (hi - lo > 1) {
      ll mid = (hi + lo) / 2;
      int keta = getKeta(A + B * mid);
      if (keta < k) { lo = mid; } else { hi = mid; }
    }
    lb = lo;
  }
  {
    ll lo = -1;
    ll hi = L;
    while (hi - lo > 1) {
      ll mid = (hi + lo) / 2;
      int keta = getKeta(A + B * mid);
      if (keta <= k) { lo = mid; } else { hi = mid; }
    }
    ub = lo;
  }
  return ub - lb;
}

// 桁数
ll keta(ll A, ll B, ll L) {
  ll res = 0;
  for (int k = 1; k <= 19; k++) {
    res += k * keta2(A, B, L, k);
  }
  return res;
}

ll solve(ll A, ll B, ll L) {
  if (L <= 10) {
    string s;
    REP(i, L) s += to_string(A + B*i);
    ll res = 0;
    REP(i, s.size()) {
      res = (res * 10 + (s[i]-'0')) % MOD;
    }
    return res;
  } else {
    ll L2 = L/2;
    ll x = solve(A, B, L2);
    ll y = solve(A + B*L2, B, L - L2);
    ll res = x * mod_pow(10, keta(A+B*L2, B, L-L2), MOD) % MOD + y;
    return res % MOD;
  }
}

