	for (int i = 0; i < a.size(); i++) {
		for (int j = 0; j < a.size(); j++) {
			E[i][j] = (i == j);
		}
	}
	while (n > 0) {
		if (n & 1)E = matrix_mul(E, a);
		a = matrix_mul(a, a);
		n >>= 1;
	}
	return E;
}
