void mul(vvl &a, vvl &b, vvl &c) {
  int n = a.size();
  int m = b[0].size();
  c.resize(n);
  for (int i = 0; i < n; i++) {
    c[i].resize(m);

    for (int j = 0; j < m; j++) {
      c[i][j] = 0;
      for (int k = 0; k < a[i].size(); k++) {
        c[i][j] += a[i][k] * b[k][j];
        c[i][j] %= P;
      }
    }
  }
}


