        auto y = pow(x, p/2);
        auto z = (y*y) % m;
        return p%2 == 1 ? (x*z) % m : z;
    };
    function<long long (int, long long)> f = [&](int k, long long r) {
        if (r == 0) {
            return 0LL;
        }
        if (r % 2 == 1) {
