        }
        auto y = f(k, r/2);
        auto factor = pow(pow(10, k), r/2);
        return (y + y * factor) % m;
    };
    function<long long (int, long long)> g = [&](int k, long long r) {
        if (r == 0) {
            return 0LL;
        }
        if (r % 2 == 1) {
