	inline vector<long long>& operator [] (int i) { return val[i]; }
	inline Matrix operator * (Matrix other)const
	{
		Matrix R(val.size(), other[0].size());
		for (int i = 0; i != val.size(); ++i)
			for (int j = 0; j != other[0].size(); ++j)
				for (int k = 0; k != other.size(); ++k)
					R[i][j] = (R[i][j] + (val[i][k] * other[k][j]) % MOD) % MOD;
		return R;
	}
	void print()const
	{
		for (int i = 0; i != val.size(); i++)
		{
			for (int j = 0; j != val[i].size(); j++)
			{
				cout << val[i][j];
