				{
					cout << endl;
				}
				else
				{
					cout << " ";
				}
			}
		}
	}
};

Matrix matpow(Matrix A, long long n) {
	Matrix R(A.size(), A.size());
	for (int i = 0; i < A.size(); ++i) R[i][i] = 1;
	while (n > 0) {
		if (n & 1) R = R * A;
		A = A * A;
		n >>= 1;
	}
	return R;
}

long long modpow(long long a, long long n) {
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % MOD;
		a = a * a % MOD;
		n >>= 1;
	}
	return res;
}

int f(int n, int r) {
	if (n == 0) return 0;
	if (n % 2 == 1) {
		ll pl = n - 1;
		int x = f(pl, r);
		return ((x * r) % MOD + 1) % MOD;
	}
	else {
		ll pl = n / 2;
		int x = f(pl, r);
		return ((x * modpow(r, pl)) % MOD + x) % MOD;
	}
}
int g(int n, int r) {
	if (n == 0) return 0;
	if (n % 2 == 1) {
		ll pl = n - 1;
		int x = g(pl, r);
		return ((x * r) % MOD + pl) % MOD;
	}
	else {
		ll pl = n / 2;
		int x = g(pl, r);
		return ((x * modpow(r, pl)) % MOD + x + (pl * f(pl, r)) % MOD) % MOD;
	}
}

