long long inq(long long x, long long y)
{
    if (y == 0) return 1;
    long long l = inq(x, y / 2);
    if (y % 2) return l * l * x;
    return l * l;
}

long long inq(long long x, long long y, long long MOD)
{
    if (y == 0) return 1 % MOD;
    long long l = inq(x, y / 2, MOD);
    if (y % 2) return l * l % MOD * x % MOD;
    return l * l % MOD;
}

long long divide(long long x, long long y)
{
    x = (x + mm) % m;
    y = (y + mm) % m;
    long long kek = inq(y, phim - 1, m);
    return x * kek % m;
}

long long scalar(long long k, long long b, long long x, long long a, long long n)
{
    k = (mm + k) % m;
    b = (mm + b) % m;
    x = (mm + x) % m;
    a = (mm + a) % m;
    n = (mm + n) % m;
    long long d = b * inq(a, n, m) % m * (n - 1) % m + mm - b * divide((inq(a, n, m) - a + mm) % m, a - 1);
    d = d % m;
    d = divide(d, a - 1);
    d = (d + mm + k * divide(inq(a, n, m) - 1 + mm, a - 1)) % m;
    return d * x % m;
}

long long phi(long long m)
{
    long long s = m;
    vector<pair<int, int> > kek;
    for (int i = 2; i * i <= m; i++)
    {
        while (m % i == 0)
        {
            if (kek.size() == 0 || kek[kek.size() - 1].first != i)
                kek.push_back({i, 1});
            else
                kek[kek.size() - 1].second++;
            m /= i;
        }
    }
    if (m > 1)
    {
        kek.push_back({m, 1});
    }
    for (int i = 0; i < kek.size(); i++)
    {
        s = s - s / inq(kek[i].first, 1);
    }
    return s;
}

long long log10(long long x)
{
    if (x < 10)
        return 1;
    return log10(x / 10) + 1;
}

