	auto g = [&]( auto &&g, ll l ) -> mint {
		if ( l == 0 ) return ( 0 );
		if ( l % 2 )
		{
			auto x = g( g, l - 1 );
			return ( x * base + 1 );
		}
		else
		{
			auto x = g( g, l / 2 );
			mint t = base;
			return ( modpow( t, l / 2 ) * x + x );
		}
	};

	auto f = [&]( auto &&f, ll l ) -> mint {
		if ( l == 0 ) return ( 0 );
		if ( l % 2 )
		{
			auto x = f( f, l - 1 );
			return ( x * base + b * ( l - 1 ) );
		}
		else
		{
			auto x = f( f, l / 2 );
			mint t = base;
			return ( modpow( t, l / 2 ) * x + x + g( g, l / 2 ) * b * ( l / 2 ) );
		}
	};

