        ret[i] = res.get(0,0)*((a*x[i]+b)%mod) + res.get(0,2)*a%mod;
        ret[i]%=mod;
        cnt[i]*=(i+1);
    }
    ll len = 0;
    ll ans=0;
    for(int i = 17;i>=0;--i){
        ans += ret[i]*powmod(10,len)%mod;
        len += cnt[i];
    }
    cout<<ans%mod<<endl;
    return 0;
}

