ll powll(ll x, ll y){
    x %= mod;
    ll res = 1LL;
    while(y){
        if (y & 1LL)
            res *= x;
        res %= mod;
        x = (x*x) % mod;
        y >>= 1LL;
    }
    return res;
}

ll calc1(ll n, ll p){
    ll ten = powll(10, p);
    ll ret = 0, x = 1, c = 1;
    while (n){
        if (n & 1){
            ret = (ret * powll(ten, c)) % mod;
            ret = (ret + x) % mod;
        }
        x = (x + x * powll(ten, c)) % mod;
        c *= 2;
        n /= 2;
    }
    return ret;
}

ll calc2(ll n, ll p){
    ll ten = powll(10, p);
    ll ret = 0, x = 0, c = 1, d = 0;
    while (n){
        if (n & 1){
            ll tmp = (x + calc1(c, p) * d) % mod;
            ret = (ret + tmp * powll(ten, d)) % mod;
            d += c;
        }
        ll tmp = (x + calc1(c, p) * c) % mod;
        x = (x + tmp * powll(ten, c)) % mod;
        c *= 2;
        n /= 2;
    }
    return ret;
}

ll calc2_naive(ll n, ll p){
    ll ret = 0;
    ll x = 1;
    ll ten = powll(10, p);
    REP(i,n){
        ret = (ret + i * x) % mod;
        x = (x * ten) % mod;
    }
    return ret;
}

ll naive(ll a, ll n, ll b, ll d){
    ll ret = 0;
    ll ten = powll(10, d), base = 1;
    REP(i,n){
        ll tmp = (a - i * b) % mod;
        tmp = (tmp + mod) % mod;
        tmp = (tmp * base) % mod;
        ret = (ret + tmp) % mod;
        base = (base * ten) % mod;
    }
    return ret;
}

