long long P;

ll power(ll e, ll x) {
  if (x == 0) return 1;
  if (x % 2 == 0) return power((e * e) % P, x / 2);
  return (e * power(e, x - 1)) % P;
}

void mul(vvl &a, vvl &b, vvl &c) {
  int n = a.size();
  int m = b[0].size();
  c.clear();
  c.resize(n);
  for (int i = 0; i < n; i++) {
    c[i].resize(m);
    for (int j = 0; j < m; j++) {
      for (int k = 0; k < a[i].size(); k++) {
        c[i][j] += (a[i][k] * b[k][j]) % P;
        c[i][j] %= P;
      }
    }
  }
}


