template<typename T>
Matrix<T> companion_pow(const Matrix<T>& A, long long m) {
	assert(A.col() == A.row());
	int n = A.col();
	Matrix<T> u(1, n), Ak = A;
	u[0][n-1] = 1;
	while(m > 0) {
		if(m&1) {
			u = u*Ak;
		}
		Matrix<T> a(1, n);
		for(int i = 0; i < n; ++i) {
			a[0][i] = Ak[n-1][i];
		}
		a = a*Ak;
		for(int i = n-1; i >= 0; --i) {
			for(int j = 0; j < n; ++j) {
				Ak[i][j] = a[0][j];
			}
			auto a00 = a[0][0];
			for(int j = 0; j < n-1; ++j) {
				a[0][j] = a[0][j+1]+A[0][j]*a00;
			}
			a[0][n-1] = A[0][n-1]*a00;
		}
		m >>= 1;
	}
	Matrix<T> res(n);
	for(int i = n-1; i >= 0; --i) {
		for(int j = 0; j < n; ++j) {
			res[i][j] = u[0][j];
		}
		auto u00 = u[0][0];
		for(int j = 0; j < n-1; ++j) {
			u[0][j] = u[0][j+1]+A[0][j]*u00;
		}
		u[0][n-1] = A[0][n-1]*u00;
	}
	return res;
}

