		if(abs(A[i][i]) < EPS) continue;
		Num r = Num(1) / A[i][i];
		for(int j = i+1; j < n; j ++) {
			Num u = A[j][i] * r;
			for(int k = n-1; k >= i; k --)
				A[j][k] -= u * A[i][k];
		}
	}
	for(int i = 0; i < n; i++){
		if(abs(A[i][m-1]) > EPS)	ret = i;
	}
