vvi mult(vvi a, vvi b, ll MOD) {
    int l = a[0].size();
    assert(l == b.size());
    int m = a.size(), n = b[0].size();
    vvi res(m, vi(n));
    REP (i, m) REP (j, n) REP (k, l) {
        res[i][j] += a[i][k] * b[k][j];
        res[i][j] %= MOD;
    }
    return res;
}

vvi pow(vvi a, ll k, ll MOD) {
    assert(a.size() == a[0].size());
    assert(k >= 0);
    int n = a.size();
    vvi res(n, vi(n));
    REP (i, n) res[i][i] = 1;
    while(k) {
        if (k&1) res = mult(res,a,MOD);
        a = mult(a,a,MOD);
        k >>= 1;
    }
    return res;
}

ll L, A, B, MOD;
ll digit[19];

ll s(ll n) {
    return A + B * n;
}

int solve() {
    ll k = 1;
    REP (i, 18) {
        ll lo = -1, hi = L;
        while (hi - lo > 1ll) {
            ll mid = (hi+lo)/2;
            if (s(mid) >= k) hi = mid;
            else lo = mid;
        }
        digit[i] = hi;
        k *= 10;
    }
    digit[18] = L;

    vvi X(3, vi(1));
    X[0][0] = A % MOD;
    X[1][0] = A % MOD;
    X[2][0] = 1;
    k = 1;
    bool f = true;
    REP (i, 18) {
        k *= 10;
        k %= MOD;
        vvi C(3, vi(3));
        C[0][0] = k;
        C[0][1] = 1;
        C[0][2] = B % MOD;
        C[1][0] = 0;
        C[1][1] = 1;
        C[1][2] = B % MOD;
        C[2][0] = 0;
        C[2][1] = 0;
        C[2][2] = 1;
        int n = digit[i+1]-digit[i];
        if (n == 0) continue;
        if (f) C = pow(C, n-1, MOD);
        else C = pow(C, n, MOD);
        assert(C.size() == 3);
        assert(C[0].size() == 3);
        f = false;
        X = mult(C, X, MOD);
        assert(X.size() == 3);
        assert(X[0].size() == 1);
    }
    return X[0][0] % MOD;
}

