void matpow(ll pow, matrix &res, const matrix &A,
            int n, int m) {  // res[n x m] = res[n x m] * (A[m x m]^pow)
	static matrix tmp;
	rep(i,0,m) rep(j,0,m) tmp[i][j]=A[i][j];

	while (pow>0) {
		if (pow%2) matmul(res,res,tmp,n,m,m);
		matmul(tmp,tmp,tmp,m,m,m);
		pow/=2;
	}
}

