ll modpow(ll a, ll b, ll m){
    ll r = 1;
    a %= m;
    while(b){
        if(b&1)r=r*a%m;
        a=a*a%m;
        b>>=1;
    }
    return r;
}

ll calc1(ll n, ll r){
    if(n<=4){
        ll ret = 0;
        ll x = 1;
        REP(i,n){
            ret += x;
            ret %= m;
            x = x * r % m;
        }
        return ret;
    }else{
        if(n%2==0){
            return calc1(n/2,r)*(1+modpow(r,n/2,m))%m;
        }else{
            return (calc1(n/2,r)*(1+modpow(r,n/2,m))%m + modpow(r,n-1,m)) % m;
        }
    }
}
ll calc2(ll n, ll r){
    if(n<=4){
        ll ret = 0;
        ll x = 1;
        r %= m;
        REP(i,n){
            ret += x*i%m;
            ret %= m;
            x = x * r % m;
        }
        return ret;
    }else{
        ll ret = 0;
        ll n2 = n/2;
        ret += calc2(n2,r)*(1+modpow(r,n2,m))%m;
        ret %= m;
        ret += n2*modpow(r,n2,m)%m*calc1(n2,r);
        ret %= m;
        if(n%2==1){
            ret += (n-1)*modpow(r,n-1,m)%m;
            ret %= m;
        }
        return ret;
    }
}

ll solve(ll n, ll a, ll b, int len){
    if(n<=0)return 0;
    ll thr = 1;
    REP(i,len)thr *= 10;
    ll ng = -1, ok = n;
    while(ng+1<ok){
        ll x = (ok+ng)/2;
        (a+b*x>=thr ? ok : ng) = x;
    }
    if(ok==n){
        return solve(n,a,b,len-1);
    }
    thr = thr%m*10%m;
    ll n2 = n-ok;
    ll add = modpow(thr,n2,m) * solve(ok,a,b,len-1) % m;
    a = (a + b * (n-1)) % m;
    b = m-b%m;
    add += a * calc1(n2,thr) % m;
    add += b * calc2(n2,thr) % m;
    return add % m;
}

