struct matrix
{
	vector<vector<ll> >mat;
	matrix(int N, int M)
	{
		mat = vector<vector<ll> >(N, vector<ll>(M, 0));
	}
	matrix(vector<vector<ll> >a)
	{
		mat = a;
	}
	vector<ll>&operator[](int i)
	{
		return mat[i];
	}
	void ident()
	{
		for(int i = 0; i < sz(mat); i++)
			for(int j = 0; j < sz(mat); j++)
				mat[i][j] = (i == j);
	}
	matrix operator*(const matrix &o)
	{
		matrix ret(sz(mat), sz(o.mat[0]));
		for(int i = 0; i < sz(ret.mat); i++)
			for(int j = 0; j < sz(ret.mat[i]); j++)
				for(int k = 0; k < sz(mat[0]); k++)
					ret[i][j] = (ret[i][j] + mat[i][k] * o.mat[k][j]) % MOD;
		return ret;
	}
};
matrix expo(matrix a, ll pw)
{
