ll M;

struct mint {
    ll x;
    mint(ll x = 0) : x(x % M) {}
    mint& operator += (const mint a) {
        if ( (x += a.x) >= M) { x -= M; }
        return *this;
    }
    mint& operator -= (const mint a) {
        if ( (x += M - a.x) >= M) { x -= M; }
        return *this;
    }
    mint& operator *= (const mint a) {
        (x *= a.x) %= M;
        return *this;
    }
    mint operator + (const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator - (const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator * (const mint a) const {
        mint res(*this);
        return res *= a;
    }
};

ll L, A, B;

vector<mint> first_term;  // 桁数 i のものの等差数列の初項
vector<ll> cnt;         // 桁数 i のものが等差数列に登場する数

vector<ll> pow_ten;

// x の n 乗 を m で余りをとったもの
ll mod_pow(ll x, ll n, ll mod) {
    x %= mod;
    ll res = 1;
    while ( n > 0) {
        if (n & 1) { res = res * x % mod; } // 最下位ビットが立っているときに x^(2^i) を掛ける
        x = x * x % mod;                    // x を順次 2 乗していく
        n >>= 1;
    }
    return res;
}
template <typename T> inline T power(T x, uint64_t n, T e = 1) { T r = e; while (n > 0) { if (n & 1) r *= x; x *= x; n >>= 1; } return r; }

// 10^n を返す
static inline ll Pow(ll n) { return pow_ten[n]; }
// 数字 n の桁数を返す
static inline ll DigitCnt(ll n) {
    string s = to_string(n);
    return s.length();
}

// 桁数が k のときの初項 x が、元の等差数列でいうと何番目にあたるかを求める(基数は 0)
// 桁数が A より少ないもしくは S(L-1) より大きい場合は -1 が返る
ll GetFirstIndex(ll k) {
    ll ab = A + B;
    // 掛け算の場合…割り算 if を使って判定できる
    if(LLINF / ab > (L - 1)) {
        // OK
        if(k < DigitCnt(A)) { return -1; }
        else if(k == DigitCnt(A)) { return 0; }
        else if(k > A + B * (L-1)) { return -1; }
    } else {
        // overflow
        if(k < DigitCnt(A)) { return -1; }
        else if(k == DigitCnt(A)) { return 0; }
    }

    // Si = A + B * i なので、 i < (10^(k-1) - A) / B のときの i が、
    // k-1 桁のときの最大の i, なのでその i+1 が答え
    ll i = (Pow(k-1) - A) / B;
    if(i <= 0) { i = 1; }
    else if((Pow(k-1) - A) % B != 0) { i++; }

    if(L <= i) { return -1; }

    return i;
}

// 桁数が k のときの初項 x を求める
// 桁数が A より少ないもしくは S(L-1) より大きい場合は -1 が返る
mint GetFirstTerm(ll k) {
    ll i = GetFirstIndex(k);
    if(i < 0) { return -1; }
    return mint(A) + mint(B) * mint(i);
}

// 桁数が k のものが、元の等差数列でいくつ出てくるかを求める
ll GetCnt(ll k) {
    if(GetFirstIndex(k) < 0) { return 0; }
    ll ub = GetFirstIndex(k+1);
    if(ub == -1) { ub = L; }
    return ub - GetFirstIndex(k);
}

// 初項 a, 公比 b の等比数列の第 n 項(1-indexed)までの和を求めます
// mod は素数でなくともいけます
mint GeoProSum(mint a, mint b, uint64_t n) {
    // 第 1 項までの和から初めて、第 n 項になるまで遷移を繰り返す
    uint64_t cur = 1;
    mint ret = a;
    while(cur < n) {
        if(cur * 2 <= n) {
            ret *= (power(b, cur) + 1);
            cur *= 2;
        }
        else if(cur + 1 <= n) {
            ret += power(b, cur);
            cur++;
        }
    }

    return ret;
}

mint AriGeoProSum(ll k, uint64_t n) {
    uint64_t cur = 1;
    mint ret = 0;
    while(cur < n) {
        if(cur * 2 <= n) {
            ret *= (power(power(mint(10), k), cur) + 1);
            ret += mint(cur) * (GeoProSum(1, power(mint(10), k), cur));
            cur *= 2;
        }
        else if(cur + 1 <= n) {
            ret += GeoProSum(1, power(mint(10), k), cur);
            cur++;
        }
    }

    return ret;
}

