int main() {
  using u64 = std::uint_fast64_t;
  using mint = runtime_modint;
  using vec_type = array_matrix<mint, static_cast<std::size_t>(1),
                                static_cast<std::size_t>(3)>;
  using trans_type = array_matrix<mint, static_cast<std::size_t>(3),
                                  static_cast<std::size_t>(3)>;

  u64 l, a, b, m;
  std::cin >> l >> a >> b >> m;
  mint::set_mod(m);

  vec_type vec(
      {{static_cast<mint>(0), static_cast<mint>(a), static_cast<mint>(1)}});
  trans_type trans(
      {{static_cast<mint>(0), static_cast<mint>(0), static_cast<mint>(0)},
       {static_cast<mint>(1), static_cast<mint>(1), static_cast<mint>(0)},
       {static_cast<mint>(0), static_cast<mint>(b), static_cast<mint>(1)}});
  u64 next = static_cast<u64>(1);

  while (l != static_cast<u64>(0)) {
    while (next <= a) {
      next *= static_cast<u64>(10);
    }
    trans[static_cast<std::size_t>(0)][static_cast<std::size_t>(0)] =
        static_cast<mint>(next);
    u64 step =
        std::min(l, (next - a - static_cast<u64>(1)) / b + static_cast<u64>(1));
    vec = vec * power(trans, step, std::multiplies<trans_type>(),
                      identity<mint, 3>());
    a += b * step;
    l -= step;
  }

  std::cout
      << vec[static_cast<std::size_t>(0)][static_cast<std::size_t>(0)].value()
      << std::endl;

  return 0;
}

