//1+x+x^2+....+x^(n-1)を求める
ll powsum1(ll x, ll n){
    x %= MOD;
    ll now = 1, res = 0, pos = 0;
    for(int i = 0; (1ll<<i) <= n; i++){
        if(n & (1ll<<i)){
            res += now * mpow(x, pos);
            res %= MOD;
            pos += 1ll<<i;
        }
        now = now*(1+mpow(x, 1ll<<i)), now %= MOD;
    }
    return res;
}

//0+1*x+2*(x^2)+....+(n-1)*x^(n-1)を求める
ll powsum2(ll x, ll n){
    x %= MOD;
    ll now = 0, res = 0, pos = 0;
    for(int i = 0; (1ll<<i) <= n; i++){
        if(n & (1ll<<i)){
            ll tmp = now+pos*(powsum1(x, (1ll<<i)));
            tmp %= MOD;
            tmp *= mpow(x, pos), tmp %= MOD;
            res += tmp, res %= MOD;
            pos += 1ll<<i;
        }
        ll sub = now+(1ll<<i)*powsum1(x, (1ll<<i));
        sub %= MOD;
        sub *= mpow(x, (1ll<<i)), sub %= MOD;
        now += sub, now %= MOD;
    }
    return res;
}

