template<typename T>
T extgcd(T a, T b, T &x, T &y){ 
  T d = a;
  if(b != 0){
    d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  }else{
    x = 1, y = 0;
  }
  return d;
}

template <typename T>
T modinv(T a, T m){
  long long x = 0, y = 0;
  extgcd<long long>(a, m, x, y);
  x %= m;
  if(x < 0)x += m;
  return x;
}

template <int MOD = int(1e9+7)>
struct LMatrix{
  ll mo = M;
  vector<vector<long long>> v;
  int n, m;
  LMatrix(int n_, int m_ = -1): n(n_), m(m_){
    if(m < 0)m = n;
    v.resize(n);
    for(int i = 0; i < n; i++)v[i].resize(m);
  }
  void set_mo(ll m){
    mo = m;
  }
  void identity(){
    assert(n == m);
    for(int i = 0; i < n; i++){
      for(int j = 0; j < n; j++){
        v[i][j] = (i == j ? 1: 0);
      }
    }
  }
  vector<long long> &operator[](size_t i){
    return v[i];
  }
  const vector<long long> &operator[](size_t i) const{
    return v[i];
  }
  LMatrix operator*(const LMatrix &r) const{
    assert(m == r.n);
    int l = r.m;
    LMatrix res(n, l);
    for(int i = 0; i < n; i++){
      for(int j = 0; j < l; j++){
        res.v[i][j] = 0;
        for(int k = 0; k < m; k++){
          res.v[i][j] = (res.v[i][j] + v[i][k] * r.v[k][j] % mo) % mo;
        }
      }
    }
    return res;
  }
  LMatrix operator+(const LMatrix &r) const{
    assert(n == r.n);
    assert(m == r.m);
    LMatrix res(n, m);
    for(int i = 0; i < n; i++){
      for(int j = 0; j < m; j++){
        res[i][j] = (v[i][j] + r[i][j]) % mo;
      }
    }
    return res;
  }
  LMatrix operator-(const LMatrix &r) const{
    assert(n == r.n);
    assert(m == r.m);
    LMatrix res(n, m);
    for(int i = 0; i < n; i++){
      for(int j = 0; j < m; j++){
        res[i][j] = (v[i][j] - r[i][j]) % mo;
        if(res[i][j] < 0)res[i][j] += mo;
      }
    }
    return res;
  }
  template <typename T>
  LMatrix operator*(T a) const{
    LMatrix res = *this;
    for(int i = 0; i < n; i++){
      for(int j = 0; j < n; j++){
        res[i][j] = a * res[i][j] % mo;
      }
    }
    return res;
  }
  LMatrix inv2() const{
    assert(n == 2 && m == 2);
    long long det = v[0][0] * v[1][1] % mo - v[0][1] * v[1][0] % mo;
    if(det < 0)det += mo;
    assert(det != 0);
    LMatrix res(2, 2);
    long long inv = modinv(det, (long long)mo);
    res[0][0] = v[1][1];
    res[1][1] = v[0][0];
    res[1][0] = - v[1][0];
    res[0][1] = - v[0][1];
    for(int i = 0; i < n; i++){
      for(int j = 0; j < m; j++){
        res[i][j] %= mo;
        res[i][j] = res[i][j] * inv % mo;
        if(res[i][j] < 0)res[i][j] += mo;
      }
    }
    return res;
  }
};

template <typename T, int MOD = int(1e9+7)>
LMatrix<MOD> operator*(T a, const LMatrix<MOD> b){
  return b * a;
}

template <int MOD = int(1e9+7)>
LMatrix<MOD> powerm(LMatrix<MOD> &a, long long n){
  long long tmp = n;
  LMatrix<MOD> curr = a;
  LMatrix<MOD> res(a.n);
  res.identity();
  while(tmp){
    if(tmp % 2 == 1){
      res = res * curr;
    }
    curr = curr * curr;
    tmp /= 2;
  }
  return res;
}

template <typename T>
T power(T a, T n, T mod) {
  T res = 1;
  T tmp = n;
  T curr = a;
  while(tmp){
    if(tmp % 2 == 1){
      res = (T)(res * curr % mod);
    }
    curr = (T)(curr * curr % mod);
    tmp >>= 1;
  }

  return res;
}


