// g(l*2) = g(l)*10^kl + g(l) + bl*f(l)

mint f(ll l, ll ten) {
  if (l == 0) { return 0; }
  if (l%2 == 1) {
    ll pl = l-1;
    mint x = f(pl, ten);
    return x * ten + 1;
  } else {
    ll pl = l/2;
    mint x = f(pl, ten);
    return x * mint(ten).pow(pl) + x;
  }
}

mint g(ll l, ll ten) {
  if (l == 0) { return 0; }
  if (l%2 == 1) {
    ll pl = l-1;
    mint x = g(pl, ten);
    return x*ten + b*pl;
  } else {
    ll pl = l/2;
