using vec = vector<ll>;
using mat = vector<vec>;

mat mul(mat& A, mat& B, ll mod) {
	mat C(A.size(), vec(B[0].size(), 0));
	for (int i = 0; i < A.size(); i++) {
		for (int k = 0; k < B.size(); k++) {
			for (int j = 0; j < B[0].size(); j++) {
				(C[i][j] += A[i][k] * B[k][j] % mod) %= mod; 
			}
		}
	}
	return C;
}

mat pow(mat A, ll n, ll mod) {
	mat B(A.size(), vec(A.size(), 0));
	for (int i = 0; i < A.size(); i++) {
		B[i][i] = 1;
	}
	while (n > 0) {
		if (n & 1) B = mul(B, A, mod);
		A = mul(A, A, mod);
		n >>= 1;
	}
	return B;
}

const ll MOD = 1000000007;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

map<ll, int> prime_factor(ll n) {
    map<ll, int> res;
    for (ll i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            ++res[i];
            n /= i;
        }
    }
    if (n != 1) res[n] = 1;
    return res;
}

ll euler(ll n) {
    map<ll, int> pv = prime_factor(n);
    ll res = 1;
    for (auto& p : pv) {
        ll hoge = 1;
        for (int i = 0; i < p.second - 1; i++) {
            hoge *= p.first;
        }
        res *= (hoge * p.first - hoge);
    }
    return res;
}

