////////////////////

int upper(llong l, llong r, llong A, llong B, llong target)
{
	if (A + B * r < target) { return r; }

	llong m = l;
	while (r > l)
	{
		m = (l + r) / 2;
		llong x = A + B * m;

		if (x < target)
		{
			l = m;
		}
		else
		{
			r = m;
		}

		if (l + 1 == r && A + B * l < target && A + B * r >= target)
		{
			return r;
		}
	}
	return m;
}

struct X
{
	const llong k;
	const llong A;
	const llong B;
	const llong MOD;

	llong pow10(llong x  =1)
	{
		return modPow(10, k * x, MOD);
	}

	llong f(llong l)
	{
		if (l == 1) { return 1; }

		// f(l+1) = f(l) * pow(10, k) + 1
		// f(l*2) = f(l) * pow(10, k * l) + f(l)
		if (l & 1)
		{
			llong ll = l - 1;
			return (f(ll) * pow10() + 1) % MOD;
		}
		else
		{
			llong ll = l / 2;
			return (f(ll) * pow10(l) + f(ll)) % MOD;
		}
	}

	llong g(llong l)
	{
		if (l == 0) { return 0; }
		// g(l+1) = g(l) * pow(10, k) + 1
		// g(l*2) = g(l) * pow(10, k * l) + g(l) + B * ll * f(l)
		assert(l <= MOD);
		if (l & 1)
		{
			llong ll = l - 1;
			return (g(ll) * pow10() + B * ll) % MOD;
		}
		else
		{
			llong ll = l / 2;
			return (g(ll) * pow10(ll) + g(ll) + B * ll * f(ll)) % MOD;
		}
	}
};


void solve()
{
	READ(llong, L, A, B, MOD);

	std::vector<llong> index;
	{
		llong t = 1;
		llong l = 0;
		REP(i, 18)
		{
			index.push_back(upper(l, L, A, B, t));
			t *= 10;
		}
	}
	index.push_back(L);

	A %= MOD;
	B %= MOD;


	llong ans = 0;
	REP(i, index.size() - 1)
	{
		llong k = i + 1;
		llong n = (index[i + 1] - index[i]);
		if (n == 0) { continue; }
		llong a = (A + B * index[i]) % MOD;

		X x{ k, a, B, MOD };
		ans = ans * modPow(10, n * k, MOD);
		ans %= MOD;

		DEBUG("ans: ", ans);
		DEBUG("a: ", a);
		DEBUG("F: ", x.f(n));
		DEBUG("G: ", x.g(n));
		ans += a * x.f(n) % MOD;
		ans += x.g(n) % MOD;
		DEBUG("ans -> ", ans);
		ans %= MOD;
	}
	WRITE(ans);

}

