    ll res=0,keta=1;
    ll ans=0;
    ll now=10;
    while(now<=(ll)1e18){
        ll next=(now-1-a)/b;
        if(next>l-1)next=l-1;
        if(next*b>=now-a){
            keta++;now*=10;
