int solve(ll L,ll R,int id)
{
	ll n=(R-L)/b+1;
	for(int i=0;i<3;i++)for(int j=0;j<3;j++)ret.a[i][j]=i==j;
	A.init(id);
	while(n)
	{
		if(n&1)ret=ret*A;
		A=A*A,n>>=1;
	}
	ans=(1ll*ans*ret.a[0][0]+L%m*ret.a[1][0]+b%m*ret.a[2][0])%m;
