    unsigned long long tot_len = 0;
    for (int i = 0; i < len.size(); ++i) {
        tot_len += 1LLU * len[i] * (v[i + 1] - v[i]);
    }
    for (int i = 0; i < len.size(); ++i) {
        //cout << len[i] << " [" << v[i] << " " << v[i + 1] << ")" << endl;
        tot_len -= 1LLU * len[i] * (v[i + 1] - v[i]);
        ans += calc(len[i], v[i], v[i + 1] - 1, tot_len);
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

