    for (int i = 0; i < sz; i++) {
      for (int j = 0; j < sz; j++) {
        for (int k = 0; k < sz; k++) {
          c.at(i).at(k) += a.at(i).at(j) * b.at(j).at(k);
        }
      }
    }
    return c;
