const int M = 18;

int mod;

struct Mat
{
	int m[3][3];

	Mat(int v)
	{
		memset(m, 0, sizeof m);
		for(int i=0; i<3; i++)
			m[i][i] = v;
	}

	Mat operator* (const Mat &a) const
	{
		Mat r(0);
		for(int i=0; i<3; i++)
			for(int j=0; j<3; j++)
				for(int k=0; k<3; k++)
					r.m[i][j] = (r.m[i][j] + m[i][k] * 1ll * a.m[k][j]) % mod;
		return r;
	}

};

int modexp(Mat a, long b, int s)
{
	Mat r(1);
	while(b)
	{
		if(b & 1)
			r = r * a;
		a = a * a;
		b >>= 1;
	}
	return (s * 1ll * r.m[0][1] + r.m[0][2]) % mod;
}

int modexp(int a, long b)
{
	int r = 1;
	while(b)
	{
		if(b & 1)
			r = (r * 1ll * a) % mod;
		a = (a * 1ll * a) % mod;
		b >>= 1;
	}
	return r;
}

long t[M+1];

long bs(long n, long a, long b, long lim)
{
	long l = -1, r = n;
	while(l != r)
	{
		long mid = l+r+1 >> 1;
		if(a + mid * b < lim)
			l = mid;
		else
			r = mid-1;
	}
	return l;
}

