	for(int i=1; i<=M; i++)
	{
		t1 *= 10;
		t[i] = bs(l-1, a, b, t1);
		long A = a + (t[i-1] + 1) * b;
		long n = t[i] - t[i-1];
		if(n)
		{
			Mat a(1);
			a.m[0][0] = t1 % mod;
			a.m[0][1] = 1;
			a.m[1][2] = b % mod;
			int r = modexp(a, n, A % mod);
			int x = modexp(t1 % mod, n);
			ans = (ans * 1ll * x + r) % mod;
		}
	}
