struct mint {
    ll x;
    mint(ll x = 0) : x(x % M) {}
    mint& operator += (const mint a) {
        if ( (x += a.x) >= M) { x -= M; }
        return *this;
    }
    mint& operator -= (const mint a) {
        if ( (x += M - a.x) >= M) { x -= M; }
        return *this;
    }
    mint& operator *= (const mint a) {
        (x *= a.x) %= M;
        return *this;
    }
    mint operator + (const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator - (const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator * (const mint a) const {
        mint res(*this);
        return res *= a;
    }
};

