long long P;

ll power(ll e, ll x) {
  if (x == 0) return 1;
  if (x % 2 == 0) return power((e * e) % P, x / 2);
  return (e * power(e, x - 1)) % P;
}

void mul(vvl &a, vvl &b, vvl &c) {
  int n = a.size();
  int m = b[0].size();
  c.clear();
  c.resize(n);
  for (int i = 0; i < n; i++) {
    c[i].resize(m);
    for (int j = 0; j < m; j++) {
      for (int k = 0; k < a[i].size(); k++) {
        c[i][j] += (a[i][k] * b[k][j]) % P;
        c[i][j] %= P;
      }
    }
  }
}


int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  ll l, a, b;
  cin >> l >> a >> b >> P;

  ll A = a;
  ll ans = 0;
  ll mx = 10, mn = 1;
  ll num = 0;
  for (int first = 1; first <= 19; first++) {
    ll sz = (max(mx - A, 0LL) + b - 1) / b - (max(mn - A, 0LL) + b - 1) / b;

    if (num + sz > l) sz = l - num;
    num += sz;

    vvl v({{ans, a % P, 1}});
    vvl S({
              {power(10 % P, first), 0,     0},
              {1,                    1,     0},
              {0,                    b % P, 1},
          });
    vvl I({{1, 0, 0},
           {0, 1, 0},
           {0, 0, 1}});

    auto SS = S;

    for (int k = sz; k > 0; k >>= 1) {
      if (k % 2 == 1) {
        SS = I;
        mul(S, SS, I);
      }
      mul(S, S, SS);
      S = SS;
    }

    mul(v, I, S);

    ans = S[0][0];

    a += b * sz;

    if (num == l) break;
    mx = mx * 10;
    mn = mn * 10;
  }
  cout << ans << endl;

  return 0;
}

