template<typename T>
class Matrix {
    int sz;
    int mod;
public:
    std::vector<std::vector<T>> A;
    int size() {
        return sz;
    }
    Matrix(std::vector<std::vector<T>> v, int m = default_mod) {
        mod = m;
        sz = v.size();
