        assert(sz == (int)(v[0].size()));
        A.clear();
        A.resize(sz, std::vector<T>(sz, 0));
        for(int i=0;i<sz;++i) {
            for(int j=0;j<sz;++j) {
                A[i][j] = v[i][j];
            }
        }
    }
    Matrix(Matrix<T> &B, int m = default_mod) {
        mod = m;
        sz = B.sz;
        A.clear();
        A.resize(sz, std::vector<T>(sz));
        for(int i=0;i<sz;++i) {
            for(int j=0;j<sz;++j) {
                A[i][j] = B[i][j];
            }
        }
    }
    Matrix(int n, int m = default_mod) {
        mod = m;
        sz = n;
        A.clear();
        A.resize(sz, std::vector<T>(sz, 0));
    }
    void to_I() {
        A.clear();
        A.resize(sz, std::vector<T>(sz, 0));
        for(int i=0;i<sz;++i) {
            A[i][i] = 1;
        }
    }
    void print() {
        for(int i=0;i<sz;++i) {
            for(int j=0;j<sz;++j) {
                std::cout << A[i][j] << " ";
            }
            std::cout << std::endl;
        }
    }
    std::vector<T>&operator[](int i) {
        return A[i];
    }
    Matrix<T> &operator+=(Matrix<T> B) {
        for(int i=0;i<sz;++i) {
            for(int j=0;j<sz;++j) {
                A[i][j] += B[i][j];
                A[i][j] %= mod;
            }
        }
        return (*this);
    }
    Matrix<T> &operator*=(Matrix<T> B) {
        std::vector<std::vector<T>> C(sz, std::vector<T>(sz, 0));
        for(int i=0;i<sz;++i) {
            for(int j=0;j<sz;++j) {
                for(int k=0;k<sz;++k) {
                    C[i][j] += (A[i][k] * B[k][j]) % mod;
                    C[i][j] %= mod;
                }
            }
        }
        A = C;
        return (*this);
    }
    std::vector<T> operator *(std::vector<T> v) {
        assert(sz = (int)(v.size()));
        std::vector<T> res(sz, 0);
        for(int i=0;i<sz;++i) {
            for(int j=0;j<sz;++j) {
                res[i] += (A[i][j] * v[j]) % mod;
                res[i] %= mod;
            }
        }
        return res;
    }
    Matrix<T> &operator^=(long long k) {
        Matrix<T> B(sz, mod);
        B.to_I();
        while(k > 0) {
            if(k&1) B *= *this;
            *this *= *this;
            k = k >> (1ll);
        }
        A = B.A;
        return (*this);
    }
};
