Int mod_pow(Int x, Int a, Int m = MOD){
    if(a == 0)return 1;
    Int res = mod_pow(x, a / 2, m);
    res = res * res % m;
    if(a % 2)res *= x;
    return res % m;
}

Int inv(Int x, Int m = MOD){
    return mod_pow(x, m-2, m);
}


//1 + x + x^2+ .. + x^k 
Int sum_of_xk(Int x, Int k){
    if(k == 0)return 1;
    if(k % 2 == 0)return (mod_pow(x, k, m) + sum_of_xk(x, k-1)) % m;
    else {
        Int tmp = sum_of_xk(x, (k-1) / 2);
        return tmp * (1 + mod_pow(x, (k+1) / 2, m)) % m;
    }
}

Int sum_of_kxk(Int x, Int k ){
    if(k == 0)return 0;
    if(k % 2 == 0) return (sum_of_kxk(x, k-1) + k * mod_pow(x, k) % m) %m;
    Int even = 0, odd = 0;
    even = 2*sum_of_kxk(x*x%m, (k-1) / 2) % m;
    odd = 2 * x % m * sum_of_kxk(x*x%m,(k-1)/2) % m;
    odd += x * sum_of_xk(x*x%m, (k-1)/2);
    odd %= m;
    return (even + odd) % m;
}


Int calc(Int l, Int r, Int k, Int R){
