    res -= b * sum_of_kxk(mod_pow(10, k, m), r-l) % m;
    res %= m;
    if(res < 0)res += m;
    return res * mod_pow(10, R, m) % m;
}

Int keta(Int x){
    if(x == 0)return 0;
    return keta(x / 10) + 1;
}

