    const long l = n_k, r = pow(10, k, M), e0 = calc_e(l, r, M),
               d0 = calc_d(l, r, M), a = mod(A + B * v_k, M), b = mod(B, M);
    const long c_k = mod(mod(a * e0, M) + mod(b * d0, M), M);
