    M ret = V<V<ll>>(MSIZE, V<ll>(MSIZE));
    loop (MSIZE, i) loop (MSIZE, j) {
        loop (MSIZE, s) {
            ret[i][j] += a[i][s] * b[s][j] % m;
            ret[i][j] %= m;
        }
    }
    return ret;
}

