ll pow(ll n, ll x = 10)
{
    if (n == k && x == 10)
    {
        return pp10[n];
    }

    ll re = 1;
    ll bit = 1;

    for (ll i = 0; i <= 62; ++i)
    {
        if (n & bit)
            re = re * x % m;
        x = x * x % m;
        bit *= 2;
    }

    return re;
}

ll f(ll l)
{
    if (l == 1)
        return 1;
    if (l % 2)
        return (f(l - 1) * pow(k) + 1) % m;
    return (1 + pow(l / 2, pow(k))) * f(l / 2) % m;
}

ll g(ll l)
{
    if (l == 1)
        return 0;
    if (l % 2)
        return (pow(k) * g(l - 1) + (l - 1)) % m;
    return ((1 + pow(l / 2, pow(k))) * g(l / 2) + l / 2 * f(l / 2)) % m;
}

