            ++d;
            X /= 10;
        }
        while(ub - lb > 1){
            ll mid = (lb + ub) / 2;
            X = A + B * mid;
            int k = 0;
            while(X > 0){
                ++k;
                X /= 10;
            }
            if(k > d)   ub = mid;
            else    lb = mid;
        }
        table.emplace_back(d, l, ub);
        l = ub;
    }

    using Vec = vector<ll>;
    using Matrix = vector<Vec>;
    auto Mul = [&](const Matrix& X, const Matrix& Y) -> Matrix {
        Matrix res(X.size(), Vec(X[0].size(), 0));
        for(int i = 0; i < (int)X.size(); ++i){
            for(int k = 0; k < (int)X[0].size(); ++k){
                for(int j = 0; j < (int)Y.size(); ++j){
                    res[i][j] = (res[i][j] + X[i][k] * Y[k][j] % M) % M;
                }
            }
        }
        return res;
    };
    auto Pow = [&](Matrix X, ll n) -> Matrix {
        Matrix res(X.size(), Vec(X[0].size(), 0));
        for(int i = 0; i < (int)X.size(); ++i)  res[i][i] = 1;
        while(n){
            if(n & 1)   res = Mul(res, X);
            X = Mul(X, X);
            n >>= 1;
        }
        return res;
    };

    vector<ll> pow10(19);
    pow10[0] = 1;
    for(int i = 0; i + 1 <= 18; ++i)    pow10[i + 1] = pow10[i] * 10;

    ll ans = 0;
    for(auto tup : table){
        int d;
        ll l, r;
        tie(d, l, r) = tup;
        Matrix W(3, Vec(3, 0));
        W[0][0] = pow10[d] % M;
        W[0][1] = W[1][1] = W[2][2] = 1;
        W[1][2] = B;
        W = Pow(W, r - l);
        ll X = W[0][0] * ans % M;
        X = (X + W[0][1] * A) % M;
        X = (X + W[0][2]) % M;
        ll Y = W[1][0] * ans % M;
        Y = (Y + W[1][1] * A) % M;
        Y = (Y + W[1][2]) % M;
        ans = X, A = Y;
    }

    cout << ans << endl;
}

