Matrix mul(const Matrix &A, const Matrix &B, int M) {
	Matrix C = Matrix(A.size(), vector< ll >(B[0].size(), 0));
	rep(i, C.size())
		rep(k, B.size()) if (A[i][k])
			rep(j, C[0].size())(C[i][j] += A[i][k] * B[k][j] % M) %= M;
