int pow(int n, int p, int k) {//n^k(mod p)
	if (k != 0) {
		if (p % 2 == 0) {
			int x = pow(n, p, k / 2);
			return (long long)x*x%p;
		}
		else {
			int x = pow(n, p, k - 1);
			return (long long)x*n%p;
		}
	}
	return 1;
}

