typedef double Num;
typedef vector<Num> Vec;
typedef vector<Vec> Mat;

int mrank(Mat A) {
	int n = A.size();
	int m = A[0].size();
	int ret = 0;
	for(int i = 0; i < n; i ++) {
		//DEBUG(i);
		int pivot = i;
		for(int j = i+1; j < n; j ++)
			if(abs(A[pivot][i]) < abs(A[j][i])) pivot = j;
		swap(A[i], A[pivot]);
		if(abs(A[i][i]) < EPS) continue;
		Num r = Num(1) / A[i][i];
		for(int j = i+1; j < n; j ++) {
			Num u = A[j][i] * r;
			for(int k = n-1; k >= i; k --)
				A[j][k] -= u * A[i][k];
		}
	}
	for(int i = 0; i < n; i++){
		if(abs(A[i][m-1]) > EPS)	ret = i;
	}
	/*REP(i,n) pite(ALL(A[i]));
	cout << endl;*/
	return ret;
}
