mint f(ll t, mint &c){
    if (t==0) return 0;
    if (t&1){
        return f(t-1,c)*c+1;
    }else{
        t/=2;
        return f(t,c)*(c.pow(t)+1);
    }
}

mint g(ll t, mint &c){
    if (t==0) return 0;
    if (t&1){
        return g(t-1,c)*c+t-1;
    }else{
        t/=2;
        return g(t,c)*(c.pow(t)+1)+f(t,c)*t;
    }
}

