      comp1 *= 10;
      comp2 *= 10;
    }
    comp2--;
    if(comp2 < A_ || MAX < comp1) continue;
    ll s = (comp1 - A_ + B_) / B_;
    ll t = (comp2 - A_ - 1) / B_;
    t = min(t, L-1);
    mat P(3, vec(3));
    P[0][0] = (comp2+1) % MOD; P[0][1] = 1; P[0][2] = 0;
    P[1][0] = 0; P[1][1] = 1; P[1][2] = 1;
    P[2][0] = 0; P[2][1] = 0; P[2][2] = 1;
    P = pow_mat(P, t-s+1);
    X = (P[0][0] * X) % MOD + (P[0][1] * ((A + (B * s) % MOD) % MOD)) % MOD + (P[0][2] * B % MOD);
    X %= MOD;
  }
  cout << (X + MOD) % MOD  << endl;
}

