template<typename T>
using Matrix = std::vector<std::vector<T>>;

ll mod;
template<typename T>
Matrix<T> add(const Matrix<T>& a, const Matrix<T>& b) {
	int n = a.size(), m = a[0].size();
	assert(a.size() == b.size() && a[0].size() == b[0].size());
	Matrix<T> res(n, std::vector<T>(m, 0));
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			res[i][j] = a[i][j] + b[i][j] % mod;
		}
	}
	return res;
}

template<typename T>
Matrix<T> mult(const Matrix<T>& a, const Matrix<T>& b) {//a:n*m matrix,b:m*l matrix
	int n = a.size(), m = a[0].size(), l = b[0].size();
	Matrix<T> res(n, std::vector<T>(l, 0));
	for (int i = 0; i < n; ++i) {
		for (int k = 0; k < m; ++k) {
			for (int j = 0; j < l; ++j) {
				res[i][j] += a[i][k] * b[k][j] % mod;
			}
		}
	}
	REP(i, n)REP(j, l)res[i][j] %= mod;
	return res;
}

template<typename T>
Matrix<T> fact(Matrix<T> a, long long n) {
	Matrix<T>  e(a.size(), std::vector<T>(a.size(), 0));
	for (int i = 0; i < (int)a.size(); ++i) {
		e[i][i] = 1;
	}
	while (n >= 1) {
		if (n & 1) e = mult(e, a);
		a = mult(a, a);
		n /= 2;
	}
	return e;
}
using ull =  unsigned long long;
ull po(ull a, ull n, ull m) {
	if (n == 0)return 1;
	ll d = po(a, n / 2, m);
	if (n & 1)return a * d % m * d % m;
	return d * d % m;
}
ull inv(ull a, ull m) {
	return po(a, m - 2, m);
}
int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll n, a, b;
	cin >> n >> a >> b >> mod;


	auto calc = [&](ll s, ll le, ll k) {
		ll t = 1;
		REP(j, k)t *= 10;

		Matrix<ll> cols = { {t % mod ,1}, {0,1} };
		Matrix<ll> colt = { {t % mod,1,mod - 1}, {0,t % mod,1},{0,0,1} };

		cols = fact(cols, le - 1);
		colt = fact(colt, le - 1);
		auto ress = mult(cols, Matrix<ll>({ {1},{1} }));
		auto rest = mult(colt, Matrix<ll>({ {0},{(t + 1) % mod},{1} }));
		return (ress[0][0] * s % mod - rest[0][0] * (b % mod) % mod + mod) % mod;
	};
	ull d = 0, ans = 0;
	for (int i = 17; i >= 0; --i) {
		ll t = 1;
		REP(j, i)t *= 10;

		ll r = (10 * t - a + b - 1) / b;
		ll l = (t - a + b - 1) / b;
		if (l >= n)continue;
		l = max(l, 0ll);
		r = min(r, n);
		if (l >= r)continue;
		ans += calc((a + b * (r - 1)) % mod, r - l, i + 1) * po(10, d, mod) % mod;
		ans %= mod;
		d += (r - l) * (i + 1);
	}
	cout << ans << endl;

}

