  int N = ass.size();
  // initialize
  identity_mat(bss);
  // calculate
  vector<vector<int>> xss(N, vector<int>(N, 0)), tss(N, vector<int>(N, 0));
  copy_mat(ass, xss);
  while (k > 0) {
