int digit(ll x) {
	int ans = 0;
	while (x > 0) {
		x /= 10;
		ans++;
	}
	return ans;
}

vvmodll mul(vvmodll A, vvmodll B) {
	vvmodll C(A.size(), vmodll(B[0].size()));
	Loop(i, A.size()) {
		Loop(j, B[0].size()) {
			Loop(k, A[0].size()) {
				C[i][j] += A[i][k] * B[k][j];
			}
		}
	}
	return C;
}

vmodll mul(vvmodll A, vmodll x) {
	vmodll y(A.size());
	Loop(i, A.size()) {
		Loop(j, x.size()) {
			y[i] += A[i][j] * x[j];
		}
	}
	return y;
}

vvmodll pow(const vvmodll &A, ll p) {
	vvmodll ret(A.size(), vmodll(A.size()));
	if (p == 0) {
		Loop(i, A.size()) ret[i][i] = 1;
		return ret;
	}
	else if (p == 1) return A;
	else {
		ret = pow(A, p / 2);
		ret = mul(ret, ret);
		if (p % 2 == 1) ret = mul(ret, A);
		return ret;
	}
}

