LL calc_ketasuu(LL num)
{
	return ceil(log10(num));
}

void solve()
{
	LL L, A, B, M;
	LL kakeru, ketasuu;
	LL ans;
	LL tmp;

	cin >> L >> A >> B >> M;

	kakeru = 1;
	ans = 0;
	for (int i = L - 1; i >= 0; i--) {
		tmp = A + B * i;
		ans = (ans + (tmp * kakeru)) % M;
        ketasuu = calc_ketasuu(tmp);
		FOR(j, 0, ketasuu) {
			kakeru *= 10;
		}
	}

	cout << ans << endl;
}

int main(void)
{
	solve();

	return 0;
}

