ll cle(ll l, ll r) {
	if (l == 0)
		return 0;
	if (l % 2 == 1) {
		l--;
		return inff(r * cle(l,r) + 1);
	}
	else
	{
		l /= 2;
		ll rl = getpow(r, l);
		return inff((rl + 1) * cle(l,r));
	}
}
ll cld(ll l, ll r, ll a, ll b) {
	if (l == 0)
		return 0;
	if (l % 2 == 1) {
		l--;
		ll bl = inff(b * l);
		return inff(r * cld(l, r, a, b) + inff(a + bl));
	}
	else {
		l /= 2;
		ll bl = inff(b * l);
		ll rl = getpow(r, l);
		return inff(inff(rl + 1) * cld(l,r,a,b) + inff(bl * cle(l,r)));
	}
}
