inline ll mul(ll x, ll y) {
  if (x > m) x %= m;
  if (y > m) y %= m;
  return (x * y) % m;
}

inline ll add(ll x, ll y) {
  if (x > m) x %= m;
  if (y > m) y %= m;
  ll s = (x + y) % m;
  if (s < 0) return s + m;
  return s;
}

int check(ll i) {
