using namespace std;

using ll = long long;
using ld = long double;

inline ll ceil_ll(ll x, ll y) { return (x + y - 1) / y; }

using Matrix = vector<vector<ll>>;
Matrix mulMatrix(const Matrix &A, const Matrix &B, const ll MOD) {
    vector<vector<ll>> C(3, vector<ll>(3));
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < 3; ++k) {
                (C[i][j] += (A[i][k] * B[k][j]) % MOD) %= MOD;
            }
        }
    }
    return C;
}

Matrix powMatrix(Matrix A, ll e, const ll MOD) {
    vector<vector<ll>> X(3, vector<ll>(3));
    X[0][0] = X[1][1] = X[2][2] = 1;
    for ( ; 0 < e; e >>= 1) {
        if (e & 1) X = mulMatrix(X, A, MOD);
        A = mulMatrix(A, A, MOD);
    }
    return X;
}

ll pow10_ll(ll e, const ll MOD) {
    ll a = 10, x = 1;
    for ( ; 0 < e; e >>= 1) {
        if (e & 1) (x *= a) %= MOD;
        (a *= a) %= MOD;
    }
    return x;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    // cout << setprecision(8) << setiosflags(ios::fixed);

    ll L, A, B, M;
    cin >> L >> A >> B >> M;

    constexpr int DIGITS = 19;
    vector<ll> num(DIGITS);
    vector<pair<ll, ll>> seg(DIGITS);
    for (ll d = 1, pow10 = 1; d < DIGITS; ++d) {
        seg[d].first = ceil_ll(pow10 - A, B);
        seg[d].second = min(ceil_ll(10 * pow10 - A - B, B), L - 1);

        ll s_l = A + B * seg[d].first, s_r = A + B * seg[d].second;
        if (pow10 <= s_l && s_r < 10 * pow10 && seg[d].first <= seg[d].second)
            num[d] = seg[d].second - seg[d].first + 1;

        pow10 *= 10;
    }

    vector<ll> mul(DIGITS);
    for (int d = DIGITS - 2; 0 < d; --d) {
        mul[d] = mul[d + 1] + (d + 1) * num[d + 1];
    }

    ll ans = 0;
    for (ll d = 1, pow10 = 10; d < DIGITS; ++d) {
        if (num[d] != 0) {
            vector<vector<ll>> X(3, vector<ll>(3));
            X[0][0] = pow10; X[0][1] = 1;
            X[1][1] = 1; X[1][2] = B;
            X[2][2] = 1;

            X = powMatrix(X, num[d], M);

            const ll s0 = (A + B * seg[d].first) % M;
            ll s = (X[0][1] * s0 + X[0][2]) % M;
            (ans += (s * pow10_ll(mul[d], M)) % M) %= M;
        }

        (pow10 *= 10) %= M;
    }

    cout << ans << endl;

    return 0;
}

