// k 桁になる要素の添え字の両端の添え字
pair<ll,ll> ketaRange(ll A, ll B, ll L, int k) {
  ll lb, ub;
  {
    ll lo = -1;
    ll hi = L;
    while (hi - lo > 1) {
      ll mid = (hi + lo) / 2;
      int keta = getKeta(A + B * mid);
      if (keta < k) { lo = mid; } else { hi = mid; }
    }
    lb = hi;
  }
  {
    ll lo = -1;
    ll hi = L;
    while (hi - lo > 1) {
      ll mid = (hi + lo) / 2;
      int keta = getKeta(A + B * mid);
      if (keta <= k) { lo = mid; } else { hi = mid; }
    }
    ub = hi;
  }
  return {lb, ub};
}

