pair<long long, long long> rec(long long x, long long k, long long mod){
  if(k == 1) return {1,0};
  pair<long long,long long> p = rec(x,k/2,mod);
  long long f = p.first, s = p.second;
  long long f_ = f*(1+mod_pow(x,k/2,mod))%mod;
  if(k%2) f_ += mod_pow(x,k-1,mod), f_ %= mod;
  long long s_ = (s + (s+f*(k/2)%mod)%mod*mod_pow(x,k/2,mod)%mod)%mod;
  if(k%2) s_ += (k-1)%mod*mod_pow(x,k-1,mod)%mod, s_ %= mod;
  return {f_,s_};
}

