inline ll mul(ll x, ll y) {
  if (x > m) x %= m;
  if (y > m) y %= m;
  return (x * y) % m;
}

inline ll add(ll x, ll y) {
  ll s = (x + y) % m;
  if (s < 0) return s + m;
  return s;
}

int check(ll i) {
  if (i == -1) return 0;
  ll x = a + b * i;
  int res = 0;
  while (x) {
    x /= 10;
    res++;
  }
  return res;
}

ll pot(ll base, ll expo) {
  if (expo == 0) return 1;
  ll y = pot(base, expo / 2);
  y = mul(y, y);
  if (expo & 1) return mul(y, base);
  return y;
}

// (1 + x + x^2 + ... + x^n) % m
ll geo_sum(ll n, ll x) {
  if (n == 0) return 1;
  if (n&1) {
    ll y = geo_sum(n/2, mul(x, x));
    return mul(add(1, x), y);
  } 
  ll z = pot(x, n);
  ll y = geo_sum(n-1, x);
  return add(z, y);
}

// d/dx {geo_sum(n, x)}
ll geo_sum_dif(ll n, ll x) {
  if (n == 0) return 0;
  if (n&1) {
    ll s1 = geo_sum(n/2, mul(x,x));
    ll s2 = mul(mul(2, x), geo_sum_dif(n/2, mul(x, x)));
    s2 = mul(add(1,x), s2);
    return add(s1, s2);
  }
  ll s1 = geo_sum_dif(n-1, x);
  ll s2 = mul(n, pot(x, n-1));
  return add(s1, s2);
}

// x + 2x^2 + 3x^3 + ... + nx^n
ll special_sum(ll n, ll x) {
  ll y = geo_sum_dif(n, x);
  return mul(x, y);
}


