		{
			continue;
		}

		mat recurrenceMatrix(4, 4);
		recurrenceMatrix(0, 0) = rll(base), recurrenceMatrix(0, 1) = 0, recurrenceMatrix(0, 2) = 0, recurrenceMatrix(0, 3) = 0,
