int lower_rem_v(int kei, int rem, int x) {
    if (rem >= x) return rem;
    return (x - rem + kei - 1) / kei * kei + rem;
}
int upper_rem_i(int kei, int rem, int x) {
    if (rem > x) return 0;
    return (x - rem + kei) / kei;
}
int upper_rem_v(int kei, int rem, int x) {
    if (rem > x) return rem;
    return (x - rem + kei) / kei * kei + rem;
}


