vector<vector<ll> > matrixPow(vector<vector<ll> > mat, ll n) {
    vector<vector<ll> > res;
    FOR(i,0,2) res.emplace_back(vector<ll> {0,0,0});
    FOR(i,0,2) res[i][i] = 1;
    while (n > 0) {
        if (n & 1LL) res = res * mat;
        mat = mat * mat;
        n >>= 1LL;
    }
    return res;
}

