mint f(mint x, int n) {
    if (n == 0) return 0;
    Matrix<mint> m(2,2);
    mint init[2][2] = {
        { x, 1 },
        { 0, 1 }
    };
    rep (i,2) rep (j,2) m[i][j] = init[i][j];
    m = m.pow(n);
    return m[0][1];
}

mint g(mint x, int n) {
    if (n == 0) return 0;
    Matrix<mint> m(3,3);
    mint init[3][3] = {
        { x, 1, 0 },
        { 0, 1, -1 },
        { 0, 0, 1 }
    };
    rep (i,3) rep (j,3) m[i][j] = init[i][j];
    m = m.pow(n-1);
    return m[0][0]*(n-1) + m[0][1]*(n-2) + m[0][2];
}

