int M;

vvi mat_mul(const vvi &A, const vvi &B) {
    int sn = sz(A);
    int sm = sz(A[0]);
    assert(sz(B) == sm);
    int sl = sz(B[0]);

    vvi ret(sn, vi(sl));
    rep(y, 0, sn) {
        rep(x, 0, sl) {
            int tmp = 0;
            rep(k, 0, sm) {
                tmp += A[y][k] * B[k][x] % M;
                tmp %= M;
            }
            ret[y][x] = tmp;
        }
    }
    return ret;
}

vvi mat_pow(vvi A, int pw) {
    assert(sz(A) == sz(A[0]));
    int size = sz(A);

    vvi ret(size, vi(size, 0));
    rep(i, 0, size) ret[i][i] = 1;

    while (pw) {
        if (pw & 1) {
            ret = mat_mul(ret, A);
        }
        A = mat_mul(A, A);
        pw >>= 1;
    }
    return ret;
}

