ll pow_(ll x, ll t) {
  if (t == 0) return 1;
  if (t%2 == 1) {
    return pow_(x,t-1)*x%mod;
  } else {
    ll y = pow_(x,t/2);
    return y*y%mod;
  }
}

ll f(ll l) {
  if (l == 0) return 0;
  if (l%2 == 1) {
    ll pl = l-1;
    ll x = f(pl);
    return (x*(ten%mod) + 1) % mod;
  } else {
    ll pl = l/2;
    ll x = f(pl);
    return (x*pow_(ten%mod, pl) + x) % mod;
  }
}
ll g(ll l) {
  if (l == 0) return 0;
  if (l%2 == 1) {
    ll pl = l-1;
    ll x = g(pl);
    return (x*(ten%mod) + b*(pl)) % mod;
  } else {
    ll pl = l/2;
    ll x = g(pl);
    return (x*pow_(ten%mod, pl) + x + b*(pl)%mod*f(pl)) % mod;
  }
}

