int mod;
ll b, ten;

ll f(ll l) {
  if (l == 0) return 0;
  if (l%2 == 1) {
    ll pl = l-1;
    ll x = f(pl);
    return (x*(ten%mod) + 1) % mod;
  } else {
    ll pl = l/2;
    ll x = f(pl);
    return (x*pow_(ten%mod, pl) + x) % mod;
  }
}
ll g(ll l) {
  if (l == 0) return 0;
  if (l%2 == 1) {
    ll pl = l-1;
    ll x = g(pl);
    return (x*(ten%mod) + b*(pl)) % mod;
  } else {
    ll pl = l/2;
    ll x = g(pl);
    return (x*pow_(ten%mod, pl) + x + b*(pl)%mod*f(pl)) % mod;
  }
}

int main() {
  ll L, a;
  cin >> L >> a >> b >> mod;
  ll last = a+b*(L-1);
  ll ans = 0;
  ten = 1;
  for (int i = 1; i <= 18; ++i) {
    ll l = ten, r = ten*10-1;
    if (last < l) continue;
    if (a > r) continue;
    ll na = 0; // 初項
    ll nl = 0; // 長さ
    {
      if (a >= l) na = a;
      else {
        na = ((l-a)+(b-1))/b*b+a;
        na = min(na, last);
      }
    }
    {
      ll nlast = 0;
      if (last <= r) nlast = last;
      else {
        nlast = (r-a)/b*b+a;
      }
      nl = (nlast-na)/b+1;
    }
    ten *= 10;
    (ans += na*f(nl) % mod) %= mod;
    (ans += g(nl)) %= mod;
  }
  cout << ans << endl;
