        assert(n == x.n && m == x.m);
        rep (i,n) rep (j,m) a[i][j] += x[i][j];
        return *this;
    }
    Matrix& operator-=(Matrix const& x) {
        assert(n == x.n && m == x.m);
        rep (i,n) rep (j,m) a[i][j] -= x[i][j];
        return *this;
    }
