    Matrix operator-(Matrix const& x) const { return Matrix(*this) -= x; }
    Matrix operator*(Matrix const& x) const {
        assert(m == x.n);
        Matrix ret(n,x.m);
        rep (i,n) rep (j,m) rep (k,x.m) ret[i][k] += a[i][j] * x[j][k];
        return ret;
    }
