}

mat pow_mat(mat mt_a, ll k) {
	mat mt_b(mt_a.size(), vec(mt_a.size()));
	rep(i, mt_a.size()) mt_b[i][i] = 1;
	while (k > 0) {
		if (k % 2) mt_b = mul(mt_b, mt_a);
		mt_a = mul(mt_a, mt_a);
		k /= 2;
	}
	return mt_b;
}

