mat mul(mat &A, mat &B) {
    mat C(A.size(), vec(B[0].size()));
    for(int i = 0; i < A.size(); i++) {
        for(int j = 0; j < B[0].size(); j++) {
            for(int k = 0; k < B.size(); k++) C[i][j] = (C[i][j] % m + ((A[i][k] % m) * (B[k][j] % m)) % m ) % m;
        }
    }
    return C;
}

mat pow(mat A, ll n) {
    mat B(A.size(), vec(A.size()));
    for(int i = 0; i < A.size(); i++) B[i][i] = 1LL;
    if(n == 0) return B;
    mat C(A.size(), vec(A.size()));
    C = pow(mul(A, A), n / 2);
    if(n & 1) C = mul(C, A);
    return C;
}

