const ll MAX_RANGE = 5e10;

int N;
ll lmn, rmx, tmn, bmx;
ll direction[4][2];

ll calc(ll mn, ll mx, int i1, int i2, ll t) {
    ll r = mx, l = mn;
    if (direction[i1][1] != MAX_RANGE) {
        r = max(r, direction[i1][1]-t);
        l = min(l, direction[i1][0]-t);
    }
    if (direction[i2][1] != MAX_RANGE) {
        r = max(r, direction[i2][1]+t);
        l = min(l, direction[i2][0]+t);
    }
    return r-l;
}

ll calcArea(ll t) {
    ll c = calc(lmn, rmx, LEFT, RIGHT, t) * calc(tmn, bmx, DOWN, UP, t);
    return c;
}

void candidates(ll mn, ll mx, int i1, int i2, vi& cand) {
    ll lo = -1, hi = MAX_RANGE;
    while (hi - lo > 2) {
        ll m1 = (hi+2*lo)/3;
        ll m2 = (2*hi+lo)/3;
        if (calc(mn, mx, i1, i2, m1) > calc(mn, mx, i1, i2, m2)) lo = m1;
        else hi = m2;
    }
    ll minValue = calc(mn, mx, i1, i2, lo+1);
    ll minTime = lo+1;

    lo = -1, hi = minTime;
    while (hi - lo > 1) {
        ll mid = (hi+lo)/2;
        if (calc(mn, mx, i1, i2, mid) == minValue) hi = mid;
        else lo = mid;
    }
    cand.PB(hi);

    lo = minTime, hi = MAX_RANGE;
    while (hi - lo > 1) {
        ll mid = (hi+lo)/2;
        if (calc(mn, mx, i1, i2, mid) == minValue) lo = mid;
        else hi = mid;
    }
    cand.PB(lo);
}

ld solve() {
    ll ans = 1e18;
    vi cands(1);
    candidates(lmn, rmx, LEFT, RIGHT, cands);
    candidates(tmn, bmx, DOWN, UP, cands);
    FORE (c, cands) {
        ans = min(ans, calcArea(c));
    }
    return ans/4.0l;
}

