ll mod;

ll mod_pow(ll a, ll n) {
	if(n == 0) return 1;
	ll res = mod_pow(a, n / 2);
	if(n % 2 == 0) return res * res % mod;
	else return a * res % mod * res % mod;
}

mat mat_mul(const mat &A, const mat &B) {//if invalid, assert. taking mod.
	assert((int)A[0].size() == (int)B.size());
	mat C(A.size(), vl(B[0].size()));
	rep(i, 0, (int)A.size()) {
		rep(k, 0, (int)B.size()) {
			rep(j, 0, (int)B[0].size()) {
				C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod;
			}
		}
	}
	return C;
}

mat mat_pow(mat A, ll n) {
	mat B((int)A.size(), vl((int)A.size()));
	rep(i, 0, (int)A.size()) {
		B[i][i] = 1;
	}
	while(n > 0) {
		if(n & 1) B = mat_mul(B, A);
		A = mat_mul(A, A);
		n >>= 1;
	}
	return B;
}

ll L, A, B;
pl P[20];
ll C[20];
ll E[20];

void solve() {
	cin >> L >> A >> B >> mod;
	ll tmp = 1;
	ll at = 0;

	int i = 0;
	while(at != L) {
		tmp *= 10;
		if(A + B * at >= tmp) P[i].fst = at, P[i].sec = at;
		else {
			ll ok = at, ng = L;
			while(abs(ok - ng) > 1) {
				ll m = (ok + ng) / 2;
				if(A + B * m < tmp) ok = m;
				else ng = m;
			}
			P[i].fst = at, P[i].sec = ok + 1;
			at = ok + 1;
		}
		i++;
	}
	int M = i;

	tmp = 1;
	rep(i, 0, M) {
		MUL(tmp, 10);
		mat D = mat(3, vl(3, 0));
		D[0][0] = tmp;
		D[1][0] = tmp;
		D[1][1] = tmp;
		D[2][0] = (A + B * (P[i].sec - 1)) % mod;
		D[2][1] = (mod - B % mod) % mod;
		D[2][2] = 1;

		mat vec = mat(3, vl(1, 0)); vec[0][0] = 1;
		auto R = mat_mul(mat_pow(D, P[i].sec - P[i].fst), vec);
		C[i] = R[2][0];
		E[i] = R[0][0];
		// debug(i, C[i], E[i], P[i], tmp);
	}
	ll res = 0;
	tmp = 1;
	rer(i, M, 0) {
		ADD(res, C[i] * tmp % mod);
		MUL(tmp, E[i]);
	}
	cout << res << "\n";
}

