lli gp(lli r,lli n)
{
    if(n==0)
        return 1;
    if(n&1)
        return ((1+r)*gp(r*r%mod,n/2))%mod;
    return (1+r*gp(r,n-1))%mod;
}

lli agp(lli r,lli n)
{
    if(n==0)
        return 0;
    if(n&1)
        return (r*(gp(r,n-1)+agp(r,n-1)))%mod;

    lli ans=0,b=po(r,n/2);

