int count_digit(const __int128 value) {
	if (value < 10) {
		return 1;
	}
	else {
		return 1 + count_digit(value / 10);
	}
}
__int128 lower_bound(const __int128 a, const __int128 b, const __int128 length, const int target) {
	__int128 left = 0;
	__int128 right = length;
	while (left < right) {
		auto mid = (left + right) / 2;
		if (count_digit(a + b * mid) < target) {
			left = mid + 1;
		}
		else {
			right = mid;
		}
	}
	return right;
}
__int128 power10(const __int128 exp, const __int128 mod) {
	if (exp == 0) {
		return 1;
	}
	else if (exp == 1){
		return 10;
	}
	else {
		auto r = power10(exp / 2, mod);
		return (((r * r) % mod) * power10(exp % 2, mod)) % mod;
	}
}
__int128 power(const __int128 base, const __int128 exp, const __int128 mod) {
	if (exp == 0) {
		return 1;
	}
	else if (exp == 1) {
		return base;
	}
	else {
		auto r = power(base, exp / 2, mod);
		return (((r * r) % mod) * power(base, exp % 2, mod)) % mod;
	}
}
__int128 upper_bound(const __int128 a, const __int128 b, const __int128 length, const int target) {
	__int128 left = 0;
	__int128 right = length;
	while (left < right) {
		auto mid = (left + right) / 2;
		if (count_digit(a + b * mid) <= target) {
			left = mid + 1;
		}
		else {
			right = mid;
		}
	}
	return right;
}
__int128 t(const __int128 base, const __int128 length, const __int128 mod) {
	if (length == 1) {
		return 1;
	}
	else if (length == 2) {
		return (base + 1) % mod;
	}
	else {
		auto r = t(base, length / 2, mod);
		return ((r + t(base, length - length / 2, mod) * power(base, length / 2, mod) % mod) % mod);
	}
}
__int128 s(const __int128 base, const __int128 length, const __int128 mod) {
	if (length == 0) {
		return 1;
	}
	else if (length == 1) {
		return length - 1;
	}
	else {
		auto r = s(base, length / 2, mod);
		auto l = s(base, length - length / 2, mod);
		r = (r + (t(base, length / 2, mod) * (length - length / 2)) % mod) % mod;
		l = (l * power(base, length / 2, mod)) % mod;
		return (l + r) % mod;
	}
}
int main() {
	long long int l, a, b, m; std::cin >> l >> a >> b >> m;
	__int128 sum = 0;
	__int128 sum_digits = 1;
	for (auto i = 18; i > 0; --i) {
		auto from = lower_bound(a, b, l, i);
		auto until = upper_bound(a, b, l, i);
		if (from != until) {
			auto temp = (((a + b * from % m) % m) * t(power10(i, m), until - from , m)) % m;
			temp = (temp + b * s(power10(i, m), until - from, m) % m) % m;
			temp = (temp * sum_digits) % m;
			sum += temp;
			sum %= m;
			for (auto c = 0; c < i; ++c) {
				sum_digits = (sum_digits * power10((until - from), m)) % m;
			}
		}
	}
	std::cout << static_cast<long long int>(sum) << std::endl;
};

