long long mod;

long long modpow(long long n, long long r) {
    n %= mod;
    long long ret = 1; long long tmp = (long long) n;
    while (r != 0) {
        if (r % 2) ret *= tmp;
        tmp *= tmp; tmp %= mod; ret %= mod;
        r /= 2;
    }
    return ret;
}

int main() {
    long long l, a, b, m; cin >> l >> a >> b >> m;
    mod = m;
    vector<long long> v[19], bb[19], tmpbb[19];
