        if (en < c[k-1]) continue;
        long long stk = max(st, (c[k-1] - a + b - 1) / b * b + a);
        long long enk = min(en, (c[k] - 1 - a) / b * b + a);
        long long lk = (enk - stk) / b + 1;
        //cout << k << " " << stk << " " << enk << " " << lk << endl;
        v[k].emplace_back(b);
        bb[k].emplace_back(b);
