        long long tmppow = c[k] % mod;
        for (int i = 0; i < 60; i++) {
            long long s = v[k].back();
            long long t = bb[k].back();
            long long x = (s * tmppow % mod + (s + t) % mod) % mod;
            v[k].emplace_back(x);
            long long y = tmpbb[k].back() * tmppow % mod; 
            tmpbb[k].emplace_back((y + tmpbb[k].back()) % mod);
            long long u = (t * tmppow % mod + t) % mod;
            u = u * 2 % mod;
            bb[k].emplace_back(u);
            tmppow = (tmppow * tmppow) % mod;
            //cout << v[k].back() << " " << bb[k].back() << endl;
        }
        long long len = 0; long long tmp = 0; long long tmpb = 0;
        for (int i = 59; i >= 0; i--) {
            if (len + (1LL << i) <= lk) {
                tmp = ((tmp * modpow(modpow(10, (1LL << i)), k) % mod));
                tmpb = ((tmpb * modpow(modpow(10, (1LL << i)), k)) % mod + tmpbb[k][i]) % mod;
                tmp += (bb[k][i] * len % mod + v[k][i]) % mod;
                tmp %= mod;
                len += 1LL << i;
            }
        }
        //cout << tmp << " " << tmpb << " " << ((mod + stk % mod - b % mod) % mod) << endl;
        tmp += ((mod + stk % mod - b % mod) % mod) * tmpb % mod;
        tmp %= mod;
        pv.emplace_back(tmp, modpow(modpow(10, lk), k));
    }
    long long ans = 0;
    for (auto it: pv) {
        //cout << it.first << " " << it.second << endl;
