    while(L>0){
        ll c = cnt(L, A, B);
        ll p = 1;
        for(ll i=0; i<nDigit(A); i++){
            p*=10;
            p%=mod;
        }
        vector<ll> b = {ans, A%mod, 1};
        vector<vector<ll>> K = {{p,  0,    0},
                                {1,  1,    0},
                                {0, B%mod, 1}};
        K = mod_pow(K, c, mod);
        vector<ll> a(3);
        a[0] = (b[0] * K[0][0] + b[1] * K[1][0] + b[2] * K[2][0]) % mod;
        a[1] = (b[0] * K[0][1] + b[1] * K[1][1] + b[2] * K[2][1]) % mod;
        a[2] = (b[0] * K[0][2] + b[1] * K[1][2] + b[2] * K[2][2]) % mod;

        ans = a[0];
        L -= c;
        A += B*c;
    }
    cout << ans << endl;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

typedef vector<ll> vec;
typedef vector<vec> mat;

mat mul(mat& A, mat& B, ll mod) {
    mat C(A.size(), vec(B[0].size(), 0));
    for (int i = 0; i < A.size(); i++) {
        for (int k = 0; k < B.size(); k++) {
            for (int j = 0; j < B[0].size(); j++) {
                (C[i][j] += A[i][k] * B[k][j] % mod) %= mod;
            }
        }
    }
    return C;
}

mat pow(mat A, ll n, ll mod) {
    mat B(A.size(), vec(A.size(), 0));
    for (int i = 0; i < A.size(); i++) {
        B[i][i] = 1;
    }
    while (n > 0) {
        if (n & 1) B = mul(B, A, mod);
        A = mul(A, A, mod);
        n >>= 1;
    }
    return B;
}

const ll MOD = 1000000007;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

map<ll, int> prime_factor(ll n) {
    map<ll, int> res;
    for (ll i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            ++res[i];
            n /= i;
        }
    }
    if (n != 1) res[n] = 1;
    return res;
}

ll euler(ll n) {
    map<ll, int> pv = prime_factor(n);
    ll res = 1;
    for (auto& p : pv) {
        ll hoge = 1;
        for (int i = 0; i < p.second - 1; i++) {
            hoge *= p.first;
        }
        res *= (hoge * p.first - hoge);
    }
    return res;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n, a, b, m;
    cin >> n >> a >> b >> m;

    ll lim_max = 1000000000000000000LL, lim_min = lim_max / 10;
    ll ans = 0;
    ll foobar = 1;
    ll e = euler(m);
    for (int i = 18; i >= 1; i--) {
        if (foobar == 0) break;
        ll ok1 = n - 1, ng1 = -1;
        while (ok1 - ng1 > 1) {
            ll mid = (ok1 + ng1) / 2;
            ll val = a + mid * b;
            if (lim_min <= val) ok1 = mid;
            else ng1 = mid;
        }

        ll ok2 = 0, ng2 = n;
        while (ng2 - ok2 > 1) {
            ll mid = (ok2 + ng2) / 2;
            ll val = a + mid * b;
            if (val < lim_max) ok2 = mid;
            else ng2 = mid;
        }

        if (ok2 < ok1) {
            lim_min /= 10;
            lim_max /= 10;
            continue;
        }

        ll v1 = a + ok1 * b;
        ll v2 = a + ok2 * b;
        if (v1 < lim_min || v1 >= lim_max || v2 < lim_min || v2 >= lim_max) {
            lim_max /= 10;
            lim_min /= 10;
            continue;
        }

        // ok1 <= ok2
        ll first_val = v1;
        ll p = ok2 - ok1 + 1;
        mat A = {{1, 0, 0}, {1, 1, 0}, {0, 1, lim_max % m}};
        A = pow(A, p, m);
        mat B = {{b % m}, {first_val % m}, {0}};
        (ans += mul(A, B, m)[2][0] * foobar % m) %= m; 

        (foobar *= modpow(10, p * i % e, m)) %= m;
        lim_min /= 10;
        lim_max /= 10;
    }
    cout << ans << endl;
    return 0;
}

