// modint {{{
template<i64 P>
struct ModIntT {
    static_assert(P >= 2, "P must be a prime");
    i64 v_;  // [0,P)

    ModIntT() : v_(0) {}
    ModIntT(i64 v) {
        i64 r = v % P;
        v_ = r >= 0 ? r : r+P;
    }

    ModIntT operator-() const {
        return ModIntT(-v_);
    }
    ModIntT& operator+=(ModIntT rhs) {
        v_ += rhs.v_;
        v_ %= P;
        return *this;
    }
    ModIntT& operator-=(ModIntT rhs) {
        v_ += P;
        v_ -= rhs.v_;
        v_ %= P;
        return *this;
    }
    ModIntT& operator*=(ModIntT rhs) {
        v_ *= rhs.v_;
        v_ %= P;
        return *this;
    }

    ModIntT& operator++() {
        return *this += 1;
    }
