template<i64 I>
struct RtModIntT {
    static i64 M;

    static i64 get_mod() { return M; }
    static void set_mod(i64 m) { M = m; }

    i64 v_;  // [0,M)

    RtModIntT() : v_(0) {}
    RtModIntT(i64 v) {
        i64 r = v % M;
        v_ = r >= 0 ? r : r+M;
    }

    RtModIntT operator-() const {
        return RtModIntT(-v_);
    }
    RtModIntT& operator+=(RtModIntT rhs) {
        v_ += rhs.v_;
        v_ %= M;
        return *this;
    }
    RtModIntT& operator-=(RtModIntT rhs) {
        v_ += M;
        v_ -= rhs.v_;
        v_ %= M;
        return *this;
    }
    RtModIntT& operator*=(RtModIntT rhs) {
        v_ *= rhs.v_;
        v_ %= M;
        return *this;
    }

    RtModIntT& operator++() {
        return *this += 1;
    }
    RtModIntT& operator--() {
        return *this -= 1;
    }
    RtModIntT operator++(int) {
        return exchange(*this, *this+1);
    }
    RtModIntT operator--(int) {
        return exchange(*this, *this-1);
    }

    explicit operator i64() const { return v_; }
};
