    1LL,
    10LL,
    100LL,
    1000LL,
    10000LL,
    100000LL,
    1000000LL,
    10000000LL,
    100000000LL,
    1000000000LL,
    10000000000LL,
    100000000000LL,
    1000000000000LL,
    10000000000000LL,
    100000000000000LL,
    1000000000000000LL,
    10000000000000000LL,
    100000000000000000LL,
    1000000000000000000LL,
};

void solve() {
    i64 L = RD();
    i64 A = RD();
    i64 B = RD();
    i64 M = RD();

    ModM::set_mod(M);

    i64 cnts[19] {};
    {
        i64 sum = 0;
        FOR(i, 1, SIZE(cnts)) {
            i64 xmax = POW10[i] - 1;
            if(A > xmax) continue;
            i64 q = (xmax-A) / B;
            i64 k = (q+1) - sum;
            cnts[i] = k;
            if(chmin(cnts[i], L-sum)) break;
            sum += k;
        }
    }
    DBG(cnts);

    vector<ModM> v { 0, A, 1 };
    FOR(i, 1, SIZE(cnts)) {
        auto mat = Matrix<ModM>::zeros(3);
        mat.at(0,0) = POW10[i];
        mat.at(0,1) = 1;
        mat.at(1,1) = 1;
        mat.at(1,2) = B;
        mat.at(2,2) = 1;

        auto matpow = mat.pow(cnts[i]);
        v = matpow * v;
    }

    PRINTLN(v[0]);
}

