#define llint long long

using namespace std;

llint n, a, b, mod;
llint beki[19];

llint modpow(llint a, llint n)
{
	if(n == 0) return 1;
	if(n % 2){
		return ((a%mod) * (modpow(a, n-1)%mod)) % mod;
	}
	else{
		return modpow((a*a)%mod, n/2) % mod;
	}
}

llint calc2(llint n, llint x)
{
	if(n == 0) return 0;
	if(n % 2){
		return (calc2(n-1, x) + modpow(10, (n-1)*x%mod) % mod) % mod;
	}
	else{
		llint res = calc2(n/2, x);
		llint ret = res * modpow(10, n/2*x) % mod + res; ret %= mod;
		return ret;
	}
}

llint calc(llint l, llint r, llint d)
{
	if(l > r) return 0;
	if(l == r) return (a%mod+b%mod*l%mod) % mod;
	if(r-l+1%2){
		return (calc(l+1, r, d) + modpow(10, (r-l)%mod*d%mod) % mod * (a%mod+b%mod*l%mod) % mod) % mod;
	}
	else{
		llint m = (l+r)/2;
		llint res = calc(l, m, d);
		llint ret = res * modpow(10, (r-m)%mod*d%mod) % mod + res; ret %= mod;
		ret += b*(r-m)%mod * calc2(r-m, d) % mod, ret %= mod;
		return ret;
	}
}

