int pow(int n, int p, int k) {//n^k(mod p)
	if (k != 0) {
		if (p % 2 == 0) {
			int x = pow(n, p, k / 2);
			return (long long)x*x%p;
		}
		else {
			int x = pow(n, p, k - 1);
			return (long long)x*n%p;
		}
	}
	return 1;
}

int logg(long long n) {
	int co = 0;
	while (n > 0) {
		n /= 10;
		co++;
	}
	return co;
}

int main() {
	long long l, a, b, m,di=1;
	cin >> l >> a >> b >> m;
	long long ans = 0;
	vector<long long> s(l,a);
	vector<int> da(l);
	da[0] = logg(a);
	for (int i = 1;i < l;i++) {
		s[i] = s[i - 1] + b;
		da[i] = logg(s[i]);
	}
	for (int i = l-1;i >-1;i--) {
		s[i] %= m;
		if (i != l - 1) {
			for (int j = 0;j < da[i + 1];j++)
				di = (di * 10) % m;
			ans = (ans + di * s[i]) % m;
		}
	}
	cout << ans << endl;
}

