ll cle(ll l,ll r,ll m) {
	if (l == 0)
		return 0;
	if (l % 2 == 0) {
		ll ol = l / 2;
		ll rl = getpow(r, ol, m);
		return (cle(ol, r, m) * ((rl + 1) % m))% m;
	}
	else {
		ll ol = l - 1;
		ll rl = getpow(r, ol, m);
		return (cle(ol, r, m) + rl) % m;
	}
}
ll cld(ll l,ll r,ll m,ll a, ll b) {
	if (l == 0)
		return 0;
	if (l % 2 == 0) {
		ll ol = l / 2;
		ll rl = (getpow(r, ol, m)+1) % m;
		ll bl = ((b * ol)% m);
		return (((rl * cld(ol, r, m, a, b)) % m) 
			+ ((bl * cle(ol, r, m)) % m)) % m;
	}
	else {
		ll ol = l - 1;
		ll abl = (a + ((b * ol)%m)) % m;
		return (((r * cld(ol, r, m, a, b)) % m) + abl) % m;
	}

}
