        {
            _l = n;
            _a = new int[_l];
            memset(_a, 0, _l * sizeof(int));
        }

        modVector(const modVector& src)
        {
            _l = src._l;
            _a = new int[_l];   
            memcpy(_a, src._a, _l * sizeof(int));         
        }

        modVector(int *a, int n)
        {
            _l = n;
            _a = new int[_l];   
            memcpy(_a, a, _l * sizeof(int));         
        } 

        modVector(const vector<int> &v)
        {
            _l = (int) v.size();
            _a = new int[_l];   
            for( int i = 0; i < _l; i++ ) _a[i] = v[i];
        }
        modVector& operator = ( const modVector& b )
        {
            if( _l != b._l )
            {
                if( _a != NULL ) delete _a;
                _l = b._l;
                _a = new int[_l];
            }
            memcpy(_a, b._a, _l * sizeof(int));
            return *this;
        }

        ~modVector()
        {
            if(_a != NULL) delete _a;
        }

        int& operator[](int k)
        {
            return _a[k];
        }

        int get(int k) const
        {
            return _a[k];
        }

        const modVector operator + (const modVector &b) const
        {
            // w == b.h, h == b.w
            modVector ans(*this);
            ans += b;
            return ans;
        }

        modVector& operator += ( const modVector& b )
        {
            for( int i = 0; i < _l; i++ ) _a[i] += b.get(i); 
            return (*this);
        }

        const modVector operator * (const modArray &b) const
        {
            // _l == b.w
            modVector ans(_l);
            for( int r = 0; r < _l; r++)
            {
                int t = 0;
                for( int i = 0; i < _l; i++ )
                {
                    t = modadd(t, modmul(get(i), b.at(r, i)));                        
                }
                ans[r] = t;
            }
            return ans;
        }

        modVector& operator *= ( const modArray& b )
        {
            *this = *this * b; 
            return (*this);
        }        

        void print() const
        {
            for( int i = 0; i < _l; i++ ) cout << _a[i] << " ";
            cout << endl;
        }        
};

