mat mul(mat &A, mat &B, ll MOD){ // A*B
  mat C(A.size(), vec(B[0].size()));
  rep(i,A.size()) rep(k,B.size()){
    rep(j,B[0].size()){
      __uint128_t a = A[i][k];
      __uint128_t b = B[k][j];
      __uint128_t ab = a*b;
      ab %= MOD;

      C[i][j] = (C[i][j]+(ll)ab)%MOD;
    }
  }
  return C;
}
mat pow(mat A, ll n, ll MOD){ // A^n
  mat B(A.size(), vec(A.size()));
  rep(i,A.size()) B[i][i] = 1;
  while(n>0){
    if(n&1) B=mul(B,A,MOD);
    A=mul(A,A,MOD);
    n>>=1;
  }
  return B;
}

ll mod_pow(ll x, ll n, ll mod){
  if(n==0) return 1;
  ll res = mod_pow(x * x % mod, n / 2, mod);
  if(n & 1) res = res * x % mod;
  return res;
}

