MAT mul(MAT &a,MAT &b,int mat_size){
    MAT c;
    REP(i,mat_size){
        REP(j,mat_size){
            c.mat[i][j]=0;
            REP(k,mat_size)(c.mat[i][j]+=a.mat[i][k] * b.mat[k][j]), c.mat[i][j] %= MOD;
        }
    }
    return c;
}

MAT ruijou(MAT &a,int power){
    MAT c,res;
    REP(i,3) REP(j,3){
        if(i != j){
            c.mat[i][j] = 0;
            res.mat[i][j] = 0;
        }
        else{
            c.mat[i][j] = 1;
            res.mat[i][j] = 1;
        }
    }
    c = mul(c,a,3);


    int tmp = 1;
    while(tmp <= power){
        if( tmp & power){
            res = mul(res,c,3);
        }
        tmp *= 2;
        c = mul(c,c,3);
    }
    return res;
}

int rui(int x, int a){
    int res = 1;
    int tmp = 1;
    while(tmp <= a){
        if(tmp & a){
            res *= x;
            res %= MOD;
        }
        tmp *= 2;
        x *= x;
        x %= MOD;
    }
    return res;
}

