    M operator-() const { return {mod()-x}; }
    M& operator+=(M r) { if ((x += r.x) >= mod()) x -= mod(); return *this; }
    M& operator-=(M r) { if ((x += mod()-r.x) >= mod()) x -= mod(); return *this; }
    M& operator*=(M r) { (x *= r.x) %= mod(); return *this; }
    M operator+(M r) const { return M(*this) += r; }
    M operator-(M r) const { return M(*this) -= r; }
    M operator*(M r) const { return M(*this) *= r; }
    M& operator/=(M r) { return *this *= r.inv(); }
    M operator/(M r) const { return *this * r.inv(); }
    M pow(ll n) const {
        if (n < 0) return inv().pow(-n);
        M v = *this, r = 1;
        for (; n > 0; n >>= 1, v *= v) if (n&1) r *= v;
        return r;
    }
    M inv() const {
        assert(x != 0);
        ll t = 1, v = x, q, r;
        while (v != 1) {
            q = mod() / v; r = mod() % v;
            if (r * 2 < v) {
                t *= -q; t %= mod(); v = r;
            } else {
                t *= q + 1; t %= mod(); v -= r;
            }
        }
        return t;
    }
    static int gen() { // assume mod():prime
        if (mod() == 2) return 1;
        vector<int> ps;
        int n = mod()-1;
        for (int i = 2; i*i <= n; ++i) {
            if (n % i) continue;
            ps.push_back(i);
            do n /= i; while (n % i == 0);
        }
        if (n > 1) ps.push_back(n);
        n = mod()-1;
        auto check = [&](M g) {
            for (int p : ps) if (g.pow(n/p) == 1) return false;
            return true;
        };
        for (int g = 2; g <= n; ++g) if (check(g)) return g;
        return -1;
    }
};
