long long MOD;
long long modpow(unsigned long long b){
  long long ans = 1;
  long long a = 10;
  while (b > 0){
    if (b % 2 == 1){
      ans *= a;
      ans %= MOD;
    }
    a *= a;
    a %= MOD;
    b /= 2;
  }
  return ans;
}
long long gp(int i, unsigned long long N){
  //1+10^i+10^2i+...+10^(N-1)i
  if (N == 1){
    return 1;
  } else {
    if (N % 2 == 0){
      long long ans = gp(i, N / 2);
      ans *= modpow(N / 2 * i) + 1;
      ans %= MOD;
      return ans;
    } else {
      long long ans = gp(i, N - 1);
      for (int j = 0; j < i; j++){
        ans *= 10;
        ans %= MOD;
      }
      ans++;
      ans %= MOD;
      return ans;
    }
  }
}
long long apgp(int i, unsigned long long N){
  //1+2*10^i+3*10^2i+...+N*10^(N-1)i
  if (N == 1){
    return 1;
  } else {
    if (N % 2 == 0){
      long long ans = apgp(i, N / 2);
      ans *= modpow(N / 2 * i) + 1;
      ans %= MOD;
      ans += gp(i, N / 2);
      ans %= MOD;
      return ans;
    } else {
      long long ans = apgp(i, N - 1);
      for (int j = 0; j < i; j++){
        ans *= 10;
        ans %= MOD;
      }
      ans += N;
      ans %= MOD;
      return ans;
    }
  }
}
long long apgp2(unsigned long long lb, unsigned long long ub, long long B, int i){
  unsigned long long len = (ub - lb) / B + 1;
  long long ans = 0;
  if (lb >= B){
    ans += gp(i, len) * ((lb - B) % MOD) % MOD;
  } else {
    ans -= gp(i, len) * ((B - lb) % MOD) % MOD;
    ans += MOD;
  }
  ans %= MOD;
  ans += B % MOD * apgp(i, len) % MOD;
  ans %= MOD;
  return ans;
}
