  reps(i, 18) {
    i64 c = (power((i64) 10, i) + B - A) / B;
    if (B * c == power((i64) 10, i) + B - A) c--;
    cnt[i] = c < 0 ? 0 : c;
  }
  rreps(i, 18) cnt[i] -= cnt[i - 1];

  mint t;
  function<mint(i64)> g = [&](i64 n) -> mint {
    if (n == 1) return 1;
    if (n % 2 == 0) {
      n /= 2;
      return g(n) * (power(t, n) + 1);
    } else {
      n -= 1;
      return g(n) + power(t, n);
    }
  };
  function<mint(i64)> h = [&](i64 n) -> mint {
    if (n == 1) return 0;
    if (n % 2 == 0) {
      n /= 2;
      return h(n) * (power(t, n) + 1) + g(n) * n;
    } else {
      n -= 1;
      return h(n) + g(n);
    }
  };
  function<mint(i64, i64, i64)> f = [&](i64 n, i64 x, i64 y) -> mint {
    return g(n) * x + h(n) * y;
  };

  mint ans = 0;
  i64 s = 1;
  reps(i, 18) {
    i64 c = min(L, cnt[i]);
    if (c == 0) continue;

    t = power((mint) 10, i);
    ans *= power(t, c);
    ans += f(c, A + B * (s - 1), B);

    L -= c, s += c;
  }
  cout << ans << '\n';
}

