mint calc(mint a, mint r, mint d, int n) {
  if (n == 0) return 0;
  if (n % 2) return calc(a, r, d, n - 1) + pow(r, n - 1) * (a - d * (n - 1));
  return calc(a, r, d, n / 2) * (pow(r, n / 2) + 1) - d * (n / 2) * pow(r, n / 2) * mint::geometric_progression(r, n / 2);
}
