ll M;

mat mul (mat &A, mat &B) {
    mat C(A.size(), vec(B[0].size()));
    Rep (i, A.size()) {
        Rep (k, B.size()){
            Rep (j, B[0].size()) {
                C[i][j] = (C[i][j] + (A[i][k] * B[k][j]) % M) % M;
            }
        }
    }
    return C;
}

mat matpow(mat A, ll n) {
    mat B(A.size(), vec(A.size()));
    Rep (i, A.size()) {
        B[i][i] = 1;
    }
    while (n > 0) {
        if (n & 1) B = mul(B, A);
        A = mul(A, A);
        n >>= 1;
    }
    return B;
}

