    {
        for ( ll i = 0; i < (ll)mat.size(); i++ ) mat[i][i] = 1;
    }
    ll get_rows() { return mat.size(); }
    ll get_cols() { return mat[0].size(); }
    matrix operator+( matrix &b ) const
    {
        matrix temp;
        ll ro, co;
        ro = b.get_rows();
        co = b.get_cols();
        temp.resize( ro, co, 0 );
        for ( ll i = 0; i < ro; i++ )
        {
            for ( ll j = 0; j < co; j++ )
            {
                // temp.mat[i][j]=mat[i][j]+b.mat[i][j];
                temp.mat[i][j] = ( mat[i][j] % MOD ) + ( b.mat[i][j] % MOD );
                temp.mat[i][j] %= MOD;
            }
        }
        return temp;
    }
    matrix operator*( matrix &b ) const
    {
        matrix temp;
        ll ro, co;
        ro = mat.size();
        co = b.get_cols();
        ll mi = b.get_rows();
        temp.resize( ro, co, 0 );
        for ( ll i = 0; i < ro; i++ )
