                    temp.mat[i][j] +=
                        ( ( mat[i][k] % MOD ) * ( b.mat[k][j] % MOD ) );
                    temp.mat[i][j] %= MOD;
                }
            }
        }
        return temp;
    }
    void print()
    {
        for ( auto &i : mat )
        {
            for ( auto &j : i ) cout << j << " ";
            cout << endl;
        }
    }
};

matrix power( matrix a, ll b )
{
    matrix ans;
    ans.resize( a.get_rows(), a.get_cols(), 0 );
    ans.identity();
    while ( b )
    {
        if ( b & (ll)1 ) { ans = ans * a; }
        a = a * a;
        b >>= 1;
    }
    return ans;
}

