ll cle(ll l, ll r) {
	if (l == 0)
		return 0;

	if (l % 2 == 0) {
		l /= 2;
		ll rl = getpow(r, l);
		return inff((1 + rl) * cle(l, r));
	}
	else {
		l--;
		ll rl = getpow(r, l);
		return inff(cle(l, r) + rl );
	}
}

ll cld(ll l,ll r,ll a,ll b) {
	if (l == 0)
		return 0;
	if (l % 2 == 0) {
		l /= 2;
		ll bl = inff(b * l);
		ll rl = getpow(r, l);
		return inff(inff((1 + rl) * cld(l, r, a, b)) + inff(bl * cle(l, r)));
	}
	else {
		l--;
		ll bl = inff(b * l);
		return inff(r * cld(l, r, a, b) + a + bl);
	}

}
