long long L, A, B, M;

mat mal( mat a, mat b )
{
	mat c( 3, vec( 3 ) );
	for( int i = 0; i < 3; i++ ) {
		for( int j = 0; j < 3; j++ ) {
			for( int k = 0; k < 3; k++ ) {
				c[i][j] += a[i][k] * b[k][j] % M;
				c[i][j] %= M;
			}
		}
	}
	return c;
}

mat powmat( mat m, long long n )
{
	mat res( 3, vec( 3 ) );
	for( int i = 0; i < 3; i++ ) res[i][i] = 1;
	while( n ) {
		if( n & 1 ) res = mal( res, m );
		m = mal( m, m );
		n >>= 1;
	}
	return res;
}

int main() {

