	long long ans = 0;
	for( long long pow10 = 10; pow10 <= 1e18; pow10 *= 10 ) {
		if( pow10 <= A ) continue;
		long long Cd = (pow10 - A + B - 1) / B;
		Cd = min( Cd, L );
		mat m( 3, vec( 3 ) );
		m[0][0] = pow10 % M;
		m[1][0] = 1;
		m[1][1] = 1;
		m[2][1] = B % M;
