int check(ll i) {
  if (i == -1) return 0;
  ll x = a + b * i;
  int res = 0;
  while (x) {
    x /= 10;
    res++;
  }
  return res;
}

ll pot(ll base, ll expo) {
  if (expo == 0) return 1;
  ll y = pot(base, expo / 2);
  y = (y * y) % m;
  if (expo & 1) return (y * base) % m;
  return y;
}

// (1 + x + x^2 + ... + x^n) % m
ll geo_sum(ll n, ll x) {
  if (n == 0) return 1;
  if (n&1) {
    ll y = geo_sum(n/2, (x*x) % m);
    return ((1 + x) * y) % m;
  } 
  ll z = pot(x, n);
  ll y = geo_sum(n-1, x);
  return (z + y) % m;
}

// d/dx {geo_sum(n, x)}
ll geo_sum_dif(ll n, ll x) {
  if (n == 0) return 0;
  if (n&1) {
    ll s1 = geo_sum(n/2, (x*x)%m);
    ll s2 = ( ((2 * x) % m) * geo_sum_dif(n/2, (x*x)%m)) % m;
    s2 = ((1+x) * s2) % m;
    return (s1 + s2) % m;
  }
  ll s1 = geo_sum_dif(n-1, x);
  ll s2 = (n * pot(x, n-1)) % m;
  return (s1 + s2) % m;
}

// x + 2x^2 + 3x^3 + ... + nx^n
ll special_sum(ll n, ll x) {
  ll y = geo_sum_dif(n, x);
  return (x * y) % m;
}


ll go1(int len) {
  ll lo = -1;
  ll hi = r-1;
  while (hi - lo > 1) {
    ll mid = (lo + hi) / 2;
    if (check(mid) < len) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  if (check(hi) == len) return hi;
  return r;
}

ll go2(ll lo, ll hi, ll init_expo, ll len) {
  if (lo == hi) return 0;
  ll aux_10 = pot(10, init_expo);
  ll f1 = ((a % m) * aux_10) % m;
  ll f2 = ((b % m) * aux_10) % m;
  ll c = pot(10, len);
  // ll g1 = 0;
  // for (ll i = 0; i < hi-lo; i++) { g1 += pot(c, i); g1 %= m; }
  ll g1 = geo_sum(hi-1-lo, c);
  ll d = lo + hi - 1;
  d %= m;
  ll g21 = (g1 * d) % m;
  // ll g221 = 0;
  // for (ll i = 0; i < hi-lo; i++) { g221 += (i * pot(c, i)) % m; g221 %= m; }
  ll g221 = special_sum(hi-1-lo, c);
  ll g222 = (lo * g1) % m;

  ll sum = (g221 + g222) % m;
  ll dif = (g21 - sum) % m;
  if (dif < 0) dif += m;
  // cerr << f1 << "  " << g1 << " " << f2 << " " << dif << endl;
  return ((f1 * g1) % m + (f2 * dif) % m) % m;
}

int main() {
