            Matrix M = create(op,B);
            M = pow(M, curr+1-prev);
            s += B*prev;
            s %= mod;
            X = (X*M.data[0][0]%mod+s*M.data[1][0]%mod+M.data[2][0]%mod);
            X %= mod;
            prev = curr+1;
        }

        op *= 10;
    }

    cout<<X<<endl;

    return 0;
}

