int64_t MOD;
int64_t MODN;

struct Matrix {
    vector<int64_t> buf;
    size_t _rsize;
    Matrix(size_t row, size_t col)
        : buf(row * col)
        , _rsize(row)
    {
    }

    size_t rsize() const
    {
        return _rsize;
    }
    size_t csize() const
    {
        return buf.size() / rsize();
    }
    Matrix pow(int64_t y)
    {
        if (y == 0) {
            Matrix m(rsize(), csize());
            for (size_t i = 0; i < rsize(); i++) {
                m(i, i) = 1;
            }
            return m;
        }
        if (y % 2 == 0) {
            return ((*this) * (*this)).pow(y / 2);
        } else {
            return (*this) * (this->pow(y - 1));
        }
    }
    int64_t& operator()(size_t i, size_t j)
    {
        return this->buf[j * rsize() + i];
    }
    const int64_t& operator()(size_t i, size_t j) const
    {
        return this->buf[j * rsize() + i];
    }

    friend Matrix operator*(const Matrix& lh, const Matrix& rh)
    {
        if (lh.csize() != rh.rsize()) {
            throw runtime_error("the number of columns of 1st argument and the number of rows of 2nd argument does not match!");
        }

        Matrix result(lh.rsize(), rh.csize());
        for (size_t i = 0; i < result.rsize(); i++) {
            for (size_t j = 0; j < result.csize(); j++) {
                result(i, j) = 0;
                for (size_t k = 0; k < lh.csize(); k++) {
                    result(i, j) += lh(i, k) * rh(k, j) % MOD;
                    result(i, j) %= MOD;
                }
            }
        }
        return result;
    }
};

int64_t dpow(const int64_t x, const int64_t y)
{
    if (y == 0) {
        return 1;
    }
    if (y % 2 == 0) {
        return dpow(x * x % MOD, y / 2);
    } else {
        return x * dpow(x, y - 1) % MOD;
    }
}

int64_t inv(int64_t x)
{
    return dpow(x, MODN - 1);
}

int64_t dfloor(int64_t x, int64_t y);
int64_t dceil(int64_t x, int64_t y);

int64_t dfloor(int64_t x, int64_t y)
{
    if (y < 0) {
        return dfloor(-x, -y);
    }
    if (x < 0) {
        return -dceil(-x, y);
    }
    return x / y;
}

int64_t dceil(int64_t x, int64_t y)
{
    if (y < 0) {
        return dceil(-x, -y);
    }
    if (x < 0) {
        return -dfloor(-x, y);
    }
    return (x + y - 1) / y;
}

