using ll = int64_t;

ll get_i(ll a, ll b, ll mx) {
  mx -= a;
  if (mx < 0) return -1;
  return mx / b;
}

ll pm(ll x, ll i, ll m) {
  if (i == 0) return 1;
  if ((i%2) == 1) return (x*pm(x,i-1,m)) % m;
  ll h = pm(x,i/2,m);
  return (h*h) % m;
}

using Mat = vector<vector<ll>>;
constexpr int sz = 3;

Mat mul(const Mat& lhs, const Mat& rhs, const ll m) {
  Mat res(sz, vector<ll>(sz, 0));
  REP(i,sz)REP(j,sz)REP(k,sz) {
    res[i][j] += lhs[i][k] * rhs[k][j];
    res[i][j] %= m;
  }
  return res;
}

Mat pow_m(const Mat& lhs, const ll rhs, const ll m) {
  if (rhs == 0) {
    Mat res(sz, vector<ll>(sz, 0));
    REP(i,sz) res[i][i] = 1;
    return res;
  } else if ((rhs % 2) == 1) {
    return mul(pow_m(lhs, rhs-1, m), lhs, m);
  } else {
    const auto h = pow_m(lhs, rhs/2, m);
    return mul(h, h, m);
  }
}

ll solve(ll l, ll d, ll a, ll b, ll m) {
  Mat A(sz, vector<ll>(sz, 0));
  A[0][0] = 1;
  A[0][1] = 1;
  A[1][1] = pm(10, d, m);
  A[1][2] = pm(10, d, m);
  A[2][2] = pm(10, d, m);
  Mat Al = pow_m(A, l, m);
  vector<ll> v(sz, 0);
  v[1] = a;
  v[2] = b;
  ll r = Al[0][0] * 0 + Al[0][1] * a + Al[0][2] * b;
  return r % m;
}

int main()
{
  ll l,a,b,m;
  cin>>l>>a>>b>>m;
  vector<ll> v;
  ll p = 1;
  REP(i,19) {
    v.push_back(min(l-1, get_i(a, b, p - 1)));
    p *= 10;
  }
  a %= m;
  b %= m;
  vector<ll> df(18);
  REP(i,18) {
    ll diff = v[i+1] - v[i];  
    df[i] = diff;
  }
  ll mul = 1;
  ll sum = 0;
  for(int i=17; i>=0; --i) {
    ll a2 = a + b * ((m + v[i+1]) % m);
    a2 %= m;
    sum += solve(df[i], i+1, a2, (m - b) % m, m) * mul;
    sum %= m;
    ll tmp = pm(10, df[i], m);
    mul *= pm(tmp, i+1, m);
    mul %= m;
  }
  cout << sum << endl;
  return 0;
}

