const int MAT=3;
struct Mat { ll v[MAT][MAT]; };
Mat mulmat(Mat& a,Mat& b,int mod=1e9+7,int n=MAT) {
	Mat r;
	rep(x,n) rep(y,n) r.v[x][y]=0;
	rep(x,n) rep(z,n) rep(y,n) {
		r.v[x][y] += a.v[x][z]*b.v[z][y];
		if(r.v[x][y]>mod) r.v[x][y] -= mod;
	}
	rep(x,n) rep(y,n) r.v[x][y]%=mod;
	return r;
}
Mat powmat(ll p,Mat a,int mod=1e9+7,int n=MAT) {
	Mat r;
	rep(x,n) rep(y,n) r.v[x][y]=0;
	rep(i,n) r.v[i][i]=1;
	while(p) {
		if(p%2) r=mulmat(r,a,mod,n);
		a=mulmat(a,a,mod,n);
		p>>=1;
	}
	return r;
}

ll modpow(__int128_t a, ll n,ll mo) {
	__int128_t r=1;
	while(n) r=r*((n%2)?a:1)%mo,a=a*a%mo,n>>=1;
	return r;
}

ll l,a,b,m,shita=0,deg=1,ans,s;
ll d[100]={};  // 開始地点

bool f(ll x,ll deg){
	x = a+b*(x-1);
	if(log10(x)<deg)return true;
	return false;
}

bool g(ll deg){
	if(deg-1<=log10(a) && log10(a)<deg)return true;
	return false;
}

void init(){
