	ans=0;
	s=a%m;
}

int main(void){
	init();
	reg(i,1,19){
		ll ue=l;
		if(f(ue,i)){
			d[i]=l;
			deg=i;
			break;
		}
		if(shita==0){
			if(g(i)){
				shita=1;
			}else{
				d[i]=d[i-1];
			continue;
			}
		}
		while(ue-shita>1){
			ll mid=(ue+shita)/2;
			if(f(mid,i)){
				shita=mid;
			}else{
				ue=mid;
			}
		}
		d[i]=shita;
	}
	// reg(i,1,19)cerr<<d[i]<<" ";
