		Mat mt = {.v={{modpow(10,i,m),1,0},{0,1,b},{0,0,1}}};
		Mat mt2 = powmat(d[i]-d[i-1],mt,m);
		// cerr<<"==="<<endl;
		// rep(j,3){
		// 	rep(k,3)cerr<<mt2.v[j][k]<<" ";
		// 	cerr<<endl;
		// }
		// cerr<<"==="<<endl;
		ll ans2=((mt2.v[0][0]*ans)%m+(mt2.v[0][1]*s)%m+mt2.v[0][2])%m;
		ll s2=((mt2.v[1][0]*ans)%m+(mt2.v[1][1]*s)%m+mt2.v[1][2])%m;
		ans=ans2;
		s=s2;
		// cerr<<d[i]-d[i-1]<<" "<<ans<<" "<<s<<endl;
	}
	cout<<ans<<endl;
	return 0;
}

