template<class T> struct mat {/*@formatter:off*/
    int h, w;
    vector<vector<T>> d;
    mat() {}
    mat(int h, int w, T v = 0) : h(h), w(w), d(h, vector<T>(w)) { if(h==w)unit(v); }
    mat(vector<vector<T>> &v) : h(sz(v)), w(sz(v[0])), d(v) {}
    mat(vector<T> &v) : h(1), w(sz(v)) {d.push_back(v);}
    mat(initializer_list<T> v) {        h = 1, w = 0;        fora(a, v)w++;        d.assign(h, vector<T>(w));        int nw = 0;        fora(a, v) {            d[0][nw] = a;            nw++;        }    }
    mat(initializer_list<initializer_list<T>> v) {        h = 0, w = 0;        fora(a, v)h++;        fora(a, v) {            fora(b, a)w++;            break;        }        fora(a, v) {            int cw = 0;            fora(b, a)cw++;            assert(w == cw);/*横の長さがすべて等しいことを調べる*/}        d.assign(h, vector<T>(w));        int nh = 0, nw = 0;        fora(a, v) {            nw = 0;            fora(b, a) {                d[nh][nw] = b;                nw++;            }            nh++;        }    }

    vector<T> &operator[](int i) { return d[i]; }
    void fill(T v = 0) { rep(i, h)rep(j, w) d[i][j] = v; }
    void unit(T v = 1) {assert(h==w); rep(i,h) d[i][i] = v; }
    mat operator+(mat &a) { /* same size*/ mat res(h, w);        rep(i, h)rep(j, w) res[i][j] = d[i][j] + a[i][j];        return res;    }
    mat operator-(mat &a) { /* same size*/ mat res(h, w);        rep(i, h)rep(j, w) res[i][j] = d[i][j] - a[i][j];        return res;    }
    //参照を取らないので使いやすい このmatは行列累乗では使わないため基本これでいい
    mat operator*(mat a) {mat res(h, a.w);        rep(i, h)rep(k, w)rep(j, a.w) res[i][j] += d[i][k] * a[k][j];        return res;    }
    //参照を取るので高速powなどで使う
    void mul_fast(mat &a) {        vector<vector<T> > res(h,vector<T>(w) ) ;        rep(i, h)rep(k, w)rep(j, a.w) res[i][j] += d[i][k] * a[k][j];        swap(res,d);    }
    mat &operator+=(mat &a) { return *this = (*this) + a; }
    mat &operator-=(mat &a) { return *this = (*this) - a; }
    mat &operator*=(mat a) {  mul_fast(a);return *this; }
    mat operator^(ll n) {        assert(h == w);        mat x = *this;        mat r(h, w);        r.unit();        while (n) {            if (n & 1) r *= x;            x *= x;            n >>= 1;        }        return r;    }
    mat &operator^=(ll n) {return *this=(this)^ n;}
    mat pow(ll n) {        return operator^ (n);    }
};

