    } else {
      hi = mid;
    }
  }
  if (check(hi) == len) return hi;
  return r;
}

ll go2(ll lo, ll hi, ll init_expo, ll len) {
  if (lo == hi) return 0;
  ll aux_10 = pot(10, init_expo);
  ll f1 = mul(a, aux_10);
