                XX[i*3+k] = 0;
                for(int j=0;j<3;j++){
                    XX[i*3+k] = (XX[i*3+k] + X[i*3+j] * X[j*3+k] % mod) % mod;
                }
            }
        }
        matpow(XX, ans, n/2, mod);
    }else{
        int64_t XX[9];
        for(int i=0;i<3;i++){
            for(int k=0;k<3;k++){
