int64_t powd(int64_t a,int64_t b){//a^bを求める
	if(b==0){
		return 1;
	}else{
		int64_t temp = powd(a,b/2);
		temp = temp * temp;
		if(b%2==1){
			temp = temp * a;
		}
		return temp;
	}
}


template<class T> class matrix2d{
public:
	matrix2d(ll row,ll col):row(row),col(col){
		value.resize(row);
		for(ll i1=0;i1<row;i1++){
			value[i1].resize(col);
		}
	}
	matrix2d(ll row,ll col,T initial):row(row),col(col){
		value.resize(row);
		for(ll i1=0;i1<row;i1++){
			value[i1].resize(col,initial);
		}

	}
	template<class UnaryOperation>
	matrix2d& elementwise(UnaryOperation op){
		for(ll i1=0;i1<row;i1++){
			transform(value[i1].begin(),value[i1].end(),value[i1].begin(),op);
		}
		return *this;
	}
	template<class BinaryOperation>
	matrix2d& elementwise(const matrix2d& c,BinaryOperation op){
		for(ll i1=0;i1<row;i1++){
			transform(value[i1].begin(),value[i1].end(),c.value[i1].begin(),value[i1].begin(),op);
		}
		return *this;
	}

	//add
	matrix2d operator+(const T& c) const{
		matrix2d copy = matrix2d(*this);
		copy+=c;
		return copy;
	}
	matrix2d& operator+=(const T& c){
		auto func1 = std::bind(std::plus<T>(),std::placeholders::_1,c);
		elementwise(func1);
		return *this;
	}
	matrix2d operator+(const matrix2d& c) const{
		matrix2d copy=matrix2d(*this);
		copy+=c;
		return copy;

	}
	matrix2d& operator+=(const matrix2d& c){
		assert(col == c.col&&row==c.row);
		elementwise(c,std::plus<T>());
		return *this;
	}
	//multiply
	matrix2d operator*(const T& c) const{
		matrix2d copy = matrix2d(*this);
		copy*=c;
		return copy;
	}
	matrix2d& operator*=(const T& c){
		assert(col == c.col&&row==c.row);
		auto func1 = std::bind(std::multiplies<T>(),std::placeholders::_1,c);
		elementwise(func1);
		return *this;
	}
	matrix2d operator*(const matrix2d& c) const{
		matrix2d copy=new matrix2d(*this);
		copy*=c;
		return copy;
	}
	matrix2d& operator*=(const matrix2d& c){
		assert(col == c.col&&row==c.row);
		elementwise(c,std::multiplies<T>());
		return *this;
	}

	//subtract
	template<class U>
	matrix2d& operator-(const U &c){
		matrix2d copy=new matrix2d(*this);
		copy-=c;
		return copy;
	}
	template<class U>
	matrix2d& operator-=(const U &c){
		operator+=(c*-1);
	}
	//divide
	matrix2d operator/(const T& c) const{
		matrix2d copy = matrix2d(*this);
		copy/=c;
		return copy;
	}
	matrix2d& operator/=(const T& c){
		auto func1 = std::bind(std::divides<T>(),std::placeholders::_1,c);
		elementwise(func1);
		return *this;
	}
	matrix2d operator/(const matrix2d& c) const{
		matrix2d copy=new matrix2d(*this);
		copy/=c;
		return copy;
	}
	matrix2d& operator/=(const matrix2d& c){
		assert(col == c.col&&row==c.row);
		elementwise(c,std::divides<T>());
		return *this;
	}
	matrix2d operator%(const T &c) const{
		matrix2d copy = matrix2d(*this);
		copy%=c;
		return copy;
	}
	matrix2d& operator%=(const T& c){
		auto func1 = std::bind(std::modulus<T>(),std::placeholders::_1,c);
		elementwise(func1);
		return *this;
	}

	matrix2d dot(const matrix2d &c){
		assert(col==c.row);
		matrix2d retval(row,c.col);
		for(ll i1=0;i1<row;i1++){
			for(ll i2=0;i2<c.col;i2++){
				T sum=0;
				for(ll i3=0;i3<col;i3++){
					sum += (value[i1][i3]*c.value[i3][i2]);
				}
				retval(i1,i2)=sum;
			}
		}
		return retval;
	}

	matrix2d pow(ll b){//(この行列)^bを求める
		assert(row==col);
		if(b==0){
			//return I
			matrix2d<T> id(row,col,0);
			for(ll i1=0;i1<row;i1++){
				id(i1,i1)=1;
			}
			return id;
		}else{
			matrix2d<T> temp = pow(b/2);
			temp = temp.dot(temp);
			if(b%2==1){
				temp=temp.dot(*this);
			}
			return temp;
		}
	}
	matrix2d powmod(ll b,ll m){//(この行列)^b mod mを求める
		assert(row==col);
		if(b==0){
			//return I
			matrix2d<T> id(row,col,0);
			for(ll i1=0;i1<row;i1++){
				id(i1,i1)=1;
			}
			return id;
		}else{
			matrix2d<T> temp = powmod(b/2,m);
			temp = temp .dot(temp);
			temp%=m;
			if(b%2==1){
				temp=temp.dot(*this);
				temp%=m;
			}
			return temp;
		}
	}


	const T& operator()(ll row,ll col) const{
		return value[row][col];
	}

	T& operator()(ll row,ll col){
		return value[row][col];
	}
private:
	vector<vector <T> > value;
	ll row,col;

};
