template <class TOut, class TFunc, class TPos = llong>
TPos search_lower(TPos l, TPos r, TFunc f, TOut target)
{
	for (TPos len = r - l; len != 0; )
	{
		TPos m = l + len / 2;
		if (f(m) < target)
		{
			len -= len / 2 + 1;
			l = m + 1;
		}
		else
		{
			len /= 2;
		}
	}
	return l;
}

template <class TOut, class TFunc, class TPos>
TPos search_upper(TPos l, TPos r, TFunc f, TOut target)
{
	for (TPos len = r - l; len != 0; ) {
		TPos m = l + len / 2;

		if (f(m) >= target)
		{
			len -= len / 2 + 1;
			l = m + 1;
		}
		else
		{
			len -= len / 2;
		}
	}
	return l;
}

struct X
{
	const llong k;
	const llong A;
	const llong B;
	const llong MOD;

	map<llong, llong> fmemo, gmemo;

	llong pow10(llong x  =1)
	{
		return modPow(10, k * x, MOD);
	}

	llong f(llong l)
	{
		if (l == 1) { return 1; }
		if (fmemo.find(l) != fmemo.end()) { return fmemo[l]; }

		// f(l+1) = f(l) * pow(10, k) + 1
		// f(l*2) = f(l) * pow(10, k * l) + f(l)
		if (l & 1)
		{
			llong ll = l - 1;
			return fmemo[l] = (f(ll) * pow10() % MOD + 1) % MOD;
		}
		else
		{
			llong ll = l / 2;
			return fmemo[l] = (f(ll) * pow10(ll) % MOD + f(ll)) % MOD;
		}
	}

	llong g(llong l)
	{
		if (l == 0) { return 0; }
		if (gmemo.find(l) != gmemo.end()) { return gmemo[l]; }
		// g(l+1) = g(l) * pow(10, k) + 1
		// g(l*2) = g(l) * pow(10, k * l) + g(l) + B * ll * f(l)

		if (l & 1)
		{
			llong ll = l - 1;
			return gmemo[l] = (g(ll) * pow10() % MOD + B * ll) % MOD;
		}
		else
		{
			llong ll = l / 2;
			return gmemo[l] = ((g(ll) * pow10(ll) % MOD + g(ll) % MOD) + B * ll % MOD * f(ll)) % MOD;
		}
	}
};


void solve()
{
	READ(llong, L, A, B, MOD);

	std::vector<llong> index;
	{
		llong t = 1;
		REP(i, 18)
		{
			index.push_back(search_lower(0LL, L, CONV1(x, A+B*x), t));
			t *= 10;
		}
	}
	index.push_back(L);

	A %= MOD;
	B %= MOD;

	llong ans = 0;
	REP(i, index.size() - 1)
	{
		llong k = i + 1;
		llong n = (index[i + 1] - index[i]);
		if (n == 0) { continue; }
		llong a = (A + B * index[i]) % MOD;

		X x{ k, a, B, MOD };
		ans = ans * modPow(10, n * k, MOD);
		ans %= MOD;

		DEBUG("ans: ", ans);
		DEBUG("a: ", a);
		DEBUG("F: ", x.f(n));
		DEBUG("G: ", x.g(n));
		ans += a * x.f(n) % MOD;
		ans %= MOD;
		ans += x.g(n) % MOD;
		ans %= MOD;
		DEBUG("ans -> ", ans);
	}
	WRITE(ans);
}

