mat mul(mat &a,mat &b)
{
  mat res(a.size(),vec(b[0].size(),0));
  for(int i=0;i<a.size();i++)
  {
    for(int k=0;k<b.size();k++)
    {
      for(int j=0;j<b[0].size();j++)
      {
        res[i][j]+=a[i][k]*b[k][j];
      }
    }
  }
  return res;
}

mat pow(mat &a,ll n)
{
  mat b(a.size(),vec(a.size(),0));
  for(int i=0;i<a.size();i++)
  {
    b[i][i]=1;
  }
  while(n>0)
  {
    if(n&1)b=mul(b,a);
    a=mul(a,a);
    n>>=1;
  }
  return b;
}
