Matrix matrixmul(Matrix& a, Matrix& b) {
    Matrix c(a.size(), MatrixChild(b[0].size()));

    for (int i = 0; i < (int)a.size(); ++i)
        for (int k = 0; k < (int)b.size(); ++k)
            for (int j = 0; j < (int)b[0].size(); ++j)
                c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % mod;

