    Matrix b(a.size(), MatrixChild(a.size()));

    for (int i = 0; i < (int)a.size(); ++i)
        b[i][i] = 1;

    while (n > 0) {
        if (n & 1)
            b = matrixmul(b, a);
        a = matrixmul(a, a);
        n >>= 1;
    }

    return b;
