template< typename T >
class Matrix
{
public:
	explicit Matrix( size_t row_size, size_t col_size )
	{
		mElement.assign( row_size, vector<T>() );
		REP( i, row_size ) mElement[i].assign( col_size, T(0) );
	}

	const vector<T>& operator[] ( size_t row ) const
	{ return mElement[row]; }
	vector<T>& operator[] ( size_t row )
	{ return mElement[row]; }

	const size_t rowSize() const
	{ return mElement.size(); }
	const size_t colSize() const
	{ return mElement[0].size(); }

protected:
	vector<vector<T>> mElement;
};

template< typename T >
class SquareMatrix : public Matrix<T>
{
public:
	explicit SquareMatrix( size_t size )
		: Matrix<T>( size, size )
	{}

	void identity()
	{
		REP( i, this->rowSize() ) REP( j, this->colSize() )
			(*this)[i][j] = i == j ? T(1) : T(0);
	}

	SquareMatrix<T> operator* ( const SquareMatrix& rhs ) const
	{
		size_t size = min( this->colSize(), rhs.colSize() );
		SquareMatrix<T> ret( size );
		REP( i, size )
		REP( k, size )
		REP( j, size )
		{
			ret[i][j] = ret[i][j] + (*this)[i][k] * rhs[k][j];
		}
		return ret;
	}

	SquareMatrix<T> operator^ ( size_t n ) const
	{
		SquareMatrix base = *this;
		SquareMatrix ret( this->rowSize() );
		ret.identity();
		while( n > 0 )
		{
			if( n & 1 ) ret = ret * base;
			base = base * base;
			n >>= 1;
		}
		return ret;
	}

	SquareMatrix<T> mul ( const SquareMatrix& rhs, ll mod ) const
	{
		size_t size = min( this->colSize(), rhs.colSize() );
		SquareMatrix<T> ret( size );
		REP( i, size )
		REP( k, size )
		REP( j, size )
		{
			ret[i][j] = (ret[i][j] + (*this)[i][k] * rhs[k][j] % mod) % mod;
		}
		return ret;
	}

	SquareMatrix<T> pow ( size_t n, ll mod ) const
	{
		SquareMatrix base = *this;
		SquareMatrix ret( this->rowSize() );
		ret.identity();
		while( n > 0 )
		{
			if( n & 1 ) ret = ret.mul( base, mod );
			base = base.mul( base , mod );
			n >>= 1;
		}
		return ret;
	}
};

template <typename T>
void calcPow_mod( T x, vector<T>& powArray, T mod )
{
	REP( i, powArray.size() ) if( i != 0 )
		powArray[i] = powArray[i - 1] * x % mod;
}

