{
    ll l,a,b,mod; cin>>l>>a>>b>>mod;
    vector<ll> powAry( 19, 1 );
    calcPow_mod<ll>( 10, powAry, cINF );
    auto add = [&mod]    ( ll a, ll b ) { return ( a + b ) % mod; };
    auto mul = [&mod]    ( ll a, ll b ) { return a * b % mod; };

    auto solve = [&mod, &b, &powAry, add, mul]
    (ll& ans, ll start, ll end, ll d)
    {
        ll n = ( end - start ) / b + 1;
        SquareMatrix<ll> mtx(3);
        mtx[0][0] = powAry[d]%mod; mtx[0][1] = 1; mtx[0][2] = 0;
        mtx[1][0] = 0; mtx[1][1] = 1; mtx[1][2] = b%mod;
        mtx[2][0] = 0; mtx[2][1] = 0; mtx[2][2] = 1;
        mtx = mtx.pow( n, mod );
        ans = add( mul( ans, mtx[0][0] ), mul( start%mod, mtx[0][1] ) );
        ans = add( ans, mtx[0][2] );
