template<size_t N>
class matN{
  public:
  lli m[N][N] = {};
  matN(){}
  matN(std::initializer_list<lli> init){
    auto it = init.begin();
    for(int i = 0; i < N; i++){
      for(int j = 0; j < N; j++){
        m[i][j] = (((*it)%mod)+mod)%mod;
        ++it;
      }
    }
  }
};

template<size_t N>
const matN<N> operator*(const matN<N>& lhs, const matN<N>& rhs){
  matN<N> ans;
  for(int i = 0; i < N; i++){
    for(int j = 0; j < N; j++){
      for(int k = 0; k < N; k++){
        ans.m[i][j] += lhs.m[i][k]*rhs.m[k][j];
        ans.m[i][j] %= mod;
      }
    }
  }
  return ans;
}

