    if(A>tmp){
      ns_d.push_back(0);
    }else{
      ns_d.push_back((tmp-A)/B+1);
    }
    tmp = tmp*10+9;
  }
  ns_d.push_back(L);

  matN<3> mat_total = {1,0,0,0,1,0,0,0,1};
