int keta(int a) {
	int res = 0;
	while (a > 0) {
		a /= 10;
		res++;
	}
	return res;
}


int L, A, B, M;

int po(int a, int p) {
	if (p == 0)return 1;
	int res = po(a, p / 2);
	res = (res * res) % M;
	if (p & 1) {
		res = (res * a) % M;
	}
	return res;
}

int calc(int z, int c) {
	if (c == 0)return 0;
	if (c == 1)return 1;

	int res = calc(z, c / 2);


	res = (res + (res * po(z, c / 2))) % M;

	if (c & 1) {
		res = (res + po(z, c - 1)) % M;
	}
	return res;
}

int calc2(int z, int c) {
	if (c == 0)return 0;
	if (c == 1)return 0;

	int res = calc2(z, c / 2);

	res = (res + (res * po(z, c / 2))) % M;


	res = (res + (((c / 2) * po(z, c / 2)) % M) * calc(z, c / 2)) % M;



	if (c & 1) {
		res = (res + ((c - 1) % M) * po(z, c - 1)) % M;
	}
	return res;
}



