        cout<<A%MOD<<'\n';
        return 0;
    }

    ll cur = A;
    ll val = cur%MOD;
    ll stp = L-1;

    while(stp)
    {
        //find end term in this mag
        ll mgi = mg(cur+B);
        ll p = (tp[mgi]-cur)/B;
        if( (tp[mgi]-cur)%B==0 )p--;
        p = min( stp, p );
        stp-=p;

        vector<ll> MA(3);
        MA[0]=val;
        MA[1]=(cur+B)%MOD;
        MA[2]=B%MOD;

        Mat T;
        T.m[0][0]=tp[mgi]%MOD;
        T.m[0][1]=1;

        T.m[1][1]=T.m[1][2]=1;

        T.m[2][2]=1;

        T = matPow(T,p);
        MA = matMul(T,MA);

        val=MA[0];
        cur=cur+p*B;
    }

    cout<<val<<'\n';

    return 0;
}

