ll l,a,b;
ll m;

inline ll addmod(ll a, ll b){
    return (a+b)%m;
}
inline ll mulmod(ll a, ll b){
    return (a*b)%m;
}
inline ll expmod(ll a, ll b){
    ll ret = 1;
    while(b){
        if(b & 1)ret = mulmod(ret, a);
        a = mulmod(a, a);
        b >>= 1;
    }
    return ret;
}

int getdigit(ll x){
    int ret = 0;
    while(x){
        ret++;
        x /= 10;
    }
    return ret;
}

pll solve(ll l, ll r){ // assume A[l] and A[r] have same number of digits
    ll lf = a + l * b;
    ll d = getdigit(lf);

    ll stripa = lf % m, stripb = b % m, stairb = b % m;
    ll reta = 0, retb = 0;
    ll sz = r - l + 1;
    ll td = expmod(10, d);
    // solve for strip of A
    while(sz){
        if(sz & 1) reta = addmod(mulmod(reta, td), stripa);
        stripa = addmod(mulmod(stripa, td), stripa);
        td = mulmod(td, td);
        sz >>= 1;
    }
    // solve for stairs of B
    sz = r - l;
    td = expmod(10, d);
    ll copp = 1, copret = 0;
    while(sz){
        if(sz & 1){
            retb = addmod(mulmod(retb, td), addmod(mulmod(stripb, copret), stairb));
            copret = addmod(copret, copp);
        }
        stairb = addmod(mulmod(stairb, td), addmod(mulmod(stripb, copp), stairb));
        stripb = addmod(mulmod(stripb, td), stripb);
        td = mulmod(td, td);
        copp = mulmod(copp, 2);
        sz >>= 1;
    }

    d *= r - l + 1;
//    printf("solve %lld-%lld = %lld %lld\n",l,r,reta, retb);
    return {addmod(reta, retb), d};
}

pll dnc(ll l, ll r){ // value under mod, digits
    ll lf = a + l * b;
    ll rg = a + r * b;

    if(getdigit(lf) != getdigit(rg)){
        ll mid = (l + r)/2;
        pll vl = dnc(l, mid);
        pll vr = dnc(mid+1, r);
        return {addmod(mulmod(vl.F, expmod(10, vr.S)), vr.F), vl.S + vr.S};
    }else{
//        printf("solve for %lld - %lld\n",lf,rg);
        return solve(l, r);
    }
}

