int L, A, B, M;

int logpow(int x, long long p)
{
	x %= M;
	if (p == 0) {
		return 1;
	}
	if (p % 2) {
		return x % M * logpow(x, p-1) % M;
	}
	int t = logpow(x % M, p/2);
	return t * t % M;
}


template <class T>
struct Matrix
{
	int row;
	int column;
	vector<vector<T>> v;
	vector<T> &operator[](int i) { return (v[i]); }
	Matrix(int i, int j)
	{
		init(i, j);
	}
	Matrix()
	{
		init(0, 0);
	}
	void init(int i, int j)
	{
		row = i;
		column = j;
		v.resize(i, vector<T>(j, 0));
	}
	Matrix(const Matrix &cp)
	{
		row = cp.row;
		column = cp.column;
		v = cp.v;
	}
	~Matrix()
	{
	}
	Matrix operator=(const Matrix &a)
	{
		row = a.row;
		column = a.column;
		v = a.v;
		return (*this);
	}

	Matrix operator+(const Matrix &a)
	{
		Matrix r(row, column);
		for (int i = 0; i < row; i++)
		{
			for (int j = 0; j < column; j++)
			{
				r.v[i][j] = v[i][j] + a.v[i][j];
			}
		}
		return (r);
	}

	Matrix operator-(const Matrix &a)
	{
		Matrix r(row, column);
		for (int i = 0; i < row; i++)
		{
			for (int j = 0; j < column; j++)
			{
				r.v[i][j] = v[i][j] - a.v[i][j];
			}
		}
		return (r);
	}
	Matrix operator*(const Matrix &a)
	{
		Matrix r(row, a.column);
		for (int i = 0; i < row; i++)
		{
			for (int j = 0; j < a.column; j++)
			{
				for (int k = 0; k < column; k++)
				{
					r.v[i][j] += (v[i][k] % M) * (a.v[k][j] % M) % M;
					r.v[i][j] %= M;
				}
			}
		}
		return (r);
	}
	Matrix operator*(const int b)
	{
		Matrix r(row, column);
		for (int i = 0; i < row; i++)
		{
			for (int j = 0; j < column; j++)
			{
				r.v[i][j] = b * v[i][j];
			}
		}
		return (r);
	}
	Matrix operator+(const int b)
	{
		Matrix r(row, column);
		for (int i = 0; i < row; i++)
		{
			for (int j = 0; j < column; j++)
			{
				r.v[i][j] = b + v[i][j];
			}
		}
		return (r);
	}
	Matrix operator-(const int b)
	{
		Matrix r(row, column);
		for (int i = 0; i < row; i++)
		{
			for (int j = 0; j < column; j++)
			{
				r.v[i][j] = v[i][j] - b;
			}
		}
		return (r);
	}
	void unit_matrix()
	{
		int n = row;
		for (int i = 0; i < n; i++)
		{
			for (int j = 0; j < n; j++)
			{
				v[i][j] = 0;
				if (i == j)
					v[i][j] = 1;
			}
		}
	}
	Matrix<T> accumu_sum()
	{
		Matrix<T> r(this->row+1, this->column+1);
		for (int i = 1; i <= this->row; i++)
		{
			for (int j = 1; j <= this->column; j++)
			{
				r[i][j] = this->v[i-1][j-1] + r[i-1][j] + r[i][j-1] - r[i-1][j-1];
			}
		}
		return (r);
	}
	T get_sum_accumu(int r1, int c1, int r2, int c2) //半開区間で指定
	{
		return v[r2][c2] + v[r1][c1] - v[r2][c1] - v[r1][c2];
	}

	Matrix transposed()
	{
		Matrix t(column, row);
		for (int i = 0; i < row; i++)
		{
			for (int j = 0; j < column; j++)
			{
				t[j][i] = v[i][j];
			}
		}
		return (t);
	}
	friend ostream &operator<<(ostream &lhs, const Matrix<T> &rhs)
	{
		for (int i = 0; i < rhs.row; i++)
		{
			for (int j = 0; j < rhs.column - 1; j++)
			{
				lhs << rhs.v[i][j] << " ";
			}
			lhs << rhs.v[i][rhs.column - 1];
			if (i != rhs.row-1) cout << endl;
		}
		return lhs;
	}
	friend istream &operator>>(istream &lhs, Matrix<T> &rhs)
	{
		for (int i = 0; i < rhs.row; i++)
		{
			for (int j = 0; j < rhs.column; j++)
			{
				lhs >> rhs.v[i][j];
			}
		}
		return lhs;
	}
};

Matrix<int> logpowM(Matrix<int> x, long long p)
{
	if (p == 0) {
		Matrix<int> t = x;
		t.unit_matrix();
		return t;
	}
	if (p % 2) {
		return x * logpowM(x, p - 1);
	}
	auto t = logpowM(x, p/2);
	return t * t;
}


void init()
{
	cin >> L >> A >> B >> M;
	int D = 0;
	int G = 1;
	int res = 0;
	while (L) {
		{
			D = 0;
			G = 1;
			int t = A;
			while (t) {
				D++;
				t /= 10;
				G *= 10;
			}
		}
		int k;
		if (D < 18) {
			k = (G - A + B - 1) / B - 1;
		} else {
			k = L - 1;
		}
		assert(G >= 0);
		k = min(k, L-1);
		int k10 = logpow(10, D);
		Matrix<int> LL(3, 3);
		LL[0][0] = k10 % M;
		LL[0][1] = 1;
		LL[1][1] = 1;
		LL[1][2] = B % M;
		LL[2][2] = 1;
		Matrix<int> RR(3, 1);
		RR[0][0] = res;
		RR[1][0] = A % M;
		RR[2][0] = 1;
		auto t = logpowM(LL, k + 1);
		auto u = t * RR;
		res = u[0][0];
		L -= k + 1;
		A += (k + 1) * B;
	}
	cout << res << endl;
}

