Mat mat_pow(const Mat& a, ll n) {
	Mat ret;
	if (n == 0) {
		ret = Mat(a.size(), vector<ll>(a[0].size()));
		for (int i = 0; i < a.size(); i++) ret[i][i] = 1;
		return ret;
	}
	if (n % 2 == 0) {
		Mat t = mat_pow(a, n / 2);
		ret = t * t;
	}
	else {
		Mat t = mat_pow(a, n / 2);
		ret = t * t;
		ret = ret * a;
	}
	return ret;
}
