using ull=unsigned long long;
using M=vector<vector<ull>>;
ull m;

ull modpow(ull a,ull p){
  ull res=1;
  ull power = a;
  while(p){
    if(p&1){
      res*=power;
      res%=m;
    }
    power*=power;
    p>>=1;
  }
  return res;
}

ull fastpow(ull a,ull p){
  ull res=1;
  ull power = a;
  while(p){
    if(p&1){
      res*=power;
    }
    power*=power;
    p>>=1;
  }
  return res;
}

M mat_mul(const M& A, const M& B){
  M C{{0,0,0},{0,0,0},{0,0,0}};
  rep(i,3)rep(j,3)rep(k,3) {
    C[i][j]+=A[i][k]*B[k][j];
    C[i][j]%=m;
  }
  return C;
}


void solve(){
  ull l,a,b; cin>>l>>a>>b>>m;
  vector<ull> C(19,0);
  rep(d,1,19){
    if((ll)pow(10,d)-1-(ll)a>=0){
      C[d]=((ll)pow(10,d)-1-(ll)a)/b+1;
    } else {
      C[d]=0;
    }
  }
  rep(d,18,0,-1){
    C[d]-=C[d-1];
  }
  rep(d,1,19){
    C[d]=min(l,C[d]);
    l-=min(l,C[d]);
  }

  M A{{1,0,0},{0,1,0},{0,0,1}};
  rep(d,1,19){
    M res{{1,0,0},{0,1,0},{0,0,1}};
    M power{{modpow(10,d),1,0},{0,1,b%m},{0,0,1}};
    ull p=C[d];
    while(p){
      if(p&1) res=mat_mul(res,power);
      power=mat_mul(power,power);
      p>>=1;
    }
    A=mat_mul(res,A);
  }
  ull ans=0;
  ans+=(a%m)*(A[0][1])%m;
  ans+=A[0][2];
  cout<<ans%m<<"\n";
}

