using namespace std;

int digit(int64_t x){
    int ret = 0;
    for(;x>0;ret++) x /= 10;

    return ret;
}

void matpow(const int64_t *X, int64_t *ans, int64_t n, int64_t mod){
    if(n==0){
        for(int i=0;i<3;i++){
            for(int j=0;j<3;j++){
                ans[i*3+j] = (i==j ? 1 : 0);
            }
        }
    }else if(n==1){
        for(int i=0;i<9;i++) ans[i] = X[i] % mod;
    }else if(n%2 == 0){
        int64_t XX[9];
        for(int i=0;i<3;i++){
            for(int k=0;k<3;k++){
                XX[i*3+k] = 0;
                for(int j=0;j<3;j++){
                    XX[i*3+k] = (XX[i*3+k] + X[i*3+j] * X[j*3+k] % mod) % mod;
                }
            }
        }
        matpow(XX, ans, n/2, mod);
    }else{
        int64_t XX[9];
        for(int i=0;i<3;i++){
            for(int k=0;k<3;k++){
                XX[i*3+k] = 0;
                for(int j=0;j<3;j++){
                    XX[i*3+k] = (XX[i*3+k] + X[i*3+j] * X[j*3+k] % mod) % mod;
                }
            }
        }
        matpow(XX, ans, n/2, mod);
        for(int i=0;i<9;i++){
            XX[i] = ans[i];
            ans[i] = 0;
        }
        for(int i=0;i<3;i++){
            for(int k=0;k<3;k++){
                for(int j=0;j<3;j++){
                    ans[i*3+k] = (ans[i*3+k] + XX[i*3+j] * X[j*3+k] % mod) % mod;
                }
            }
        }
    }
}

int main(){   
    int64_t L, A, B, M;
    cin >> L >> A >> B >> M;

    pair<int,int> pos[19];
    for(int i=1;i<=18;i++){
        int l = -1, r = L;
        while(r-l > 1){
            int m = (l+r) / 2;
            if(digit(A + m*B) < i) l = m;
            else r = m;
        }
        pos[i].first = r;
        l = -1; r = L;
        while(r-l > 1){
            int m = (l+r) / 2;
            if(digit(A + m*B) <= i) l = m;
            else r = m;
        }
        pos[i].second = r;
    }

    A %= M; B %= M;
    int64_t s = 0, n = A, d = 1;
    for(int i=1;i<=18;i++){
        d *= 10;
        int64_t X[9] = {0}, Xp[9];
        X[0] = d % M;
        X[1] = X[4] = X[5] = X[8] = 1;
        matpow(X, Xp, pos[i].second - pos[i].first, M);
        s = (Xp[0]*s%M + Xp[1]*n%M + Xp[2]*B%M) % M;
        n = (Xp[3]*s%M + Xp[4]*n%M + Xp[5]*B%M) % M;
    }

    cout << s << endl;

    return 0;
}

