ll modp(ll a,ll b,ll m){
  if(b==0) return 1;
  if(b%2) return modp(a,b-1,m)*a%m;
  return modp(a,b/2,m)*modp(a,b/2,m)%m;
}
ll npow(ll a,ll b){
  if(b==0) return 1;
  if(b%2) return npow(a,b-1)*a;
  return npow(a,b/2)*npow(a,b/2);
}
