#include <bits/stdc++.h>
using namespace std;
using LL = long long;
LL m[9];

// 行列積のロジックを一部抽出した版.
// @param p1 ～ q3: 行列の要素.
// @param MOD: M.
// @return ret: 行列積の計算結果.
LL matrixProduct(LL p1, LL p2, LL p3, LL q1, LL q2, LL q3, LL MOD){
    LL ret = 0;
    ret += (p1 % MOD) * (q1 % MOD), ret %= MOD;
    ret += (p2 % MOD) * (q2 % MOD), ret %= MOD;
    ret += (p3 % MOD) * (q3 % MOD), ret %= MOD;
    return ret;
}

// 本問で設定している (3×3)行列 の Cd 乗 を 計算.
// @param p: Cd乗.
// @param a: 10 の d乗.
// @param b: B.
// @param MOD: M.
// @return: 特に無し.
void matrix33(LL p, LL a, LL b, LL MOD){

    // 1. p を 2 で 割っていく(q: 商, r: 余り).
    map<LL, LL> t;
    while(p){
        LL q = p >> 1, r = p & 1;
        t[q] = r;
        p >>= 1;
    }
    // for(auto &p : t) cout << p.first << " " << p.second << endl;

    // 2. 1. の 結果から, 逆算.
    // (初期状態)
    // 第 0成分(1行1列): a, 第 1成分(1行2列): 0, 第 2成分(1行3列): 0
    // 第 3成分(2行1列): 1, 第 4成分(2行2列): 1, 第 5成分(2行3列): 0
    // 第 6成分(3行1列): 0, 第 7成分(3行2列): b, 第 8成分(3行3列): 1
    m[0] = 1, m[1] = 0, m[2] = 0;
    m[3] = 0, m[4] = 1, m[5] = 0;
    m[6] = 0, m[7] = 0, m[8] = 1;
    for(auto &p : t){
        if(p.first != 0){
            LL t11 = m[0], t12 = m[1], t13 = m[2],
               t21 = m[3], t22 = m[4], t23 = m[5],
               t31 = m[6], t32 = m[7], t33 = m[8];
            m[0] = matrixProduct(t11, t12, t13, t11, t21, t31, MOD);
            m[1] = matrixProduct(t11, t12, t13, t12, t22, t32, MOD);
            m[2] = matrixProduct(t11, t12, t13, t13, t23, t33, MOD);
            m[3] = matrixProduct(t21, t22, t23, t11, t21, t31, MOD);
            m[4] = matrixProduct(t21, t22, t23, t12, t22, t32, MOD);
            m[5] = matrixProduct(t21, t22, t23, t13, t23, t33, MOD);
            m[6] = matrixProduct(t31, t32, t33, t11, t21, t31, MOD);
            m[7] = matrixProduct(t31, t32, t33, t12, t22, t32, MOD);
            m[8] = matrixProduct(t31, t32, t33, t13, t23, t33, MOD);
        }
        if(p.second == 1){
            LL t11 = m[0], t12 = m[1], t13 = m[2],
               t21 = m[3], t22 = m[4], t23 = m[5],
               t31 = m[6], t32 = m[7], t33 = m[8];
            m[0] = matrixProduct(t11, t12, t13, a, 1, 0, MOD);
            m[1] = matrixProduct(t11, t12, t13, 0, 1, b, MOD);
            m[2] = matrixProduct(t11, t12, t13, 0, 0, 1, MOD);
            m[3] = matrixProduct(t21, t22, t23, a, 1, 0, MOD);
            m[4] = matrixProduct(t21, t22, t23, 0, 1, b, MOD);
            m[5] = matrixProduct(t21, t22, t23, 0, 0, 1, MOD);
            m[6] = matrixProduct(t31, t32, t33, a, 1, 0, MOD);
            m[7] = matrixProduct(t31, t32, t33, 0, 1, b, MOD);
            m[8] = matrixProduct(t31, t32, t33, 0, 0, 1, MOD);
        }
    }

    return;

}

int main() {

    // 1. 入力情報取得.
    LL L, A, B, M;
    scanf("%lld %lld %lld %lld", &L, &A, &B, &M);

    // 2. 解説通り.
    // d = 1, 2, ... , 18 で, 解説にある, 以下の計算式をベースに合算.
    // [計算式]
    // (X, s, 1) × matrix33(Cd, 10 の d乗, B, M) = (X × 10 の d乗 + s, s + B, 1)
    LL ans[3] = {0, A, 1};
    LL cur10 = 1, bef10 = 1;
    for(int i = 1; i <= 18; i++){
        // 2-1. 10 の べき乗 を 更新.
        cur10 *= 10;

        // 2-2. Cd を 計算.
        // i を 数列の桁数 と 見て, 計算.
        // ex.
        // i = 1, A = 3, B = 4 の 場合.
        // 0桁 … max(0, 0 - A) ÷ B = 0
        // 1桁 … max(0, 9 - A) ÷ B = 1
        // -> C1 = 1 - 0 = 1個.
        // ※ C1 は 2個 の はず.
        // 
        // i = 2, A = 3, B = 4 の 場合.
        // 1桁 … max(0, 9 - A)  ÷ B =  1
        // 2桁 … max(0, 99 - A) ÷ B = 24
        // -> C2 = 24 - 1 = 23個.
        // 
        // i = 3, A = 3, B = 4 の 場合.
        // 2桁 … max(0, 99 - A)  ÷ B =  24
        // 3桁 … max(0, 999 - A) ÷ B = 249
        // -> C3 = 249 - 24 = 225個.
        LL d1 = max(0LL, bef10 - 1 - A) / B;
        LL d2 = max(0LL, cur10 - 1 - A) / B;
        LL Cd = d2 - d1;
        // d1 が 0 の場合 かつ d2 が 0 より大きい場合は, 
        // d2 の方で, 初項 A を 含んでいる筈なので, Cd を 1増やす必要があるはず.
        if(d1 == 0 && d2 > 0) Cd++;
        // printf("Cd=%lld, L=%lld\n", Cd, L);

        // 2-3. 行列計算.
        matrix33(min(Cd, L), cur10, B, M);

        // 2-4. 行列 ans を 更新.
        LL t[3] = {0, 0, 0};
        t[0] = matrixProduct(ans[0], ans[1], ans[2], m[0], m[3], m[6], M);
        t[1] = matrixProduct(ans[0], ans[1], ans[2], m[1], m[4], m[7], M);
        t[2] = matrixProduct(ans[0], ans[1], ans[2], m[2], m[5], m[8], M);
        swap(t, ans);

        // 2-5. 計算を継続するかチェック.
        // 等差数列の長さは, L と指定されているので, 1回計算するごとに, Cd個分 を 減らす 必要あり.
        L -= Cd;
        // L が 0未満となったら, 計算終了と見ることが出来る.
        if(L < 0) break;

        // 2-6. 前回 の 10 の べき乗 を 保存.
        bef10 = cur10;
    }

    // for(int i = 0; i < 3; i++) printf("ans[%d]=%lld ", i, ans[i]);
    // printf("\n");

    // 3. 出力 ～ 後処理.
    printf("%lld\n", ans[0]);
    return 0;

}

