int Pow(int x, int k) {
  int ret = 1, p = x;
  while (k > 0) {
    if (k & 1) {
      ret = ret * p;
      ret %= MOD;
    }
    p = p * p;
    p %= MOD;
    k /= 2;
  }
  return ret;
}


