#include <bits/stdc++.h>
using namespace std;
typedef __int128 LL;
LL mod;
LL M[4][4], res[4][4], tmp[4][4];
LL B[4];
LL pw(LL a, LL b){
    LL ans = 1;
    while(b){
        if(b%2) ans = ans*a%mod;
        a = a*a%mod;
        b/=2;
    }
    return ans;
}
int main(){
    LL l, a, b;
    scanf("%lld%lld%lld", &l, &a, &b);
    scanf("%lld", &mod);
    if(l == 1){
        printf("%lld\n", a%mod);
        return 0;
    }
    LL lo = a, hi = a + (l-1)*b;

    LL m = l;

    LL sum = 1, ans = 0;
    for(int i=0;i<=20;i++){
        LL l = -1, r = -1;
        LL x = 0, y = m;
        while(x <= y){
            LL mid = (x+y)/2;
            if(a + mid*b >= sum) l = a + mid*b, y = mid-1;
            else x = mid+1;
        }

        x = 0, y = m;
        while(x <= y){
            LL mid = (x+y)/2;
            if(a + mid*b < sum*10) r = a + mid*b, x = mid+1;
            else y = mid-1;
        }
        r = min(r, hi);

        LL d = (r-l)/b+1;

        if(l != -1 && r != -1 && l <= r){
            if(d == 1){
                for(int j=0;j<i+1;j++) ans = (ans * pw(10, d))%mod;
                ans = (ans + l)%mod;
            }
            else{
                memset(M, 0, sizeof(M));
                memset(B, 0, sizeof(B));
                memset(res, 0, sizeof(res));

                d--;

                M[1][1] = pw(10, i+1);
                M[1][2] = 1;
                M[1][3] = 1;
                M[2][2] = 1;
                M[2][3] = 1;
                M[3][3] = 1;

                B[1] = l%mod;
                B[2] = l%mod;
                B[3] = b%mod;

                int t = d;
                bool st = 0;
                while(d){
                    if(d%2){
                        if(!st) for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) res[i][j] = M[i][j];
                        else{
                            memset(tmp, 0, sizeof(tmp));
                            for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) for(int k=1;k<=3;k++) tmp[i][j] = (tmp[i][j] + M[i][k]*res[k][j])%mod;
                            for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) res[i][j] = tmp[i][j];
                        }
                        st = 1;
                    }
                    memset(tmp, 0, sizeof(tmp));
                    for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) for(int k=1;k<=3;k++) tmp[i][j] = (tmp[i][j] + M[i][k]*M[k][j])%mod;
                    for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) M[i][j] = tmp[i][j];
                    d/=2;
                }
                d = t+1;
                LL x = (res[1][1]*B[1] + res[1][2]*B[2] + res[1][3]*B[3])%mod;

                for(int j=0;j<i+1;j++) ans = (ans * pw(10, d))%mod;
                ans = (ans + x)%mod;
            }
        }

        sum *= 10;
    }
    printf("%lld\n", ans);
}

