ll m;
ll cale(ll l, ll r) {
	if (l == 0)
		return 0;
	// sum(0,l - 1)pow(r,i)

	if (l % 2 == 0) {
		ll ol = l / 2;
		// sum(0, 2l - 1)pow(r,i)
		// sum(0, l - 1)pow(r,i) + sum(l,2l - 1) pow(r,i)
		// el + sum(0,l - 1) pow(r, i + l)
		// el + pow(r,l) sum(0,l - 1) pow(r,i)
		// (1 + pow(r,l)) el
		ll rl = getpow(r, ol, m);
		return (((1 + rl) % m) * cale(ol, r)) % m;
	}
	else {
		ll ol = l - 1;
		// sum (0,l + 1 - 1)pow(r,i)
		// r sum(0, l - 1)pow(r,i) + 1
		// r^0+r^1+r^2+r^3
		// 1 + r(r^0+r^1+r^2)
		return (((r * cale(ol, r)) % m) + 1) % m;

	}
}
ll cald(ll l, ll r, ll a, ll b) {
	if (l == 0)
		return 0;
	if (l % 2 == 0) {
		ll ol = l / 2;
		// d(2*l) = sum(0,2*l - 1)pow(r,2 * l - 1 - i)(a+bi)
		// 0~l-1とl~2l - 1に分離する
		// 一つ目
		// sum(0,l-1)pow(r,2*l - 1 - i)(a+bi)
		// r^lsum(0,l-1)pow(r,l - 1- i)(a+ bi)
		// 二つ目
		// sum(l,2l - 1) pow(r,2*l - 1 - i)(a+bi)
		// sum(0,l - 1) pow(r,2 * l - 1 - (i + l))(a + b(i + l))
		// sum(0,l - 1) pow(r,l - 1 - i)(a + bi) 
		// bl sum(0,l - 1) pow(r, l - 1- i)
		// bl (sum(0,l - 1) pow(r,i))= el
		// pow(r,l) dl + dl + bl(el)
		// (pow(r,l) + 1) dl + bl(el)
		ll rl = getpow(r, ol, m);
		ll bl = (b * ol) % m;
		return (((((rl + 1) % m) * cald(ol, r, a, b)) % m )
			+ (bl * cale(ol, r)) % m) % m;

	}
	else {
		ll ol = l - 1;

		// dl+1=sum(0,l + 1 - 1)pow(r,l - 1 - i)(a + bi)
		// rを分離すると(a+bi)も分離する
		// r^l(a+b0) + r^(l-1)(a+b) = r(r^(l-1)(a+b0)+r^(l-2)(a+b))
		// 最後がr^0で、これは先に分離してしまう
		// 最後は(a + bl)
		ll bl = (b * ol) % m;
		return (((r * cald(ol, r, a, b)) % m )+ ((a + bl) % m)) % m;

	}
}
void solv() {
	ll L, a, b;
	cin >> L >> a >> b >> m;

	ll ab = (a % m);
	ll bef = 0;
	ll d = 1;
	ll res = 0;
	rep2(i, 1, 19)
	{
		ll t = pow(10, i);
		(d *= 10) %= m;
		if (a > t)
			continue;
		ll hi = L;
		ll lo = 0;
		while (lo + 1 < hi)
		{
			ll mid = (hi + lo) / 2;
			if (a + b * mid >= t) {
				hi = mid;
			}
			else {
				lo = mid;
			}
		}

		ll l = hi - bef;
		(res *= (getpow(d, l, m))) %= m;
		(res += cald(l, d, ab, (b % m))) %= m;
		bef = hi;
		(ab = a + (b % m) * hi) %= m;

	}
	cout << res << endl;
}



