  FOR(i, 1, 19){
    l[i] = (ten[i-1] - A + B - 1) / B;
    r[i] = (ten[i] - A + B - 1) / B;
    l[i] = max(0LL, l[i]);
    r[i] = min(L, r[i]);
  }
  ll res = 0;
  ll curr = 1;
  A %= M;
  B %= M;
  for(int i = 18; i >= 1; i--){
    ten[i] %= M;
    if(l[i] >= L)continue;
    if(r[i] <= l[i])continue;
    ll tmp1 = ((A + B * (l[i] % M) % M) % M) * power<ll>(ten[i], r[i] - l[i], M) % M;
    ll tmp2 = B * (power<ll>(ten[i], r[i] - l[i] - 1, M) - 1) % M;
    tmp2 = tmp2 * ten[i] % M;
    tmp2 = tmp2 * modinv<ll>(ten[i] - 1, M) % M;
    if(tmp2 < 0)tmp2 += M;
    ll tmp3 = (A + B * ((r[i] % M) - 1) % M) % M;
    ll tmp = (tmp1 + tmp2 - tmp3) % M;
    if(tmp < 0)tmp += M;
    tmp = tmp * modinv(ten[i] - 1, M) % M;
    if(tmp < 0)tmp += M;
    res = (res + curr * tmp % M) % M;
