    return c;
  };
  auto id = [&] {
    mat c{};
    for (size_t i = 0; i < sz; i++) {
      c.at(i).at(i) = 1;
    }
    return c;
  };
  auto pow = [&] (mat a, long long b) {
    auto c = id();
    for (; b > 0; b /= 2) {
      if (b % 2 == 1) c = prod(c, a);
      a = prod(a, a);
    }
    return c;
  };
  auto act = [&] (mat a, vec b) {
    vec c{};
    for (size_t i = 0; i < sz; i++) {
      for (size_t j = 0; j < sz; j++) {
        c.at(i) += a.at(i).at(j) * b.at(j);
      }
    }
    return c;
  };
  auto cal = [&] (int p, long long L, long long A, long long B) {
    return act(pow(mat({
      std::array<mint, sz>{::pow(mint(10), p), 1, 0},
      std::array<mint, sz>{0, 1, 1},
      std::array<mint, sz>{0, 0, 1}
    }), L), vec{0, A, B}).at(0);
  };
  auto lb = [&] (long long x) {
    if (x <= A) return 0LL;
    if (A + (L - 1) * B < x) return L;
    return (x + (B - 1) - A) / B;
  };
  constexpr int max = 18;
  long long lwr = 1, upr = 10;
  mint ret = 0;
  for (int p = 1; p <= max; p++) {
    auto l = lb(lwr), r = lb(upr);
    ret *= ::pow(mint(10), (r - l) * p);
    ret += cal(p, r - l, A + l * B, B);
    lwr *= 10, upr *= 10;
  }
  std::cout << ret << std::endl;
  return 0;
}

