int rui(int x, int a){
    int res = 1;
    int tmp = 1;
    while(tmp <= a){
        if(tmp & a){
            res *= x;
            res %= MOD;
        }
        tmp *= 2;
        x *= x;
        x %= MOD;
    }
    return res;
}

