ll find_len(ll S0,ll L,ll B) {
	int z=len(S0);
	ll l=0,r=L;
	while (l<r) {
		ll m=l+(r-l)/2;
		ll Sm=S0-B*m;
		if (z==len(Sm)) l=m+1; else r=m;
	}
	return l;
}

