LL f(LL ll,LL rr,LL dif,LL num, LL pp){
    ll%=MOD;
    rr%=MOD;
    dif%=MOD;
    pp%=MOD;
    if(num==1)return ll;
    if(num&1){
        return (f(ll,rr-dif,dif,num-1,pp)*pp+rr)%MOD;
    }
    return f((ll*pp+(ll+dif))%MOD,(rr+(rr-dif)*pp)%MOD,2*dif*(1+pp)%MOD,num/2,pp*pp%MOD);
}
