struct Matrix{
	int row, col;
	LL MOD;
	VVL mat;

	Matrix(int r, int c, LL p = mod) : row(r), col(c), MOD(p) { 
		mat.assign(r, VL(c, 0));
	}
	Matrix(const Matrix &x, LL p = mod) : MOD(p){
		mat = x.mat;
		row = x.row;
		col = x.col;
	}
	Matrix(const VVL &A, LL p = mod) : MOD(p){
		mat = A;
		row = A.size();
		col = A[0].size();
	}

	// x * 单位阵 
	inline void E(int x = 1) {
		assert(row == col);
		Rep(i, row) mat[i][i] = x;
	}

	inline VL& operator[] (int x) {
		assert(x >= 0 && x < row);
		return mat[x];
	}

	inline Matrix operator= (const VVL &x) {
		row = x.size();
		col = x[0].size();
		mat = x;
		return *this;
	}

	inline Matrix operator+ (const Matrix &x) {
		assert(row == x.row && col == x.col);
		Matrix ret(row, col);
		Rep(i, row) {
			Rep(j, col) {
				ret.mat[i][j] = mat[i][j] + x.mat[i][j];
				ret.mat[i][j] %= MOD;
			}
		}
		return ret;
	}

	inline Matrix operator* (const Matrix &x) {
		assert(col == x.row);
		Matrix ret(row, x.col);
		Rep(k, x.col) {
			Rep(i, row) {
				if(mat[i][k] == 0) continue;
				Rep(j, x.col) {
					ret.mat[i][j] += mat[i][k] * x.mat[k][j];
					ret.mat[i][j] %= MOD;
				}
			}
		}
		return ret;
	}

	inline Matrix operator*= (const Matrix &x) { return *this = *this * x; }
	inline Matrix operator+= (const Matrix &x) { return *this = *this + x; }

	inline void print() {
		Rep(i, row) {
			Rep(j, col) {
				cout << mat[i][j] << " ";
			}
			cout << endl;
		}
	}
};

// 矩阵快速幂，计算x^y 
inline Matrix mat_pow_mod(Matrix x, LL y) {
	Matrix ret(x.row, x.col);
	ret.E();
	while(y){
		if(y & 1) ret *= x;
        x *= x;
        y >>= 1;
	}
	return ret;
}

inline LL pow_mod(LL x, LL y, LL p = mod){
	LL ret = 1;
	while(y){
		if(y & 1) ret = (ret * x) % p;
        x = (x * x) % p;
        y >>= 1;
	}
	return ret;
} 

