LL L, A, B, M, bit = 10, ans; 

// 从数列第 st 项开始，查找区间 [L, R]，使得区间内的所有数都小于 bit 大于 bit/10。 
// 有返回 true 没有返回 false 
bool getLR(LL &st, LL bit, LL &l, LL &r) {
	if(st >= L || A + st * B >= bit) return false;
	l = st;
	r = L - 1;

	while(l < r) {
		LL mid = (l + r) >> 1;
		if(A + mid * B < bit) l = mid + 1;
		else r = mid;
	}
	if(A + r * B >= bit) --r;
	l = st;
	st = r + 1; // 下一个起始位置 
	return true;
}

int main(){
	//freopen("MyOutput.txt","w",stdout);
	//freopen("input.txt","r",stdin);
	//INIT();
	cin >> L >> A >> B >> mod;

	LL st = 0, bit = 10;
	For(i, 1, 19) { // 枚举位数 
		LL l, r; 
		if(getLR(st, bit, l, r)) {
			Matrix mat(3, 3); 
			mat[0][0] = bit % mod;
			mat[0][1] = mat[0][2] = mat[1][2] = mat[2][1] = 0;
			mat[1][0] = mat[1][1] = mat[2][2] = 1;
			mat[2][1] = B % mod;

			mat = mat_pow_mod(mat, r - l + 1);

			Matrix ret(1, 3); 
			ret[0][0] = ans;
			ret[0][1] = (A + l * B) % mod;
			ret[0][2] = 1;

			ret *= mat;

			ans = ret[0][0];
		}
		bit *= 10;
	}

	cout << ans << endl;
    return 0;
}

