class Matrix
{
	LL a[3][3];
	int sz;
public:

	int size()
	{
		return sz;
	}
	Matrix(int n = 0)
	{
		sz = n;
		MEM(a, 0);
	}
	LL* operator [](int i)
	{
		return a[i];
	}
	Matrix ones(int n)
	{
		Matrix ret(n);
		for (int i = 0; i < n; i++) ret[i][i] = 1;
		return ret;
	}
	void init(LL A, LL B, LL C, int n = 3)
	{
		sz = n;
		MEM(a, 0);
		a[0][0] = A, a[0][1] = 1, a[0][2] = 0; // cur
		a[1][0] = 0, a[1][1] = 1, a[1][2] = C; // B
		a[2][0] = 0, a[2][1] = 0, a[2][2] = 1; // 1
	}
	Matrix operator *(Matrix& m)
	{
		int n = m.size();
		Matrix ret(n);
		for (int k = 0; k < n; k++)
		{
			for (int i = 0; i < n; i++)
			{
				for (int j = 0; j < n; j++)
				{
					ret[i][j] = (ret[i][j] + a[i][k] * m[k][j]) % M;
				}
			}
		}
		return ret;
	}
	Matrix operator +(Matrix& m)
	{
		int n = m.size();
		Matrix ret(n);
		for (int i = 0; i < n; i++)
		{
			for (int j = 0; j < n; j++)
			{
				ret[i][j] = a[i][j] + m[i][j];
				if (ret[i][j] >= M) ret[i][j] -= M;
			}
		}
		return ret;
	}
	Matrix operator ^(LL b)
	{
		Matrix ret = ones(sz);
		Matrix A = *this;
		while (b)
		{
			if (b & 1) ret = ret * A;
			A = A * A;
			b >>= 1;
		}
		return ret;
	}
} B;
