const int INF = 1 << 29;
const int MOD = 1e9 + 7;

int64 mod;
int64 power_mod(int64 a, int64 n) {
  int64 ret = 1;
  for (; n; n >>= 1) {
    if (n & 1) ret = ret * a % mod;
    a = a * a % mod;
  }
  return ret;
}

// sum_{i,0,n-1}q^i
int64 geometric_seq(int64 q, int64 n) {
  q %= mod;
  if (n == 1) return 1;
  if (n % 2) return (1 + q * geometric_seq(q, n - 1)) % mod;
  int64 ret = geometric_seq(q, n / 2);
  ret = ret * (power_mod(q, n / 2) + 1) % mod;
  return ret;
}

// sum_{i,0,n-1}i*q^i
int64 geometric_seq1(int64 q, int64 n) {
  q %= mod;
  if (n == 1) return 0;
  if (n % 2) return (geometric_seq(q, n - 1) +
                     geometric_seq1(q, n - 1)) % mod * q % mod;
  int64 t = power_mod(q, n / 2);
  int64 L = geometric_seq1(q, n / 2);
  int64 R = (L * t % mod + n / 2 * t % mod * geometric_seq(q, n / 2) % mod) % mod;
  return (L + R) % mod;
}

int get_len(int64 n) {
  int ret = 0;
  for (; n; n /= 10) ++ret;
  return ret;
}

int64 solve(int64 a0, int64 d, int64 k, int64 len) {
  int64 q = power_mod(10, k);
  int64 ret = geometric_seq(q, len - 1) * d % mod * q % mod;
  trace(q, ret);
  ret += power_mod(q, len) * a0 % mod;
  ret %= mod;
  int64 last = (a0 + (len - 1) * d) % mod;
  ret += mod - last;
  ret %= mod;
  return ret;
}

int main() {
  int64 L, A, B;
  scanf("%lld%lld%lld%lld", &L, &A, &B, &mod);
  int longest = get_len(A + (L - 1) * B);
  int64 pre = 0, ret = 0;
  for (int k = 1; k <= longest; ++k) {
    if (k < get_len(A + B * pre)) continue;
    int64 low = pre, high = L - 1;
    while (low != high) {
      int64 mid = (low + high + 1) / 2;
      if (get_len(A + B * mid) > k) {
        high = mid - 1;
      } else {
        low = mid;
      }
    }
    int64 len = high - pre + 1;
    // trace(k, pre, high);
    int64 a0 = (A % mod + pre * B % mod) % mod;
    int64 d = B % mod;
    int64 q = power_mod(10, k);
    int64 cur = (a0 + (len - 1) * d % mod) * geometric_seq(q, len) % mod;
    cur = (cur + mod - geometric_seq1(q, len) * d % mod) % mod;
    // trace(cur);
    ret = ret * power_mod(10, len * k) % mod + cur;
    ret %= mod;
    pre = high + 1;
  }
  printf("%lld\n", ret);
  return 0;
}

