	else if (diff == 1) { return 1; }
	int hl = diff / 2;
	int ans1 = ret1(hl,dg);
	ans1 *= (ru(10, dg*hl) + 1); ans1 %= p;
	if (diff % 2 == 1) {
		ans1 += ru(10, dg*(diff - 1));
	}
	return ans1 % p;
}
int ret2(int diff, int dg) {
	if (diff == 0) { return 0; }
	else if (diff == 1) { return 1; }
	int hl = diff / 2;
	int ans2 = ret2(hl, dg);
	ans2 *= (ru(10, dg*hl) + 1); ans2 %= p;
	ans2 += ret1(hl, dg)*hl; ans2 %= p;
	if (diff % 2 == 1) {
		ans2 += ret1(diff, dg);
	}
	return ans2 % p;
}
