		for(int j=0;j<R.get_width();j++){
			R.value[i][j]=0;
			for(int k=0;k<multi_cnt;k++){

				R.value[i][j] = mod(R.value[i][j] + mod(A.value[i][k] * B.value[k][j]));

			}
		}
	}
	return R;

}

matrix matrix_beki(matrix A,long long cnt){
