M matmul(M a, M b) {
    M ret = V<V<ll>>(MSIZE, V<ll>(MSIZE));
    loop (MSIZE, i) loop (MSIZE, j) {
        loop (MSIZE, s) {
            ret[i][j] += a[i][s] * b[s][j] % m;
            ret[i][j] %= m;
        }
    }
    return ret;
}

int main() {
    ll l, a, b; cin >> l >> a >> b >> m;
    ll crr = a;

