template <typename T>
Matrix<T> calc_mat(Matrix<T> A, Matrix<T> B, int enable_mod = true) {
    Matrix<T> C(A.size(), vector<T>(B[0].size()));
    for(int i=0; i<A.size(); i++) {
        for(int k=0; k<B.size(); k++) {
            for(int j=0; j<B[0].size(); j++) {
                if(!enable_mod) C[i][j] += A[i][k] * B[k][j]; // modなし
                else C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % M; // modあり
            }
        }
    }
    return C;
}

template <typename T>
Matrix<T> mat_pow(Matrix<T> A, ll n, int enable_mod = true) {
    if(n < 0) return A;
    Matrix<T> B(A.size(), vector<T>(A.size()));
    for(int i=0; i<A.size(); i++) B[i][i] = 1;
    while(n > 0) {
        if(n & 1) B = calc_mat(B, A, enable_mod);
        A = calc_mat(A, A, enable_mod);
        n >>= 1;
    }
    return B;
}

// N * M 行列のランクを求める
// 整数行列でも基本変形時に分数になるので double 型に限定しています
// 位数 2 の有限体では (演算を xor とかに直した形で) 確認済み、他は未 Verify なのでもしかしたらやばいかもしれない
int mat_rank(Matrix<double> A) {
    int N = A.size(), M = A[0].size();

    int res = 0;
    for(int i=0; i<M; i++) {
        // 絶対値が最も大きいものを探す
        double max_elem = 0; int piv = -1;
        for(int j=res; j<N; j++) {
            if(abs(A[j][i]) > max_elem) {
                max_elem = abs(A[j][i]);
                piv = j;
            }
        }

        // res 行目を piv 行目に変えて、行基本変形
        if(piv < 0) continue;
        swap(A[res], A[piv]);

        // res 行目を正規化
        // F_2 の場合はここは不要
        {
            double div = A[res][i];
            for(int k=0; k<M; k++) {
                A[res][k] = 1.0 * A[res][k] / div;
            }
        }

        for(int j=0; j<N; j++) {
            if(j == res) continue;
            assert(A[res][i] != 0);
            double mul = A[j][i];
            for(int k=0; k<M; k++) {
                // 場合に応じて xor に変えるなりする
                A[j][k] = A[j][k] - mul * A[res][k];
            }
        }
        res++;
    }
    return res;
}

