ll L, A, B, M;

//A*Bの計算
mat mul(mat &A, mat &B) {
	mat C(A.size(), vec(B[0].size()));
	for (int i = 0; i < A.size(); i++)
	{
		for (int k = 0; k < B.size(); k++)
		{
			for (int j = 0; j < B[0].size(); j++)
			{
				C[i][j] = ((C[i][j] % M) + (((A[i][k] % M) * (B[k][j] % M)) % M)) % M;
			}
		}
	}
	return C;
}

//A^nの計算
mat mat_pow(mat A, lint n) {
	mat B(A.size(), vec(A.size()));
	for (int i = 0; i < A.size(); i++)
	{
		B[i][i] = 1LL;
	}
	while (n > 0) {
		if (n & 1) B = mul(B, A);
		A = mul(A, A);
		n >>= 1LL;
	}
	return B;
