}
mat mul(mat &a,mat &b, ll mod){ //a*bなのでn*mとm*l→n*l
    mat c(a.size(),vec(b.at(0).size(),0));
    rep(i,a.size()){
        rep(k,b.size()){
            rep(j,b.at(0).size()){
                //ll ab = (a.at(i).at(k)*b.at(k).at(j))%mod;
