                    cout<<aa<<' '<<bb<<endl;
                }
                (aa+=mod)%=mod;
                (bb+=mod)%=mod;
                (aa*=bb)%=mod; 
                (c.at(i).at(j) += aa)%=mod;
                if(c.at(i).at(j)<0){
                    cout<<"over"<<endl;
                    cout<<aa<<' '<<bb<<endl;
                }
            }
        }
    }
    return c;
}

mat matpow(mat a, ll pow, ll mod){
    mat b(a.size(),vec(a.size(),0));
    rep(i,a.size()) b.at(i).at(i) = 1;
    while(pow>0){
        if(pow&1) b = mul(b,a,mod);
        a = mul(a,a,mod);
        pow >>= 1;
    }
    return b;
}

