const int MAX_N = 210, MAX_M = 210;

template<typename T> class Matrix {
public:
    size_t N, M; //N*M行列
    T data[MAX_N][MAX_M];

    Matrix(size_t init_N, size_t init_M) : N(init_N), M(init_M) {

    }

    Matrix operator+(const Matrix& A) {
        assert(A.N == N && A.M == M);
        Matrix res(N, M);
        rep(i, N) rep(j, M) res.data[i][j] = data[i][j] + A.data[i][j];
        return res;
    }

    Matrix& operator+=(const Matrix& A) {
        assert(A.N == N && A.M == M);
        rep(i, N) rep(j, M) data[i][j] += A.data[i][j];
        return *this;
    }

    Matrix operator-(const Matrix& A) {
        assert(A.N == N && A.M == M);
        Matrix<T> res(N, M);
        rep(i, N) rep(j, M) res.data[i][j] = data[i][j] - A.data[i][j];
        return res;
    }

    Matrix& operator-=(const Matrix& A) {
        assert(A.N == N && A.M == M);
        rep(i, N) rep(j, M) data[i][j] -= A.data[i][j];
        return *this;
    }

    Matrix operator*(const Matrix& A) {
        assert(M == A.N);
        Matrix res(N, A.M);

        rep(i, N) rep(j, A.M) {
            rep(k, M) res.data[i][j] += data[i][k] * A.data[k][j];
        }
        return res;
    }

    Matrix& operator*=(const Matrix<T>& A) {
        return *this = *this * A;
    }

    Matrix operator*(T a) {
        Matrix res(N, M);
        rep(i, N) rep(j, M) res.data[i][j] = data[i][j] * a;
        return res;
    }

    Matrix& operator*=(ll a) {
        rep(i, N) rep(j, M) data[i][j] *= a;
        return *this;
    }

    bool operator==(Matrix& A) {
        if (N != A.N || M != A.M) return false;

        rep(i, N) rep(j, M) {
            if (data[i][j] != A.data[i][j]) return false;
        }
        return true;
    }

    bool operator!=(Matrix& A) {
        return !(*this == A);
    }

    Matrix transpose() {
        Matrix res(M, N);
        rep(i, N) rep(j, M) res.data[j][i] = data[i][j];
        return res;
    }

    ll trace() {
        assert(N == M);
        ll res = 0;
        rep(i, N) res += data[i][i];
        return res;
    }

    void display() {

        rep(i, N) {
            rep(j, M) cerr << data[i][j] << " ";
            cerr << endl;
        }
    }

    Matrix E(const ll n) {
        Matrix res(n, n);
        rep(i, n) rep(j, n) res.data[i][j] = (i == j);
        return res;
    }

    Matrix pow(const ll n) {
        assert(N == M);
        bitset<60> bs(n);
        int pow_cnt = 0;
        rep(i, 60) if (bs[i]) pow_cnt = i + 1;
        Matrix P = *this;
        Matrix res = E(N);

        rep(i, pow_cnt) {
            if (bs[i]) res *= P;
            P *= P;
        }
        return res;
    }

};

