using modint = ModInt;


inline ll nyapow(ll b,ll n){
  ll ret = 1;
  while(n){
    if(n & 1) ret *= b;
    b *= b;
    n >>= 1;
  }
  return ret;
}

modint func(ll len, ll a, ll d, ll keta){
  modint ten = modint(10).pow(keta);
  modint ret = 0;
  modint memo = 0;
  for(ll cur = 0 , i = 63 - __builtin_clzll(len) ; i >= 0 ; i-- ){
    // ret
    ret = ret * ten.pow(cur) + ret + memo * d * cur;
    // memoの桁長を2倍
    memo = memo * (ten.pow(cur)) + memo;
    // cur
    cur <<= 1;

    if( (len >> i) & 1){
      cur += 1;
      ret = ret * ten + a + modint(d) * modint(cur - 1);
      memo = memo * ten + 1;
    }
    trc(cur , ret , memo);
  }
  trc(ret);
  return ret;

}

void solve(){
  inl(L,A,B); in(mod);

  modint ans = 0;
  rep1(keta , 19){
    if(L == 0) break;
    if( nyapow(10 ,keta-1 ) <= A && A < nyapow(10,keta) ){
      ll N = min( L ,  ( nyapow(10,keta) - A + B - 1 ) / B );
      ans *= modint(10).pow(N).pow(keta);
      modint addans = func( N , A , B , keta);
      ans += addans;
      A = A + B * N;
      L = L - N;
    }
  }
  out(ans);


}

