int M;

int MOD(int a){
	return (a %= M) >= 0 ? a : a + M;
}

int power(int a, int N){
	if(N == 0) return 1;
	else if(N % 2 == 0) return power(MOD(a * a), N / 2);
	else return MOD(a * power(a, N - 1));
}

