vector<vector<int>> mat_pro(vector<vector<int>> X, vector<vector<int>> Y){
	vector<vector<int>> ans(X.size(), vector<int>(Y[0].size(), 0));
	int i, j, k;
	for(i = 0; i < X.size(); i++){
		for(j = 0; j < Y[0].size(); j++){
			for(k = 0; k < Y.size(); k++){
				ans[i][j] = MOD(ans[i][j] + X[i][k] * Y[k][j]);
			}
		}
	}
	return ans;
}

vector<vector<int>> mat_power(int N, vector<vector<int>> X, int K){
	if(K == 0){
		vector<vector<int>> ans(N, vector<int>(N, 0));
		for(int i = 0; i < N; i++){
			ans[i][i] = 1;
		}
		return ans;
	}
	else if(K % 2 == 0){
		return mat_power(N, mat_pro(X, X), K / 2);
	}
	else{
		return mat_pro(X, mat_power(N, X, K - 1));
	}
}

