__int128 mod_pow(__int128 x, __int128 k, __int128 mod){
  __int128 ret = 1;
  while(k){
    if(k&1) ret *= x, ret %= mod;
    x *= x, x %= mod;
    k >>= 1;
  }
  return ret;
}

