ll L, A, B, M;

ll MODpow(ll n, ll m) {
    ll result = 1;
    while (m) {
        if (m % 2 == 1) {
            result *= n;
            result %= M;
        }

        m /= 2;
        n *= n;
        n %= M;
    }

    return result;
}

ll f(ll i, ll j) {
    ll result = 0;
    ll s_i = A + B * i;
    ll pre = i;
    for (ll num = to_string(s_i).size(); ; num++) {
        //初めてpow(10, num + 1)以上になるインデックスを求める
        if (num >= 17) {
            result += num * (j - pre);
            break;
        }

        ll tar = 1;
        for (ll k = 0; k <= num; k++) {
            tar *= 10;
        }
        ll ok = i, ng = j;
        while (ok != ng - 1) {
            ll mid = (ok + ng) / 2;
            ll s_mid = A + B * mid;
            (s_mid < tar ? ok = mid : ng = mid);
        }

        result += num * (ok - pre + 1);

        pre = ok + 1;

        if (ok == j - 1) {
            break;
        }
    }

    return result;
}

ll solve(ll i, ll j) {
    if (j == i + 1) {
        return (A + B * i) % M;
    }

    //半分ずつ
    ll mid = (i + j) / 2;

    //[mid, j)の桁数の和
    ll d = f(mid, j);

    ll result = (MODpow(10, d) * solve(i, mid) % M + solve(mid, j)) % M;

    return result;
}

