    for(int i=0;i<=18;i++){
        LL l = -1, r = -1;
        LL x = 0, y = m;
        while(x <= y){
            LL mid = (x+y)/2;
            if(a + mid*b >= sum) l = a + mid*b, y = mid-1;
            else x = mid+1;
        }

        x = 0, y = m;
        if(i != 18){
            while(x <= y){
                LL mid = (x+y)/2;
                if(a + mid*b < sum*10) r = a + mid*b, x = mid+1;
                else y = mid-1;
            }
        }
        else r = hi;
        r = min(r, hi);

        LL d = (r-l)/b+1;

        if(l != -1 && r != -1 && l <= r){
