                B[1] = l%mod;
                B[2] = l%mod;
                B[3] = b%mod;

                int t = d;
                bool st = 0;
                while(d){
                    if(d%2){
                        if(!st) for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) res[i][j] = M[i][j];
