                            for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) for(int k=1;k<=3;k++) tmp[i][j] = (tmp[i][j] + M[i][k]*res[k][j])%mod;
                            for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) res[i][j] = tmp[i][j];
                        }
                        st = 1;
                    }
                    memset(tmp, 0, sizeof(tmp));
                    for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) for(int k=1;k<=3;k++) tmp[i][j] = (tmp[i][j] + M[i][k]*M[k][j])%mod;
                    for(int i=1;i<=3;i++) for(int j=1;j<=3;j++) M[i][j] = tmp[i][j];
                    d/=2;
                }
                d = t+1;
                LL x = (res[1][1]*B[1] + res[1][2]*B[2] + res[1][3]*B[3])%mod;

                for(int j=0;j<i+1;j++) ans = (ans * pw(10, d))%mod;
                ans = (ans + x)%mod;
            }
        }

        sum *= 10;
