ll modpow(ll x,ll n,ll mod){
    ll ret=1;
    while(n){
        if(n&1) ret=ret*x%mod;
        x=x*x%mod; n>>=1;
    }
    return ret;
}
ll sum(ll a,ll r,ll n,ll mod){
    if(n==0)return 0;
    if(n==1) return a%mod;
    ll x=sum(a,r,n/2,mod);
    ll ret=(x+modpow(r,n/2,mod)*x%mod)%mod;
    if(n&1) ret=(a+r*ret%mod)%mod;
    return ret;
}
ll sum2(ll a,ll r,ll n,ll mod){
    if(n==0)return 0;
    if(n==1) return 0;
    if(n&1){
        return (sum2(a,r,n-1,mod)+sum(a,r,n-1,mod))%mod;
    }
    ll x=sum2(a,r,n/2,mod);
    // cout<<r<<" "<<n<<" "<<x<<endl;
    x=(x*(modpow(r,n/2,mod)+1ll)%mod+(n/2ll)*sum(a,r,n/2,mod)%mod)%mod;
    // cout<<r<<" "<<n<<" "<<x<<endl;
    return x;
}

