template<typename T>
vector<vector<T>> operator*(
    const vector<vector<T>>& a1, const vector<vector<T>>& a2) {
  int n = a1.size();
  int m = a1[0].size();
  if (a2.size() != m) {
    cerr << "Matrix dimensions don't match for multiplication!" << endl;
    exit(1);
  }
  int l = a2[0].size();
  vector<vector<T>> result(n, vector<T>(l));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < l; j++) {
      for (int k = 0; k < m; k++) {
        result[i][j] += a1[i][k] * a2[k][j];
      }
    }
  }
  return result;
}

template<typename T>
vector<T> operator*(const vector<vector<T>>& matrix, const vector<T>& v) {
  int n = matrix.size();
  int m = matrix[0].size();
  if (v.size() != m) {
    cerr << "Matrix and vector dimensions don't match for multiplication!"
         << endl;
    exit(1);
  }
  vector<T> result(n);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      result[i] += matrix[i][j] * v[j];
    }
  }
  return result;
}

template<typename T>
vector<vector<T>> MatrixPower(const vector<vector<T>>& matrix, int64 p) {
  int n = matrix.size();
  if (p == 0) {
    vector<vector<T>> return_value(n, vector<T>(n));
    for (int i = 0; i < n; i++) {
      return_value[i][i] = 1;
    }
    return return_value;
  } else if (p % 2 == 1) {
    return matrix * MatrixPower(matrix, p - 1);
  } else {
    auto m = MatrixPower(matrix, p / 2);
    return m * m;
  }
}

