void
matmlt(ll res[3][3], ll val[3][3], ll mod)
{
        ll ans[3][3];

        rep (i, 3) {
                rep (j, 3) {
                        ans[i][j] = 0LL;
                        ans[i][j] += (res[i][0] * val[0][j]) % mod;
                        ans[i][j] %= mod;
                        ans[i][j] += (res[i][1] * val[1][j]) % mod;
                        ans[i][j] %= mod;
                        ans[i][j] += (res[i][2] * val[2][j]) % mod;
                        ans[i][j] %= mod;
                }
        }

        rep (i, 3) {
                rep (j, 3) {
                        res[i][j] = ans[i][j];
                }
        }
}

ll find_lastidx(int digits, ll a, ll b, ll L)
{
        ll left = 0LL;
        ll right = L - 1LL;
        ll now = (left + right) / 2LL;
        ll cand = L;
        ll purpose = pow(10LL, digits);

        while (left <= right) {
                ll nowval = a + b * now;

                if (nowval < purpose) {
                        left = now + 1;
                        now = (left + right) / 2LL;
                }
                else {
                        cand = min(cand, now);
                        right = now - 1;
                        now = (left + right) / 2LL;
                }
        }

        return cand - 1LL;
}

