template <typename T>
struct Matrix {
    int r, c;
    using Container = vector2d<T>;
    Container m;
    int row() const { return r; }
    int column() const { return c; }
    Matrix() {}
    // O(RC)
    Matrix(int row, int column = -1, T val = 0) {
        if (row <= 0) row = 0;
        if (column < 0) column = row;
        c = column, r = row;
        m.resize(r);
        for (int i = 0; i < m.size(); i++) {
            m[i].resize(c, val);
        }
    }

    // O(RC)
    Matrix(const Matrix<T>& rhs) {
        m = rhs.m;
        r = rhs.row();
        c = rhs.column();
    }

    ~Matrix() {}

    vector<T>& operator[](int i) {
        return m[i];
    }

    // O(ABC) AxB 型と BxC型 の積の場合
    Matrix<T> operator*(const Matrix<T>& x) {
        if (c != x.r) return I(0);
        Matrix<T> retval = Matrix<T>(r, x.c);
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < x.c; j++) {
                T tmp = 0;
                for (int k = 0; k < c; k++) {
                    tmp += m[i][k] * x.m[k][j];
                }
                retval[i][j] = tmp;
            }
        }
        return retval;
    }

    Matrix<T> operator*(const T& x) {
        if (c != x.r) return I(0);
        Matrix<T> retval = Matrix<T>(r, x.c);
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < x.c; j++) {
                retval[i][j] *= x;
            }
        }
        return retval;
    }

    Matrix<T> operator+(const Matrix<T>& mat) {
        if (mat.r != mat || mat.c != c) return I(0);
        Matrix<T> retval = Matrix<T>(*this);
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                retval[i][j] += mat[i][j];
            }
        }
        return retval;
    }

    Matrix<T> operator-(const Matrix<T>& mat) {
        return (*this) + (mat * -1);
    }

    // O(N^3)
    T det() {
        int n = min(r, c);
        T retval = 1, buf;
        Matrix<T> a = Matrix<T>(this);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i < j) {
                    buf = a[i][j] / a[i][i];
                    for (int k = 0; k < n; k++) {
                        a[j][k] -= a[i][k] * buf;
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            retval *= a[i][i];
        }
        return retval;
    }

    void power(int64_t p) {
        if(r != c) return;
        auto mul = *this;
        *this = I(r);
        for (; p > 0; p >>= 1, mul = mul * mul) {
            if (p & 1) {
                *this = mul * (*this);
            }
        }
    }

    static Matrix<T> I(int n) {
        Matrix<T> a(n, n, 0);
        for (int i = 0; i < n; i++) {
            a[i][i] = 1;
        }
        return a;
    }
};

int main() {
