	cin >> L >> A >> B >> M;
	mod = M;
	ll mx = A + B * (L - 1);
	ll dmx = getdigit(mx);
	modll ans=0;
	ll first = A;
	for (int i = getdigit(A); i <= dmx; i++) {
		modll r = modpow(modll(10), i);
		ll n;
		if (i == dmx) {
			n = (mx - first) / B + 1;
		}
		else {
			n = (intpow(10, i) - first) / B+1;
		}
		ans *= modpow(r, n);
		modll s = (modll(1) - modpow(r, n))* modinv((modll(1) - r).val, mod);
		ans += modll(B) * (modll(n) - s)*modinv((modll(1)-r).val,mod) + modll(first) * s;
		first = A + B * n;
	}
	cout << ans.val << endl;
}

