            int cnt = 0;
            while (tmp % i == 0) {
                tmp /= i;
                cnt++;
            }
            if (cnt > 0) {

                primes.push_back(make_pair(i, cnt));
            }
        }
    }
    if (tmp != 1) {
        primes.push_back(make_pair(tmp, 1));
    }
    MODN = 1;
    for (const auto& pa : primes) {
        int64_t p;
        int n;
        tie(p, n) = pa;
        MODN *= p - 1;
        rep(i, n - 1)
        {
            MODN *= p;
        }
    }

    int64_t result = 0;
    rep(d, 18)
    {
        int64_t e = 1;
        rep(i, d)
        {
            e *= 10;
        }
        int64_t lb = max(0L, dceil(e - A, B));
        int64_t ub = min(L - 1, dfloor(10 * e - A - 1, B));

        int64_t X = A % MOD;
        int64_t Y = B % MOD;
        int64_t C = (X + lb % MOD * Y % MOD) % MOD;
        int64_t m = ub - lb;
        int64_t M = m % MOD;
        int64_t E = dpow(10, d + 1);

        if (m >= 0) {
            int64_t S;
            if (E == 1) {
                int64_t t1 = dmul(dadd(M, 1), dadd(X, dmul(Y, lb % MOD)));
                int64_t t2 = dmul(dmul(M, dadd(M, 1)), inv(2));
                S = dadd(t1, t2);
            } else {
                int64_t t1 = dadd(C, dmul(M, Y));
                int64_t t2 = dminus(dmul(C, dpow(E, m + 1)));
                int64_t t3 = dmul(
                    dmul(
                        dmul(dminus(Y), E),
                        dadd(1, dminus(dpow(E, m)))),
                    inv(dadd(1L, dminus(E))));
                S = dmul(dadd(dadd(t1, t2), t3), inv(dadd(1, dminus(E))));
            }
            result = dadd(dmul(result, dpow(E, m + 1)), S);
        }
    }
    cout << result << endl;

    return 0;
}

