mtl matprod(mtl &x, mtl &y){
    int n = x.size();
    mtl ans = mtl(n, vl(n, 0));
    rep(i, n){
        rep(j, n){
            rep(k, n){
                ans[i][j] = (ans[i][j] + x[i][k] * y[k][j] % m) % m;
            }
        }
    }
    return ans;
}

mtl matpow(mtl &x, ll a){
    int n = x.size();
    mtl ans = mtl(n, vl(n, 0));
    rep(i, n) ans[i][i] = 1;
    while(a){
        if(a & 1) ans = matprod(ans, x);
        a >>= 1;
        x = matprod(x, x);
    }
    return ans;
}

ll solve(ll n, ll c, ll t){
    mtl x = {
            {1, 0, 0},
            {b, 1, 0},
            {0, 1, t}
    };
    x = matpow(x, n);
    return (x[2][0] + x[2][1] * c % m) % m;
}


