LL L, A, B, M;

long long modPow(long long x, long long y){
    long long r=1, a=x%M;
    while(y > 0){
        if((y&1) == 1) r = (r*a) % M;
        a = (a*a) % M;
        y /= 2;
    }
    return r;
}

long long _Pow(long long x, long long y){
    long long r=1, a=x;
    while(y > 0){
        if((y&1) == 1) r = r*a;
        a = a*a;
        y /= 2;
    }
    return r;
}

int disit(LL n) {
  int res = 0;
  while(n > 0) {
    res++;
    n /= 10;
  }
  return res;
}

LL term(LL a, LL b, int i) {
  return a + b*i;
}

LL hoge(LL len, LL p) {
  // 1 + p + p^2 + ... + p^(len-1)
  if (len == 1) return 1;
  if (len % 2 == 0) {
    return (hoge(len/2, p) * (1+_Pow(p, len/2)%M)%M) % M;
  } else {
    return (hoge(len-1, p) + _Pow(p, len-1)%M) % M;
  }
}

LL hoge2(LL len, LL p) {
  // 1*p^(len-1) + 2*p^(len-2) + ... + (len-1)*p + len*1
  // 6 + 500 + 40000 + 3000000 + 200000000 + 10000000000
  if (len == 0) return 0;
  if (len == 1) return 1;
  if (len % 2 == 0) {
    return hoge2(len/2, p)*(1+_Pow(p, len/2)%M)%M + (len/2)%M*hoge(len/2, p)%M;
  } else {
    return (len + p*hoge2(len-1, p)%M) % M;
  }
}

void solve() {
  cin >> L >> A >> B >> M;
  LL res = 0;

  LL i = L-1;
  LL zeros = 0;
  while(i >= 0) {
    LL start = term(A, B, i);
    int d = disit(start);
    LL len = min(i+1LL, (start-_Pow(10, d-1))/B + 1);
    i = i-len+1;
    LL end = term(A, B, i);
    i--;

    LL tmp = end*hoge(len, _Pow(10, d)%M)%M;
    tmp = (tmp + B*hoge2(len-1, _Pow(10, d)%M)%M) % M;

    res = (res + (tmp*modPow(10, zeros))%M) % M;

    zeros += d * len;
  }

  cout << res << endl;
}

int main() {
	solve();
	return 0;
}

