ll f(int k, ll l) { // 桁数, 項数
    if (l == 0) return 0;
    if (l % 2) {
        return (f(k, l - 1) * modpow(10LL, k, M) + 1) % M;
    } else {
        ll ret = f(k, l / 2) * modpow(10LL, k * (l / 2) % M, M);
        ret %= M;
        ret += f(k, l / 2);
        ret %= M;
        return ret;
    }
}
ll g(int k, ll l) {
    if (l == 0) return 0;
    if (l % 2) {
        ll ret = g(k, l - 1) * modpow(10LL, k, M);
        ret %= M;
        ret += B * (l - 1) % M;
        ret %= M;
        return ret;
    } else {
        ll ret = g(k, l / 2) * modpow(10LL, k * (l / 2) % M, M);
        ret %= M;
        ret += g(k, l / 2);
        ret %= M;
        ret += B * (l / 2) % M * f(k, l / 2) % M;
        ret %= M;
        return ret;
    }
}
