    {
        long long naive = 0;
        long long A = a;
        long long B = b;
        for (int i = 0; i < l; i++)
        {
            naive = (naive * inq(10, log10(A), m) + A) % m;
            A = A + B;
        }
        cout << naive << endl;
        return 0;
    }
    long long last = a + (l - 1) * b;
    long long zeroes = 0;
    long long ans = 0;
    for (int i = log10(last); i >= 1 && l > 0; i--)
    {
        //cout << "last = " << last << endl;
        //cout << "zeroes = " << zeroes << endl;
        long long lesser = inq(10, i - 1);
        long long steps = (last - lesser + b - 1) / b;
        if (last - steps * b >= lesser) steps++;
        steps = min(steps, l);
        l = l - steps;
        ans = (ans + mm + scalar(last, -b, inq(10, zeroes, m), inq(10, log10(last)), steps)) % m;
        zeroes += steps * log10(last);
        last = last - steps * b;
        //cout << ans << endl;
    }
    cout << ans;
}

