struct mint {
    ll x; // typedef long long ll;
    mint(ll x=0):x((x%mod+mod)%mod){}
    mint operator-() const { return mint(-x);}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod-a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod-2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};
istream& operator>>(istream& is, const mint& a) { return is >> a.x;}
ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}

struct Matrix {
    mint m[3][3];
    Matrix(vector<mint> v) {
        rep(i, 9) {
            m[i/3][i%3] = v[i];
        }
    }
};

Matrix multiple(Matrix a, Matrix b) {
    vector<mint> v(9);
    rep(i, 9) {
        ll x = i/3;
        ll y = i%3;
        rep(j, 3) {
            v[i] += a.m[x][j]*b.m[j][y];
        }
    }
    return Matrix(v);
}

Matrix power(Matrix a, ll n) {
    if (n==0) {
        vector<mint> v(9);
        rep(i, 9) {
            if (i==0 || i==4 || i==8) v[i] = 1;
            else v[i] = 0;
        }
        return Matrix(v);
    }
    if (n==1) return a;
    if (n%2==0) {
        return power(multiple(a, a), n/2);
    }
    return multiple(a, power(a, n-1));
}



