ll find_len(ll L,ll A,ll B) {
	int z=len(A);
	ll l=0,r=L;
	while (l<r) {
		ll m=l+(r-l)/2;
		if (z==len(A+B*m)) l=m+1; else r=m;
	}
	return l;
}

