const ll MOD=1e9+7;
const int N=500000;
ll modpow(ll x,ll n,ll mod){
    ll ret=1;
    while(n){
        if(n&1) ret=ret*x%mod;
        x=x*x%mod; n>>=1;
    }
    return ret;
}
ll sum(ll a,ll r,ll n,ll mod){
    if(n==0)return 0;
    if(n==1) return a%mod;
    ll x=sum(a,r,n/2,mod);
    ll ret=(x+modpow(r,n/2,mod)*x%mod)%mod;
    if(n&1) ret=(a+r*ret%mod)%mod;
    return ret;
}
ll sum2(ll a,ll r,ll n,ll mod){
    if(n==0)return 0;
    if(n==1) return 0;
    if(n&1){
        return (sum2(a,r,n-1,mod)+sum(a,r,n-1,mod))%mod;
    }
    ll x=sum2(a,r,n/2,mod);
    // cout<<r<<" "<<n<<" "<<x<<endl;
    x=(x*(modpow(r,n/2,mod)+1ll)%mod+(n/2ll)*sum(a,r,n/2,mod)%mod)%mod;
    // cout<<r<<" "<<n<<" "<<x<<endl;
    return x;
}

main(){
    ll l,a,b;
    cin>>l>>a>>b;
    ll m=lin();
    ll res=0,keta=1;
    ll ans=0;
    ll now=10;
    while(now<=(ll)1e18){
        ll next=(now-1-a)/b;
        if(next>l-1)next=l-1;
        if(next*b>=now-a){
            keta++;now*=10;
            continue;
        }
        ll cnt=next-res+1;
        ll A=(a%m+(res%m)*(b%m)%m)%m,B=b%m;
        ll s=keta,t=cnt;
        ll T=modpow(10,s,m);
        ans=ans*modpow(T,t,m)%m;
        ans=(ans+A*sum(1,T,t,m)%m)%m;
        // cout<<ans<<" ";
        assert(ans>0);
        ans=(ans+B*sum2(1,T,t,m)%m)%m;
        assert(ans>0);
        // cout<<ans<<endl;
        keta++;
        if(now==1e18)break;
        now*=10;
        res=next+1;
    }
    cout<<ans;
}

