template<class T, int N> struct mat : matar<matar<T, N>, N> {
    using matar<matar<T, N>, N>::matar;
    using matar<matar<T, N>, N>::size;
    template<class U> mat(vector<vector<U>> &a) {    assert(sz(a) == sz(a[0]) && sz(a) == N);        rep(i, N)rep(j, N)(*this)[i][j] = a[i][j];    };
    template<class U> mat(initializer_list<initializer_list<U>> a) {        int i = 0, j = 0;        fora(v, a) {            j = 0;            fora(x, v) {                (*this)[i][j] = x;                j++;            }            i++;        }    }
    void unit(int v = 1) {rep(i, N)rep(j, N)(*this)[i][j] = 0;rep(i, N)(*this)[i][i] = v;}
    void zero() { rep(i, N) rep(j, N)(*this)[i][j] = 0; }
    mat(int v = 0) { if (v == 0)zero(); else unit(v); }
    int h() const { return size(); }
    int w() const { return size(); }
    template<class U> void fill(U v) { rep(i, N)rep(j, N)(*this)[i][j] = v; }
    T sum() {T res = 0;rep(i, N)rep(j, N)res += (*this)[i][j];return res;}
    mat operator+(mat &r) {mat res = mat();rep(i, N) rep(j, N)res[i][j] = (this)[i][j] + r[i][j];return res;}
    mat operator-(mat &r) {mat res = mat();rep(i, N) rep(j, N)res[i][j] = (this)[i][j] - r[i][j];return res;}
    mat operator*(mat &r) {mat res = mat();rep(i, N) rep(j, N) rep(k, N)res[i][j] += (*this)[i][k] * r[k][j];return res;}
    mat &operator+=(mat &r) { return *this = *this + r; }
    mat &operator-=(mat &r) { return *this = *this - r; }
    mat &operator*=(mat &r) { return *this = *this * r; };
    mat &operator^=(int k) {return *this = pow(k);}
    mat operator^(int k) {return pow(k);}
