int main() {
  ll L, A, B, M;
  cin >> L >> A >> B >> M;

  P digit = P(1, 1);
  ll tmp = 10;
  while (A >= tmp) {
    tmp *= 10;
    ++digit.first;
  }

  ll last = A + B * (L-1);
  tmp = 10;
  while (last >= tmp) {
    tmp *= 10;
    ++digit.second;
  }

  ll init = A;
  ll ans = 0;
  ll pow10 = pow(10, digit.first);

  for (int k=digit.first; k<=digit.second; ++k) {
    if (pow10 <= init) {
      pow10 *= 10;
      continue;
    }

    ll num = (min(pow10 - 1, last) - init) / B + 1;

    vl rem(64), dp(64), dp2(64), power(64);
    rem[0] = pow10 % M;
    dp[0] = 1;
    dp2[0] = 1;
    power[0] = 1;

    rep(i,63) {
      rem[i+1] = rem[i] * rem[i] % M;
      dp[i+1] = dp[i] * (1 + rem[i]) % M;
      dp2[i+1] = (dp2[i] * (1 + rem[i]) + dp[i] * power[i]) % M;
      power[i+1] = power[i] * 2 % M;
    }

    ll expo = 1, sigma_a = 0;
    ll expo2 = 1, sum = 0, sigma_b = 0;

    for (int i=63; i>=0; --i) {
      if ((num >> i) & 1) {
        (sigma_a += expo * dp[i]) %= M;
        (expo *= rem[i]) %= M;
      }

      if (((num - 1) >> i) & 1) {
        (sigma_b += sum * power[i] + expo2 * dp2[i]) %= M;
        (sum += expo2 * dp[i]) %= M;
        (expo2 *= rem[i]) %= M;
      }
    }

    (ans *= expo) %= M;
    (ans += (init % M) * sigma_a + (B % M) * sigma_b) %= M;
    init += B * num;

    pow10 *= 10;
  }

  cout << ans << endl;
  return 0;
}

