int modsum1(int D, int n, int M){
    //int S = 0;
    //REP(i, n) S = (S + modpow(D, i, M)) % M;
    int S = 0;
    int now = 0;
    IREP(i, 64){
        if(now > 0){ 
            S = (S * (1 + modpow(D, now, M))) % M;
            now *= 2;
            if(((n >> i) & 1) == 1) {
                S += modpow(D, now, M);
                S %= M;
                now++;
            }
        }else if(((n >> i) & 1) == 1){
            S = 1;
            now = 1;
        }
    }

    return S;
}

int modsum2(int D, int n, int M){
    //int S = 0;
    //REP(i, n) S = (S + i * modpow(D, i, M)) % M;

    int S = 0;
    int now = 0;
    IREP(i, 64){
        if(now > 0){ 
            int T = (S * modpow(D, now, M)) % M;
            int U = (modsum1(D, 2 * now, M) - modsum1(D, now, M) + M) % M;
            U = ((now % M) * U) % M;
            S = (S + T + U) % M;
            now *= 2;
            if(((n >> i) & 1) == 1) {
                S += ((now % M) * modpow(D, now, M)) % M;
                S %= M;
                now++;
            }
        }else if(((n >> i) & 1) == 1){
            S = 0;
            now = 1;
        }
    }

    return S;
}

