struct mint {
    long long x;
    mint(long long x=0):x((x%MOD+MOD)%MOD){}
    mint operator-() const { return mint(-x);}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += MOD-a.x) >= MOD) x -= MOD;
    	return *this;
    }
    mint& operator*=(const mint a) {
    	(x *= a.x) %= MOD;
        if(x < 0) x += MOD;
    	return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(long long t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
    	if (t&1) a *= *this;
        return a;
    }
    // for prime MOD
    mint inv() const {
        return pow(MOD-2);
    }
    mint& operator/=(const mint a) {
    	return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};

ll digit(ll x){
    ll ret = 0;
    while(x){
        ret++;
        x /= 10;
    }
    return ret;
}

void Main(){
    ll L,A,B; cin >> L >> A >> B >> MOD;
    ll d[20][2]; REP(i,20)REP(j,2) d[i][j] = 1;
    REP(i,19){
        ll l = 0, r = L+1;
        while(r-l>1){
            ll x = (l+r)/2;
            if(digit(A+(x-1)*B) < i+1) l = x;
            else r = x;
        }
        d[i][1] = d[i+1][0] = r;
    }
    d[19][1] = L+1;

    ll mind = digit(A), maxd = digit(A+(L-1)*B);

    vector<mint> sum(20);
    FOR(i,mind,maxd+1){
        ll len = d[i][1] - d[i][0];
        if(len <= 0) continue;

        ll cnt = 0;
        mint doub(A+(d[i][0]-1)*B), b(B);
        while(len){
            if(len&1){
                sum[i] = sum[i]*mint(10).pow(i*(1<<cnt)) + doub;
                doub += b*(1<<cnt);
            }
            doub = doub*mint(10).pow(i*(1<<cnt)) + doub + b*(1<<cnt);
            b = b*mint(10).pow(i*(1<<cnt)) + b;
            len >>= 1;
            cnt++;
        }
    }

    mint ans;
    ll cum = 0;
    RFOR(i,maxd+1,mind){
        ll len = d[i][1] - d[i][0];
        ans += sum[i]*mint(10).pow(cum);
        cum += i*len;
    }

    cout << ans.x << en;
    return;
}

