int mod_inv(int X,int mao){
	int a = X, b = mao, u = 1, v = 0;
	while(b) {
		int t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	if(u < 0) u += mao;
	return u;
}

int mod_inv(int X){
	return mod_inv(X,MOD);
}

int powow1(int n,int k){
	return powow(k,10) * (powow((n - 1) * k,10) - 1 + MOD) % MOD * mod_inv((powow(k,10) - 1 + MOD) % MOD) % MOD;
}

long long Garner(vector<long long> b, vector<long long> m) {
    m.push_back(mo); // banpei
    vector<long long> coeffs((int)m.size(), 1);
    vector<long long> constants((int)m.size(), 0);
    for (int k = 0; k < (int)b.size(); ++k) {
        long long t = (b[k] - constants[k]) * mod_inv(coeffs[k], m[k]) % m[k];
        for (int i = k+1; i < (int)m.size(); ++i) {
            (constants[i] += t * coeffs[i]) %= m[i];
            (coeffs[i] *= m[k]) %= m[i];
        }
    }
    return constants.back();
}

int calc(int a,int b,int n,int k){
	int ans = (a * powow(k * n,10) % MOD - (a + (n - 1) * b) + MOD) % MOD;
	ans = (ans + b * powow1(n,k)) % MOD;
	return ans * mod_inv((powow(k,10) - 1 + MOD) % MOD) % MOD;
}

