long long inq(long long x, long long y)
{
    if (y == 0) return 1;
    long long l = inq(x, y / 2);
    if (y % 2) return l * l * x;
    return l * l;
}

long long inq(long long x, long long y, long long MOD)
{
    if (y == 0) return 1 % MOD;
    long long l = inq(x, y / 2, MOD);
    if (y % 2) return l * l % MOD * x % MOD;
    return l * l % MOD;
}

long long phi(long long m)
{
    long long r = 0;
    for (int i = 1; i <= m; i++)
    {
        if (__gcd(i, m) == 1) r++;
    }
    return r;
    long long s = m;
    vector<pair<int, int> > kek;
    for (int i = 2; i * i <= m; i++)
    {
        while (m % i == 0)
        {
            if (kek.size() == 0 || kek[kek.size() - 1].first != i)
                kek.push_back({i, 1});
            else
                kek[kek.size() - 1].second++;
            m /= i;
        }
    }
    if (m > 1)
    {
        kek.push_back({m, 1});
    }
    for (int i = 0; i < kek.size(); i++)
    {
        s = s - s / inq(kek[i].first, 1);
    }
    return s;
}

long long divide(long long x, long long y)
{
    x = (x + mm) % m;
    y = (y + mm) % m;
    //cout << x << "/" << y;
