mll pow_(ll a, ll b) {
    if(b == 0) return mll(1);
    if(b%2 == 1) {
        return pow_(a,b-1)*mll(a);
    } else {
        mll c = pow_(a,b/2);
        return c*c;
    }
}

mll f(ll n) {
    if(n==0) return mll(0);

    if(n%2) {    
        return f(n-1) + pow_(ten, n-1);   
    } else {
        return f(n/2)*(pow_(ten, n/2) + mll(1));
    }
}

mll g(ll n) {
    if(n==0) return mll(0);
    if(n%2) {
        return g(n-1)*mll(ten) + mll(n-1);
    } else {
        return g(n/2)*(pow_(ten, n/2)+mll(1)) + f(n/2)*mll(n/2);
    }
}


