LL calc_w(LL v){
    LL w = 0;
    while(v > 0){
        ++w;
        v /= 10;
    }
    return w;
}

LL binary_w(LL w, LL A, LL B, LL L){
    if(calc_w(A) >= w) return 0;
    if(calc_w(A + B*L) < w) return L;
    LL left = 0;
    LL right = L;
    while(left+1 < right){
        LL middle = (left+right)/2;
        if(calc_w(A + B*middle) < w){
            left = middle;
        }else{
            right = middle;
        }
    }
    return left+1;
}

LL mod_pow(LL n, LL m, LL p){
    if(m <= 0) return 1;
    LL res = mod_pow(n, m/2, p);
    res = res * res % p;
    if(m&1) res = res * n % p;
    return res;
}

LL pow_seq(LL b, LL len, LL p){
    if(len == 0) return 0;
    if(len == 1) return 1;
    LL part = pow_seq(b, len/2, p);
    LL base = mod_pow(b, len/2, p);
    LL res = part + base * part % p;
    if(len&1) res = (res + mod_pow(b, len-1, p)) % p;
    return res;
}

LL calc(LL A, LL B, LL left, LL right, LL reed, LL w, LL M){
    LL begin = (A + left * B) * mod_pow(10, reed, M) % M;
    if(left == right) return 0;
    if(left + 1 == right) return begin;

    LL w2 = mod_pow(10, w, M);
    LL right2 = left + (right - left) / 2;
    LL part = calc(A, B, left, right2, reed, w, M);
    LL base = mod_pow(w2, right2-left, M);
    LL res = (part + base * part % M + base * (right2-left) % M * pow_seq(w2, (right2-left), M) % M) % M;
    if((right - left) & 1){
        LL last = (A + (right-1) * B) * mod_pow(10, reed, M) % M * mod_pow(w2, right-1, M) % M;
        res = (res + last) % M;
    }
    return res;
}

int main(){
    LL L, A, B, M;
    cin >> L >> A >> B >> M;
    LL ans = 0;
    LL reed = 0;
    for(LL w = 1; w < 19; ++w){
        LL left = binary_w(w, A, B, L);
        LL right = binary_w(w+1, A, B, L);
        cerr << "w=" << w << ", left=" << left << ", right=" << right << ", " << A + left*B << endl;
        LL part = calc(A, B, left, right, reed, w, M);
        cerr << "part=" << part << endl;
        ans = (ans * mod_pow(10, w*(right-left), M) % M + part) % M;
        reed += w * (right - left);
        if(right == L) break;
    }
    cout << ans << endl;
    return 0;
}

