int m;
LL d;
int mul(int x,int y){
	return (LL)x*y%m;
}
int fpow(LL x,LL y){
	int z=1;
	x%=m;
	while(y){
		if(y&1)
			z=mul(z,x);
		y>>=1;
		x=mul(x,x);
	}
	return z;
}
pair<int,int> solve(LL w,int o){
	if(w==1)
		return make_pair(1,0);
	int a,b,e=fpow(o,w/2);
	pair<int,int> p=solve(w/2,o);
	a=p.first,b=p.second;
	p.first=mul(a,e+1);
	p.second=(mul(b,e+1)+mul(a,(w/2)%m))%m;
	if(w&1){
		a=p.first,b=p.second;
		p.first=(mul(a,o)+1)%m;
		p.second=(b+a)%m;
	}
	return p;
}
int main()
{
	LL w,l,r,o,a,b,c,s;
	int i;
	pair<int,int> p;
	cin>>w>>l>>r>>m;
	d=r;
	r=l+d*(w-1);
	s=0;
	o=1;
	for(i=0;i<18;i=i+1){
		a=max(l,o);
		a+=(l%d-a%d+d)%d;
		b=min(r,o*10-1);
		b-=(b%d-r%d+d)%d;
		o*=10;
		if(a>b)
			continue;
		c=(b-a)/d+1;
		s=mul(s,fpow(o,c));
		p=solve(c,o%m);
		s+=mul(a%m,p.first);
		s+=mul(d%m,p.second);
		s%=m;
	}
	cout<<s;
	return 0;
}

