ll MOD;

int calc_lg(ll x) {
  int res = 0;
  while (x > 0) {
    ++res;
    x /= 10;
  }
  return res;
}

ll calc_ten(int e) {
  ll v = 1;
  for (int i = 0; i < e; i++) v *= 10;
  return v;
}

ll power(ll x, ll e) {
  x %= MOD;
  ll v = 1;
  for (; e > 0; e >>= 1) {
    if (e & 1) {
      v = v * x % MOD;
    }
    x = x * x % MOD;
  }
  return v;
}

// sum[ x^i, {i, 0, e}]
ll geometricSum(ll x, ll e) {
  x %= MOD;
  ll n = e + 1, v = 0, p = 1;
  for (int b = 63 - __builtin_clzll(n); b >= 0; b--) {
    v = (v * p % MOD + v) % MOD;
    p = p * p % MOD;
    if ((n >> b) & 1) {
      v = (v * x + 1) % MOD;
      p = p * x % MOD;
    }
  }
  return v;
}

// sum[i * x^(n-1-i), {i, 0, n - 1}]
ll func(ll b, ll n) {
  if (n == 1) return 0;
  ll a = func(b, n / 2);
  ll x = a;
  x += (n - n / 2) % MOD * geometricSum(b, n / 2 - 1) % MOD;
  x %= MOD;
  ll y = a * power(b, (n + 1) / 2) % MOD;
  ll res = (x + y) % MOD;
  if (n % 2 == 1) {
    res += (n / 2) % MOD * power(b, n / 2) % MOD;
    res %= MOD;
  }
  return res;
}

int main() {
#ifdef DEBUG
  ifstream ifs("in.txt");
