#endif
  ll L, A, B;
  while (cin >> L >> A >> B >> MOD) {
    ll res = 0, cur = 0;
    while (cur < L) {
      int lg = calc_lg(A);
      ll ten = calc_ten(lg);
      // x >= (ten - A) / B
      ll x = min(L - cur, (ten - A + B - 1) / B);
      res = res * power(ten, x) % MOD;
      res += A % MOD * geometricSum(ten % MOD, x - 1) % MOD;
      res %= MOD;
      res += B % MOD * func(ten % MOD, x) % MOD;
      res %= MOD;
      cur += x;
      A += B * x;
    }
    cout << res << endl;
  }
  return 0;
}

