ll modpow(ll x, ll y){
    if(y == 0)return 1;
    if(y == 1)return x % mod;
    ll res = modpow(x,y/2);
    res = res * res % mod;
    if(y%2)res = res * x % mod;
    return res;
}
ll pow2(ll x, ll y){
    if(y == 0)return 1;
    if(y == 1)return x;
    ll res = pow2(x,y/2);
    res = res * res;
    if(y%2)res = res * x;
    return res;
}
