class UnionFind {
public:
	vector<int> par;
	UnionFind(int n) {
		par = vector<int>(n, -1);
	}
	int root(int a) {
		if (par[a] < 0) {
			return a;
		}
		else {
			return par[a] = root(par[a]);
		}
	}
	int size(int a) {
		return -par[root(a)];
	}
	bool connect(int a, int b) {
		a = root(a);
		b = root(b);
		if (a == b) {
			return false;
		}
		if (size(a) < size(b)) {
			swap(a, b);
		}
		par[a] += par[b];
		par[b] = a;
		return true;
	}
};
struct edge { int cost, u, v; };
bool cmp(edge& a, edge& b) { return a.cost < b.cost; }
vector<edge> es;
int kruskal(int V) {
	sort(es.begin(), es.end(), cmp);
	UnionFind UF(V);
	ll res = 0;
	for (edge e : es) {
		if (UF.connect(e.u, e.v)) {
			res += e.cost;
		}
	}
	return res;
}
vector<int> fac, finv;
void factorial(int N) {
	fac.resize(N); finv.resize(N);
	fac[0] = finv[0] = 1;
	rep(i, 1, N)fac[i] = Mul(fac[i - 1], i);
	finv[N - 1] = mpow(fac[N - 1], mod - 2);
	rrep(i, N - 2, -1) finv[i] = Mul(finv[i + 1], i + 1);
}
int nCr(int n, int m) {
	if (m < 0 || n < m) return 0;
	return Mul(Mul(fac[n], finv[m]), finv[n - m]);
}
ll merge_cnt(vector<int>& a) {
	int n = a.size();
	if (n <= 1) return 0;
	ll cnt = 0;
	vector<int> b(a.begin(), a.begin() + n / 2);
	vector<int> c(a.begin() + n / 2, a.end());
	cnt += merge_cnt(b);
	cnt += merge_cnt(c);
	int ai = 0, bi = 0, ci = 0;
	while (ai < n) {
		if (bi < b.size() && (ci == c.size() || b[bi] <= c[ci])) {
			a[ai++] = b[bi++];
		}
		else {
			cnt += n / 2LL - bi;
			a[ai++] = c[ci++];
		}
	}
	return cnt;
}
void fft(vector<com>& x, bool inv) {
	int s = x.size();
	if (s == 1) return;
	else {
		vector<com> even(s / 2), odd(s / 2);
		rep(i, 0, s / 2) {
			even[i] = x[i * 2];
			odd[i] = x[i * 2 + 1];
		}
		fft(even, inv);
		fft(odd, inv);
		com w = 1, w_0 = polar(1.0, (inv ? -1 : 1) * 2LL * M_PI / s);
		int t = s / 2 - 1;
		rep(i, 0, s) {
			x[i] = even[i & t] + w * odd[i & t];
			w *= w_0;
		}
	}
}
#define MAX_V 100010
vector<edge> G[MAX_V]; ll dist[MAX_V];
void dijkstra(int s) {
	priority_queue<P, vector<P>, greater<P> > que;
	fill(dist, dist + MAX_V, INF);
	dist[s] = 0;
	que.push(P(0, s));
	while (!que.empty()) {
		P p = que.top();
		que.pop();
		int v = p.second;
		if (dist[v] < p.first) continue;
		for (int i = 0; i < G[v].size(); ++i) {
			edge e = G[v][i];
			if (dist[e.v] > dist[v] + e.cost) {
				dist[e.v] = dist[v] + e.cost;
				que.push(P(dist[e.v], e.v));
			}
		}
	}
}
int diameter(vector<vector<edge>>& g) {
	function<P(int, int)> DFS = [&](int prev, int v) {
		P r(0, v);
		rep(i, 0, g[v].size()) {
			edge e = g[v][i];
			if (e.v == prev) continue;
			P tmp = DFS(v, e.v);
			tmp.first += e.cost;
			if (r.first < tmp.first) r = tmp;
		}
		return r;
	};
	P r = DFS(-1, 0);
	P t = DFS(-1, r.second);
	return t.first;
}
int match(vector<vector<int>>& g) {
	int n = g.size();
	vector<int> color(n, -1);
	int white_cnt = 0;
	function<bool(int, int, int)> DFS = [&](int u, int prev, int c) {
		color[u] = c;
		if (c == 1) white_cnt++;
		for (auto v : g[u]) if (v != prev) {
			if (color[v] == -1) {
				if (!DFS(v, u, 1 - c)) return false;
			}
			else if (color[v] != 1 - c) {
				return false;
			}
		}
		return true;
	};
	if (!DFS(0, -1, 0)) return -1;
	return white_cnt;
}
class flow {
private:
	struct Edge { int to, cap, rev; };
	vector<vector<Edge>> G; vector<bool> used;
public:
	void flowsize(int V){G.resize(V); used.resize(V);}
	void add_edge(int from, int to, int cap) {
		G[from].push_back({ to,cap,(int)G[to].size() });
		G[to].push_back({ from,0,(int)G[from].size() - 1 });
	}
	int max_flow(int s, int t) {
		int res = 0;
		function<int(int, int, int)> DFS = [&](int v, int t, int f) {
			if (v == t) return f;
			used[v] = true;
			rep(i, 0, G[v].size()) {
				Edge& e = G[v][i];
				if (!used[e.to] && e.cap > 0) {
					int d = DFS(e.to, t, min(f, e.cap));
					if (d > 0) {
						e.cap -= d; G[e.to][e.rev].cap += d;
						return d;
					}
				}
			}
			return 0;
		};
		while (1) {
			fill(used.begin(), used.end(), 0);
			int f = DFS(s, t, inf);
			if (f == 0) return res;
			res += f;
		}
	}
};
