vector<vector<ll>> matmul(vector<vector<ll>> a, vector<vector<ll>> b) {
	vector<vector<ll>> ans(a.size(), vector<ll>(b[0].size(), 0));
	rep(i, 0, a.size())rep(j, 0, b[0].size())rep(k,0,b.size()) {
		ans[i][j] = Addm(ans[i][j],Mulm(a[i][k]%m,b[k][j]%m));
	}
	return ans;
}
vector<vector<ll>> matpow(vector<vector<ll>> a, ll t) {
	vector<vector<ll>> ans(a.size());
	rep(i, 0, a.size()) {
		ans[i].resize(a.size(), 0);
		ans[i][i] = 1;
	}
	while (t) {
		if (t % 2) ans = matmul(ans, a);
		a = matmul(a, a); t >>= 1;
	}
	return ans;
}
ll modpow(ll a, ll b){
	ll r = 1; a %= m;
	while (b) { r = Mulm(r,((b % 2) ? a : 1)), a = Mulm(a,a), b >>= 1; }
	return r;
}

