class Integer{
public:
  string val;
  Integer():val("0"){}
  Integer(string num,bool reversed=0){if(!reversed)R(num); val = num;}
  Integer(Int num){val = to_string(num); R(val);}

  void R(string &a){reverse(a.begin(),a.end());}
  bool neg(const string &a)const{return a.back() == '-';}
  char& operator [] (Int i){assert(i<(Int)val.size());return val[i];}

  bool operator ==  (Integer b) {R(b.val); return *this == b.val;}
  bool operator ==  (string b) {R(b);return val == b;}
  template<class T> bool operator == (T b){return *this == Integer(b);}

  bool operator !=  (Integer b) {R(b.val); return *this != b.val;}
  bool operator !=  (string b) {R(b);return !(val == b);}
  template<class T> bool operator != (T b){return *this != Integer(b);}

  bool operator >=  (Integer b) {R(b.val); return *this >= b.val;}
  bool operator >=  (string b) {return !(*this < b);}
  template<class T> bool operator >= (T b){return *this >= Integer(b);}

  bool operator >   (Integer b) {R(b.val); return *this > b.val;}
  bool operator >   (string b) {return *this>=b && *this != b;}
  template<class T> bool operator > (T b){return *this > Integer(b);}

  bool operator <=  (Integer b) {R(b.val); return *this <= b.val;}
  bool operator <=  (string b) {return *this<b || *this == b;}
  template<class T> bool operator <= (T b){return *this <= Integer(b);}

  bool operator <   (Integer b) {R(b.val); return *this < b.val;}
  template<class T> bool operator < (T b){return *this < Integer(b);}

   bool operator <   (string b) {
    R(b);
    const string &a = val;
    if(neg(a) != neg(b)) return neg(a)? 1:0;
    if(a.size() != b.size()) return !neg(a)? (a.size()<b.size()):(a.size()>b.size());
    for(Int i=a.size()-1;i>=0;i--)if(a[i] != b[i]) return !neg(a)? a[i] < b[i]: a[i] > b[i];
    return 0;
  }

  Integer operator + (string b){
    R(b);
    string a = val;
    string fa = neg(a)? "-":"";
    string fb = neg(b)? "-":"";
    if(neg(a)) a.pop_back();
    if(neg(b)) b.pop_back();
    if(Integer(a,1) < Integer(b,1)) swap(a,b),swap(fa,fb);

    if(fa == fb){
      a += '0';
      for(Int i=0;i<(Int)a.size()-1;i++){
        if(i < (Int)b.size()) a[i] += b[i]-'0';
        a[i+1] += (a[i]-'0')/10;
        a[i] = (a[i]-'0')%10 + '0';
      }
      if(a.size() > 1 && a.back() == '0') a.pop_back();
