/*掛け算*/
mat mult(const mat &A,const mat &B){
  assert(A[0].size() == B.size());
  Int n = A.size(),m = B.size(),l = B[0].size();
  mat C(A.size(),vec(l,0));

  for(Int i=0;i<n;i++)
    for(Int j=0;j<l;j++)
      for(Int k=0;k<m;k++) {
	C[i][j] += (A[i][k]*B[k][j]);
	C[i][j] %= mod;
      }  
  return C;
}

mat pow(mat A,Integer y){
  mat res(A.size(), vec(A.size()));
  for(Int i=0;i<(Int)A.size();i++) res[i][i] = 1;
  while(y != 0){
    if(y%2 == 1) res = mult(res, A);
    A = mult(A, A);
    y /= 2;
  }
  return res;
}


