		Matrix x=*this;

		while(n){
			if(n&1)res*=x;
			x*=x;
			n>>=1;
		}
		return res;
	}

	Matrix transpose(){
		Matrix T(a[0].size(),vector<Mint>(a.size()));
		for(int i=0;i<a.size();i++){
			for(int j=0;j<a[0].size();j++)T[j][i]=a[i][j];
