	Mint det(){
		Mint ret=1;
		vector<vector<Mint>>m=a;

		for(int i=0;i<a.size();i++){
			if(m[i][i]==0){
				for(int j=i+1;j<a.size();j++)if(m[j][i]!=0){
					swap(m[i],m[j]);
					ret=-ret;
					break;
				}
			}
			if(m[i][i]==0)return 0;
			ret*=m[i][i];

			Mint in=m[i][i].inv();
			for(int j=0;j<a.size();j++)m[i][j]*=in;
			for(int j=i+1;j<a.size();j++){
				Mint coef=m[j][i];
				for(int k=0;k<a.size();k++)m[j][k]-=m[i][k]*coef;
			}
		}
		return ret;
	}

	//det(A-tI)
	vector<Mint>eigenpoly(){
		int n=a.size();
		vector<Mint>eval(n+1);
		for(int i=0;i<=n;i++){
			auto A=*this;
			for(int j=0;j<n;j++)A[j][j]-=i;
			eval[i]=A.det();
		}

		vector<Mint>ret(n+1);
		for(int i=0;i<=n;i++){
			vector<Mint>p(n+1);
			p[0]=eval[i];
			Mint den=1;
			for(int j=0;j<=n;j++){
				if(j==i)continue;
				den*=i-j;
				for(int k=n-1;k>=0;k--){
					p[k+1]+=p[k];
					p[k]*=-j;
				}
			}
			den=den.inv();
			for(int j=0;j<=n;j++)p[j]*=den;
			for(int j=0;j<=n;j++)ret[j]+=p[j];
		}
		return ret;
	}
};
