ll extgcd(ll a, ll b, ll& x, ll& y){
  ll d = a;
  if(b != 0){
    d = extgcd(b, a%b, y, x);
    y -= (a/b) * x;
  }else{
    x = 1;
    y = 0;
  }
  return d;
}
ll mod_inverse(ll a, ll m){
  ll x, y;
  extgcd(a, m, x, y);
  return (m + x % m) % m;
}
ll mod_pow(ll x, ll n, ll mod){
  if(n==0) return 1;
  ll res = mod_pow(x * x % mod, n / 2, mod);
  if(n & 1) res = res * x % mod;
  return res;
}

int get_keta(ll x){
  int keta = 0;
  while(x>0){ keta++; x/=10; }
  return keta;
}

ll solve(ll L, ll A, ll B, ll M, ll st, ll ed, ll base){
  ll keta = get_keta(A + B*st);
  ll N = ed-st+1;
  if(N==0) return 0;

  ll AA = A + B * ed;
  A = AA;

  ll c = mod_pow(10, keta, M);

  ll x = (((N-1)%M) * mod_pow(c, N+1, M))%M;
  x -= ((N%M) * mod_pow(c, N, M))%M;
  x += M;
  x %= M;
  x += c;
  x %= M;
  x *= mod_pow(mod_inverse(c-1, M),2,M);
  x %= M;

  ll y = mod_pow(c, N, M);
  y -= 1;
  y += M;
  y %= M;
  y *= mod_inverse(c-1, M);
  y %= M;

  if(c==0){
    x = 0;
    y = 1;
  }
  if(c==1){
    x = ((N%M) * ((N-1)%M))%M;
    x *= mod_inverse(2, M);
    x %= M;
    y = N % M;
  }

  A %= M;
  B %= M;
  ll ret = (A * y)%M;
  ret -= (B * x)%M;
  ret += M;
  ret %= M;

  ret *= mod_pow(10, base, M);
  ret %= M;

  cerr << keta << " " << N << " " << A << " " << B << " " << c << " " << x << " " << y << " " << ret << endl;
  return ret;
}


