static SQWORD addModM(SQWORD x, SQWORD y, SQWORD m)
{ 
    return (x + y) % m;
}

static SQWORD subModM(SQWORD x, SQWORD y, SQWORD m)
{
    return (x - y + ANS_MOD) % m;
}

static SQWORD mulModM(SQWORD x, SQWORD y, SQWORD m) 
{
