void solve() {
  vi64 cnt(19);
  i64 L, A, B, M; cin >> L >> A >> B >> M;
  reps(i, 18) {
    i64 c = (power((i64) 10, i) - A + B) / B;
    if (B * c == power((i64) 10, i) + B - A) c--;
    if (c < 0) c = 0;
    cnt[i] = c;
  }
  rreps(i, 18) cnt[i] -= cnt[i - 1];
  vi64 as(19);
  reps(i, 18) as[i] = A + cnt[i] * B;
  if (L == 1) {
    cout << A % M << '\n';
    return;
  }
  mod = M;
  mint ans = 0;
  i64 s = 1;
  reps(i, 18) {
    i64 c = min(L, cnt[i]);
    if (c == 0) continue;
    i64 t = s + c - 1;
    {
      mint G = power((mint) 10, i);
      mint T = power(G, t - s + 1);

      ans *= T;
      ans += (mint) A * (T - 1) / (G - 1);
      ans += (mint) B * (T * (s - 1) + (T - G) / (G - 1) - (t - 1)) / (G - 1);
    }
    L -= c;
    s = t + 1;
  }
  cout << ans << '\n';
}

