  vll separator = {0};
  rep (i, max_digit - min_digit) {
    int digit = i + min_digit;
    ll target = po10[digit] - 1;
    separator.push_back((target - a) / b + 1);
  }
  separator.push_back(l);
  debug(separator);
  int sz = separator.size() - 1;
  vll rest(sz), sumdig(sz);
  assert(min_digit + sz - 1 == max_digit);
  rep (i, sz) {
    int digit = min_digit + i;
    ll elm_count = separator[i+1] - separator[i];
    sumdig[i] = elm_count % m * digit % m;
    if (elm_count == 0) {
      rest[i] = 0;
      continue;
    }
    vi proc;
    ll ec_dup = elm_count;
    while (ec_dup > 1) {
      if (ec_dup & 1) {
        proc.push_back(1);
        ec_dup -= 1;
      } else {
        proc.push_back(0);
        ec_dup >>= 1;
      }
    }
    reverse(all(proc));
    debug(proc);
    ll cnt = 1;
    ll crest = (a + (b % m) * (separator[i] % m)) % m;
    ll cdigit = digit;
    ll bdiff = b % m;
    for (int t : proc) {
      if (t == 1) {
        crest = (crest * po(10, digit, m) + a + (b % m) * ((separator[i] + cnt) % m)) % m;
        cdigit = (cdigit + digit) % m;
        bdiff = (bdiff * po(10, digit, m) + b) % m;
        cnt += 1;
      } else {
        crest = (crest * (po(10, cdigit, m) + 1) + bdiff * (cnt % m)) % m;
        bdiff = (bdiff * (po(10, cdigit, m) + 1)) % m;
        cdigit = (cdigit * 2) % m;
        cnt *= 2;
      }
    }
    assert(cnt == elm_count);
    rest[i] = crest;
  }

  debug(rest);
  debug(sumdig);
  sumdig.push_back(0);
  ll ans = 0;
  rep (i, sz) {
    ans = (ans + rest[i]) % m;
    ans = (ans * po(10, sumdig[i+1], m)) % m;
  }
