ll gcd(ll a, ll b) {
  return b == 0 ? a : gcd(b, a % b);
}

int calc_lg(ll x) {
  int res = 0;
  while (x > 0) {
    ++res;
    x /= 10;
  }
  return res;
}

ll calc_ten(int e) {
  ll v = 1;
  for (int i = 0; i < e; i++) v *= 10;
  return v;
}

ll power(ll x, ll e, ll MOD) {
  ll v = 1;
  for (; e > 0; e >>= 1) {
    if (e & 1) {
      v = v * x % MOD;
    }
    x = x * x % MOD;
  }
  return v;
}

long long modinv(long long a, long long m) {
  assert(gcd(a, m) == 1);
  long long b = m, u = 1, v = 0;
  while (b) {
    long long t = a / b;
    a -= t * b;
    swap(a, b);
    u -= t * v;
    swap(u, v);
  }
  u %= m;
  if (u < 0) u += m;
  return u;
}

// sum[ x^i, {i, 0, e}]
ll geometricSum(ll x, ll e, ll MOD) {
  ll n = e + 1, v = 0, p = 1;
  for (int b = 63 - __builtin_clzll(n); b >= 0; b--) {
    v = (v * p % MOD + v) % MOD;
    p = p * p % MOD;
    if ((n >> b) & 1) {
      v = (v * x + 1) % MOD;
      p = p * x % MOD;
    }
  }
  return v;
}

ll func(ll b, ll n, ll M) {
  ll res = power(b, n + 1, M);
  res += (M - (n + 1) % M * b % M) % M;
  res %= M;
  res += n % M;
  res %= M;
  ll k = (b - 1 + M) % M;
  k = k * k % M;
  res = res * modinv(k, M) % M;
  return res;
}

ll solveSub(ll L, ll A, ll B, ll M) {
  ll goal = A + B * L;
  ll res = 0, cur = 0;
  while (A < goal) {
    int lg = calc_lg(A);
    ll ten = calc_ten(lg);
    // x >= (ten - A) / B
    ll x = min(L - cur, (ten - A + B - 1) / B);
    res = res * power(ten % M, x, M) % M;
    res += A % M * geometricSum(ten % M, x - 1, M) % M;
    res %= M;
    res += B % M * func(ten % M, x - 1, M) % M;
    res %= M;
    // fin
    cur += x;
    A += B * x;
  }
  return res;
}

inline long long mod(long long a, long long m) {
  return (a % m + m) % m;
}

long long extGcd(long long a, long long b, long long &p, long long &q) {
  if (b == 0) {
    p = 1;
    q = 0;
    return a;
  }
  long long d = extGcd(b, a % b, q, p);
  q -= a / b * p;
  return d;
}

// 中国剰余定理
// リターン値を (r, m) とすると解は x ≡ r (mod. m)
// 解なしの場合は (0, -1) をリターン
pair<long long, long long> ChineseRem(const vector<long long> &b, const vector<long long> &m) {
  long long r = 0, M = 1;
  for (int i = 0; i < (int)b.size(); ++i) {
    long long p, q;
    long long d = extGcd(M, m[i], p, q);  // p is inv of M/d (mod. m[i]/d)
    if ((b[i] - r) % d != 0) return make_pair(0, -1);
    long long tmp = (b[i] - r) / d * p % (m[i] / d);
    r += M * tmp;
    M *= m[i] / d;
  }
  return make_pair(mod(r, M), M);
}

vector<ll> factorize(ll M) {
  vector<ll> res;
  for (ll p = 2; p * p <= M; p++) {
    if (M % p == 0) {
      ll v = 1;
      while (M % p == 0) {
        v *= p;
        M /= p;
      }
      res.push_back(v);
    }
  }
  if (M != 1) res.push_back(M);
  return res;
}

int main() {
#ifdef DEBUG
  ifstream ifs("in.txt");
  cin.rdbuf(ifs.rdbuf());
#endif
  ll L, A, B, M;
  while (cin >> L >> A >> B >> M) {
    vector<ll> ms = factorize(M);
    vector<ll> bs;
    for (ll m : ms) {
      bs.push_back(solveSub(L, A, B, m));
    }
    auto res = ChineseRem(bs, ms);
    cout << res.fst << endl;
  }
  return 0;
}

