		}
		ll a, nl;
		if (A >= l) {
			a = A;
		} else {
			ll n = ((l - A) + (B - 1)) / B;
			a = A + n * B;
			a = min(a, last);
		}
		ll nlast = 0;
		if (last <= r) {
			nlast = last;
		} else {
			ll n = (r - A) / B;
			nlast = A + n * B;
		}
		nl = (nlast - a) / B + 1;

		ans *= mypow(ten % M, nl, M) % M;
		ans %= M;
		ans += (a % M * f(nl, B, ten, M)) % M;
