	rep(x,n) rep(y,n) r.v[x][y]=0;
	rep(i,n) r.v[i][i]=1;
	while(p) {
		if(p%2) r=mulmat(r,a,mod,n);
		a=mulmat(a,a,mod,n);
		p>>=1;
	}
	return r;
}

