			exit(1);
		}
		this->n = n;
		this->vec.resize(n, vector<int>(n));
		rep(i, n) {
			rep(j, n)this->vec[i][j] = vec[i * n + j];
		}
	}
	int operator[](int a) {
		return vec[a / n][a % n];
	}
	unsigned int size() {return n;}
	matrix operator*(const matrix a) {
		if (this->n != a.n) {
			cerr << "Invalid maltiple in matrix" << endl;
			exit(1);
		}
		vector<int> memo(n);
		rep(i, n) {
			rep(j, n) {
				rep(k, n) {
					memo[j] += vec[i][k] * a.vec[k][j];
				}
			}
			vec[i] = memo;
			memo.clear();
			memo.resize(n);
		}
		return *this;
	}
	matrix letmod(int m) {
		rep(i, n) {
			rep(j, n)vec[i][j] %= m;
		}
		return *this;
	}
	static matrix measure(int n) {
		matrix res(n);
		res.letMeasure();
		return res;
	}
};
matrix mypow(matrix a, int b, int m) {
	a.letmod(m);
