ll cle(ll l, ll r) {
	if (l == 0)
		return 0;

	if (l % 2 == 1) {
		l--;
		ll rl = getpow(r, l, m);
		return (cle(l, r) + rl) % m;
	}
	else {
		l /= 2;
		ll rl = getpow(r, l, m);
		return ((rl + 1) * cle(l, r)) % m;
	}
}
ll cld(ll l, ll r, ll a, ll b) {
	if (l == 0)
		return 0;

	if (l % 2 == 1) {
		l--;
		ll bl = (b * l) % m;
		return ((r * cld(l, r, a, b)) % m + a + bl) % m;
	}
	else {
		l /= 2;
		ll bl = (b * l) % m;
		ll rl = getpow(r, l, m);
		return ((((rl + 1) % m) * cld(l, r, a, b)) % m + (bl * cle(l, r))) % m;
	}

}
