ll solve(ll ans, ll b, ll mod, ll digs, ll init, ll len)
{
    debug_printf("------------ solve ans=%lld digs=%lld init=%lld len=%lld\n",
                 ans, digs, init, len);

    ll init_matrix[3][3] = {
        {((ll)pow(10LL, digs)) % mod, 0LL, 0LL},
        {1LL, 1LL, 0LL},
        {0LL, b % mod, 1LL},
    };

    ll pm[64][3][3];
    memcpy(pm[0], init_matrix, sizeof(init_matrix));

    debug_printf("---- pm[0]\n");
    debug_print(pm[0][0], 3);
    debug_print(pm[0][1], 3);
    debug_print(pm[0][2], 3);

    rep (i, 63) rep (j, 3) rep (k, 3) {
        pm[i+1][j][k] = (pm[i][j][0] * pm[i][0][k]) % mod;
        pm[i+1][j][k] %= mod;
        pm[i+1][j][k] += (pm[i][j][1] * pm[i][1][k]) % mod;
        pm[i+1][j][k] %= mod;
        pm[i+1][j][k] += (pm[i][j][2] * pm[i][2][k]) % mod;
        pm[i+1][j][k] %= mod;
    }

    ll result_m[3][3] = {
        {1LL, 0LL, 0LL},
        {0LL, 1LL, 0LL},
        {0LL, 0LL, 1LL},
    };

    ll pos = 0LL;
    while (len) {
        if (len & 1LL) {
            ll rr[3][3];
            rep (j, 3) rep (k, 3) {
                rr[j][k] = (result_m[j][0] * pm[pos][0][k]) % mod;
                rr[j][k] %= mod;
                rr[j][k] += (result_m[j][1] * pm[pos][1][k]) % mod;
                rr[j][k] %= mod;
                rr[j][k] += (result_m[j][2] * pm[pos][2][k]) % mod;
                rr[j][k] %= mod;
            }
            memcpy(result_m, rr, sizeof(result_m));
        }
        len >>= 1LL;
        pos++;
    }

    ll ret = 0;
    ret += (ans * result_m[0][0]) % mod;
    ret %= mod;
    ret += ((init % mod) * result_m[1][0]) % mod;
    ret %= mod;
    ret += (1LL * result_m[2][0]) % mod;
    ret %= mod;

    return ret;
}

void _main()
{
    ll len; llin(len);
    ll a; llin(a);
    ll b; llin(b);
    ll mod; llin(mod);

    ll idxs[20] = {};
    srep (digs, 1, 20) {
        ll left = 0;
        ll right = len - 1LL;
        ll now = (left + right) / 2LL;
        ll border = pow(10LL, digs-1LL);
        idxs[digs] = len;
        for ( ; left <= right; now = (left + right) / 2LL) {
            ll val = a + b * now;
            if (val >= border) {
                idxs[digs] = min(idxs[digs], now);
                right = now - 1LL;
            }
            else {
                left = now + 1LL;
            }
        }
    }

    debug_printf("---- idxs\n");
    debug_print(idxs, 20);

    ll ans = 0;

    srep (digs, 1, 19) {
        ll init = a + b * idxs[digs];
        ll llen = idxs[digs+1] - idxs[digs];
        ans = solve(ans, b, mod, digs, init, llen);
    }

    debug_printf("---- ans\n");
    cout << ans << endl;
}

