vector< vector<ll> > product(vector< vector<ll> > A, vector< vector<ll> > B){
	int height = A.size(), width = B[0].size(), n = B.size();

	vector< vector<ll> > C(height, vector<ll>(width, 0));

	for(int i=0;i<height;++i){
		for(int j=0;j<width;++j){
			for(int k=0;k<n;++k){
				C[i][j] += (A[i][k] * B[k][j]) % M;
                C[i][j] %= M;
			}
		}
	}

	return C;
}

vector< vector<ll> > matrix_pow(vector< vector<ll> > A, ll t) {
    int n = A.size();
    vector< vector<ll> > B(n, vector<ll>(n, 0));
    for(int i=0;i<n;++i) B[i][i] = 1;
    while(t){
        if(t & 1){
            B = product(B, A);
        }
        A = product(A, A);
        t >>= 1;
    }
    return B;
}

ll modpow(ll a, ll t) {
    ll ret = 1LL;
    while(t){
        if(t & 1LL){
            ret *= a;
            ret %= M;
        }
        a *= a;
        a %= M;
        t >>= 1;
    }
    return ret;
}

int main() {
    cin >> L >> A >> B >> M;
    carry_over[0] = 0;
    ll con_9 = 9LL;
    for(int i=1;i<19;++i) {
        if(A + B * L <= con_9) {
            carry_over[i] = L;
            break;
        }
        ll ng = -1, ok = L;
        while(ok-ng > 1) {
            ll mid = (ng+ok)/2;
            if(A+B*mid <= con_9) {
                ng = mid;
            } else {
                ok = mid;
            }
        }
        carry_over[i] = ok;

        con_9 = (con_9+1) * 10 - 1;
    }

    ll ans = 0LL;
    ll pow10 = 10LL;
    A %= M;
    B %= M;
    for(int d=0;d<19&&carry_over[d]<L;) {
        int dd = d;
        while(carry_over[dd] == carry_over[d]) {
            ++d;
        }
        --d;
        for(int i=0;i<d-dd;++i) {
            pow10 *= 10LL;
            pow10 %= M;
        }

        vector<vector<ll>> matrixA(3, vector<ll>(3, 0)), matrixB(3, vector<ll>(1, 0LL));
        matrixA[0][0] = pow10;
        matrixA[0][1] = 1LL;
        matrixA[1][1] = 1LL;
        matrixA[1][2] = B;
        matrixA[2][2] = 1LL;
        matrixB[0][0] = 0;
        matrixB[1][0] = (A + B * carry_over[d]) % M;
        matrixB[2][0] = 1LL;

        vector<vector<ll>> matrixC = product(matrix_pow(matrixA, carry_over[d+1]-carry_over[d]), matrixB);
        ans *= modpow(pow10, carry_over[d+1]-carry_over[d]);
        ans %= M;
        ans += matrixC[0][0];
        ans %= M;

        dd = ++d;
        while(carry_over[dd] == carry_over[d]) {
            ++d;
        }
        --d;
        for(int i=0;i<d-dd+1;++i) {
            pow10 *= 10LL;
            pow10 %= M;
        }
    }

    cout << ans << endl;
}

