		int sub = int(1LL * c2 * ((A + ((pr - 1) % M) * (B % M)) % M) % M) - int(1LL * c3 * (B % M) % M);
		if (sub < 0) sub += M;
		ans = (ans + 1LL * sub * binpow(10, curlen, M)) % M;
		if (ans >= M) ans -= M;
		curlen += nlen * i;
	}
	cout << ans << endl;
	return 0;
}

