typedef vector<vector<ll>> Matrix;

ll MOD;

void matunit(Matrix &A) {
    for (int i=0;i<3;i++) A[i][i] = 1;
}

void matmul(Matrix &A, Matrix B) {
    Matrix C(vector<vector<ll>>(3,vector<ll>(3,0LL)));
    for (int i=0;i<3;i++) for (int j=0;j<3;j++) for (int k=0;k<3;k++) C[i][j] = (C[i][j] + (A[i][k]%MOD) * (B[k][j]%MOD) % MOD) % MOD;
    for (int i=0;i<3;i++) for (int j=0;j<3;j++) A[i][j] = C[i][j];
}

void matpow(Matrix &M, ll e) {
    Matrix B(vector<vector<ll>>(3,vector<ll>(3)));
    for (int i=0;i<3;i++) for (int j=0;j<3;j++) B[i][j] = M[i][j];
    Matrix C(vector<vector<ll>>(3,vector<ll>(3,0LL)));
    matunit(C);
    while (e) {
        if (e & 1) {
            matmul(C,B);
        }
        e >>= 1;
        matmul(B,B);
    }
    for (int i=0;i<3;i++) for (int j=0;j<3;j++) M[i][j] = C[i][j];
}

int digit(ll x) {
    int ans = 0;
    while (x) {
        x /= 10;
        ans++;
    }
    return ans;
}

int main(void) {
    ll L, A, B, M;
    cin >> L >> A >> B >> M;
    MOD = M;

    // 各桁数の要素数を求める
    vector<ll> N(20,0), F(20,0);
    ll base = 1, v = A, w = L;
    // v は各桁数の最小値, w は残り要素数
    for (int i=1;i<=19;i++) {
        base *= 10;
        if (v < base && w > 0) {
            N[i] = min(w,(base-v+B-1)/B);
            F[i] = v;
            v += B*N[i];
            w -= N[i];
        }
    }

    // 行列を累乗
    vector<Matrix> X(20,vector<vector<ll>>(3,vector<ll>(3)));
    base = 1;
    for (int i=1;i<=19;i++) {
        base *= 10;
        X[i][0][0] = base;
        X[i][0][1] = 1;
        X[i][1][1] = 1;
        X[i][1][2] = B%MOD;
        X[i][2][2] = 1;
        matpow(X[i],N[i]);
    }

    // 行列積
    Matrix E(vector<vector<ll>>(3,vector<ll>(3)));
    matunit(E);
    for (int i=19;i>0;i--) matmul(E,X[i]);
    // for (int i=0;i<3;i++) {
