    vector<ll> V(3,0LL);
    V[1] = A%MOD; V[2] = 1LL;
    ll ans = 0;
    for (int i=0;i<3;i++) ans = (ans + E[0][i] * V[i] % MOD) % MOD;
    cout << ans << endl;

    return 0;
}

