        unsigned long long cnt = (L*10-1 - cur)/b+1 ;
        cnt = min(cnt ,l);

        l -= cnt ;

        ans = matrixMult(base ,matrixPower(multi ,cnt))[0][0] ;

        cur += cnt*b ;
    }
