//!  8888ba.88ba             dP            oo           !//
//!  88  '8b  '8b            88                         !//
//!  88   88   88 .d8888b. d8888P 88d888b. dP dP.  .dP  !//
//!  88   88   88 88'  '88   88   88'  '88 88  '8bd8'   !//
//!  88   88   88 88.  .88   88   88       88  .d88b.   !//
//!  dP   dP   dP '88888P8   dP   dP       dP dP'  'dP  !//
//!=====================================================!//
template <typename T>
struct Matrix
{
    Matrix(const std::size_t R, const std::size_t C, const T zero = T{0}) : R{R}, C{C}, ZERO(zero), table(R, std::vector<T>(C, ZERO)) {}
    Matrix(const Matrix& m) : R{m.R}, C{m.C}, ZERO{m.ZERO}, table{m.table} {}
    Matrix& operator=(const Matrix& m)
    {
        assert(R == m.R), assert(C == m.C);
        for (std::size_t i = 0; i < R; i++) {
            for (std::size_t j = 0; j < C; j++) { table[i][j] = m[i][j]; }
        }
        return *this;
    }
    const std::vector<T>& operator[](const std::size_t r) const { return assert(r < R), table[r]; }
    std::vector<T>& operator[](const std::size_t r) { return assert(r < R), table[r]; }
    friend Matrix operator+(const Matrix& m) { return m; }
    friend Matrix operator-(const Matrix& m)
    {
        Matrix ans(m.R, m.C, m.ZERO);
        for (std::size_t r = 0; r < m.R; r++) {
            for (std::size_t c = 0; c < m.C; c++) { ans.table[r][c] = -m.table[r][c]; }
        }
        return ans;
    }
    friend Matrix operator+(const Matrix& m1, const Matrix& m2)
    {
        assert(m1.R == m2.R), assert(m1.C == m2.C), assert(m1.ZERO == m2.ZERO);
        Matrix ans(m1.R, m1.C, m1.ZERO);
        for (std::size_t i = 0; i < m1.R; i++) {
            for (std::size_t j = 0; j < m1.C; j++) { ans[i][j] = m1.table[i][j] + m2.table[i][j]; }
        }
        return ans;
    }
    friend Matrix operator-(const Matrix& m1, const Matrix& m2)
    {
        assert(m1.R == m2.R), assert(m1.C == m2.C), assert(m1.ZERO == m2.ZERO);
        Matrix ans(m1.R, m1.C, m1.ZERO);
        for (std::size_t i = 0; i < m1.R; i++) {
            for (std::size_t j = 0; j < m1.C; j++) { ans[i][j] = m1.table[i][j] - m2.table[i][j]; }
        }
        return ans;
    }
    friend Matrix operator*(const Matrix& m1, const Matrix& m2)
    {
        assert(m1.C == m2.R), assert(m1.ZERO == m2.ZERO);
        Matrix ans(m1.R, m2.C, m1.ZERO);
        for (std::size_t i = 0; i < m1.R; i++) {
            for (std::size_t j = 0; j < m2.C; j++) {
                for (std::size_t k = 0; k < m1.C; k++) { ans[i][j] += m1.table[i][k] * m2.table[k][j]; }
            }
        }
        return ans;
    }
    friend Matrix operator*(const Matrix& m, const T& t)
    {
        Matrix ans(m.R, m.C, m.ZERO);
        for (std::size_t i = 0; i < m.R; i++) {
            for (std::size_t j = 0; j < m.C; j++) { ans[i][j] = m.table[i][j] * t; }
        }
        return ans;
    }
    friend Matrix operator/(const Matrix& m, const T& t)
    {
        assert(t != m.ZERO);
        Matrix ans(m.R, m.C, m.ZERO);
        for (std::size_t i = 0; i < m.R; i++) {
            for (std::size_t j = 0; j < m.C; j++) { ans[i][j] = m.table[i][j] / t; }
        }
        return ans;
    }
    friend Matrix operator*(const T& t, const Matrix& m) { return m * t; }
    friend Matrix operator^(const Matrix& m, const long long n) { return assert(n > 0), n == 1 ? m : n % 2 == 1 ? m*(m ^ (n - 1)) : ((m * m) ^ (n / 2)); }
    friend Matrix& operator+=(Matrix& m1, const Matrix& m2)
    {
        assert(m1.R == m2.R), assert(m1.C == m2.C), assert(m1.ZERO == m2.ZERO);
        for (std::size_t i = 0; i < m1.R; i++) {
            for (std::size_t j = 0; j < m1.C; j++) { m1.table[i][j] += m2.table[i][j]; }
        }
        return m1;
    }
    friend Matrix& operator-=(Matrix& m1, const Matrix& m2)
    {
        assert(m1.R == m2.R), assert(m1.C == m2.C), assert(m1.ZERO == m2.ZERO);
        for (std::size_t i = 0; i < m1.R; i++) {
            for (std::size_t j = 0; j < m1.C; j++) { m1.table[i][j] -= m2.table[i][j]; }
        }
        return m1;
    }
    friend Matrix& operator*=(Matrix& m1, const Matrix& m2) { return m1 = m1 * m2; }
    friend Matrix& operator*=(Matrix& m, const T& t)
    {
        for (std::size_t i = 0; i < m.R; i++) {
            for (std::size_t j = 0; j < m.C; j++) { m.table[i][j] *= t; }
        }
        return m;
    }
    friend Matrix& operator/=(Matrix& m, const T& t)
    {
        assert(t != m.ZERO);
        for (std::size_t i = 0; i < m.R; i++) {
            for (std::size_t j = 0; j < m.C; j++) { m.table[i][j] /= t; }
        }
        return m;
    }
    friend Matrix& operator^=(Matrix& m, const long long n) { return m = m ^ n; }
    friend std::ostream& operator<<(std::ostream& os, const Matrix& m)
    {
        os << "[\n";
        for (std::size_t i = 0; i < m.R; i++) {
            os << "[";
            for (std::size_t j = 0; j < m.C; j++) { os << m[i][j] << ","; }
            os << "]\n";
        }
        return (os << "]\n");
    }
    const std::size_t R, C;
    const T ZERO;
    std::vector<std::vector<T>> table;
};
