//!  88   88   88 .d8888b. dP 88d888b.  !//
//!  88   88   88 88'  '88 88 88'  '88  !//
//!  88   88   88 88.  .88 88 88    88  !//
//!  dP   dP   dP '88888P8 dP dP    dP  !//
//!=====================================!//
int main()
{
    const ll L = read<ll>(), A = read<ll>(), B = read<ll>(), M = read<ll>();
    constexpr int D = 18;
    std::vector<ll> ds(D + 1, -1LL), dt(D + 1, -1LL);
    std::vector<ll> dig(D + 1, 1LL);
    for (int d = 1; d <= D; d++) { dig[d] = dig[d - 1] * 10LL; }
    for (int d = 1; d <= D; d++) { ds[d] = (dig[d - 1] - A + B - 1) / B, dt[d] = (dig[d] - A + B - 1) / B; }
    using P = std::pair<ll, ll>;
    std::map<int, P, std::greater<int>> index;
    for (int d = 1; d <= D; d++) {
        chmax(ds[d], 0LL), chmax(dt[d], 0LL), chmin(dt[d], L);
        if (dt[d] > ds[d]) { index[d] = {ds[d], dt[d]}; }
    }
    for (int d = 0; d <= D; d++) { dig[d] %= M; }
    DModInt base(1, M), TEN(10, M), ans(0, M);
    for (const auto& p : index) {
        const ll d = p.first;
        const ll s = p.second.first, t = p.second.second;
        Matrix<DModInt> coeff(3, 3, DModInt(0, M));
        coeff[0][0] = coeff[0][1] = coeff[1][1] = DModInt(dig[d], M);
        coeff[1][2] = coeff[2][2] = DModInt(1, M);
        coeff ^= (t - s);
        const auto U = coeff[0][2], T = coeff[1][2];
        ans += base * (T * (A + B * (t - 1)) - U * B);
        const ll keta = (t - s) * d;
        base *= (TEN ^ (keta));
    }
    std::cout << ans << std::endl;
    return 0;
}

