mat3 modulo(mat3 x,ll p){
	return {x[0]%p,x[1]%p,x[2]%p,x[3]%p,x[4]%p,x[5]%p,x[6]%p,x[7]%p,x[8]%p};
}
vec3 mul(mat3 A,vec3 x){
	return {A[0]*x[0]+A[1]*x[1]+A[2]*x[2],
			A[3]*x[0]+A[4]*x[1]+A[5]*x[2],
			A[6]*x[0]+A[7]*x[1]+A[8]*x[2]};
}
vec3 to_vec(mat3 A,int x){
	return {A[x],A[x+3],A[x+6]};
}
mat3 to_mat(vec3 a,vec3 b,vec3 c){
	return {a[0],b[0],c[0],a[1],b[1],c[1],a[2],b[2],c[2]};
}
mat3 mul(mat3 A,mat3 B,ll p){
	return modulo(to_mat(mul(A,to_vec(B,0)),mul(A,to_vec(B,1)),mul(A,to_vec(B,2))),p);
}
mat3 pow(mat3 A,ll n,ll p){
	if(n==0)return {1,0,0,0,1,0,0,0,1};
	if(n==1)return A;
	mat3 A_pow_half = pow(A,n/2,p);
	mat3 A_pow_mod2 = mul(A_pow_half,A_pow_half,p); 
	if(n%2==0)return A_pow_mod2;
	return mul(A_pow_mod2,A,p);
}
ll pow(ll x,ll n,ll p){
	if(n==0)return 1;
	if(n==1)return x;
	ll x_pow_half = pow(x,n/2,p);
	if(n%2==0)return x_pow_half*x_pow_half%p;
	else return (x_pow_half*x_pow_half%p)*x%p;
}
ll digits(ll a){
	ll i=0;
	while(a>=1){
		++i;
		a/=10;
	}
	return i;
}
//maxi(a,b)=max{ i | digits(a)==digits(a+b*i) }
ll maxi(ll a,ll b){
	const ll digit_a=digits(a);
	ll i_min=0,i_max=1e18;
	while(i_min+1<i_max){
		ll i_mid=i_min+(i_max-i_min)/2;
		if(digits(a+b*i_mid)==digit_a){
			i_min=i_mid;
		}else{
			i_max=i_mid;
		}
	}
	if(digits(a+b*i_max)==digit_a)return i_max;
	else return i_min;
}
mat3 solve(ll l,ll a,ll b,ll m){
	//(x,a,1) -> (10^digit(a)x+a,a+b,1)
	mat3 A={pow(10,digits(a),m),1,0,0,1,b%m,0,0,1};
	ll len_this_digit = std::min(l,maxi(a,b)+1);
	mat3 Apow = pow(A,len_this_digit,m);
	if(len_this_digit == l)return Apow;
	else return mul(solve(l-len_this_digit,a+b*(maxi(a,b)+1),b,m),Apow,m);
}
