using PP = pair<long, long>;
const int INF = 1e9;

long n, a, b, m;
vector<PP> decomp() {
  long l = a;
  long rem = n;
  vector<PP> ret;
  for (int base = 1; ; base *= 10) {
    long num = (base - l + b - 1) / b;
    if (num < 0) num = 0;
    if (rem <= num) {
      ret.push_back(PP(l, rem));
      return ret;
    }
    ret.push_back(PP(l, num));
    l += num * b;
    rem -= num;
  }
}

long modpow(long b, long e) {
  if (e == 0) return 1;
  if (e % 2 == 1) return b * modpow(b, e - 1) % m;
  long t = modpow(b, e / 2);
  return t * t % m;
}

long cat(long a, long d, long n) {
  if (n == 0) return 0;
  if (n % 2 == 1) {
    long res = modpow(10, d * (n - 1)) % m;
    return (res + cat(a, d, n - 1)) % m;
  }

  long res = cat(a, d, n / 2);
  long t = (res + res * modpow(10, d * (n / 2)) % m) % m;
  return t;
}

long sub(long a, long b, long d, long n) {
  if (n == 0) return 0;
  if (n % 2 == 1) {
    long res = cat(a, d, n);
    return (res + sub(b, b, d, n - 1)) % m;
  }

  long res = sub(a, b, d, n / 2);
  long t = (res + res * modpow(10, d * (n / 2)) % m) % m;
  long c = cat(d * n, d, n / 2);
  return (t + c) % m;
}

