    ldLk+=200;
    while(retll10(i)<(1+A+B*ldLk)){
      ldLk--;
    }
    if (ldLk<0)ldLk=-1;

    iLe[i-1]=min(ldLk,L-1);
    iLs[i]=(ll)iLe[i-1]+1;
  }

  /*
  for(int i=0;i<iketa+1;i++){
    cout<<iLs[i]<<endl;
