   */

  //cout<<iL[i-1]<<" "<<(A+B*iLe[i-1])<<" "<<(A+B*(iLs[i-1]+1))<<endl;



  vector<BSPLmatrix> bsplmt(36);int wid=0;
  ll geta=1LL;
  for(int i=iketa;i>=0;i--){
    ll end=iLe[i];
    if (end==-1LL)break;
    ll start=iLs[i];
    //今計算してるとのろの桁
