     */


    ll loop=end-start+1;//バイナリスプリッティングで統合する数
    if (loop<=0)continue;

    BSPLmatrix mtnow;
    mtnow.a_a=(A%M+(B%M)*start)%M;
    mtnow.a_b=B%M;
    //mtnow.A=(A%M+(B%M)*start)%M;
    mtnow.c=1LL;
    mtnow.b=retll10(i+1)%M;
    mtnow.p=retll10(i+1)%M;
    for(ll lp=loop;;){
      if (lp%2LL==1LL){
        bsplmt[wid]=mtnow;wid++;
        mtnow.a_a=(mtnow.a_b+mtnow.a_a)%M;
        if (lp==1LL)break;
      }
      ll tmp=mtnow.a_a*(mtnow.p+1)+mtnow.a_b;
      tmp%=M;
      mtnow.a_b=mtnow.a_b*2*(mtnow.p+1)%M;
