 */

#define ANS_MOD (1000000007LL)

static SQWORD addMod(SQWORD x, SQWORD y)
{ 
    return (x + y) % ANS_MOD;
}

static SQWORD subMod(SQWORD x, SQWORD y)
{
    return (x - y + ANS_MOD) % ANS_MOD;
}

static SQWORD mulMod(SQWORD x, SQWORD y) 
{
    return (x * y) % ANS_MOD;
}

static SQWORD powMod(SQWORD x, SQWORD e) {
    SQWORD v = 1;
    for (; e; x = mulMod(x, x), e >>= 1) {
        if (e & 1) {
            v = mulMod(v, x);
        }
    }
    return v;
}

static SQWORD divMod(SQWORD x, SQWORD y)
{
    return mulMod(x, powMod(y, ANS_MOD - 2));
}


static SQWORD combMod(SQWORD n, SQWORD k)
{
    SQWORD v=1;
    for(SQWORD i=1; i<=k; i++) {
        v = divMod(mulMod(v, n-i+1),i);
    } 
    return v;
}

/*----------------------------------------------*/
static SQWORD addModM(SQWORD x, SQWORD y, SQWORD m)
{ 
    return ((x % m) + (y % m)) % m;
}

static SQWORD subModM(SQWORD x, SQWORD y, SQWORD m)
{
    return ((x % m) - (y % m) + m) % m;
}

static SQWORD mulModM(SQWORD x, SQWORD y, SQWORD m) 
{
    return ((x % m) * (y % m)) % m;
}

static SQWORD powModM(SQWORD x, SQWORD e, SQWORD m) {
    SQWORD v = 1;
    for (; e; x = mulModM(x, x, m), e >>= 1) {
        if (e & 1) {
            v = mulModM(v, x, m);
        }
    }
    return v;
}

/**
 *  整数のべき乗演算
 */
static SQWORD powSQWORD(SQWORD x, SQWORD e) {
    SQWORD v = 1;
    for (; e; x = x*x, e >>= 1) {
        if (e & 1) {
            v = v*x;
        }
    }
    return v;
}

/*------------------------------------------------*/

/**
 *  f(l)
 *      10^(k-1)d + 10^(k-2)d + 10^(k-3)d + ..... + 1 を求める。
 */
static SQWORD calcTenPowSequenceMod(
    SQWORD sqDigits,    /* k */
    SQWORD sqBaseNum,   /* 10^d */
    SQWORD sqMod)       /* Mod */
{

    if (1 == sqDigits) {
        return 1;
    }

    if (0 == (sqDigits % 2)) {
        SQWORD sqRet;
        SQWORD sqModHalf = calcTenPowSequenceMod(sqDigits / 2, sqBaseNum, sqMod);
        sqRet = mulModM(sqModHalf
                        ,powModM(sqBaseNum, sqDigits / 2, sqMod)
                        ,sqMod);
        sqRet = addModM(sqRet, sqModHalf, sqMod); 
        return sqRet;
    } else {
        SQWORD sqRet =  calcTenPowSequenceMod(sqDigits - 1, sqBaseNum, sqMod);
        sqRet = mulModM(sqRet, sqBaseNum, sqMod);
        sqRet = addModM(sqRet, 1, sqMod);
        return sqRet;
    }
}

static SQWORD calcModA(
    SQWORD sqDigits,    /* k */
    SQWORD sqBaseNum,   /* 10^d */
    SQWORD sqInput_M,   /* M */
    SQWORD sqInput_A)   /* A */
{
//    printf("calcModA k[%lld] sqBaseNum[%lld], A[%lld]\n", sqDigits, sqBaseNum, sqInput_A);

    SQWORD sqRet = mulModM(sqInput_A, 
                            calcTenPowSequenceMod(sqDigits, sqBaseNum, sqInput_M), sqInput_M);
    return sqRet;
}    


/**
 *  g(l) = 0*10(k-1)d + B * 10^(k-2)d + 2B * 10^(k-3)d + ..... + (k-1)B * 10^0 を求める。
 * 
 *  g(l+1) = g(l) * sqBaseNum + Bl
 *  g(2l)  = g(l) * sqBaseNum^l + g(l) + Bl*f(l) 
 */
static SQWORD calcModB(
    SQWORD sqDigits,    /* k */
    SQWORD sqBaseNum,   /* 10^d */
    SQWORD sqMod,       /* m */
    SQWORD sqInput_B)
{
    if (1 == sqDigits) {
        return 0;
    }

    SQWORD sqRet;

    if (0 == (sqDigits % 2)) {
        SQWORD sqModHalf = calcModB(sqDigits / 2, sqBaseNum, sqMod, sqInput_B);

        /* Upper */
        SQWORD sqUpper = mulModM(sqModHalf
                                    ,powModM(sqBaseNum, sqDigits / 2, sqMod)
                                    ,sqMod);
        sqUpper = addModM(sqUpper, sqModHalf, sqMod);

        /* Lower */
        SQWORD sqLower = calcTenPowSequenceMod(sqDigits / 2, sqBaseNum, sqMod);
        sqLower = mulModM(sqLower, 
                            mulModM(sqDigits / 2, (sqInput_B % sqMod), sqMod), 
                            sqMod);

        sqRet = addModM(sqUpper, sqLower, sqMod);
        return sqRet;
    } else {
        SQWORD sqRet =  calcModB(sqDigits - 1, sqBaseNum, sqMod, sqInput_B);
        sqRet = mulModM(sqRet, sqBaseNum, sqMod);
        sqRet = addModM(sqRet, mulModM((sqInput_B % sqMod), (sqDigits-1), sqMod), sqMod);

        return sqRet;
    }
}


