        int64_t L = (A + B % MOD * l) % MOD;
        int64_t R = (A + B % MOD * r) % MOD;
        if(l <= r){
            int64_t num = r-l+1;
            for(int t=0; t<d; t++) mul(ans, power_mod(10, num));
            int64_t b = power_mod(10, d);
