            tmp = (tmp + (mod - (b % mod)) * calc2(x, d)) % mod;
            tmp = (tmp + mod) % mod;

            ans = (ans + tmp * base) % mod;

            base = (base * powll(powll(10, d), x)) % mod;
            n = m;
        }
        t /= 10;
    }    

    cout << ans << endl;

    return 0;
}

