/* subroutines */

inline void initvec(vec a) { memset(a, 0, sizeof(vec)); }
inline void initmat(mat a) { memset(a, 0, sizeof(mat)); }

inline void unitmat(mat a) {
  initmat(a);
  for (int i = 0; i < N; i++) a[i][i] = 1;
}

inline void copymat(const mat a, mat b) { memcpy(b, a, sizeof(mat)); }

inline void mulmatmod(const mat a, const mat b, mat c, int mod) {
  for (int i = 0; i < N; i++)
    for (int j = 0; j < N; j++) {
      c[i][j] = 0;
      for (int k = 0; k < N; k++)
        c[i][j] = (c[i][j] + a[i][k] * b[k][j] % mod) % mod;
    }
}

inline void powmatmod(const mat a, ll b, mat c, int mod) {
  mat s, t;
  copymat(a, s);
  unitmat(c);

  while (b > 0) {
    if (b & 1) {
      mulmatmod(c, s, t, mod);
      copymat(t, c);
    }

    mulmatmod(s, s, t, mod);
    copymat(t, s);
    b >>= 1;
  }
}

inline void mulmatvecmod(const mat a, const vec b, vec c, int mod) {
  for (int i = 0; i < N; i++) {
    c[i] = 0;
    for (int j = 0; j < N; j++)
      c[i] = (c[i] + a[i][j] * b[j] % mod) % mod;
  }
}

void printmat(const mat a) {
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      if (j) putchar(' ');
      printf("%lld", a[i][j]);
    }
    putchar('\n');
  }
}

ll powmod(ll a, ll b, int mod) {  // a^b % mod
  ll pm = 1;
  while (b > 0) {
    if (b & 1) pm = (pm * a) % mod;
    a = (a * a) % mod;
    b >>= 1;
  }
  return pm;
}

