    a = (a * a) % p;
    b >>= 1;
  }
  return res;
}


int getKeta(ll x) {
  int res = 0;
  while (x > 0) {
    x /= 10;
    res++;
  }
  return res;
}

// k 桁になる要素の添え字の両端の添え字
pair<ll,ll> ketaRange(ll A, ll B, ll L, int k) {
  ll lb, ub;
  {
    ll lo = -1;
    ll hi = L;
    while (hi - lo > 1) {
      ll mid = (hi + lo) / 2;
      int keta = getKeta(A + B * mid);
      if (keta < k) { lo = mid; } else { hi = mid; }
    }
    lb = hi;
  }
  {
    ll lo = -1;
    ll hi = L;
    while (hi - lo > 1) {
      ll mid = (hi + lo) / 2;
      int keta = getKeta(A + B * mid);
      if (keta <= k) { lo = mid; } else { hi = mid; }
    }
    ub = hi;
  }
  return {lb, ub};
}

ll solve(ll A, ll B, ll L) {
  ll res = 0;
  for (int k = 1; k <= 18; k++) {
    ll from, to;
    tie(from,to) = ketaRange(A, B, L, k);
    ll n = to - from;
    if (n == 0) continue;
    // cout << k << ":" << from << " " << to << endl;
    const ll TEN = pow(10, k);

    Matrix M = zero(3);
    M[0][0] = TEN; M[0][1] = 1;
    M[1][1] = 1; M[1][2] = 1;
    M[2][2] = 1;
    Array b = Array({0, A+from*B, B});

    REP(i, 3) REP(j, 3) M[i][j] %= MOD;
    REP(i, b.size()) b[i] %= MOD;

    M = pow(M, n);
    Array R = mul(M, b);
    // cout << "k=" << k << ", n="<< n << ", res=" << R[0] << endl;
    res = (res * mod_pow(10, k * n % (MOD-1), MOD) % MOD + R[0] % MOD) % MOD;
  }
  return res;
}

