const int INF = 1e9;

long n, a, b, m;
vector<PP> decomp() {
  long l = a;
  long rem = n;
  vector<PP> ret;
  for (long base = 1; ; base *= 10) {
    long num = (base - l + b - 1) / b;
    if (num < 0) num = 0;
    if (rem <= num) {
      ret.push_back(PP(l, rem));
      return ret;
    }
    ret.push_back(PP(l, num));
    l += num * b;
    rem -= num;
  }
}

long modpow(long b, long e) {
  if (e == 0) return 1;
  if (e % 2 == 1) return b % m * modpow(b, e - 1) % m;
  long t = modpow(b, e / 2);
  return t * t % m;
}

long cat(long d, long n) {
  if (n == 0) return 0;
  if (n % 2 == 1) {
    long res = modpow(10, d * (n - 1)) % m;
    return (res + cat(d, n - 1)) % m;
  }

  long res = cat(d, n / 2);
  long t = (res + res * modpow(10, d * (n / 2)) % m) % m;
  return t;
}

long sub(long a, long b, long d, long n) {
  if (n == 0) return 0;
  if (n % 2 == 1) {
    long res = a % m * cat(d, n) % m;
    return (res + sub(b, b, d, n - 1)) % m;
  }

  long res = sub(a, b, d, n / 2);
  long t = (res + res * modpow(10, d * (n / 2)) % m) % m;
  long c = b % m * (n / 2) % m * cat(d, n / 2) % m;
  return (t + c) % m;
}

int main() {
  cin >> n >> a >> b >> m;
  vector<PP> res = decomp();

  long sum = 0;
  long mul = 0;
  for (int i = (int)res.size() - 1; i >= 0; --i) {
    if (res[i].second == 0) continue;
    long ans = sub(res[i].first, b, i, res[i].second);
    sum = (sum + ans * modpow(10, mul)) % m;
    mul += res[i].second * i;
  }
  cout << sum << endl;
}

