using large = long long;
static large mod;

static int digitcount(large x) {
    auto cnt = 1;
    while (x > 9) {
        ++cnt;
        x /= 10;
    }
    return cnt;
}

struct mat3x3 {
    large a[3][3];
    static const mat3x3 identity;
};

const mat3x3 mat3x3::identity{{{1, 0, 0}, {0, 1, 0}, {0, 0, 1}}};

mat3x3 operator+(mat3x3 x, mat3x3 y) {
    for (auto i = 0; i < 3; ++i)
        for (auto j = 0; j < 3; ++j)
            x.a[i][j] += y.a[i][j];
    return x;
}

mat3x3 operator-(mat3x3 x, mat3x3 y) {
    for (auto i = 0; i < 3; ++i)
        for (auto j = 0; j < 3; ++j)
            x.a[i][j] -= y.a[i][j];
    return x;
}

mat3x3 operator*(mat3x3 x, mat3x3 y) {
    auto m = mat3x3{};
    for (auto i = 0; i < 3; ++i)
        for (auto j = 0; j < 3; ++j)
            for (auto k = 0; k < 3; ++k)
                m.a[i][j] += x.a[i][k] * y.a[k][j];
    return m;
}

mat3x3 operator%(mat3x3 x, large y) {
    for (auto&& row : x.a)
        for (auto&& elem : row)
            elem %= y;
    return x;
}

mat3x3 power_mod(mat3x3 m, large e, large mod) {
    assert(e >= 0);
    m = m % mod;
    if (e == 0)
        return mat3x3::identity;
    if (e == 1)
        return m;

    auto p = (e % 2 == 0 ? mat3x3::identity : m);
    return p * power_mod(m * m % mod, e / 2, mod) % mod;
}

int main() {
    large l, a, b, m;
    cin >> l >> a >> b >> m;
    mod = m;

    // s_i = A + B * i

    auto last_i_for_len = vector<large>(18 + 1, -1'000'000);
    auto upper = 9LL;
    for (int declen = 1; declen <= 18; declen++, upper = (upper * 10 + 9)) {
        if (a > upper) {
            last_i_for_len[declen] = -1;
            continue;
        }

        last_i_for_len[declen] = (upper - a) / b;
    }

    auto cnt_for_len = vector<large>(18 + 1, 0);
    auto i = 0LL;
    for (int declen = 1; declen <= 18; declen++) {
        if (last_i_for_len[declen] < 0) {
            cnt_for_len[declen] = 0;
            continue;
        }
        if (i >= l) {
            cnt_for_len[declen] = 0;
            continue;
        }

        auto last_i = last_i_for_len[declen];
        if (last_i > l - 1)
            last_i = l - 1;
        if (i <= last_i) {
            cnt_for_len[declen] = last_i - i + 1;
        }
        i = last_i + 1;
    }

    auto tens = 10LL;
    auto matrix = mat3x3::identity;
    for (int declen = 1; declen <= 18; declen++, tens *= 10) {
        const auto cnt = cnt_for_len[declen];
        if (cnt <= 0)
            continue;

        auto mat = mat3x3{tens, 0, 0, 1, 1, 0, 0, b, 1} % mod;
        mat = power_mod(mat, cnt, m) % mod;
        matrix = matrix * mat % mod;
    }

    auto r = mat3x3{0, a, 1, 0, a, 1, 0, a, 1} % mod;
    r = r * matrix % mod;
    cout << r.a[0][0] << endl;
    return 0;
}

