LL MOD = 1000000007;

LL mod_pow(LL a, LL p) {
	LL r = 1;
	while (p) {
		if ((1 & p)) r = r * a % MOD;
		a = a * a % MOD;
		p >>= 1;
	}
	return r;
}

VVLL matmul(VVLL a, VVLL b) {
	int n = a.size();
	VVLL ret = VVLL(n, VLL(n, 0));
	REP(i, n)REP(j, n)REP(k, n)ret[i][j] = (ret[i][j] + a[i][k] * b[k][j]) % MOD;
	return ret;
}

VVLL matpow(VVLL a, LL p) {
	VVLL tmp = a;
	int n = a.size();
	VVLL ret = VVLL(n, VLL(n, 0LL));
	REP(i, n)ret[i][i] = 1LL;
	while (p) {
		if (p & 1)ret = matmul(ret, a);
		a = matmul(a, a);
		p >>= 1;
	}
	return ret;
}

