	for (ll k = 1, p10 = 1; k <= 18; k++, p10 *= 10) {
		// [p10, p10 * 10)の個数をcnt[k]
		ll rc = p10 * 10 - 1 >= A ? (p10 * 10 - A - 1) / B + 1 : 0;
		ll lc = p10 - 1 >= A ? (p10 - A - 1) / B + 1 : 0;
		ll cur = rc - lc;

		if (sum + cur >= L) cur = L - sum;
		cnt[k] = cur;
		sum += cur;
	}

	sum = 0;
