ll MOD;
ll modpow(ll a, ll b) {
	ll ans = 1;
	while (b) {
		if (b % 2)
			ans *= a;
		b /= 2;
		a *= a;
		ans %= MOD;
		a %= MOD;
	}
	return ans;
}

ll enmod(ll a) {
	if (a < 0) {
		a = MOD - ((0 - a) % MOD);
	}
	else
		a %= MOD;
	return a;
}

ll modwari(ll a, ll b) {
	enmod(a);
	return (a*modpow(b, MOD - 2)) % MOD;
}

int main() {
	ll L, A, B;
	cin >> L >> A >> B >> MOD;
	vector<ll> D(18);
	ll d = 1;
	for (int i = 1;i < 18;i++) {
		d *= 10;//D[i]個目までがi桁以下
		D[i] = max((d - A) / B, (ll)0);
	}
	//D[i-1]+1要素目からD[i]要素目まではi桁
	A %= MOD;
	B %= MOD;
	ll ans = 0;
	for (int i = 0;i < 18;i++) {
		//始まりの要素
		ll fir = A + (D[i - 1] + 1)*B;
		fir %= MOD;
		ll ed = A + D[i] * B;
		ed %= MOD;
		ll As = modwari(A * modpow(10, D[i]) - A, 9);
		ll Bs = modwari(B*modpow(ed - A, D[i]) + modwari(B*modpow(10, D[i]) - B * 10, 9) - enmod(fir - A), 9);
		ans += As + Bs;
		ans %= MOD;
	}
	cout << ans << endl;
}

