        for(int j=0; j<3; ++j) {
            ret[i] = (ret[i] + Apro[i][j] * X[j] % MOD) % MOD;
        }
    }
    return ret;
}

long long powmod(long long x, long long n) {
    long long ret = 1;
    while(n > 0) {
        if(n & 1) ret = ret * x % MOD;
        x = x * x;
        n >>= 1;
    }
    return ret;
}

