  reps(i, 18) {
    i64 p = power((i64) 10, i);
    if (A > p) continue;
    i64 c = (p - A) / B + 1;
    if (B * c == p + B - A) c--;
    cnt[i] = c < 0 ? 0 : c;
  }
  rreps(i, 19) cnt[i] -= cnt[i - 1];
  mint ans = 0;
  i64 s = 1;
  reps(i, 18) {
    i64 c = min(L, cnt[i]);
    if (c == 0) continue;
    i64 t = s + c - 1;
    {
      mint G = power((mint) 10, i);
      mint T = power(G, t - s + 1);

      ans *= T;
      ans += (mint) A * (T - 1) / (G - 1);
      ans += (mint) B * (T * (s - 1) + (T - G) / (G - 1) - (t - 1)) / (G - 1);
    }
    L -= c;
    s = t + 1;
  }
  cout << ans << '\n';
}

