template <typename T>
T quickpow(T b, ll e)
{
    T cur = b;
    T ans = b;
    e--;
    while (e)
    {
        if (e & 1)
            ans = ans * cur;
        cur = cur * cur;
        e >>= 1;
    }
    return ans;
}

