  rep(i, A.size()){
    rep(j, B[0].size()){
      rep(k, B.size()){
        res[i][j] = (res[i][j]+A[i][k]*B[k][j])%mod; // remove %MOD if not needed
      }
    }
  }
  return res;
}

mat pow(mat A, int n){
  mat B(A.size(), vector<value>(A.size()));
  rep(i, A.size()){
    B[i][i]=1;  // E
  }
  while (n>0) {
    if (n & 1) B = mul(B, A);
    A = mul(A, A);
    n >>= 1;
  }
  return B;
}

