// 苦手分野 重複順列
// LLの数値をつかう時は最後にLLをつける癖をつけよう

ll l, a, b, m;

int main()
{
  cin >> l >> a >> b >> m;
  MOD = m;
  ll ans = 0;
  rep(i, 1, 19) {
    // A + B * i >= 10 ^ iとなる最小のiを求めて、それから1引くと、
    // A + B * i < 10 ^ iとなる最大のiが求まる.
    ll _max = (Pow(10LL, i) - a + b - 1) / b - 1;
    ll _min = max((Pow(10LL, i - 1) - a + b - 1) / b, 0LL);
    if (_min > l - 1) break;
    if (_max < 0) continue;
    chmin(_max, l - 1);
    Matrix X, Y;
    init(1, 3, X);
    init(3, 3, Y);
    X[0][0] = ans;
    X[0][1] = Madd(a, Mmul(b, _min));
    X[0][2] = 1;
    Y[0][0] = ModPow(10LL, i);
    Y[1][0] = 1;
    Y[1][1] = 1;
    Y[2][1] = Madd(0, b);
    Y[2][2] = 1;
    Y = pow(Y, _max - _min + 1);
    X = X * Y;
    ans = X[0][0];
  }
