		if (N2 < A || COUNT == 0) {
			C[i] = 0;
			continue;
		}
		else if (N1 < A) {
			C[i] = (N2 - A) / B + 1;
		}
		else {
			C[i] = (N2 - A) / B - (N1 - A) / B;
		}
		if (COUNT < C[i]) C[i] = COUNT, COUNT = 0;
		else COUNT -= C[i];
	}
