long long MOD;
unsigned long long modpow(unsigned long long b){
  unsigned long long ans = 1;
  long long a = 10;
  while (b > 0){
    if (b % 2 == 1){
      ans *= a;
      ans %= MOD;
    }
    a *= a;
    a %= MOD;
    b /= 2;
  }
  return ans;
}
unsigned long long gp(int i, unsigned long long N){
  //1+10^i+10^2i+...+10^(N-1)i
  if (N == 1){
    return 1;
  } else {
    if (N % 2 == 0){
      unsigned long long ans = gp(i, N / 2);
      ans *= modpow(N / 2 * i) + 1;
      ans %= MOD;
      return ans;
    } else {
      unsigned long long ans = gp(i, N - 1);
      for (int j = 0; j < i; j++){
        ans *= 10;
        ans %= MOD;
      }
      ans++;
      ans %= MOD;
      return ans;
    }
  }
}
unsigned long long apgp(int i, unsigned long long N){
  //1+2*10^i+3*10^2i+...+N*10^(N-1)i
  if (N == 1){
    return 1;
  } else {
    if (N % 2 == 0){
      unsigned long long ans = apgp(i, N / 2);
      ans *= modpow(N / 2 * i) + 1;
      ans %= MOD;
      ans += gp(i, N / 2) * (N / 2 % MOD) % MOD;
      ans %= MOD;
      return ans;
    } else {
      unsigned long long ans = apgp(i, N - 1);
      for (int j = 0; j < i; j++){
        ans *= 10;
        ans %= MOD;
      }
      ans += N;
      ans %= MOD;
      return ans;
    }
  }
}
long long apgp2(unsigned long long lb, unsigned long long ub, unsigned long long B, int i){
  unsigned long long len = (ub - lb) / B + 1;
  unsigned long long ans = 0;
  if (lb >= B){
    ans += gp(i, len) * ((lb - B) % MOD) % MOD;
  } else {
    ans -= gp(i, len) * ((B - lb) % MOD) % MOD;
    ans += MOD;
  }
  ans %= MOD;
  ans += B % MOD * apgp(i, len) % MOD;
  ans %= MOD;
  return ans;
}
int main(){
  unsigned long long L, A, B, M;
  cin >> L >> A >> B >> M;
  MOD = M;
  unsigned long long C = A + B * (L - 1);
  long long r = A % B;
  long long ans = 0;
  unsigned long long digit_cnt = 0;
  for (int i = 18; i >= 1; i--){
    unsigned long long lb = 1;
    for (int j = 0; j < i - 1; j++){
      lb *= 10;
    }
    unsigned long long ub = lb * 10;
    lb = (lb - r + B - 1) / B * B + r;
    ub = (ub - r - 1) / B * B + r;
    if (lb <= C && A <= ub && lb <= ub){
      lb = max(lb, A);
      ub = min(ub, C);
      assert(lb <= ub);
      ans += apgp2(lb, ub, B, i) * modpow(digit_cnt) % MOD;
      digit_cnt += i * ((ub - lb) / B + 1);
    }
  }
  ans %= MOD;
  cout << ans << endl;
}

