ll fac(ll a,ll b){
    a%=mod;
    if(b==0)return 1;
    if(b&1)return (a*fac(a,b-1))%mod;
    return (fac(a,b/2)*fac(a,b/2))%mod;
}
ll f(ll n){
    if(n==0)return 0;
    if(n&1)return (f(n-1)*(t%mod)+1)%mod;
    else return (f(n/2)+f(n/2)*fac((t%mod),n/2))%mod;
}
ll g(ll n){
    if(n==0)return 0;
    if(n&1)return (g(n-1)*(t%mod)+n-1)%mod;
    return (g(n/2)+(g(n/2)*fac((t%mod),n/2))%mod+((n/2)*f(n/2))%mod)%mod;
}

