struct ModInt {
 private:
  static int64 M;
  int64 x;
 public:
  static void SetMod(int64 mod) {
    M = mod;
  }
  ModInt(int64 input_x) : x(input_x % M) {}
  ModInt() : x(0) {}
  int64 Value() { return x; }
  inline ModInt operator+(ModInt o) {
    ModInt r(*this); r += o; return r;
  }
  inline ModInt operator-(ModInt o) {
    ModInt r(*this); r -= o; return r;
  }
  inline ModInt operator* (ModInt o) {
    ModInt r(*this); r *= o; return r;
  }
  inline void operator+= (ModInt o) { x = (x + o.x) % M; }
  inline void operator-= (ModInt o) { x = (x + M - o.x) % M; }
  inline void operator*= (ModInt o) { x = (x * o.x) % M; }
};
int64 ModInt::M = 1;  // Do not forget to add this line.

template<typename T>
struct SquareMatrix {
 private:
  vector<vector<T>> matrix;
 public:
  const vector<vector<T>>& Value() { return matrix; }
  SquareMatrix(vector<vector<T>>& in_matrix) : matrix(in_matrix) {}
  SquareMatrix<T> operator*(SquareMatrix<T> o) {
    int n = matrix.size();
    vector<vector<T>> result(n, vector<T>(n));
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        for (int k = 0; k < n; k++) {
          result[i][j] += matrix[i][k] * o.matrix[k][j];
        }
      }
    }
    return SquareMatrix(result);
  }
  vector<T> operator*(vector<T> o) {
    int n = matrix.size();
    vector<T> result(n);
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        result[i] += matrix[i][j] * o[j];
      }
    }
    return result;
  }
  // TODO: Rewrite it without a recursion.
  SquareMatrix<T> Power(int64 p) {
    int n = matrix.size();
    if (p == 0) {
      vector<vector<T>> result(n, vector<T>(n));
      for (int i = 0; i < n; i++) result[i][i] = 1;
      return result;
    } else if (p % 2 == 1) {
      return *this * Power(p - 1);
    } else {
      auto m = Power(p / 2);
      return m * m;
    }
  }
};

