}

string SUB(string s,string t) {
  reverse(all(t));while(s.size()>t.size())t+='0';reverse(all(t));int c=0;
  rrep(i,s.size()) {
    if(c){if(s[i]=='0'){s[i]='9';c=1;}else{s[i]=(char)(s[i]-1);c=0;}}
    if(s[i]<t[i]){s[i]=(char)(s[i]-t[i]+10+'0');c=1;}
