void matpow(const int64_t *X, int64_t *ans, int64_t n, int64_t mod){
    if(n==0){
        for(int i=0;i<3;i++){
            for(int j=0;j<3;j++){
                ans[i*3+j] = (i==j ? 1 : 0);
            }
        }
    }else if(n==1){
        for(int i=0;i<9;i++) ans[i] = X[i] % mod;
    }else if(n%2 == 0){
        int64_t XX[9];
        for(int i=0;i<3;i++){
            for(int k=0;k<3;k++){
                XX[i*3+k] = 0;
                for(int j=0;j<3;j++){
                    XX[i*3+k] = (XX[i*3+k] + X[i*3+j] * X[j*3+k] % mod) % mod;
                }
            }
        }
        matpow(XX, ans, n/2, mod);
    }else{
        int64_t XX[9];
        for(int i=0;i<3;i++){
            for(int k=0;k<3;k++){
                XX[i*3+k] = 0;
                for(int j=0;j<3;j++){
                    XX[i*3+k] = (XX[i*3+k] + X[i*3+j] * X[j*3+k] % mod) % mod;
                }
            }
        }
        matpow(XX, ans, n/2, mod);
        for(int i=0;i<9;i++){
            XX[i] = ans[i];
            ans[i] = 0;
        }
        for(int i=0;i<3;i++){
            for(int k=0;k<3;k++){
                for(int j=0;j<3;j++){
                    ans[i*3+k] = (ans[i*3+k] + XX[i*3+j] * X[j*3+k] % mod) % mod;
                }
            }
        }
    }
}

