        d *= 10;
        int64_t X[9] = {0}, Xp[9];
        X[0] = d % M;
        X[1] = X[4] = X[5] = X[8] = 1;
        matpow(X, Xp, pos[i].second - pos[i].first, M);
        s = (Xp[0]*s%M + Xp[1]*n%M + Xp[2]*B%M) % M;
        n = (Xp[3]*s%M + Xp[4]*n%M + Xp[5]*B%M) % M;
    }

    cout << s << endl;

    return 0;
}

