		}

		// a + b * x < p
		ll x = ceil(p - A, B) - 1;
		if(x >= L) x = L - 1;
		ll num = x - prev;

		mat Y(3, vector<ll>(3, 0));
		Y[0][0] = p % MOD;
		Y[0][1] = 1;
		Y[1][1] = 1;
		Y[1][2] = B % MOD;
