long long int intpow(long long int base, long long int p, long long int M)
{
	if (0 == p){
		return 1;
	}
	if (0 == p % 2){
		long long int val = intpow(base, p / 2, M);
		return (val*val) % M;
	}
	else{
		return (intpow(base, p - 1, M)*base) % M;
	}
}

int digit(long long int val)
{
	long long int tmp = val, ret = 0;
	while (true){
		if (0 == tmp){
			break;
		}
		ret++;
		tmp = tmp / 10;
	};

	return ret;
}

void solv()
{
	long long int L, A, B, M; scanf("%lld%lld%lld%lld", &L, &A, &B, &M);

	long long int len = 0, ret = 0;
	for (long long int i = L - 1; i >= 0; i--){
		long long int s = A + B*i;
		ret = (ret + (s%M)*intpow(10, len, M)) % M;

		len += digit(s);
	}

	printf("%lld", ret);

	return;
}

