#define INF (2000000000000000000L)

using namespace std;

double mod(long n, long k) { return n % k >= 0 ? n % k : n % k + k; }

long pow(long x, long k, long num_mod) {
  long ret = 1, p = mod(x, num_mod);
  while (k > 0) {
    if (k & 1) {
      ret = mod(ret * p, num_mod);
    }
    p = mod(p * p, num_mod);
    k /= 2;
  }
  return ret;
}

long calc_e(long l, long r, long num_mod) {
  if (l == 0) {
    return 0;
  }
  if (l % 2 == 0) {
    const long l0 = l / 2, rpowl0 = pow(r, l0, num_mod),
               e0 = calc_e(l0, r, num_mod);
    return mod((rpowl0 + 1) * e0, num_mod);
  } else {
    const long l0 = l - 1, rpowl0 = pow(r, l0, num_mod),
               e0 = calc_e(l0, r, num_mod);
    return mod(e0 + rpowl0, num_mod);
  }
}

// assume a, b, r are less than num_mod (<= 10^9)
long calc_d(long l, long a, long b, long r, long num_mod) {
  if (l == 0) {
    return 0;
  }
  if (l % 2 == 0) {
    const long l0 = l / 2, rpowl0 = pow(r, l0, num_mod),
               bl0 = mod(b * mod(l0, num_mod), num_mod),
               d0 = calc_d(l0, a, b, r, num_mod), e0 = calc_e(l0, r, num_mod);
    const long t1 = mod((rpowl0 + 1) * d0, num_mod),
               t2 = mod(bl0 * e0, num_mod);
    return mod(t1 + t2, num_mod);
  } else {
    const long l0 = l - 1, rpowl0 = pow(r, l0, num_mod),
               bl0 = mod(b * mod(l0, num_mod), num_mod);
    const long t1 = mod(r * calc_d(l0, a, b, r, num_mod), num_mod), t2 = a,
               t3 = bl0;
    return mod(t1 + t2 + t3, num_mod);
  }
}

int main(int argc, char *argv[]) {
  // read inputs
  long L, A, B, M;
  scanf("%ld %ld %ld %ld", &L, &A, &B, &M);

  // calculate vs[k]
  //     vs[k] : min(min_i {i | s_i >= 10^{k-1}}, L)
  vector<long> vs;
  vs.push_back(0);  // let vs[0] = 0
  for (long k = 1; k <= 19; k++) {
    const long ten_pow_km1 = pow(10, k - 1, INF);
    long le = -1, ri = L;
    while (ri - le > 1) {
      const long m = (le + ri) / 2;
      if (A + B * m >= ten_pow_km1) {
        ri = m;
      } else {
        le = m;
      }
    }
    vs.push_back(ri);
    // printf("k = %ld, vs[k] = %ld\n", k, vs[k]);
  }

  // solve
  long ans = 0;
  for (long k = 1; k < 19; k++) {
    // we need to be very careful taking the mod of l
    const long v_kp1 = vs[k + 1], v_k = vs[k], n_k = v_kp1 - v_k;
    const long l = n_k, a = mod(A + mod(B, M) * mod(v_k, M), M), b = mod(B, M),
               r = pow(10, k, M), c_k = calc_d(l, a, b, r, M);
    ans = mod(mod(pow(r, n_k, M) * ans, M) + c_k, M);
    // printf("k = %ld, n_k = %ld, times = %ld\n", k, n_k, k * n_k);
  }
  printf("%ld\n", ans);

  return 0;
}

