ll cae(ll r,ll l,ll m) {
	if (l == 0)
		return 0;
	if (l % 2 == 0) {
		ll ol = l / 2;
		ll rl = getpow(r, ol, m);
		return (cae(r, ol, m) * (1 + rl)) % m;
	}
	else {
		ll ol = l - 1;
		ll rl = getpow(r, ol, m);
		return (cae(r, ol, m) + rl) % m;
	}
}
ll cad(ll r,ll l,ll a,ll b,ll m) {
	if (l == 0)
		return 0;

	if (l % 2 == 0) {
		ll ol = l / 2;
		ll rl = getpow(r, ol, m);
		ll bl = (b * ol) % m;
		return (((cad(r, ol, a, b, m) * (rl + 1)) % m) 
			+ (bl * cae(r,ol,m)) % m) % m;
	}
	else {
		ll ol = l - 1;
		ll bl = (b * ol) % m;
		ll rl = getpow(r, ol, m);
		return (((cad(r, ol, a, b, m) * r) % m) 
			+ (a + bl) % m) % m;
	}

}
