        ModInt r;
        r.i = i + m.i;
        if (r.i >= Mod) r.i -= Mod;
        return r;
    }
    ModInt operator-(ModInt m) const {
        ModInt r;
        r.i = i - m.i;
        if (r.i < 0) r.i += Mod;
        return r;
    }
    ModInt operator*(ModInt m) const {
        ModInt r;
        r.i = (ll)i * m.i % Mod;
        return r;
    }
    ModInt &operator+=(ModInt m) {
        i += m.i;
        if (i >= Mod) i -= Mod;
        return *this;
    }
    ModInt &operator-=(ModInt m) {
        i -= m.i;
        if (i < 0) i += Mod;
        return *this;
    }
    ModInt &operator*=(ModInt m) {
        i = (ll)i * m.i % Mod;
        return *this;
    }
    ModInt operator-() const {
        ModInt r;
        r.i = i == 0 ? 0 : Mod - i;
        return r;
    }
    ModInt pow(ll k) const {
        ModInt r = 1, t = *this;
        for (; k != 0; k /= 2) {
            if (k & 1) r *= t;
            t *= t;
        }
