                    r.a[i][j] = i == j;
                }
            }
            return r;
        }
        ColumnVector operator*(const ColumnVector &v) const {
            ColumnVector r;
            for (int i = 0; i < N; i++) {
                T t = 0;
                for (int k = 0; k < N; k++) {
                    t += a[i][k] * v.a[k];
                }
                r.a[i] = t;
            }
            return r;
        }
        SquareMatrix operator*(const SquareMatrix &x) const {
            SquareMatrix r;
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    T t = 0;
                    for (int k = 0; k < N; k++) {
                        t += a[i][k] * x.a[k][j];
                    }
                    r.a[i][j] = t;
                }
            }
            return r;
        }
        SquareMatrix pow(ll k) const {
            SquareMatrix r = E(), t = *this;
            for (; k != 0; k /= 2) {
                if (k & 1) r = r * t;
                t = t * t;
            }
            return r;
        }
        void print() const {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    cout << a[i][j].i << " \n"[j == N - 1];
                }
            }
        }
        T a[N][N];
