typedef struct {
  li a;
  li b;
  li c;
  li d;
  li e;
  li f;
} mat;

mat mul_mat(mat A,mat B){
  mat C;
  C.a=A.a*B.a%m;
  C.b=A.b*B.a%m+A.c*B.b%m;
  C.c=A.c*B.c%m;
  C.d=A.d*B.a%m+A.e*B.b%m+A.f*B.d%m;
  C.e=A.e*B.c%m+A.f*B.e%m;
  C.f=A.f*B.f%m;
  C.a%=m;
  C.b%=m;
  C.c%=m;
  C.d%=m;
  C.e%=m;
  C.f%=m;
  return C;
}

