typedef struct{
  li a;
  li b;
  li c;
} vec;

vec mul_vec(vec v,mat A){
  vec u;
  u.a=v.a*A.a%m+v.b*A.b%m+v.c*A.d%m;
  u.b=v.b*A.c%m+v.c*A.e%m;
  u.c=v.c*A.f%m;
  u.a%=m;
  u.b%=m;
  u.c%=m;
  return u;
}

