        long m = 0;

        public void solve(int testNumber, Scanner in, PrintWriter out) {
            long l = in.nextLong();
            long a = in.nextLong();
            long b = in.nextLong();
            m = in.nextLong();

            long res = solve(l, a % m, b % m);
            out.println(res);
