            for (int i = 0; i < n; i++) for (int j = 0; j < n; j++)
                tmp[i][j] = a[i][j];

            while (N > 0) {
                if (N % 2 == 1) res = mult(res, a);

                N /= 2;
                a = mult(a, a);
            }

            return res;
        }

