    public final int n;

    public LongSquareMatrix(int n, long init) {
        super(n, n, init);
        this.n = n;
    }

    public LongSquareMatrix(int n) {
        this(n, 0);
    }

    public LongSquareMatrix(long[][] a) {
        super(a);
        this.n = a.length;
    }

    public LongSquareMatrix(long[] a, int n) {
        super(a, n, n);
        this.n = n;
    }

    public double det() {
        double ret = 1.;
        double[][] mat = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = get(i, j);
            }
        }
        double eps = 1e-15;
        boolean swap = false;
        for (int i = 0; i < n; i++) {
            double m = mat[i][i];
            int mj = i;
            for (int j = i + 1; j < n; j++) {
                double v = mat[j][i];
                if (Math.abs(v) > Math.abs(m)) {
                    m = v;
                    mj = j;
                }
            }
            if (Math.abs(m) < eps) {
                return 0;
            }
            ret *= m;
            if (mj != i) {
                double[] tmp = new double[n];
                System.arraycopy(mat[i], 0, tmp, 0, n);
                System.arraycopy(mat[mj], 0, mat[i], 0, n);
                System.arraycopy(tmp, 0, mat[mj], 0, n);
                swap = !swap;
            }
            for (int j = i + 1; j < n; j++) {
                double r = mat[j][i] / mat[i][i];
                for (int k = i; k < n; k++) {
                    mat[j][k] -= mat[i][k] * r;
                }
            }
        }
        return swap ? -ret : ret;
    }
}


