	public static long pow(long n, long p, long mod) {
		if (p == 0)
			return 1;
		if (p == 1)
			return n % mod;
		if (p % 2 == 0) {
			long temp = pow(n, p / 2, mod);
			return (temp * temp) % mod;
		} else {
			long temp = pow(n, p / 2, mod);
			temp = (temp * temp) % mod;
			return (temp * n) % mod;

		}
	}

	public static long pow(long n, long p) {
		if (p == 0)
			return 1;
		if (p == 1)
			return n;
		if (p % 2 == 0) {
			long temp = pow(n, p / 2);
			return (temp * temp);
		} else {
			long temp = pow(n, p / 2);
			temp = (temp * temp);
			return (temp * n);

		}
	}

	public static long gcd(long x, long y) {
		if (x == 0)
			return y;
		else
			return gcd(y % x, x);
	}

	public static boolean isPrime(int n) {
		if (n <= 1)
			return false;
		if (n <= 3)
			return true;

		if (n % 2 == 0 || n % 3 == 0)
			return false;

		for (int i = 5; i * i <= n; i = i + 6)
			if (n % i == 0 || n % (i + 2) == 0)
				return false;

		return true;
	}
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    long L = scanner.nextLong();
    long A = scanner.nextLong();
    long B = scanner.nextLong();
    long M = scanner.nextLong();
    System.out.println(f(A, B, M, 0, L).r);
  }

  private static Result f(long A, long B, long M, long n, long m) {
    if (m <= n) return new Result(0, 0);
    if (m - n == 1) {
      long t = A + B * n;
      long r = t % M;
      int d = 0;
      while (t > 0) {
        t /= 10;
        d++;
      }
      return new Result(r, d);
    }
    Result rr = f(A, B, M, (n + m) / 2, m);
    Result ll = f(A, B, M, n, (n + m) / 2);
    long r = ll.r;
    for (int i = 0; i < rr.d; i++) {
      r *= 10;
      r %= M;
    }
    r += rr.r;
    r %= M;
    return new Result(r, ll.d + rr.d);
  }

  private static class Result {
    private final long r;
    private final int d;

    private Result(long r, int d) {
      this.r = r;
      this.d = d;
    }
  }
}

