partial class Solver
{
    int getDigitLength(long x)
    {
        return x.ToString().Length;
    }

    public void Run()
    {
        var L = nl();
        var A = nl();
        var B = nl();
        var M = nl();
        ModInt.SetModValue((int)M);

        long ans = 0;
        var sL_1 = A + B * (L - 1);
        var s0 = A;

        var startD = getDigitLength(s0);
        var endD = getDigitLength(sL_1);

        var start = s0;
        var startN = 0L;
        for (int d = startD; d <= endD; d++)
        {
            long lower = startN, upper = L - 1;
            long end = -1, endN = -1;
            while (lower <= upper)
            {
                var mid = (lower + upper) / 2;
                long P = A + B * mid;

                if (P.ToString().Length <= d)
                {
                    lower = mid + 1;
                    end = P;
                    endN = mid;
                }
                else
                {
                    upper = mid - 1;
                }
            }
            if (end == -1) continue; // not exists
            var N = endN - startN + 1;
            //new { d, start, end, N }.Dump();

            ans = ans * (int)BigInteger.ModPow(10, d * N, M);
            ans %= M;

            ans += Count(start, B, d, N, M);
            ans %= M;


            start = end + B;
            startN = endN + 1;
        }

        cout.WriteLine(ans);
    }

    long Count(long A0, long B, int digit, long N, long M)
    {
        long result = 0;
        {
            var P = (int)BigInteger.ModPow(10, digit, M);
            var mat = new Matrix(new ModInt[,]
            {
            { P, 0, 0 },
            { 1, 1, 0 },
            { 0, 1, 1 },
            });
            var b = new Matrix(new ModInt[,]
            {
            { B },
            { 0 },
            { 0 },
            });

            var R = Matrix.Pow(mat, N) * b;

            result += R[0, 2].ToInt();
            //cout.WriteLine(" " + R[0, 2].ToInt());
        }

        {
            var P = (int)BigInteger.ModPow(10, digit, M);
            var mat = new Matrix(new ModInt[,]
            {
            { P, 0, 0 },
            { 1, 1, 0 },
            { 0, 1, 1 },
            });
            var b = new Matrix(new ModInt[,]
            {
            { A0 },
            { 0 },
            { 0 },
            });

            var R = Matrix.Pow(mat, N) * b;

            result += R[0, 1].ToInt();
            //cout.WriteLine(" " + R[0, 1].ToInt());
        }
        return result % M;
    }
