public struct ModInt
{
    static private int mod = 0;
    private long value;

    public ModInt(long x)
    {
        this.value = x;
        Normalize();
    }

    static private long RegularMod(long x, int mod)
    {
        if (x >= mod)
        {
            if (x < 2 * mod) return x - mod;
            return x % mod;
        }
        if (x >= 0) return x;
        x = mod - RegularMod(-x, mod);
        if (x == mod) return 0;
        return x;
    }

    static public void SetModValue(int m)
    {
        ModInt.mod = m;
    }

    private void Normalize()
    {
        this.value = RegularMod(value, mod);
    }

    public override string ToString()
    {
        return value.ToString();
    }

    public int ToInt()
    {
        return (int)this.value;
    }

    public static bool operator ==(ModInt c1, ModInt c2)
    {
        return c1.value == c2.value;
    }

    public static bool operator !=(ModInt c1, ModInt c2)
    {
        return !(c1 == c2);
    }

    public static ModInt operator +(ModInt x, ModInt y)
    {
        return new ModInt(x.value + y.value);
    }
    public static ModInt operator -(ModInt x, ModInt y)
    {
        return new ModInt(x.value - y.value);
    }
    public static ModInt operator *(ModInt x, ModInt y)
    {
        return new ModInt(x.value * y.value);
    }
    public static ModInt operator /(ModInt x, ModInt y)
    {
        return new ModInt(x.value * Inverse(y.value, mod));
    }

    static private long ExtendedGcd(long a, long b, ref long x, ref long y)
    {
        if (b == 0)
        {
            x = 1; y = 0;
            return a;
        }
        else
        {
            long d = ExtendedGcd(b, a % b, ref y, ref x);
            y -= a / b * x;
            return d;
        }
    }

    static private long Inverse(long a, long mod)
    {
        long x = 0, y = 0;
        if (ExtendedGcd(a, mod, ref x, ref y) == 1)
            return (x + mod) % mod;
        else
            throw new Exception("Invalid inverse " + a + " " + mod);
    }

    public static implicit operator ModInt(long x)
    {
        return new ModInt(x);
    }

    public override bool Equals(object obj)
    {
        if (obj == null)
        {
            return false;
        }
        return this.value.Equals(((ModInt)obj).value);
    }

    public override int GetHashCode()
    {
        return this.value.GetHashCode();
    }
}
public class Matrix
{
    public int Row { get; private set; }
    public int Col { get; private set; }
    private MatrixType[] Data;
    public Matrix(int row, int col)
    {
        this.Row = row;
        this.Col = col;
        this.Data = new MatrixType[Row * Col];
    }

    public Matrix(MatrixType[,] array)
        : this(array.GetLength(0), array.GetLength(1))
    {
        int index = 0;
        for (int i = 0; i < Row; i++)
        {
            for (int j = 0; j < Col; j++)
            {
                Data[index++] = array[i, j];
            }
        }
    }

    public MatrixType this[int row, int col]
    {
        set
        {
            Data[row * Col + col] = value;
        }
        get
        {
            return Data[row * Col + col];
        }
    }

    static public Matrix UnitMatrix(int n)
    {
        var matrix = new Matrix(n, n);
        for (int i = 0; i < n; i++)
        {
            matrix[i, i] = 1;
        }
        return matrix;
    }

    static public Matrix operator +(Matrix A, Matrix B)
    {
        var C = new Matrix(A.Row, A.Col);
        for (int i = 0; i < C.Data.Length; i++)
        {
            C.Data[i] = A.Data[i] + B.Data[i];
        }
        return C;
    }

    static public Matrix operator -(Matrix A, Matrix B)
    {
        var C = new Matrix(A.Row, A.Col);
        for (int i = 0; i < C.Data.Length; i++)
        {
            C.Data[i] = A.Data[i] - B.Data[i];
        }
        return C;
    }

    static public Matrix operator *(Matrix A, Matrix B)
    {
        var C = new Matrix(A.Row, B.Col);
        for (int i = 0; i < A.Row; i++)
        {
            for (int j = 0; j < B.Col; j++)
            {
                var val = C[i, j];
                for (int k = 0; k < A.Col; k++) val += A[i, k] * B[k, j];
                C[i, j] = val;
            }
        }
        return C;
    }

    public static implicit operator Matrix(MatrixType[,] array)
    {
        return new Matrix(array);
    }

    static public Matrix Pow(Matrix A, long n)
    {
        if (n == 0) return UnitMatrix(A.Row);
        Matrix result = A.Clone(), t = A.Clone(); n--;
        while (n > 0)
        {
            if ((n & 1) != 0)
            {
                result = result * t;
            }
            t = t * t;
            n >>= 1;
        }

        return result;
    }

    public Matrix Clone()
    {
        return new Matrix(Row, Col) { Data = Data.Clone() as MatrixType[] };
    }

    static private void Swap<T>(ref T a, ref T b) { T t = a; a = b; b = t; }

}

