	public Matrix Pow(long n, long mod)
	{
		var p = One(Row);
		var x = this % mod;
		while (n > 0)
		{
			if ((n & 1) == 1) p = (p * x) % mod;
			n >>= 1;
			x = (x * x) % mod;
		}
		return p % mod;
	}
	public Matrix Pow(ulong n)
	{
		var p = One(Row);
		var x = +this;
		while (n > 0)
		{
			if ((n & 1) == 1) p *= x;
			n >>= 1;
			x *= x;
		}
		return p;
	}
	public long Determinant(long mod)
	{
		if (Row == 0) return 1;
		if (Row == 1) { var tmp = a[0, 0] % mod; return tmp >= 0 ? tmp : tmp + mod; }
		if (Row == 2) { var tmp = ((a[0, 0] % mod) * (a[1, 1] % mod) - (a[0, 1] % mod) * (a[1, 0] % mod)) % mod; return tmp >= 0 ? tmp : tmp + mod; }
		var mat = new Matrix(Row, Column, (r, c) => { var tmp = a[r, c] % mod; return tmp >= 0 ? tmp : tmp + mod; });
		var prod = 1L;
		for (var j = 0; j < Row; j++)
		{
			var pos = j;
			while (pos < Row && mat.a[pos, j] == 0) pos++;
			if (pos == Row) return 0;
			if (j != pos) { mat.SwitchRow(j, pos, j); prod = mod - prod; }
			prod = (prod * mat.a[j, j]) % mod;
			var inv = Func.Inverse(mat.a[j, j], mod);
			mat.MultiplicateRow(j, inv, j);
			mat.ModRow(j, mod, j);
			for (var i = j + 1; i < Row; i++) { mat.AddRow(j, i, -mat.a[i, j], j); mat.ModRow(i, mod, j); }
		}
		return prod;
	}
	public Matrix Invert(long mod)
	{
		var inv = One(Row);
		var tmp = new Matrix(Row, Column, (r, c) => { var x = a[r, c] % mod; return x >= 0 ? x : x + mod; });
		for (var j = 0; j < Row; j++)
		{
			var pos = j;
			while (pos < Row && tmp.a[pos, j] == 0) pos++;
			if (pos == Row) return null;
			tmp.SwitchRow(j, pos);
			inv.SwitchRow(j, pos);
			var inv2 = Func.Inverse(tmp.a[j, j], mod);
			inv.MultiplicateRow(j, inv2);
			tmp.MultiplicateRow(j, inv2, j);
			inv.ModRow(j, mod);
			tmp.ModRow(j, mod, j);
			for (var i = j + 1; i < Row; i++) { inv.AddRow(j, i, -tmp.a[i, j]); inv.ModRow(i, mod); tmp.AddRow(j, i, -tmp.a[i, j], j); inv.ModRow(i, mod, j); }
		}
		for (int j = Row - 1; j > 0; j--) for (int i = j - 1; i >= 0; i--)
			{
				inv.AddRow(j, i, -tmp.a[i, j]); inv.ModRow(i, mod);
				tmp.AddRow(j, i, -tmp.a[i, j]); tmp.ModRow(i, mod);
			}
		return inv;
	}
	public void ModRow(int i, long mod, int start = 0) { for (var y = start; y < Column; y++) { a[i, y] %= mod; if (a[i, y] < 0) a[i, y] += mod; } }
	public void SwitchRow(int i, int j, int start = 0) { for (var y = start; y < Column; y++) { var tmp = a[i, y]; a[i, y] = a[j, y]; a[j, y] = tmp; } }
	public void MultiplicateRow(int i, long r, int start = 0) { for (var y = start; y < Column; y++) a[i, y] *= r; }
	public void AddRow(int from, int to, long r, int start = 0) { for (var y = start; y < Column; y++) a[to, y] += a[from, y] * r; }
}

