	{
		var h = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
		long l = h[0], a = h[1], b = h[2];
		M = h[3];

		long r = 0, n_min = 0;
		var d_max = (a + (l - 1) * b).ToString().Length;
		for (int d = a.ToString().Length; d <= d_max; d++)
		{
			var d10 = 1L;
			for (int i = 0; i < d; i++) d10 *= 10;
			var n_max = Math.Min(l - 1, (d10 - 1 - a) / b);

			long c = a + n_min * b, n = n_max - n_min + 1;
			n_min = ++n_max;

			var q = new long[,] { { d10 % M, 1, 0 }, { 0, 1, 1 }, { 0, 0, 1 } };
			q = MPow3(q, n);
			r = (q[0, 0] * r + q[0, 1] * (c % M) + q[0, 2] * (b % M)) % M;
		}
		Console.WriteLine(r);
	}

	static long M;

	static long[,] MPow3(long[,] b, long i)
	{
		var r = new long[,] { { 1, 0, 0 }, { 0, 1, 0 }, { 0, 0, 1 } };
		for (; ; b = MProduct3(b, b))
		{
			if (i % 2 > 0) r = MProduct3(r, b);
			if ((i /= 2) < 1) return r;
		}
	}

	static long[,] MProduct3(long[,] a, long[,] b)
	{
		var r = new long[3, 3];
		for (var i = 0; i < 3; i++)
			for (int j = 0; j < 3; j++)
			{
				for (var k = 0; k < 3; k++) r[i, j] += a[i, k] * b[k, j];
				r[i, j] %= M;
			}
		return r;
	}
}

using System;
using System.IO;

namespace AtCoder
{
    class Program
    {

        private long L;
        private long A, B;
        public long M;
        static void Main(string[] args)
        {
            new Program().Solve();
        }

        public void Solve()
        {
            var sc = new Scanner();
            L = sc.NextLong();
            A = sc.NextLong();
            B = sc.NextLong();
            M = sc.NextInt();
            // そのままだと考え辛いので 1桁のやつ、2桁のやつ...と分けて考える
            // 最後に足す

            // len: 桁

            long m = 1;

            long sZero = A;
            long sLast = A + B * (L - 1);
            long ans = 0;

            long l = -1, r = 0;

            bool f = false;

            for (int len = 1; len <= 18; len++, m *= 10)
            {
                if (m * 10 - 1 < sZero)
                    continue;

                l = r;

                if (sLast < m)
                {
                    break;
                }

                r = Math.Min(L, (m * 10 - 1 - A) / B + 1);


                // 行列累乗

                // {0, S[l], B} * {m * 10, 0, 0} = {0*m*10+s[l]*1+B*0, 0*0+S[l]*1+B*1, 0*0+0*S[l]+B*1}
                //                {1     , 1, 0} 
                //                {0     , 1, 1}

                var s = new long[1, 3];
                s[0, 0] = 0;
                s[0, 1] = (A + B * l) % M;
                s[0, 2] = B;

                var t = new long[3, 3];
                t[0, 0] = (m * 10) % M;
                t[0, 1] = 0;
                t[0, 2] = 0;
                t[1, 0] = 1;
                t[1, 1] = 1;
                t[1, 2] = 0;
                t[2, 0] = 0;
                t[2, 1] = 1;
                t[2, 2] = 1;

                long b = r - l;
                while (b > 0)
                {
                    if (b % 2 == 1)
                    {
                        var nexts = new long[1, 3];
                        for (int i = 0; i < 1; i++)
                        {
                            for (int j = 0; j < 3; j++)
                            {
                                for (int k = 0; k < 3; k++)
                                {
                                    nexts[i, j] += (s[i, k] * t[k, j]) % M;
                                    nexts[i, j] %= M;
                                }
                            }
                        }

                        s = nexts;
                    }

                    var next = new long[3, 3];
                    for (int i = 0; i < 3; i++)
                    {
                        for (int j = 0; j < 3; j++)
                        {
                            for (int k = 0; k < 3; k++)
                            {
                                next[i, j] += (t[i, k] * t[k, j]) % M;
                                next[i, j] %= M;
                            }
                        }
                    }

                    t = next;

                    b /= 2;
                }
                //Console.WriteLine($"{len} {l} {r}");
                //Console.WriteLine($"{len} {s[0, 0]}");
                //Console.WriteLine($"{len} {l}");
                // s[0,0]がlen桁の時のつなげたやつ

                //　つなげたやつの桁数は len*(r-l)
                // なのでansを10^(len*(r-l)倍する

                ans *= MyMath.Pow((m * 10) % M, (r - l), M);
                ans %= M;
                ans += s[0, 0];
                ans %= M;
            }
            Console.WriteLine(ans);
            //Console.WriteLine(111519 % M);
        }
    }
}


class MyMath
{
    public static long Pow(long a, long b, long mod)
    {
        long result = 1;
        while (b > 0)
        {
            if (b % 2 == 1)
            {
                result *= a;
                result %= mod;
            }

            a *= a;
            a %= mod;
            b /= 2;
        }

        return result;
    }
}

class Scanner
{
    public Scanner()
    {
        _stream = new StreamReader(Console.OpenStandardInput());
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private readonly StreamReader _stream;
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = _stream.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

