                var n = m.GetLength(0);
                var tm = new T[n, n];
                for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) tm[i, j] = (dynamic)(i == j ? 1 : 0);
                var t = new Mat<T>(tm);
                var v = new Mat<T>(m);
                while (x != 0)
                {
                    if ((x & 1) == 1) t.Mul(v);
                    v.Mul(v);
                    x >>= 1;
                }
                m = t.m;
                return this;
            }
