  static long SequenceDigitCount(long fir, long tol, long count, long digit)
  {//初項fir, 公差tol, 項数countの等差数列で、桁数digitの整数の個数を返す
    long answer = SequenceDigitCount(fir,tol,digit);
    answer -= SequenceDigitCount(fir+tol*(count-1),tol,digit);
    return answer;
  }

  static long SequenceDigitCount(long fir, long tol, long digit)
  {//初項fir, 公差tolの等差数列で、桁数digitの整数の個数を返す
    if(fir >= Math.Pow(10,digit)) return 0;

    long numFirst = Math.Max((long)(Math.Pow(10,digit-1)-fir+digit-1)/digit, 0);
    long numSecond = ((long)Math.Pow(10,digit)-1-fir)/digit;
    return (numSecond - numFirst + 1);
  }

  static long[,] MatrixProductRepeat(long[,] originalMatrix, long n, long p)
  {//平方行列のn乗(mod p)を返す
  //ただし、mod=0でそのまま返す
    long matrixLength = originalMatrix.GetLength(0);
    long[,] answer = originalMatrix;
    List<int> multipleList = new List<int>();//0は元の行列、1は積の行列をかける

    long memo = n;
    while(memo > 1)
    {
      if(memo % 2 == 1)
      {
        multipleList.Add(0);
        memo--;
      }else
      {
        multipleList.Add(1);
        memo /= 2;
      }
    }

    for(int i = multipleList.Count()-1; i >= 0; i--)
    {
      if(multipleList[i] == 0) MatrixProduct(answer,originalMatrix,p);
      else MatrixProduct(answer,answer,p);
    }

    return answer;
  }

  static long[,] MatrixProduct(long[,] originalMatrixA, long[,] originalMatrixB, long mod)
  //行列の積(mod)を返す
