static class Program{
	static int mod;
	static void Main(){
		Sc sc=new Sc();
		var s=sc.La;
		mod=(int)s[3];
		long[][] b=new long[][]{new long[]{0},new long[]{s[2]%mod},new long[]{s[1]%mod}};
		long k=0,m=0,p=1;
		for(int i = 1;m<s[0];i++) {
			p*=10;
			k=(p-s[1])/s[2]+((p-s[1])%s[2]==0?0:1);
			k=Min(k,s[0]);
			if(k<1){continue;}
			long[][] g=new long[][]{new long[]{(p%mod),0,1},new long[]{0,1,0},new long[]{0,1,1}};
			b=Mp(b,g,k-m);
			m=k;
		}
		Console.WriteLine("{0}",b[0][0]);
	}
	static long[][] Mp(long[][] r,long[][] x,long e){
		while(e>0){
			if((e&1)>0){r=Mm(x,r);}
			x=Mm(x,x);
			e>>=1;
		}
		return r;
	}
	static long[][] Mm(long[][] a,long[][] b){
		long[][] q=new long[a.Length][];
		for(int j=0;j<a.Length;j++){
			q[j]=new long [b[0].Length];
			for(int i=0;i<b[0].Length;i++){
				for(int k=0;k<a.Length;k++){q[j][i]=(q[j][i]+a[j][k]*b[k][i])%mod;}
			}
		}
		return q;
	}
}

