static class Func
{
	public static T[] ConstantArray<T>(int n, T val) { var a = new T[n]; for (var i = 0; i < n; i++) a[i] = val; return a; }
	public static T[] MakeArray<T>(int n, Func<int, T> f) { var a = new T[n]; for (var i = 0; i < n; i++) a[i] = f(i); return a; }
	public static T[] Recurse<T>(int n, T a0, Func<int, T, T> f) { var a = new T[n]; a[0] = a0; for (var i = 1; i < n; i++) a[i] = f(i, a[i - 1]); return a; }
	public static T[] Accumulate<T>(IList<T> a, T zero, Func<T, T, T> f) { var s = new T[a.Count + 1]; s[0] = zero; for (var i = 0; i < a.Count; i++) s[i + 1] = f(s[i], a[i]); return s; }
	public static long FirstBinary(long min, long max, Predicate<long> pred)
	{
		while (min < max)
		{
			var mid = (min + max) / 2;
			if (pred(mid)) max = mid;
			else min = mid + 1;
		}
		return min;
	}
	public static long GCD(long a, long b)
	{
		var n = (ulong)Math.Abs(a); var m = (ulong)Math.Abs(b);
		if (n == 0) return (long)m; if (m == 0) return (long)n;
		int zm = 0, zn = 0;
		while ((n & 1) == 0) { n >>= 1; zn++; }
		while ((m & 1) == 0) { m >>= 1; zm++; }
		while (m != n)
		{
			if (m > n) { m -= n; while ((m & 1) == 0) m >>= 1; }
			else { n -= m; while ((n & 1) == 0) n >>= 1; }
		}
		return (long)n << Math.Min(zm, zn);
	}
	public static long Inverse(long a, long mod)
	{
		if (a < 0) { a %= mod; if (a < 0) a += mod; }
		var t = SolveLinear(a, mod);
		return t.Item1 > 0 ? t.Item1 : t.Item1 + mod;
	}
	public static long Pow(long a, long b, long mod)
	{
		var p = 1L;
		var x = a;
		while (b > 0)
		{
			if ((b & 1) == 1) p = (p * x) % mod;
			b >>= 1;
			x = (x * x) % mod;
		}
		return p;
	}
	public static Tuple<long, long> SolveLinear(long n, long m)
	{
		if (n < 0) { var p = SolveLinear(-n, m); return p == null ? p : new Tuple<long, long>(-p.Item1, p.Item2); }
		if (m < 0) { var p = SolveLinear(n, -m); return p == null ? p : new Tuple<long, long>(p.Item1, -p.Item2); }
		if (n < m) { var p = SolveLinear(m, n); return p == null ? p : new Tuple<long, long>(p.Item2, p.Item1); }
		long a = 1, b = 0, c = 0, d = 1;
		while (m > 0)
		{
			var r = n % m;
			var q = n / m;
			n = m;
			m = r;
			var tmp = a;
			a = -a * q + b;
			b = tmp;
			tmp = c;
			c = -c * q + d;
			d = tmp;
		}
		return n != 1 ? null : new Tuple<long, long>(d, b);
	}
}
class Matrix
{
	public int Row { get; protected set; }
	public int Column { get; protected set; }
	private long[,] a;
	public long this[int r, int c] { get { return a[r, c]; } set { a[r, c] = value; } }
	public Matrix(int r, int c) { Row = r; Column = c; a = new long[r, c]; }
	public Matrix(long[,] components) : this(components.GetLength(0), components.GetLength(1), (i, j) => components[i, j]) { }
	public Matrix(int r, int c, Func<int, int, long> components) : this(r, c) { for (var i = 0; i < r; i++) for (var j = 0; j < c; j++) this.a[i, j] = components(i, j); }
	public long Trace { get { var sum = 0L; for (var i = 0; i < Row; i++) sum += a[i, i]; return sum; } }
	public static Matrix operator +(Matrix p) => new Matrix(p.a);
	public static Matrix operator -(Matrix p) => new Matrix(p.Row, p.Column, (i, j) => -p.a[i, j]);
	public static Matrix operator -(Matrix p, Matrix q) => new Matrix(p.Row, p.Column, (i, j) => p.a[i, j] - q.a[i, j]);
	public static Matrix operator +(Matrix p, Matrix q) => new Matrix(p.Row, p.Column, (i, j) => p.a[i, j] + q.a[i, j]);
	public static Matrix operator *(Matrix p, long r) => new Matrix(p.Row, p.Column, (i, j) => p.a[i, j] * r);
	public static Matrix operator /(Matrix p, long r) => new Matrix(p.Row, p.Column, (i, j) => p.a[i, j] / r);
	public static Matrix operator %(Matrix p, long mod) => new Matrix(p.Row, p.Column, (i, j) => p.a[i, j] % mod);
	public static Matrix operator *(long r, Matrix p) => new Matrix(p.Row, p.Column, (i, j) => p.a[i, j] * r);
	public static Matrix operator *(Matrix p, Matrix q)
		=> new Matrix(p.Row, q.Column, (i, j) => { var sum = 0L; for (var k = 0; k < p.Column; k++) sum = (sum + p.a[i, k] * q.a[k, j]); return sum; });
	public Matrix Transpose() => new Matrix(Column, Row, (i, j) => a[j, i]);
	public override string ToString()
	{
		var sb = new StringBuilder();
		for (var i = 0; i < Row; i++) for (var j = 0; j < Column; j++) sb.Append(a[i, j] + (j == Column - 1 ? "\n" : " "));
		sb.Remove(sb.Length - 1, 1);
		return sb.ToString();
	}
	public static Matrix One(int size) => new Matrix(size, size, (i, j) => i == j ? 1 : 0);
	public static Matrix Zero(int size) => new Matrix(size, size);
	public static Matrix Diagonal(long[] diag) => new Matrix(diag.Length, diag.Length, (i, j) => i == j ? diag[i] : 0);
	public Matrix Pow(long n, long mod)
	{
		var p = One(Row);
		var x = this % mod;
		while (n > 0)
		{
			if ((n & 1) == 1) p = (p * x) % mod;
			n >>= 1;
			x = (x * x) % mod;
		}
		return p % mod;
	}
	public Matrix Pow(ulong n)
	{
		var p = One(Row);
		var x = +this;
		while (n > 0)
		{
			if ((n & 1) == 1) p *= x;
			n >>= 1;
			x *= x;
		}
		return p;
	}
	public long Determinant(long mod)
	{
		if (Row == 0) return 1;
		if (Row == 1) { var tmp = a[0, 0] % mod; return tmp >= 0 ? tmp : tmp + mod; }
		if (Row == 2) { var tmp = ((a[0, 0] % mod) * (a[1, 1] % mod) - (a[0, 1] % mod) * (a[1, 0] % mod)) % mod; return tmp >= 0 ? tmp : tmp + mod; }
		var mat = new Matrix(Row, Column, (r, c) => { var tmp = a[r, c] % mod; return tmp >= 0 ? tmp : tmp + mod; });
		var prod = 1L;
		for (var j = 0; j < Row; j++)
		{
			var pos = j;
			while (pos < Row && mat.a[pos, j] == 0) pos++;
			if (pos == Row) return 0;
			if (j != pos) { mat.SwitchRow(j, pos, j); prod = mod - prod; }
			prod = (prod * mat.a[j, j]) % mod;
			var inv = Func.Inverse(mat.a[j, j], mod);
			mat.MultiplicateRow(j, inv, j);
			mat.ModRow(j, mod, j);
			for (var i = j + 1; i < Row; i++) { mat.AddRow(j, i, -mat.a[i, j], j); mat.ModRow(i, mod, j); }
		}
		return prod;
	}
	public Matrix Invert(long mod)
	{
		var inv = One(Row);
		var tmp = new Matrix(Row, Column, (r, c) => { var x = a[r, c] % mod; return x >= 0 ? x : x + mod; });
		for (var j = 0; j < Row; j++)
		{
			var pos = j;
			while (pos < Row && tmp.a[pos, j] == 0) pos++;
			if (pos == Row) return null;
			tmp.SwitchRow(j, pos);
			inv.SwitchRow(j, pos);
			var inv2 = Func.Inverse(tmp.a[j, j], mod);
			inv.MultiplicateRow(j, inv2);
			tmp.MultiplicateRow(j, inv2, j);
			inv.ModRow(j, mod);
			tmp.ModRow(j, mod, j);
			for (var i = j + 1; i < Row; i++) { inv.AddRow(j, i, -tmp.a[i, j]); inv.ModRow(i, mod); tmp.AddRow(j, i, -tmp.a[i, j], j); inv.ModRow(i, mod, j); }
		}
		for (int j = Row - 1; j > 0; j--) for (int i = j - 1; i >= 0; i--)
			{
				inv.AddRow(j, i, -tmp.a[i, j]); inv.ModRow(i, mod);
				tmp.AddRow(j, i, -tmp.a[i, j]); tmp.ModRow(i, mod);
			}
		return inv;
	}
	public void ModRow(int i, long mod, int start = 0) { for (var y = start; y < Column; y++) { a[i, y] %= mod; if (a[i, y] < 0) a[i, y] += mod; } }
	public void SwitchRow(int i, int j, int start = 0) { for (var y = start; y < Column; y++) { var tmp = a[i, y]; a[i, y] = a[j, y]; a[j, y] = tmp; } }
	public void MultiplicateRow(int i, long r, int start = 0) { for (var y = start; y < Column; y++) a[i, y] *= r; }
	public void AddRow(int from, int to, long r, int start = 0) { for (var y = start; y < Column; y++) a[to, y] += a[from, y] * r; }
}

