var m int

// Matrix type
type Matrix struct {
	arr      []int
	row, col int
}

// MatrixInit function
func MatrixInit(row, col int, a []int) Matrix {
	arr := make([]int, row*col)
	copy(arr, a)
	res := Matrix{arr, row, col}
	return res
}

// ImatrixInit function
func ImatrixInit(n int) Matrix {
	arr := make([]int, n*n)
	for i := 0; i < n; i++ {
		arr[i+i*n] = 1
	}
	res := Matrix{arr, n, n}
	return res
}

// At function for Matrix
func (mat Matrix) At(i, j int) int {
	return mat.arr[i*mat.col+j]
}

// AddMatrix function
func AddMatrix(a, b Matrix) Matrix {
	if a.row != b.row || a.col != b.col {
		return Matrix{}
	}
	for i := 0; i < a.row*a.col; i++ {
		a.arr[i] += b.arr[i]
	}
	return a
}

// SubMatrix function
func SubMatrix(a, b Matrix) Matrix {
	if a.row != b.row || a.col != b.col {
		return Matrix{}
	}
	for i := 0; i < a.row*a.col; i++ {
		a.arr[i] -= b.arr[i]
	}
	return a
}

// MulMatrix function
func MulMatrix(a, b Matrix) Matrix {
	if a.col != b.row {
		return Matrix{}
	}
	res := MatrixInit(a.row, b.col, nil)
	for i := 0; i < res.row; i++ {
		for j := 0; j < res.col; j++ {
			for k := 0; k < a.col; k++ {
				res.arr[i*res.col+j] += (a.arr[i*a.col+k] * b.arr[k*b.col+j]) % m
				res.arr[i*res.col+j] %= m
			}
		}
	}
	return res
}

// PowMatrix function
func PowMatrix(a Matrix, n int) Matrix {
	if a.row != a.col {
		return Matrix{}
	}
	res := ImatrixInit(a.row)
	for n > 0 {
		if n&1 == 1 {
			res = MulMatrix(res, a)
		}
		a = MulMatrix(a, a)
		n >>= 1
	}
	return res
}

