type ModMatrix = object
  M: seq[seq[int]]
  modulus: int

proc initModMatrix(n: int, m: int, modulus: int): ModMatrix =
  result.M = newSeqWith(n, newSeq[int](m))
  result.modulus = modulus

proc mul(A: ModMatrix, B: ModMatrix): ModMatrix =
  var n = A.M.len()
  var m = B.M[0].len()
  var l = A.M[0].len()
  var C = initModMatrix(A.M.len(), B.M[0].len(), A.modulus)
  for i in countup(0, n - 1):
    for k in countup(0, l - 1):
      for j in countup(0, m - 1):
        C.M[i][j] = (C.M[i][j] + A.M[i][k] * B.M[k][j]) mod C.modulus
  return C

proc pow(A: ModMatrix, n: int): ModMatrix =
  var n = n
  var A = A
  var B = initModMatrix(A.M.len(), A.M.len(), A.modulus)
  for i in countup(0, A.M.len() - 1):
    B.M[i][i] = 1
  while n > 0:
    if (n and 1) == 1:
      B = mul(B, A)
    A = mul(A, A)
    n = n shr 1
  return B

