def dot_mod(a, b, mod):
    res = np.zeros((3, 3), dtype=np.int64)
    for i in range(3):
        for j in range(3):
            tmp = a[i, :] * b[:, j]
            tmp = np.mod(tmp, mod)
            res[i, j] = np.sum(tmp) % mod
    return res


def rec_pow(k, n, mod):
    cnt = 1
    k1 = k
    while cnt * 2 <= n:
        k = dot_mod(k, k, mod)
        cnt *= 2

    if cnt == n:
        return k
    else: 
        return np.mod(np.dot(k, rec_pow(k1, n-cnt, mod)), mod)


