import numpy as np
import sys

def rec_pow(k, n, mod):
    cnt = 1
    k1 = k
    while cnt * 2 <= n:
        k = np.mod(np.dot(np.mod(k, mod), np.mod(k, mod)), mod)
        cnt *= 2

    if cnt == n:
        return k
    else: 
        return np.mod(np.dot(k, rec_pow(k1, n-cnt, mod)), mod)


