    c = len(B[0])
    m = len(A[0])
    res = [[0] * c for _ in range(r)]
    for i in range(r):
        for j in range(c):
            for k in range(m):
                res[i][j] += (A[i][k] * B[k][j]) % mod
                res[i][j] %= mod
    return res


