    m = len(A[0])
    res = [[0] * c for _ in range(r)]
    for i in range(r):
        for j in range(c):
            for k in range(m):
                res[i][j] += (A[i][k] * B[k][j]) % mod
                res[i][j] %= mod
    return res


def rec_pow(k, n, mod):
    cnt = 1
    k1 = k
    while cnt * 2 <= n:
        k = dot(k, k,  mod)
        cnt *= 2

    if cnt == n:
        return k
    else: 
        return dot(k, rec_pow(k1, n-cnt, mod), mod)


