pub fn prev_power_of_ten(n: i64) -> i64 {
	let mut r = 1;
	let mut n = n;
	while {
		n /= 10;
		n > 0
	} {
		r *= 10;
	}
	r
}

pub fn next_power_of_ten(n: i64) -> i64 {
	prev_power_of_ten(n) * 10
}

#[derive(Clone)]
pub struct SquareMatrix<T> {
	elem: Vec<T>,
	size: usize,
}

impl<T> SquareMatrix<T>
where
	T: Clone,
{
	pub fn new(size: usize) -> Self
	where
		T: Default,
	{
		Self {
			size,
			elem: vec![T::default(); size * size],
		}
	}

	pub fn size(&self) -> usize {
		self.size
	}

	pub fn zeros(size: usize) -> Self
	where
		T: num::Zero,
	{
		Self {
			size,
			elem: vec![T::zero(); size * size],
		}
	}

	pub fn identity(size: usize) -> Self
	where
		T: num::Zero + num::One,
	{
		let mut elem = vec![T::zero(); size * size];
		for i in (0..size * size).step_by(size + 1) {
			elem[i] = T::one();
		}
		Self { size, elem }
	}

	pub fn get(&self, i: usize, j: usize) -> Option<&T> {
		if i < self.size && j < self.size() {
			unsafe { Some(self.elem.get_unchecked(i * self.size() + j)) }
		} else {
			None
		}
	}

	pub fn get_mut(&mut self, i: usize, j: usize) -> Option<&mut T> {
		if i < self.size && j < self.size() {
			unsafe {
				let size = self.size();
				Some(self.elem.get_unchecked_mut(i * size + j))
			}
		} else {
			None
		}
	}

	pub unsafe fn get_unchecked(&self, i: usize, j: usize) -> &T {
		self.elem.get_unchecked(i * self.size() + j)
	}

	pub unsafe fn get_unchecked_mut(&mut self, i: usize, j: usize) -> &mut T {
		let size = self.size();
		self.elem.get_unchecked_mut(i * size + j)
	}

	pub fn pow<U>(matrix: Self, exp: U) -> Self
	where
		T: num::Zero + num::One + std::ops::Add<Output = T> + std::ops::Mul<Output = T>,
		U: num::Unsigned + num::Integer,
	{
		let mut mat = matrix;
		let mut n = exp;
		let mut r = Self::identity(mat.size());
		while n > U::zero() {
			if n.is_odd() {
				r = r * &mat;
			}
			mat = &mat * &mat;
			n = n / (U::one() + U::one());
		}
		r
	}
}

impl<T> std::ops::Index<(usize, usize)> for SquareMatrix<T> {
	type Output = T;
	fn index(&self, index: (usize, usize)) -> &Self::Output {
		assert!(index.0 < self.size && index.1 < self.size);
		unsafe { self.elem.get_unchecked(index.0 * self.size + index.1) }
	}
}

impl<T> std::ops::IndexMut<(usize, usize)> for SquareMatrix<T> {
	fn index_mut(&mut self, index: (usize, usize)) -> &mut Self::Output {
		assert!(index.0 < self.size && index.1 < self.size);
		unsafe { self.elem.get_unchecked_mut(index.0 * self.size + index.1) }
	}
}

macro_rules! impl_ {
	($trait:ident:$fn:ident for $type:ty) => {
		impl_!($type; $trait:$fn);
		impl_!($type; $trait<&>:$fn);
		impl_!($type; <&> $trait:$fn);
		impl_!($type; <&> $trait<&>:$fn);
	};

	($type:ty; $(<$ref_self:tt>)? Mul$(<$($ref_rhs:tt)?>)?:$fn:ident) => {
		impl<T> std::ops::Mul<$($($ref_rhs)?)?$type> for $($ref_self)? $type
		where
			T: Clone + num::Zero + std::ops::Add<Output = T> + std::ops::Mul<Output = T>,
		{
			type Output = $type;
			fn $fn(self, rhs: $($($ref_rhs)?)?$type) -> Self::Output {
				assert_eq!(self.size(), rhs.size());

				let mut r = <$type>::zeros(self.size());

				for i in 0..self.size() {
					for k in 0..rhs.size() {
						for j in 0..rhs.size() {
							unsafe {
								*r.get_unchecked_mut(i, j) = r.get_unchecked(i, j).clone() + self.get_unchecked(i, k).clone() * rhs.get_unchecked(k, j).clone();
							}
						}
					}
				}
				r
			}
		}
	};
}

