use std::cmp;

fn indices(d: u64, a: u64, b: u64, l: u64) -> Option<(u64, u64)> {
    let calc = move |d| 10u64.pow(d as u32 - 1).checked_sub(a).map_or(0, |numer| numer.ceil_div(b));
    let start = calc(d);
    let end = cmp::min(l, calc(d+1));
    if start < end { Some((start, end)) } else { None }
}

fn calc(s: u64, d: u64, b: u64, len: u64, m: u64) -> u64 {
    let mat = vec![
        vec![10u64.pow(d as u32) % m, 1, 0],
        vec![0, 1, b],
        vec![0, 0, 1]
    ];
    let exp = pow_mat(mat, len, m);
    exp[0].iter().zip(vec![0, s, 1]).map(|(&a, b)| a*b % m).sum::<u64>() % m
}

fn pow_mat(mat: Vec<Vec<u64>>, exp: u64, m: u64) -> Vec<Vec<u64>> {
    if exp == 0 { vec![vec![1, 0, 0], vec![0, 1, 0], vec![0, 0, 1]] } else {
        let sub = pow_mat(mat.clone(), exp/2, m);
        let sq = mul_mat(&sub, &sub, m);
        if exp % 2 == 0 {
            sq
        } else {
            mul_mat(&mat, &sq, m)
        }
    }
}

fn mul_mat(m1: &[Vec<u64>], m2: &[Vec<u64>], m: u64) -> Vec<Vec<u64>> {
    let mut res = Vec::new();
    for i in 0..3 {
        let mut row = Vec::new();
        for j in 0..3 {
            let mut x = 0;
            for k in 0..3 {
                x += m1[i][k] * m2[k][j] % m;
            }
            row.push(x % m);
        }
        res.push(row)
    }
    res
}

fn pow(x: u64, exp: u64, m: u64) -> u64 {
    if exp == 0 { 1 } else {
        let sub = pow(x, exp/2, m);
        if exp % 2 == 0 {
            sub * sub % m
        } else {
            x * sub % m * sub % m
        }
    }
}

fn main() {
    read!(l = u64, a = u64, b = u64, m = u64);
    let mut coeff = 1;
    let mut ans = 0;
    for d in (1..19).rev() {
        if let Some((start, end)) = indices(d, a, b, l) {
            let s = (a + b%m * start%m) % m;
            let len = end - start;
            ans = (ans + calc(s, d, b % m, len, m) * coeff) % m;
            coeff = coeff * pow(10 % m, d * len, m) % m;
        }
    }
    println!("{}", ans);
}

