pub trait Bisect: Copy {
    fn halve(self, other: Self) -> Self;
    fn section_end(self, other: Self) -> bool;
}
impl Bisect for u64 {
    fn halve(self, other: Self) -> Self {
        if self > other {
            other + (self - other) / 2
        } else {
            self + (other - self) / 2
        }
    }
    fn section_end(self, other: Self) -> bool {
        (if self > other {
            self - other
        } else {
            other - self
        }) <= 1
    }
}
impl Bisect for i64 {
    fn halve(self, other: Self) -> Self {
        (self + other) / 2
    }
    fn section_end(self, other: Self) -> bool {
        (self - other).abs() <= 1
    }
}
impl Bisect for f64 {
    fn halve(self, other: Self) -> Self {
        (self + other) / 2.
    }
    fn section_end(self, other: Self) -> bool {
        (self - other).abs() <= 1e-8
    }
}
pub fn binary_search<T: Bisect, F: Fn(T) -> bool>(f: F, ok: T, err: T) -> T {
    let mut ok = ok;
    let mut err = err;
    while !ok.section_end(err) {
        let m = ok.halve(err);
        if f(m) {
            ok = m;
        } else {
            err = m;
        }
    }
    ok
}
type Matrix = Vec<Vec<u64>>;
pub fn mat_eye(n: usize) -> Matrix {
    let mut v = vec![vec![0; n]; n];
    for i in 0..n {
        v[i][i] = 1;
    }
    v
}
pub fn mat_mul(x: &Matrix, y: &Matrix, m: u64) -> Matrix {
    let mut z = vec![vec![0; y[0].len()]; x.len()];
    for i in 0..x.len() {
        for j in 0..y[0].len() {
            for k in 0..x[0].len() {
                z[i][j] = (z[i][j] + x[i][k] * y[k][j] % m) % m;
            }
        }
    }
    z
}
pub fn mat_pow(x: Matrix, y: u64, m: u64) -> Matrix {
    let mut x = x;
    let mut y = y;
    let mut res = mat_eye(x.len());
    while y > 0 {
        if y & 1 == 1 {
