use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let l: i64 = input();
    let a: i64 = input();
    let b: i64 = input();
    let m: i64 = input();

    let last = a + b * (l - 1);
    let mut ans = 0;
    for k in 1..19 {
        let l = i64::pow(10, k as u32 - 1);
        let r = i64::pow(10, k as u32) - 1;

        if r < a {
            continue;
        }
        if last < l {
            break;
        }

        let ka = std::cmp::max(a, a + (l - a + b - 1) / b * b);
        let klast = std::cmp::min(last, a + (r - a) / b * b);
        let kl = (klast - ka) / b + 1;

        ans *= power(10, k * kl, m);
        ans %= m;
        ans += ka % m * f(k, kl, m) % m + b % m * g(k, kl, m) % m;
        ans %= m;
    }

    println!("{}", ans);
}

fn power(x: i64, p: i64, m: i64) -> i64 {
    if p == 0 {
        1
    } else if p % 2 == 1 {
        x * power(x, p - 1, m) % m
    } else {
        let t = power(x, p / 2, m);
        t * t % m
    }
}

fn f(k: i64, l: i64, m: i64) -> i64 {
    if l == 0 {
        0
    } else if l % 2 == 1 {
        let t = f(k, l - 1, m);
        (t * power(10, k, m) + 1) % m
    } else {
        let t = f(k, l / 2, m);
        (t * power(10, k * l / 2, m) + t) % m
    }
}

fn g(k: i64, l: i64, m: i64) -> i64 {
    if l == 0 {
        0
    } else if l % 2 == 1 {
        let l = l - 1;
        let t = g(k, l, m);
        (t * power(10, k, m) + l) % m
    } else {
        let l = l / 2;
        let t = g(k, l, m);
        (t * power(10, k * l, m) % m + t + l * f(k, l, m) % m) % m
    }
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

