    let mut k = 1;
    loop {
        let t = 10usize.pow(k as u32) as usize;
        if t < a {
            k += 1;
            continue;
        }
        d[k] = (t - a + b - 1) / b;
        if d[k] >= l {
            d[k] = l;
            k += 1;
            break;
        }
        k += 1;
    }
    a = a % m;
    b = b % m;
    let mut v = vec![0, a, 1];
    let mut r = vec![vec![10, 1, 0], vec![0, 1, b], vec![0, 0, 1]];
    for i in 1..k {
        v = matvec(&matpow(&r, d[i] - d[i - 1], m), &v, m);
