        let v = v;

        let lb = min(max((v-a+b-1)/b,0),l);
        let ub = max(min((v*10-a+b-1)/b,l),0);
        let rate = powm(10,keta_sum,m);
        let x = powm(10,k+1,m);
        let w = ub-lb;
        let sum = rate*((a%m+b%m*(ub-1)%m)%m*f(x,w,m)%m-b%m*g(x,w,m)%m)%m;
        // eprintln!("{} {}",f(x,w,m),g(x,w,m));
        let sum = (sum+m)%m;
