fn matmulmod(a: &Vec<Vec<usize>>, b: &Vec<Vec<usize>>, m: usize) -> Vec<Vec<usize>> {
    (0..a.len())
        .map(|i| {
            (0..b[0].len())
                .map(|j| {
                    (0..b.len())
                        .map(|k| ((a[i][k] % m) * (b[k][j] % m)))
                        .fold(0, |i, j| (i + j) % m)
                })
                .collect()
        })
        .collect()
}

fn matpowmod(a: &Vec<Vec<usize>>, n: usize, m: usize) -> Vec<Vec<usize>> {
    let mut n = n;
    let mut ret: Vec<Vec<usize>> = (0..a.len())
        .map(|i| {
            let mut a = vec![0; a.len()];
            a[i] = 1;
            a
        })
        .collect();
    let mut cur = a.clone();
    while n > 0 {
        if n & 1 == 1 {
            ret = matmulmod(&ret, &cur, m);
        }
        cur = matmulmod(&cur, &cur, m);
        n >>= 1;
    }
    ret
}

fn matvecmod(a: Vec<Vec<usize>>, x: Vec<usize>, m: usize) -> Vec<usize> {
    (0..a.len())
        .map(|i| {
            (0..x.len())
                .map(|j| a[i][j] * x[j])
                .fold(0, |i, j| (i + j) % m)
        })
        .collect()
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (l, a, b, m) = parse!(it, 4);
    let fc = |d| {
        let x = (10usize.pow(d)).checked_sub(a).unwrap_or(0);
        let y = x % b == 0;
        min(x / b + if y { 0 } else { 1 }, l)
    };
    let cd: Vec<usize> = (0..19).map(|i| fc(i + 1) - fc(i)).collect();
    let mut x = vec![0, a, 1];
    for d in 0..19 {
        let c = vec![vec![10usize.pow(d + 1), 1, 0], vec![0, 1, b], vec![0, 0, 1]];
        let cpowd = matpowmod(&c, cd[d as usize], m);
        x = matvecmod(cpowd, x, m)
    }
    println!("{}", x[0] % m);
}

