fn bin(a: i64, b: i64, d: i64) -> i64 {
	let mut lp = 0;
    let mut rp = (1e18 as i64 - a + b - 1) / b;
    while lp < rp {
    	let hp = (rp - lp) / 2 + lp;
        let v = a + b * hp;
        if v < d {
        	lp = hp + 1;
        } else {
        	rp = hp;
        }
    }
    rp
}

