	if p == 0 {
    	vec![1, 0, 0, 0, 1, 0, 0, 0, 1]
    } else {
    	let t = v.clone();
        if p == 1 {
        	t
    	} else if p % 2 == 0 {
    		pow(&mul(v, &t, m), p / 2, m)
		} else {
        	mul(&t, &pow(v, p - 1, m), m)
        }
    }
}

