    for k in 1..19 {
        let l = i64::pow(10, k as u32 - 1);
        let r = i64::pow(10, k as u32) - 1;
        if last < l || r < a {
            continue;
        }

        let ka = std::cmp::max(a, a + (l - a + b - 1) / b * b);
        let klast = std::cmp::min(last, a + (r - a) / b * b);
        if klast < ka || ka < l || r < ka || klast < l || r < klast {
            continue;
        }

        let kl = (klast - ka) / b + 1;
        ans *= power(i64::pow(10, k as u32), kl, m);
        ans %= m;
        ans += (ka % m * f(k, kl, m) % m + b % m * g(k, kl, m) % m) % m;
        ans %= m;
    }

    println!("{}", ans);
}

fn power(x: i64, p: i64, m: i64) -> i64 {
    if p == 0 {
        1
    } else if p % 2 == 1 {
        x % m * power(x, p - 1, m) % m
    } else {
        let t = power(x, p / 2, m);
        t * t % m
    }
}

fn f(k: i64, l: i64, m: i64) -> i64 {
    if l == 0 {
        0
    } else if l % 2 == 1 {
        let l = l - 1;
        let t = f(k, l, m);
        (t * power(10, k, m) % m + 1) % m
    } else {
        let l = l / 2;
        let t = f(k, l, m);
        (t * power(i64::pow(10, k as u32), l, m) % m + t) % m
    }
}

fn g(k: i64, l: i64, m: i64) -> i64 {
    if l == 0 {
        0
    } else if l % 2 == 1 {
        let l = l - 1;
        let t = g(k, l, m);
        (t * power(10, k, m) % m + l) % m
    } else {
        let l = l / 2;
        let t = g(k, l, m);
        ((t * power(i64::pow(10, k as u32), l, m) % m + t) % m + l % m * f(k, l, m) % m) % m
    }
}

