fn calc_len(v: i64) -> i64 {
    let mut v = v;
    if v == 0 {
        return 1;
    }
    for i in 0..20 {
        if v == 0 {
            return i;
        }
        v /= 10;
    }
    return 20;
}

fn main() {
    let n = read::<i64>();
    let a = read::<i64>();
    let b = read::<i64>();
    let modulo = read::<i64>();
    let mut ans = 0;
    let mut s = 0;
    for w in 1..19 {
        if s == n || calc_len(a + b * s) != w {
            continue;
        }
        let mut l = s;
        let mut r = n;
        while r - l > 1 {
            let mid = (l + r) / 2;
            if calc_len(a + b * mid) == w {
                l = mid;
            } else {
                r = mid;
            }
        }
        let mut e = l + 1;
        let mut ten = 1;
        for _i in 0..w {
            ten = (ten * 10) % modulo;
        }
        let mut mat = Matrix::new(vec![vec![ten, 1, 0], vec![0, 1, 1], vec![0, 0, 1]]);
        mat = matrix_powmod(mat, e - s, modulo);
        let vect = Vector::new_3d(ans, (a + b * s) % modulo, b % modulo);
        ans = (mat * &vect)[0] % modulo;
        s = e;
    }
    println!("{}", ans);
}

