struct ArithSeq {
    a: i64,
    b: i64,
}
impl ArithSeq {
    #[doc = "a+bi >= x"]
    pub fn next(&self, x: i64) -> i64 {
        if x >= self.a {
            let d = x - self.a;
            let i = (d - 1 + self.b) / self.b;
            self.a + self.b * i
        } else {
            let d = self.a - x;
            let i = d / self.b;
            self.a - self.b * i
        }
    }
    #[doc = "a+bi <= y"]
    pub fn prev(&self, x: i64) -> i64 {
        let next = self.next(x);
        if next == x {
            x
        } else {
            next - self.b
        }
    }
    #[doc = "[a+bi, a+bj] <= [l, r]"]
    pub fn range(&self, l: i64, u: i64) -> Option<(i64, i64)> {
        if l > u {
            return None
        }
        let x = self.next(l);
        let y = self.prev(u);
        if x > y {
            return None
        }
        assert!(x <= y);
        if l<=x && x<=u {
            let cnt = (y-x) / self.b;
            Some((x, cnt+1))
        } else {
            None
        }
    }
}
#[derive(Clone)]
pub struct Matrix {
    v: Vec<Vec<i64>>,
}
impl Matrix {
    fn identity(n: usize) -> Self {
        let mut v = vec![vec![0; n]; n];
        for i in 0..n {
            v[i][i] = 1;
        }
        Matrix { v: v }
    }
    fn m(&self) -> usize {
        self.v.len()
    }
    fn n(&self) -> usize {
        self.v[0].len()
    }
    fn mul_rem(&self, other: &Self, mo: i64) -> Self {
        let mut r = vec![vec![0; other.n()]; self.m()];
        for i in 0..self.m() {
            for j in 0..self.n() {
                let mut v = 0;
                for k in 0..self.n() {
                    v += (self.v[i][k] * other.v[k][j]) % mo;
                    v %= mo;
                }
                r[i][j] = v;
            }
        }
        Matrix { v: r }
    }
    fn pow(&self, k: u64, mo: i64) -> Self {
        assert!(self.m() == self.n());
        let mut k = k;
        let mut x = Self::identity(self.m());
        let mut y = self.clone();
        while k > 0 {
            if k & 1 > 0 {
                x = y.clone() * x;
                x %= mo;
            }
            y = y.mul_rem(&y, mo);
            y %= mo;
            k >>= 1;
        }
        x
    }
}
impl std::ops::Add for Matrix {
    type Output = Self;
    fn add(self, other: Self) -> Self {
        let mut r = self.v.clone();
        for i in 0..self.m() {
            for j in 0..self.n() {
                r[i][j] += other.v[i][j];
            }
        }
        Matrix { v: r }
    }
}
impl std::ops::Sub for Matrix {
    type Output = Self;
    fn sub(self, other: Self) -> Self {
        let mut r = self.v.clone();
        for i in 0..self.m() {
            for j in 0..self.n() {
                r[i][j] -= other.v[i][j];
            }
        }
        Matrix { v: r }
    }
}
impl std::ops::Mul for Matrix {
    type Output = Self;
    fn mul(self, other: Self) -> Self {
        let mut r = vec![vec![0; other.n()]; self.m()];
        for i in 0..self.m() {
            for j in 0..self.n() {
                let mut v = 0;
                for k in 0..self.n() {
                    v += self.v[i][k] * other.v[k][j];
                }
                r[i][j] = v;
            }
        }
        Matrix { v: r }
    }
}
impl std::ops::Rem<i64> for Matrix {
    type Output = Self;
    fn rem(self, mo: i64) -> Self {
        let mut r = self.v.clone();
        for i in 0..self.m() {
            for j in 0..self.n() {
                r[i][j] %= mo;
            }
        }
        Matrix { v: r }
    }
}
impl std::ops::RemAssign<i64> for Matrix {
    fn rem_assign(&mut self, mo: i64) {
        for i in 0..self.m() {
            for j in 0..self.n() {
                self.v[i][j] %= mo;
            }
        }
    }
}

