    for k in (0..SZ).rev() {
        let k = k as i64;
        let mut v = 1 as i64;
        for _ in 0..k { v*=10 }
        let v = v;

        let lb = min(max((v-a+b-1)/b,0),l);
        let ub = max(min((v*10-a+b-1)/b,l),0);
        let rate = powm(10,keta_sum,m);
        let x = powm(10,k+1,m);
        let w = ub-lb;
        let sum = rate*((a+b*(ub-1))%m*f(x,w,m)%m-b*g(x,w,m)%m)%m;
        // eprintln!("{} {}",f(x,w,m),g(x,w,m));
        let sum = (sum+m)%m;
        // eprintln!("lbub {} {} {} {}",lb,ub,keta_sum,sum);
        ans = ans + sum%m;
        keta_sum += w*(k+1);

    }
    println!("{}",ans);
}

