fn keta(n: u64) -> u64 {
    if n < 10 {
        1
    } else {
        keta(n/10) + 1
    }
}

use std::ops::Range;

fn keta_range(k: u64, a: u64, b: u64, limit: u64) -> Range<u64> {
    if keta(a) > k { return 0..0 }
    if keta(a + b * limit) < k { return 0..0 }
    let start = {
        let mut left = 0;  // keta() < k
        let mut right = limit;  // keta() >= k
        for _ in 0..200 {
            let mid = (left + right) / 2;
            if keta(a + b * mid) < k {
                left = mid;
            } else {
                right = mid;
            }
        }
        right
    };
    let end = {
        let mut left = 0;  // keta() <= k
        let mut right = limit;  // keta() > k
        for _ in 0..200 {
            let mid = (left + right) / 2;
            if keta(a + b * mid) <= k {
                left = mid;
            } else {
                right = mid;
            }
        }
        right
    };
    start..end
}

use std::ops::{Add, Mul};
type K = u64;

#[derive(Debug, Clone, PartialEq)]
struct Matrix { data: Vec<Vec<K>> }

#[allow(dead_code)]
impl Matrix {
    fn new(data: &Vec<Vec<K>>) -> Matrix {
        Matrix {data: data.clone()}
    }
    fn eye(n: usize) -> Matrix {
        let mut e = vec![vec![0; n]; n];
        for i in 0..n { e[i][i] = 1; }
        Matrix::new(&e)
    }
    fn zero(h: usize, w: usize) -> Matrix {
        Matrix::new(&vec![vec![0; w]; h])
    }
    fn scalar_mul(&self, k: K) -> Matrix {
        let (h, w) = (self.data.len(), self.data[0].len());
        let data: Vec<Vec<K>> =
            (0..h).map(|i| (0..w).map(|j| k * self.data[i][j]).collect()).collect();
        Matrix::new(&data)
    }
    fn modulo(&self, md: u64) -> Matrix {
        let (h, w) = (self.data.len(), self.data[0].len());
        let data = (0..h).map(|i| (0..w).map(|j| self.data[i][j] % md).collect()).collect();
        Matrix::new(&data)
    }
    fn pow(&self, n: u64, md: u64) -> Matrix {
        if n == 0 {
            Matrix::eye(self.data.len())
        } else if n == 1 {
            self.modulo(md)
        } else if n % 2 == 0 {
            let m = (self * self).modulo(md);
            m.pow(n / 2, md).modulo(md)
        } else {
            let m = (self * self).modulo(md);
            (&m.pow(n / 2, md).modulo(md) * self).modulo(md)
        }
    }
}

impl<'t> Add<&'t Matrix> for &'t Matrix {
    type Output = Matrix;
    fn add(self, right: &'t Matrix) -> Matrix {
        let (h, w) = (self.data.len(), self.data[0].len());
        let data: Vec<Vec<K>> =
            (0..h).map(|i| (0..w).map(|j| self.data[i][j] + right.data[i][j]).collect()).collect();
        Matrix::new(&data)
    }
}

impl<'t> Mul<&'t Matrix> for &'t Matrix {
    type Output = Matrix;
    fn mul(self, right: &'t Matrix) -> Matrix {
        let (h, w, v) = (self.data.len(), right.data.len(), right.data[0].len());
        let data: Vec<Vec<K>> =
            (0..h).map(|i| (0..v).map(|k| (0..w).map(|j| self.data[i][j] * right.data[j][k]).sum()).collect())
                  .collect();
        Matrix::new(&data)
    }
}

impl<'t> Mul<&'t Matrix> for K {
    type Output = Matrix;
    fn mul(self, m: &'t Matrix) -> Matrix {
        m.scalar_mul(self)
    }
}

impl<'t> Mul<K> for &'t Matrix {
    type Output = Matrix;
    fn mul(self, k: K) -> Matrix {
        self.scalar_mul(k)
    }
}

fn powmod(x: u64, n: u64, m: u64) -> u64 {
    if n == 0 {
        1
    } else if n == 1 {
        x % m
    } else if n % 2 == 0 {
        powmod(x * x, n / 2, m) % m
    } else {
        ((powmod(x * x, n / 2, m) % m) * x) % m
    }
}

