pub fn gcd(a: u64, b: u64) -> u64 {
    let mut a = a;
    let mut b = b;
    loop {
        if b == 0 {
            return a;
        }
        a %= b;
        if a == 0 {
            return b;
        }
        b %= a;
    }
}
pub fn extgcd(a: i64, b: i64) -> (i64, i64, i64) {
    if b == 0 {
        (a, 1, 0)
    } else {
        let (g, y, x) = extgcd(b, a % b);
        (g, x, y - (a / b) * x)
    }
}
pub fn modinv(a: u64, m: u64) -> Option<u64> {
    let (g, x, _y) = extgcd(a as i64, m as i64);
    if g == 1 {
        Some((x % m as i64 + m as i64) as u64 % m)
    } else {
        None
    }
}
pub fn pow(x: u64, y: u64, z: u64) -> u64 {
    let mut x = x;
    let mut y = y;
    let mut res = 1;
    while y > 0 {
        if y & 1 == 1 {
            res = res * x % z;
        }
        x = x * x % z;
        y >>= 1;
    }
    res
}
