fn bin(a: i64, b: i64, d: i64) -> i64 {
    let mut lp = 0;
    let mut rp = (1e18 as i64 - a) / b + 1;
    while lp < rp {
        let hp = (rp - lp) / 2 + lp;
        let v = a + b * hp;
        if v < d {
            lp = hp + 1;
        } else {
            rp = hp;
        }
    }
    rp
}

fn mul(a: Vec<i64>, b: Vec<i64>, m: i64) -> Vec<i64> {
    let mut ret = vec![0; 9];
    for y in 0..3 {
        for x in 0..3 {
            let mut r = 0;
            for i in 0..3 {
                r += a[y*3+i] * b[i*3+x] % m;
                r %= m;
            }
            ret[y*3+x] = r;
        }
    }
    ret
}


fn pow(v: Vec<i64>, p: i64, m: i64) -> Vec<i64> {
    if p == 0 {
        vec![1, 0, 0, 0, 1, 0, 0, 0, 1]
    } else {
        let t = v.clone();
        if p == 1 {
            t
        } else if p % 2 == 0 {
            pow(mul(v, t, m), p / 2, m)
        } else {
            mul(t, pow(v, p - 1, m), m)
        }
    }
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

