static mut MOD: u64 = 1;

type Matrix = Vec<Vec<u64>>;

// Matrix Exponentiation
fn mat_mul(a: &Matrix, b: &Matrix) -> Matrix {
    assert!(a[0].len() == b.len());

    let h = a.len();
    let w = b[0].len();

    let mut ret = vec![vec![0; w]; h];
    for i in 0..h {
        for j in 0..w {
            for k in 0..b.len() {
                unsafe {
                    ret[i][j] += (a[i][k] * b[k][j]) % MOD;
                    ret[i][j] %= MOD;
                }
            }
        }
    }
    ret
}

fn mat_pow(a: &Matrix, mut n: u64) -> Matrix {
    let mut a = a.clone();
    let mut b = vec![vec![0; a.len()]; a.len()];
    for i in 0..a.len() {
        b[i][i] = 1;
    }
    while n>0 {
        if n&1 > 0 {
            b = mat_mul(&b, &a);
        }
        a = mat_mul(&a, &a);
        n /= 2;
    }
    b
}

pub fn mod_pow(b: u64, p: u64) -> u64 {
    unsafe {
        if p == 0 {
            return 1;
        }
        let mut ret = mod_pow(b * b % MOD, p / 2) % MOD;
        if p % 2 == 1 {
            ret = ret * b % MOD;
        }
        ret
    }
}



#[doc = " [l, r)"]
pub fn binary_search_by<F>(mut l: u64, mut r: u64, f: &F) -> Option<u64>
where
    F: Fn(u64) -> bool,
{
    assert!(l <= r);
    let r_bound = r;
    while r != l {
        let m = l + (r - l) / 2;
        if f(m) {
            r = m;
        } else {
            l = m + 1;
        }
    }
    if r == r_bound {
        None
    } else {
        Some(r)
    }
}

fn number_of_digit(mut n: u64) -> usize {
    let mut num = 0;
    while n>0 {
        num += 1;
        n/= 10;
    }
    num
}

fn main() {
    input!{
      l: u64,
      a: u64,
      b: u64,
      m: u64,
    }
    unsafe {
        MOD = m;
    }
    const D: usize = 18;

    let sd = number_of_digit(a);
    let mut first_idx = vec![None; D+1];
    let mut acm = vec![l; D+1];
    acm[0] = 0;

    for d in sd..D+1 {
        let f = |mid| {
            let v = a + mid*b;
            return number_of_digit(v) >= d
        };
        if let Some(idx) = binary_search_by(0, l, &f) {
            acm[d-1] = idx;
            if number_of_digit(a + b*idx) == d {
                first_idx[d] = Some(idx);
            }
        }
    }
    let mut ans = 0;
    for d in 1..D+1 {
        if first_idx[d].is_none() {
            continue;
        }
        let idx = first_idx[d].unwrap();
        let first = (a + idx*b) % m;
        let td = 10u64.pow(d as u32) % m;
        let v = vec![
            vec![td,0,0],
            vec![1,1,0],
            vec![0,b,1],
        ];
        let fv = vec![
            vec![0, first, 1],
        ];

        let cd = acm[d] - acm[d-1];
        let power = mat_pow(&v, cd);
        let ret = mat_mul(&fv, &power);
        let x = ret[0][0];
        ans *= mod_pow(10, cd * d as u64);
        ans %= m;
        ans += x;
        ans %= m;
    }
    println!("{}", ans);
}

use std::io::*;
use utils::*;

pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

pub fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (l, a, b, m) = i.read::<(usize, usize, usize, usize)>();
    writeln!(o, "{}", solve(l, a, b, m)).unwrap();
}
fn solve(l: usize, a: usize, b: usize, m: usize) -> usize {
    let mut ans = 0;
    for i in 0..l {
        let s = a + b * i;
        let mut s1 = s;
        while s1 != 0 {
            s1 /= 10;
            ans *= 10;
            ans = ans % m;
        }
        ans += s;
        ans = ans % m;
    }
    ans
}

pub mod utils {
    use super::*;

    pub struct CpReader<R: BufRead> {
        r: R,
        b: Vec<u8>,
    }
    impl<R: BufRead> CpReader<R> {
        pub fn new(r: R) -> Self {
            CpReader {
                r: r,
                b: Vec::new(),
            }
        }
        pub fn read_word(&mut self) -> &[u8] {
            self.b.clear();
            let mut consume = 0;
            loop {
                self.r.consume(consume);
                let b = self.r.fill_buf().unwrap();
                assert!(b.len() != 0);
                if let Some(p) = b.iter().position(|&x| x == b' ' || x == b'\n') {
                    self.b.extend_from_slice(&b[..p]);
                    consume = p + 1;
                    break;
                }
                self.b.extend_from_slice(b);
                consume = b.len();
            }
            self.r.consume(consume);
            &self.b
        }
        pub fn read_word_str(&mut self) -> &str {
            unsafe { std::str::from_utf8_unchecked(self.read_word()) }
        }

        pub fn read_line(&mut self) -> &[u8] {
            self.b.clear();
            self.r.read_until(b'\n', &mut self.b).unwrap();
            if self.b.last() == Some(&b'\n') {
                &self.b[..self.b.len() - 1]
            } else {
                &self.b
            }
        }
        pub fn read_line_str(&mut self) -> &str {
            unsafe { std::str::from_utf8_unchecked(self.read_line()) }
        }

        pub fn read<T: CpIn>(&mut self) -> T {
            T::read_from(self)
        }

        pub fn read_vec<T: CpIn>(&mut self, n: usize) -> Vec<T> {
            (0..n).map(|_| self.read()).collect()
        }
        pub fn read_iter<'a, T: CpIn>(&'a mut self, n: usize) -> CpIter<'a, R, T> {
            CpIter {
                r: self,
                n: n,
                _pd: Default::default(),
            }
        }
    }
    pub struct CpIter<'a, R: BufRead + 'a, T> {
        r: &'a mut CpReader<R>,
        n: usize,
        _pd: std::marker::PhantomData<fn() -> T>,
    }
    impl<'a, R: BufRead, T: CpIn> Iterator for CpIter<'a, R, T> {
        type Item = T;
        fn next(&mut self) -> Option<T> {
            if self.n == 0 {
                None
            } else {
                self.n -= 1;
                Some(self.r.read())
            }
        }
    }

    pub trait CpIn {
        fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self;
    }

    impl CpIn for u64 {
        fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
            read_u64_fast(&mut r.r)
        }
    }
    impl CpIn for i64 {
        fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
            read_i64_fast(&mut r.r)
        }
    }
    impl CpIn for char {
        fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
            let b = r.r.fill_buf().unwrap()[0] as char;
            r.r.consume(1);
            let s = r.r.fill_buf().unwrap()[0];
            assert!(s == b' ' || s == b'\n');
            r.r.consume(1);
            b
        }
    }

    macro_rules! cpin_tuple {
        ($($t:ident),*) => {
            impl<$($t: CpIn),*> CpIn for ($($t),*) {
                fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
                    ($($t::read_from(r)),*)
                }
            }
        };
    }

    macro_rules! cpin_cast {
        ($t_self:ty, $t_read:ty) => {
            impl CpIn for $t_self {
                fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
                    <$t_read>::read_from(r) as $t_self
                }
            }
        };
    }
    macro_rules! cpin_parse {
        ($t:ty) => {
            impl CpIn for $t {
                fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
                    r.read_word_str().parse().unwrap()
                }
            }
        };
    }
    cpin_cast!(usize, u64);
    cpin_cast!(u32, u64);
    cpin_cast!(u16, u64);
    cpin_cast!(i32, i64);
    cpin_cast!(i16, i64);
    cpin_cast!(i8, i64);

    cpin_parse!(f64);

    cpin_tuple!(T1, T2);
    cpin_tuple!(T1, T2, T3);
    cpin_tuple!(T1, T2, T3, T4);
    cpin_tuple!(T1, T2, T3, T4, T5);


    fn read_u64_fast<R: BufRead>(r: &mut R) -> u64 {
        let mut value = 0;
        loop {
            let mut idx = 0;
            let buf_len;
            {
                let buf = r.fill_buf().unwrap();
                buf_len = buf.len();
                assert!(buf_len != 0);
                while idx < buf_len && b'0' <= buf[idx] && buf[idx] <= b'9' {
                    value = value * 10 + (buf[idx] - b'0') as u64;
                    idx += 1;
                }
            }
            if idx < buf_len {
                r.consume(idx + 1);
                return value;
            }
            r.consume(idx);
        }
    }
    fn read_i64_fast<R: BufRead>(r: &mut R) -> i64 {
        let (consume, sign) = match r.fill_buf().unwrap()[0] {
            b'+' => (true, 1),
            b'-' => (true, -1),
            _ => (false, 1),
        };
        if consume {
            r.consume(1);
        }
        read_u64_fast(r) as i64 * sign
    }


}

