fn main() {
    let l: i64 = input();
    let a: i64 = input();
    let b: i64 = input();
    let m: i64 = input();

    set_mod(m);

    let last = a + b * (l - 1);
    let mut ans = Modulo(0);
    for k in 1..19 {
        let kd = i64::pow(10, k);
        let l = kd / 10;
        let r = kd - 1;
        if last < l || r < a {
            continue;
        }

        let ka = std::cmp::max(a, a + (l - a + b - 1) / b * b);
        let klast = std::cmp::min(last, a + (r - a) / b * b);
        if klast < ka || ka < l || r < ka || klast < l || r < klast {
            continue;
        }

        let kl = (klast - ka) / b + 1;
        ans *= power(kd, kl);
        ans += f(kd, kl) * ka + g(kd, kl) * b;
    }

    println!("{}", ans);
}

fn power(x: i64, p: i64) -> Modulo {
    if p == 0 {
        Modulo(1)
    } else if p % 2 == 1 {
        power(x, p - 1) * x
    } else {
        let t = power(x, p / 2);
        t * t
    }
}

fn f(kd: i64, l: i64) -> Modulo {
    if l == 0 {
        Modulo(0)
    } else if l % 2 == 1 {
        let l = l - 1;
        f(kd, l) * kd + 1
    } else {
        let l = l / 2;
        let t = f(kd, l);
        t * power(kd, l) + t
    }
}

fn g(kd: i64, l: i64) -> Modulo {
    if l == 0 {
        Modulo(0)
    } else if l % 2 == 1 {
        let l = l - 1;
        g(kd, l) * kd + l
    } else {
        let l = l / 2;
        let t = g(kd, l);
        t * power(kd, l) + t + f(kd, l) * l
    }
}

