const SZ:usize = 18;

fn powm(x:i64,k:i64,m:i64) -> i64{
    let mut k = k;
    let mut x = x%m;
    let mut ans = 1;
    while k>0 {
        if k&1==1 {
            ans = ans*x%m;
        }
        x = x*x%m;
        k>>=1;
    }
    return ans;
}

fn f(x:i64,n:i64,m:i64) -> i64{
    // eprintln!("f{}",n);
    if n<=0 { 0 } 
    else if n<=1 { 1 }
    else { 
        let hn = n/2;
        let tmp = f(x,hn,m);
        let lhs = tmp*(1+powm(x,hn,m))%m;
        let rhs = if n%2==1 {powm(x,n-1,m)} else {0};
        (lhs+rhs)%m
    }
}

fn g(x:i64,n:i64,m:i64) -> i64{
    // eprintln!("g{}",n);
    if n<=1 { 0 } 
    else { 
        let hn = n/2;
        let tmp = g(x,hn,m);
        let lhs = (tmp*(1+powm(x,hn,m))%m+hn%m*f(x,hn,m)%m*powm(x,hn,m)%m)%m;
        let rhs = if n%2==1 {(n-1)%m*powm(x,n-1,m)%m} else {0};
        (lhs+rhs)%m
    }
}

fn main() {
    input! {
        l:i64,
        a:i64,
        b:i64,
        m:i64
    };
    let max_v = a+b*(l-1);

    let mut ans = 0 ;
    let mut keta_sum = 0;
    for k in (0..SZ).rev() {
        let k = k as i64;
        let mut v = 1 as i64;
        for _ in 0..k { v*=10 }
        let v = v;
        if max_v<v || 10*v<=a {continue;}
        let lb = min(max((v-a+b-1)/b,0),l);
        let ub = max(min((v*10-a+b-1)/b,l),0);
        let rate = powm(10,keta_sum,m);
        let x = powm(10,k+1,m);
        let w = ub-lb;
        let lhs = (a%m+b%m*(((ub-1)%m)))%m*f(x,w,m)%m;
        let rhs = -b%m*g(x,w,m)%m;
        let sum = rate*((lhs+rhs)%m);
        let sum = (sum+m)%m;
        // eprintln!("lbub {} {} {} {}",lb,ub,keta_sum,sum);
        ans = ((ans + sum)%m+m)%m;    
        keta_sum += w*(k+1);

    }
    println!("{}",ans);
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

