const SZ:usize = 18;


fn powm(x:i64,k:i64,m:i64) -> i64{
    let mut k = k;
    let mut x = x%m;
    let mut ans = 1;
    while k>0 {
        if k&1==1 {
            ans = ans*x%m;
        }
        x = x*x%m;
        k>>=1;
    }
    return ans;
}

fn f(x:i64,n:i64,m:i64) -> i64{
    // eprintln!("f{}",n);
    if n<=0 { 0 } 
    else if n<=1 { 1 }
    else { 
        let hn = n/2;
        let tmp = f(x,hn,m);
        let lhs = tmp*(1+powm(x,hn,m))%m;
        let rhs = if n%2==1 {powm(x,n-1,m)} else {0};
        (lhs+rhs)%m
    }
}

fn g(x:i64,n:i64,m:i64) -> i64{
    // eprintln!("g{}",n);
    if n<=1 { 0 } 
    else { 
        let hn = n/2;
        let tmp = g(x,hn,m);
        let vl = tmp*(1+powm(x,hn,m))%m;
        let vr = hn%m*f(x,hn,m)%m*powm(x,hn,m)%m;
        let lhs = (vl+vr)%m;
        let rhs = if n%2==1 {(n-1)%m*powm(x,n-1,m)%m} else {0};
        (lhs+rhs)%m
    }
}

