        for _ in 0..k { v*=10 }
        let v = v;
        if max_v<v || 10*v<=a {continue;}
        let lb = min(max((v-a+b-1)/b,0),l);
        let ub = max(min((v*10-a+b-1)/b,l),0);
        let rate = powm(10,keta_sum,m);
        let x = powm(10,k+1,m);
        let w = ub-lb;
        let lhs = (a%m+b%m*(((ub-1)%m)))%m*f(x,w,m)%m;
        let rhs = -b%m*g(x,w,m)%m;
        let sum = rate*((lhs+rhs)%m);
        let sum = (sum+m)%m;
        // eprintln!("lbub {} {} {} {}",lb,ub,keta_sum,sum);
        ans = ((ans + sum)%m+m)%m;    
