fn main() {
    let l: i64 = input();
    let a: i64 = input();
    let b: i64 = input();
    let m: i64 = input();

    let last = a + b * (l - 1);
    let mut ans = 0;
    for k in 1..19 {
        let l = i64::pow(10, k as u32 - 1);
        let r = i64::pow(10, k as u32) - 1;
        if last < l || r < a {
            continue;
        }

        //let ka = std::cmp::max(a, a + (l - a + b - 1) / b * b);
        //let klast = std::cmp::min(last, a + (r - a) / b * b);
        //let kl = (klast - ka) / b + 1;
        //if klast < ka || ka < l || r < ka || klast < l || r < klast {
        //    continue;
        //}
        let ka = if a >= l {
            a
        } else {
            std::cmp::min(last, a + (l - a + b - 1) / b * b)
        };
        let klast = if last <= r { last } else { a + (r - a) / b * b };
        let kl = (klast - ka) / b + 1;

        ans *= power(10, k * kl, m);
        ans %= m;
        ans += (ka % m * f(k, kl, m) % m + b % m * g(k, kl, m) % m) % m;
        ans %= m;
    }

    println!("{}", ans);
}

fn power(x: i64, p: i64, m: i64) -> i64 {
    if p == 0 {
        1
    } else if p % 2 == 1 {
        x * power(x, p - 1, m) % m
    } else {
        let t = power(x, p / 2, m);
        t * t % m
    }
}

fn f(k: i64, l: i64, m: i64) -> i64 {
    if l == 0 {
        0
    } else if l % 2 == 1 {
        let t = f(k, l - 1, m);
        (t * power(10, k, m) + 1) % m
    } else {
        let t = f(k, l / 2, m);
        (t * power(10, k * l / 2, m) + t) % m
    }
}

fn g(k: i64, l: i64, m: i64) -> i64 {
    if l == 0 {
        0
    } else if l % 2 == 1 {
        let l = l - 1;
        let t = g(k, l, m);
        (t * power(10, k, m) + l) % m
    } else {
        let l = l / 2;
        let t = g(k, l, m);
        (t * power(10, k * l, m) % m + t + l * f(k, l, m) % m) % m
    }
}

use proconio::input;
use std::cmp::{min,max};

const SZ:usize = 18;

fn powm(x:i64,k:i64,m:i64) -> i64{
    let mut k = k;
    let mut x = x%m;
    let mut ans = 1;
    while k>0 {
        if k&1==1 {
            ans = ans*x%m;
        }
        x = x*x%m;
        k>>=1;
    }
    return ans;
}

fn f(x:i64,n:i64,m:i64) -> i64{
    // eprintln!("f{}",n);
    if n<=0 { 0 } 
    else if n<=1 { 1 }
    else { 
        let hn = n/2;
        let tmp = f(x,hn,m);
        let lhs = tmp*(1+powm(x,hn,m))%m;
        let rhs = if n%2==1 {powm(x,n-1,m)} else {0};
        (lhs+rhs)%m
    }
}

fn g(x:i64,n:i64,m:i64) -> i64{
    // eprintln!("g{}",n);
    if n<=1 { 0 } 
    else { 
        let hn = n/2;
        let tmp = g(x,hn,m);
        let lhs = (tmp*(1+powm(x,hn,m))%m+hn*f(x,hn,m)%m*powm(x,hn,m)%m)%m;
        let rhs = if n%2==1 {(n-1)*powm(x,n-1,m)} else {0};
        (lhs+rhs)%m
    }
}

